        async function performSearch() {
            const v = document.getElementById("search-ivrs").value.trim();
            currentData = null;
            document.getElementById("result-box").style.display = "none";
            document.getElementById("submit-btn").style.display = "none";
            const alreadyBoxReset = document.getElementById("mobile-already-submitted-box");
            if (alreadyBoxReset) alreadyBoxReset.style.display = "none";
            if (v.length !== 10) return showToast("Enter 10 digit IVRS", false);
            let rows = getConsumerRows(activeDC);
            if (!rows.length) {
                rows = await ensureDcDataLoaded(activeDC);
            }
            if (!rows.length) return showToast("Record Not Found!", false);
            const searchIvrs = normalizeLookupDigits(v);
            let found = findConsumerRowByIvrs(rows, searchIvrs);
            if (!found) {
                rows = await ensureDcDataLoaded(activeDC, true);
                found = findConsumerRowByIvrs(rows, searchIvrs);
            }
            if (!found) {
                rows = await refreshDcDataViaGviz(activeDC);
                found = findConsumerRowByIvrs(rows, searchIvrs);
            }
            if (!found) return showToast("Record Not Found!", false);
            currentData = {
                ivrs: getConsumerField(found, ["IVRS", "IVRS NO", "IVRS NUMBER", "IVRSNO"], searchIvrs),
                name: getConsumerField(found, ["NAME", "CONSUMER NAME"]),
                father: getConsumerField(found, ["FATHER", "FATHER NAME"]),
                old: normalizeMobileDisplayValue(getConsumerField(found, ["OLD MOBILE", "OLD MOBILE NO", "OLD MOBILE NUMBER", "MOBILE NO", "MOBILE NUMBER"])),
                addr: getConsumerField(found, ["ADDRESS", "ADDR", "VILLAGE"]),
                hq: getConsumerField(found, ["HQ", "HQ NAME", "HEADQUARTER", "HEAD QUARTER", "H.Q."])
            };
            document.getElementById("res-ivrs").innerText = currentData.ivrs;
            document.getElementById("res-name").innerText = currentData.name;
            document.getElementById("res-old").innerText = currentData.old || "N/A";
            document.getElementById("res-addr").innerText = currentData.addr;
            document.getElementById("result-box").style.display = "block";
            const entryBoxNow = document.getElementById("mobile-entry-box");
            const submitBtnNow = document.getElementById("submit-btn");
            const alreadyBoxNow = document.getElementById("mobile-already-submitted-box");
            if (alreadyBoxNow) alreadyBoxNow.style.display = "none";
            if (entryBoxNow) entryBoxNow.style.display = "block";
            if (submitBtnNow) submitBtnNow.style.display = "block";
            // User ki request: ab yahan already-submitted map ke fetch (~15 sec tak lag
            // sakta tha, scriptURL?action=getSummary ka pura data) ka WAIT nahi karte -
            // "Enter Correct Mobile" input aur Submit button turant (search khatam hote
            // hi) dikha dete hain, taaki search fast lage. Already-submitted check background
            // me chalta rehta hai; result aane par sirf informational banner update ho jaata
            // hai (agar match mila to), submit button phir bhi visible hi rehta hai - agar
            // koi already-submitted consumer ke liye dobara Submit dabaye, to submitToSheet()
            // ka pehle se maujood safety check hi usko block karega.
            const searchedIvrsForAsyncCheck = searchIvrs;
            loadMobileAlreadySubmittedMap().then(() => {
                if (!currentData || normalizeLookupDigits(currentData.ivrs) !== searchedIvrsForAsyncCheck) return;
                applyMobileAlreadySubmittedUi(getMobileAlreadySubmittedEntry(activeDC, currentData.ivrs));
            }).catch(() => {});
        }

        async function submitToSheet() {
            const n = document.getElementById("new-mobile").value;
            if (n.length !== 10) return showToast("Enter 10 Digit No", false);
            // Safety re-check: agar isi beech (dusre device/tab se) yeh consumer already
            // submit ho chuka ho, to yahan bhi block ho jaye - sirf UI par bharosa na rahe.
            const alreadyEntry = getMobileAlreadySubmittedEntry(activeDC, currentData?.ivrs);
            if (alreadyEntry) {
                applyMobileAlreadySubmittedUi(alreadyEntry);
                showToast("Is consumer ka mobile number pehle hi submit ho chuka hai", false);
                return;
            }
            const p = new URLSearchParams();
            p.append("ivrs", currentData.ivrs);
            p.append("name", currentData.name);
            p.append("father", currentData.father);
            p.append("old_mobile", currentData.old);
            p.append("address", currentData.addr);
            p.append("hq", currentData.hq);
            p.append("correct_mobile", n);
            p.append("dc", activeDC);
            p.append("division", activeDiv);
            p.append("timestamp", new Date().toLocaleDateString("en-GB"));
            try {
                const btn = document.getElementById("submit-btn");
                setActionButtonState(btn, "processing", "Submit");
                const response = await fetch(scriptURL, {
                    method: "POST",
                    headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                    body: p.toString()
                });

                const responseText = await response.text();
                let submitOk = response.ok;
                let submitMessage = submitOk ? "Submitted Successfully!" : "Submit error aaya";

                try {
                    const parsed = JSON.parse(responseText || "{}");
                    if (parsed && parsed.status === "error") {
                        submitOk = false;
                        submitMessage = parsed.message || "Submit error aaya";
                    } else if (parsed && parsed.message) {
                        submitMessage = parsed.message;
                    }
                } catch (_) {
                    if (!submitOk && responseText) {
                        submitMessage = responseText;
                    }
                }

                showToast(submitMessage, submitOk);
                if (!submitOk) {
                    setActionButtonState(btn, "failed", "Submit");
                    return;
                }
                setActionButtonState(btn, "done", "Submit");
                // Local map turant update kar do (60-second cache wait na karna pade) taaki
                // agar ye hi IVRS turant dobara search ho, to "already submitted" sahi dikhe.
                const submittedKey = `${normalizeLookupValue(activeDC || "")}__${normalizeLookupDigits(currentData?.ivrs || "")}`;
                if (submittedKey !== "__") {
                    mobileAlreadySubmittedMap[submittedKey] = { mobile: n, date: new Date().toLocaleDateString("en-GB") };
                }
                // SPEED FIX (2026-09-15) ka side-effect: "Download Summary Report"/
                // "Wrong Mobile No List"/"Updated List" ab is DC ka data 60-second
                // cache (mobileUpdateDcSummaryCache_) se lete hain - agar yeh submit
                // isi DC ke liye pehle se cache me ho, to yahin turant patch kar do
                // (upar wale mobileAlreadySubmittedMap patch jaisa hi pattern), taaki
                // turant baad in screens ko khola jaaye to bhi purana (stale) data na
                // dikhe, cache TTL khatam hone ka wait na karna pade.
                const patchDcKey = normalizeLookupValue(activeDC || "");
                const patchCached = patchDcKey ? mobileUpdateDcSummaryCache_[patchDcKey] : null;
                if (patchCached && Array.isArray(patchCached.data)) {
                    patchCached.data.push({
                        dc: activeDC,
                        division: activeDiv,
                        ivrs: currentData?.ivrs || "",
                        correct_mobile: n,
                        date: new Date().toLocaleDateString("en-GB")
                    });
                }
                resetForm(true);
                const searchInput = document.getElementById("search-ivrs");
                if (searchInput) searchInput.focus();
            } catch (e) {
                setActionButtonState(document.getElementById("submit-btn"), "failed", "Submit");
                showToast("Submit blocked ya network issue aaya", false);
            } finally {
                setTimeout(() => setActionButtonState(document.getElementById("submit-btn"), "idle", "Submit"), 900);
            }
        }

        async function loadCourtCaseData() {
            try {
                courtCaseRaw = await loadRemoteText(courtCaseCsvUrl);
                courtCaseCacheByDc = {};
                courtCaseRecords = isLikelyCsvPayload(courtCaseRaw) ? parseCourtCaseCsv(courtCaseRaw) : [];
                if (courtCaseRecords.length) {
                    try {
                        localStorage.setItem(courtCaseCacheStorageKey, courtCaseRaw);
                    } catch (_) {}
                } else {
                    const cachedRaw = localStorage.getItem(courtCaseCacheStorageKey) || "";
                    const cachedRecords = isLikelyCsvPayload(cachedRaw) ? parseCourtCaseCsv(cachedRaw) : [];
                    if (cachedRecords.length) {
                        courtCaseRaw = cachedRaw;
                        courtCaseRecords = cachedRecords;
                    }
                }
                courtCaseLines = courtCaseRecords.map((record) => record.rawLine);
                courtCaseRecords.forEach((record) => {
                    const dcName = normalizeLookupValue(record.dcName || "");
                    if (!dcName) return;
                    if (!courtCaseCacheByDc[dcName]) courtCaseCacheByDc[dcName] = [];
                    courtCaseCacheByDc[dcName].push(record);
                });
                return courtCaseRecords.length > 0;
            } catch (e) {
                try {
                    const retryRaw = await loadRemoteText(courtCaseCsvUrl);
                    const retryRecords = isLikelyCsvPayload(retryRaw) ? parseCourtCaseCsv(retryRaw) : [];
                    if (retryRecords.length) {
                        courtCaseRaw = retryRaw;
                        try {
                            localStorage.setItem(courtCaseCacheStorageKey, courtCaseRaw);
                        } catch (_) {}
                        courtCaseCacheByDc = {};
                        courtCaseRecords = retryRecords;
                        courtCaseLines = courtCaseRecords.map((record) => record.rawLine);
                        courtCaseRecords.forEach((record) => {
                            const dcName = normalizeLookupValue(record.dcName || "");
                            if (!dcName) return;
                            if (!courtCaseCacheByDc[dcName]) courtCaseCacheByDc[dcName] = [];
                            courtCaseCacheByDc[dcName].push(record);
                        });
                        return !!courtCaseRaw;
                    }
                } catch (_) {}
                try {
                    const cachedRaw = localStorage.getItem(courtCaseCacheStorageKey) || "";
                    const cachedRecords = isLikelyCsvPayload(cachedRaw) ? parseCourtCaseCsv(cachedRaw) : [];
                    if (!cachedRecords.length) {
                        localStorage.removeItem(courtCaseCacheStorageKey);
                        return false;
                    }
                    courtCaseRaw = cachedRaw;
                    courtCaseCacheByDc = {};
                    courtCaseRecords = cachedRecords;
                    courtCaseLines = courtCaseRecords.map((record) => record.rawLine);
                    courtCaseRecords.forEach((record) => {
                        const dcName = normalizeLookupValue(record.dcName || "");
                        if (!dcName) return;
                        if (!courtCaseCacheByDc[dcName]) courtCaseCacheByDc[dcName] = [];
                        courtCaseCacheByDc[dcName].push(record);
                    });
                    return !!courtCaseRaw;
                } catch (_) {
                    return false;
                }
            }
        }

        async function ensureConsumerDataLoadedFor(dcNames) {
            const list = Array.from(new Set((dcNames || []).map((name) => normalizeDcName(name)).filter(Boolean)));
            await Promise.all(list.map(async (dcName) => {
                if (dcCacheRows[dcName]?.length) return;
                await ensureDcDataLoaded(dcName);
            }));
        }

        // USER REQUEST (2026-09-12): Mobile/Revenue/Freeze ab teeno alag button ki
        // jagah ek hi "Choose Report Type" dropdown se select hote hain - isse
        // DC/Division/Circle sabhi scope me EK JAISA flow rehta hai (koi alag size/
        // style ka button nahi), aur screen me summary content ke liye jyada jagah
        // bachti hai.
        // USER REQUEST (2026-09-12, redesigned 2026-09-13): Report type chunne se
        // PEHLE koi report auto-select/auto-sync NAHI honi chahiye - SIRF jab user
        // khud 3 me se ek tile tap karega tabhi wo report sync hogi. (2026-09-13:
        // laal "Choose Report Type" dropdown ki jagah ab 3 professional tiles hain
        // - updateProgressReportPickerUI() unhe select hote hi ek chhoti "chip" me
        // badal deta hai.)
        const PROGRESS_REPORT_TILE_INFO = {
            MOBILE: { icon: "📱", label: "Updated Mobile No" },
            REVENUE: { icon: "💰", label: "Live-Revenue Report" },
            FREEZE: { icon: "🧊", label: "Freeze-Revenue Report" },
            OMVIG: { icon: "🛡️", label: "O&M/VIG Report" },
            LOK_ADALAT: { icon: "⚖️", label: "Lok Adalat Notice" }
        };

        // Tile-list (koi report select nahi hua) vs chhoti chip (report select ho
        // chuka hai) ke beech toggle karta hai - summaryModule ke current value ke
        // hisaab se. Chip par tap karne se wapas tile-list khulti hai
        // (showProgressReportPicker neeche dekhiye).
        function updateProgressReportPickerUI() {
            const picker = document.getElementById("progress-report-picker");
            const chip = document.getElementById("progress-report-chip");
            const info = PROGRESS_REPORT_TILE_INFO[summaryModule];
            if (info) {
                if (picker) picker.style.display = "none";
                if (chip) {
                    chip.style.display = "flex";
                    const chipIc = document.getElementById("progress-report-chip-ic");
                    const chipLbl = document.getElementById("progress-report-chip-lbl");
                    if (chipIc) chipIc.innerText = info.icon;
                    if (chipLbl) chipLbl.innerText = info.label;
                }
            } else {
                if (picker) picker.style.display = "flex";
                if (chip) chip.style.display = "none";
            }
        }

        // Chip par tap karte hi wapas tile-list khulti hai - bilkul waisa hi jaisa
        // koi report select hone se pehle (placeholder + koi sync nahi) dikhta hai.
        function showProgressReportPicker() {
            setProgressModule("");
        }

        function setProgressModule(module) {
            summaryModule = module || "";
            updateProgressReportPickerUI();
            const lokBtn = document.getElementById("progress-lok-btn");
            if (lokBtn) lokBtn.classList.toggle("active", module === "LOK_ADALAT");
            // Sirf Mobile/Revenue/Lok Adalat ko hi Daily/Monthly date-selection
            // chahiye - Freeze ko nahi (khud fixed date par bana hota hai), aur
            // jab tak kuch select hi nahi hua (placeholder) tab bhi nahi dikhna
            // chahiye.
            const reportTypeBox = document.getElementById("progress-report-type-box");
            const dateWrap = document.getElementById("progress-report-date-wrap");
            const needsDateControls = module === "MOBILE" || module === "REVENUE" || module === "LOK_ADALAT";
            if (reportTypeBox) reportTypeBox.style.display = needsDateControls ? "" : "none";
            if (dateWrap) dateWrap.style.display = needsDateControls ? "" : "none";
            if (!summaryModule) {
                renderProgressReportPlaceholder();
                return;
            }
            if (summaryModule === "FREEZE") {
                // USER REQUEST (2026-09-12): "Revenue Freeze Report" chunte hi
                // seedha NP3 (aur uske filters) khul jaate the, jabki yahan bhi
                // ek DUSRA "Choose Report Type" dropdown (5 report) sirf khaali
                // dikhna chahiye tha - koi bhi sync tabhi ho jab is dropdown se
                // khud koi report chuna jaaye. Isliye category ko khaali reset
                // karke SEEDHA (bina kisi fetch/active-freeze-check ke) chooser
                // render karte hain.
                progressFreezeCategory = "";
                resetFreezeFilterState();
                lastRevenueProgressFreezeResult = null;
                const body = document.getElementById("summary-content");
                if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
                return;
            }
            if (summaryModule === "OMVIG") {
                // USER REQUEST (2026-09-14): pehle yahan ek plain spinner-only
                // message dikhta tha - ab Revenue Live Progress jaisa hi ek-sa
                // animated "%" progress-bar dikhta hai (loadAndRenderOmvigReport
                // khud renderSyncingProgress se yeh UI banata hai), taaki poori
                // app me jahan bhi data sync hota hai wahan ek jaisa hi pattern
                // dikhe.
                loadAndRenderOmvigReport();
                return;
            }
            refreshSummary();
        }

        // Jab tak dropdown se koi report type nahi chuna gaya, summary-content me
        // yeh saaf message dikhta hai - koi bhi sync/fetch is waqt nahi chalti.
        function renderProgressReportPlaceholder() {
            const cont = document.getElementById("summary-content");
            if (cont) cont.innerHTML = `<div style="text-align:center; color:#64748b; font-size:0.75rem; font-weight:800; padding:34px 14px;">Upar diye gaye options me se ek report chunein.</div>`;
        }

        // DC/Division/Circle chunte hi Daily Progress screen khulti hai - yahan
        // wapas khaali "koi report select nahi" state par reset karte hain (koi
        // report yaad nahi rakhi jaati), taaki koi bhi sync tabhi shuru ho jab
        // user khud kisi tile par tap kare.
        function resetProgressReportTypeSelection() {
            summaryModule = "";
            omvigFilterDivision = ""; omvigFilterDc = ""; omvigFilterStatus = "";
            updateProgressReportPickerUI();
            const reportTypeBox = document.getElementById("progress-report-type-box");
            const dateWrap = document.getElementById("progress-report-date-wrap");
            if (reportTypeBox) reportTypeBox.style.display = "none";
            if (dateWrap) dateWrap.style.display = "none";
            // BUG FIX (2026-09-13): Pehle yahan pill (updateProgressReportScopeTitle)
            // update hi nahi hoti thi - DC/Division/Circle Daily Progress khulte hi
            // (report type chunne se PEHLE) pill purani hi (ya default "PROGRESS
            // REPORT") dikhti rehti thi. Ab yahan turant update karte hain, taaki
            // report type select karne se pehle hi "DC/DIVISION/CIRCLE PROGRESS
            // REPORT" saaf dikhe.
            updateProgressReportScopeTitle();
            renderProgressReportPlaceholder();
        }

        function parseSummarySelection(rawValue, mode) {
            const raw = String(rawValue || "").trim();
            if (!raw) return { daily: "", monthly: "", label: "" };

            if (mode === "DAILY") {
                if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
                    const [y, m, d] = raw.split("-");
                    return {
                        daily: `${d}/${m}/${y}`,
                        monthly: `${m}/${y}`,
                        label: `${d}/${m}/${y}`
                    };
                }
                const normalized = normalizeProgressDateValue(raw);
                const parts = normalized.split("/");
                return {
                    daily: normalized,
                    monthly: parts.length === 3 ? `${parts[1]}/${parts[2]}` : "",
                    label: normalized
                };
            }

            if (/^\d{4}-\d{2}$/.test(raw)) {
                const [y, m] = raw.split("-");
                return { daily: "", monthly: `${m}/${y}`, label: `${m}/${y}` };
            }

            const monthNameMatch = raw.match(/^([A-Za-z]+),\s*(\d{4})$/);
            if (monthNameMatch) {
                const months = {
                    january: "01", february: "02", march: "03", april: "04", may: "05", june: "06",
                    july: "07", august: "08", september: "09", october: "10", november: "11", december: "12",
                    jan: "01", feb: "02", mar: "03", apr: "04", jun: "06", jul: "07", aug: "08",
                    sep: "09", oct: "10", nov: "11", dec: "12"
                };
                const month = months[monthNameMatch[1].toLowerCase()] || "";
                const year = monthNameMatch[2];
                return { daily: "", monthly: month ? `${month}/${year}` : "", label: month ? `${month}/${year}` : raw };
            }

            return { daily: "", monthly: "", label: raw };
        }

        function getRevenueProgressFilterValue(dailyValue, monthlyValue) {
            if (summaryMode === "MONTHLY") {
                const [month, year] = String(monthlyValue || "").split("/");
                return year && month ? `${year}-${month}` : "";
            }
            return String(dailyValue || "").replace(/\//g, "-");
        }

        function getRevenueDivisionNameForDc(dcName) {
            const targetDc = normalizeDcName(dcName);
            return Object.keys(divisionConfigs).find((divisionName) => {
                return getDivisionDcNames(divisionName).some((dc) => normalizeDcName(dc) === targetDc);
            }) || "OTHER";
        }

        function isRevenueSummaryRowInScope(row) {
            const rowDc = normalizeDcName(row.dcName || "");
            if (!rowDc) return false;
            if (activeViewLevel === "DC") return rowDc === normalizeDcName(activeDC);
            if (activeViewLevel === "DIVISION") {
                return getDivisionDcNames(activeDiv).some((dc) => normalizeDcName(dc) === rowDc);
            }
            return getAllDcNames().some((dc) => normalizeDcName(dc) === rowDc);
        }

        function addRevenueSummaryCount(group, row) {
            if (row.reportType === "TD") {
                group.tdCount += 1;
                group.tdAmount += getRevenueTdAmount(row);
            } else {
                group.paidCount += 1;
                group.paidAmount += parseRevenuePaidAmount(row.paidAmount);
            }
        }

        function buildProgressRevenueSummaryRows(rows) {
            const groups = {};
            const normalizeHqName = (value) => String(value || "GENERAL").trim().toUpperCase() || "GENERAL";
            const createGroup = (key, name, extra = {}) => {
                if (!groups[key]) {
                    groups[key] = {
                        key,
                        name,
                        paidCount: 0,
                        paidAmount: 0,
                        tdCount: 0,
                        tdAmount: 0,
                        ...extra
                    };
                }
                return groups[key];
            };
            const getRowKey = (row) => {
                const rowDc = normalizeDcName(row.dcName || "");
                if (activeViewLevel === "DC") {
                    const hqName = normalizeHqName(row.hqName);
                    return `HQ||${hqName}`;
                }
                if (activeViewLevel === "DIVISION") return `DC||${rowDc}`;
                return `CIRCLE||${getRevenueDivisionNameForDc(rowDc)}||${rowDc}`;
            };

            if (activeViewLevel === "DC") {
                const hqNames = new Set();
                getConsumerRows(activeDC).forEach((row) => {
                    hqNames.add(getConsumerHqName(row));
                });
                (revenueCollectionRowsByDc[getRevenueCollectionDcKey(activeDC)] || []).forEach((row) => {
                    hqNames.add(normalizeHqName(row.hqName || row["HQ NAME"] || row.HQ || row.hq));
                });
                (rows || []).forEach((row) => {
                    if (normalizeDcName(row.dcName || "") === normalizeDcName(activeDC)) {
                        hqNames.add(normalizeHqName(row.hqName));
                    }
                });
                if (!hqNames.size) hqNames.add("GENERAL");
                Array.from(hqNames).sort().forEach((hqName) => createGroup(`HQ||${hqName}`, hqName));
            } else if (activeViewLevel === "DIVISION") {
                getDivisionDcNames(activeDiv).forEach((dcName) => {
                    const normalizedDc = normalizeDcName(dcName);
                    createGroup(`DC||${normalizedDc}`, normalizedDc);
                });
            } else {
                Object.keys(divisionConfigs).forEach((divisionName) => {
                    getDivisionDcNames(divisionName).forEach((dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        createGroup(`CIRCLE||${divisionName}||${normalizedDc}`, normalizedDc, { divisionName });
                    });
                });
            }

            (rows || []).filter(isRevenueSummaryRowInScope).forEach((row) => {
                const key = getRowKey(row);
                const group = createGroup(key, activeViewLevel === "DC"
                    ? normalizeHqName(row.hqName)
                    : normalizeDcName(row.dcName || "-") || "-", {
                        divisionName: activeViewLevel === "CIRCLE" ? getRevenueDivisionNameForDc(row.dcName || "-") : ""
                    });
                addRevenueSummaryCount(group, row);
            });

            if (activeViewLevel === "DIVISION") {
                const orderedRows = [];
                getDivisionSubDnGroups(activeDiv).forEach((group) => {
                    const groupRows = group.dcs.map((dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        return groups[`DC||${normalizedDc}`] || createGroup(`DC||${normalizedDc}`, normalizedDc);
                    });
                    orderedRows.push(...groupRows);
                    orderedRows.push(sumRevenueProgressGroups(groupRows, `${group.subDn} SUB DIVISION SUB TOTAL`, { type: "SUBDN_TOTAL" }));
                });
                return orderedRows;
            }

            if (activeViewLevel === "CIRCLE") {
                const orderedRows = [];
                Object.keys(divisionConfigs).forEach((divisionName) => {
                    const divisionRows = [];
                    getDivisionSubDnGroups(divisionName).forEach((group) => {
                        const groupRows = group.dcs.map((dcName) => {
                            const normalizedDc = normalizeDcName(dcName);
                            return groups[`CIRCLE||${divisionName}||${normalizedDc}`] || createGroup(`CIRCLE||${divisionName}||${normalizedDc}`, normalizedDc, { divisionName });
                        });
                        divisionRows.push(...groupRows);
                        orderedRows.push(...groupRows);
                        orderedRows.push(sumRevenueProgressGroups(groupRows, `${group.subDn} SUB DIVISION SUB TOTAL`, { type: "SUBDN_TOTAL", divisionName }));
                    });
                    orderedRows.push(sumRevenueProgressGroups(divisionRows, getDivisionTotalLabel(divisionName), { type: "SUB_TOTAL", divisionName }));
                });
                return orderedRows;
            }

            return Object.values(groups).sort((a, b) => String(a.name).localeCompare(String(b.name)));
        }

        function getDivisionTotalLabel(divisionName) {
            const shortName = String(divisionName || "").replace(/^DIVISION\s+/i, "").trim();
            return `${shortName} DIVISION TOTAL`;
        }

        function sumRevenueProgressGroups(list, name, extra = {}) {
            return {
                name,
                paidCount: (list || []).reduce((sum, row) => sum + Number(row.paidCount || 0), 0),
                paidAmount: (list || []).reduce((sum, row) => sum + Number(row.paidAmount || 0), 0),
                tdCount: (list || []).reduce((sum, row) => sum + Number(row.tdCount || 0), 0),
                tdAmount: (list || []).reduce((sum, row) => sum + Number(row.tdAmount || 0), 0),
                ...extra
            };
        }

        function getRevenueProgressColumnLabel() {
            if (activeViewLevel === "DC") return revenueHqLabelUpper();
            if (activeViewLevel === "DIVISION") return "DC NAME";
            return "DC NAME";
        }

        function getRevenueProgressTotals(rows) {
            return (rows || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").reduce((totals, row) => {
                totals.paidCount += Number(row.paidCount || 0);
                totals.paidAmount += Number(row.paidAmount || 0);
                totals.tdCount += Number(row.tdCount || 0);
                totals.tdAmount += Number(row.tdAmount || 0);
                return totals;
            }, { paidCount: 0, paidAmount: 0, tdCount: 0, tdAmount: 0 });
        }

        function formatProgressReportAmount(value) {
            const amount = Number(value || 0);
            // Point/paise nahi dikhane - amount Rs me poori tarah round off hoke dikhega.
            // Extra safety: agar kabhi koi garbage/asambhav bada number yahan tak pahunch
            // jaaye to bhi 0 dikhayenge, warna JS bade number ko khud "9.88e+22" jaisi
            // scientific notation me convert kar deta hai.
            // BUG FIX (2026-08-11): pehle yeh limit 1 crore (1e7) thi - iski wajah se
            // Target vs Achievement jaisi reports me DIVISION/CIRCLE scope ke TOTAL/summary
            // row (jo kai HQ/DC ke Net Bill Target ko jod kar bana hai, aasani se 1 crore se
            // upar chala jaata hai) ghalti se "0" dikha deta tha - jabki neeche wali
            // individual HQ/DC rows sahi dikhti thi (kyunki wo akele 1 crore se kam thi).
            // Ab limit 1 lakh crore (1e12) kar di hai taaki genuine circle-level totals
            // (jo kai crore tak jaa sakte hain) na katein, sirf sach me garbage/corrupt
            // (asambhav bada) number hi 0 dikhega.
            if (!Number.isFinite(amount) || Math.abs(amount) > 1e12) return "0";
            return String(Math.round(amount));
        }

        const revenueCategoryList = ["LV1", "LV2", "LV3", "LV4", "LV5"];
        const revenueCategoryDisplayLabels = {
            "LV1": "DOMESTIC",
            "LV2": "NON DOMESTIC",
            "LV3": "PUBLIC WATER WORKS AND STREET LIGHTS",
            "LV4": "LT INDUSTRIAL",
            "LV5": "AGRICULTURE AND ALLIED ACTIVITIES"
        };
        function getRevenueCategoryDisplayLabel(category) {
            return revenueCategoryDisplayLabels[category] || category;
        }

        function normalizeRevenueCategory(value) {
            const raw = normalizeLookupValue(value || "");
            const match = raw.match(/LV\s*([1-5])/);
            return match ? `LV${match[1]}` : raw;
        }

        function formatRevenueLakhValue(value) {
            const amount = parseRevenuePaidAmount(value);
            return (amount / 100000).toFixed(2);
        }

        function getRevenueCategoryTargetDcs() {
            if (activeViewLevel === "DC") return [activeDC].filter(Boolean);
            if (activeViewLevel === "DIVISION") return getDivisionDcNames(activeDiv);
            return getAllDcNames();
        }

        function getRevenueMasterRowsForDc(dcName) {
            const normalizedDc = normalizeDcName(dcName);
            const dcKey = getRevenueCollectionDcKey(dcName);
            const revenueRows = (revenueCollectionRowsByDc[dcKey] || [])
                .filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                .map((row) => ({ ...row, dcName: normalizedDc }));
            const consumerRows = getConsumerRows(dcName)
                .map(mapRevenueConsumerRow)
                .filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                .map((row) => ({ ...row, dcName: normalizedDc }));

            // Revenue reconciliation reports ka authoritative Master wahi fresh
            // Revenue CSV hai jo strict loader ne load kiya. Iske saath Mobile/
            // consumer cache merge karne par report ka total navigation-history
            // par nirbhar ho raha tha (CHHAPARA-2 me 49 extra consumers). Revenue
            // rows available hon to unhi ko use karo; consumerRows sirf legacy/
            // offline fallback hain jab Revenue Master bilkul available na ho.
            const sourceRows = revenueRows.length ? revenueRows : consumerRows;
            const mergedByIvrs = new Map();
            sourceRows.forEach((row) => {
                const ivrs = normalizeRevenueIvrs(row.ivrsNo);
                if (!ivrs) return;
                const existing = mergedByIvrs.get(ivrs) || {};
                const merged = { ...existing };
                Object.keys(row || {}).forEach((key) => {
                    const value = row[key];
                    if (value !== null && value !== undefined && String(value).trim() !== "") merged[key] = value;
                });
                merged.ivrsNo = ivrs;
                merged.dcName = normalizedDc;
                mergedByIvrs.set(ivrs, merged);
            });
            return Array.from(mergedByIvrs.values());
        }

        async function ensureRevenueCategoryMasterDataLoaded(dcNames) {
            const list = Array.from(new Set((dcNames || []).map((name) => normalizeDcName(name)).filter(Boolean)));
            await Promise.all(list.map(async (dcName) => {
                try {
                    await loadRevenueCollectionData(dcName);
                } catch (_) {}
                if (!getConsumerRows(dcName).length) {
                    try {
                        await ensureConsumerDataLoadedFor([dcName]);
                    } catch (_) {}
                }
            }));
        }

        // ISOLATED ADDITION (2026-09-17, USER-REPORTED): ensureRevenueCategoryMaster-
        // DataLoaded() ke andar dono try/catch khaali hain - kisi DC ka Master
        // consumer data load fail hone par bhi silently aage badh jaata hai, aur
        // Category Wise/HQ-Village/Target-Achievement/Top-Defaulters report us DC
        // ke bina hi (bina kisi error ke) ban jaati hai. Us shared function ko
        // KHUD nahi chheda - Freeze Revenue module bhi usi function ko use karta
        // hai aur wo module bilkul untouched rehna chahiye. Iski jagah yeh ek
        // chhota wrapper hai jo poora attempt hone ke baad bhi jin DC ka Master
        // consumer data khaali reh gaya, unhe saaf error ke roop me upar bhejta
        // hai - sirf un call-site par jo Revenue Category reconciliation reports
        // (Category Wise, HQ/Village Wise, Target vs Achievement, Top Defaulters)
        // use karte hain.
        const revenueCategoryMasterFreshAt_ = new Map();
        const revenueCategoryMasterFreshInFlight_ = new Map();
        const REVENUE_CATEGORY_MASTER_FRESH_TTL_MS = 60000;

        async function ensureRevenueCategoryMasterDataLoadedStrict_(dcNames) {
            const list = Array.from(new Set((dcNames || []).map((name) => normalizeDcName(name)).filter(Boolean)));
            const now = Date.now();
            const results = await Promise.all(list.map(async (dcName) => {
                const lastFreshAt = Number(revenueCategoryMasterFreshAt_.get(dcName) || 0);
                if (now - lastFreshAt < REVENUE_CATEGORY_MASTER_FRESH_TTL_MS && getRevenueMasterRowsForDc(dcName).length) {
                    return { dcName, ok: true };
                }
                let pending = revenueCategoryMasterFreshInFlight_.get(dcName);
                if (!pending) {
                    pending = (async () => {
                        const rows = await loadRevenueCollectionData(dcName, true, { requireRemote: true });
                        if (Array.isArray(rows) && rows.length) revenueCategoryMasterFreshAt_.set(dcName, Date.now());
                        return rows;
                    })();
                    revenueCategoryMasterFreshInFlight_.set(dcName, pending);
                }
                try {
                    const rows = await pending;
                    return { dcName, ok: Array.isArray(rows) && rows.length > 0 };
                } finally {
                    if (revenueCategoryMasterFreshInFlight_.get(dcName) === pending) {
                        revenueCategoryMasterFreshInFlight_.delete(dcName);
                    }
                }
            }));
            const failedDcs = results.filter((result) => !result.ok).map((result) => result.dcName);
            if (failedDcs.length) {
                const error = new Error(`Fresh Master consumer data load nahi ho paya in DC ke liye: ${failedDcs.join(", ")}. Purana cached data use karke report nahi banayi gayi.`);
                error.failedDcs = failedDcs;
                throw error;
            }
        }

        function createRevenueCategoryGroup(name, extra = {}) {
            const group = { name, paidTotal: 0, unpaidTotal: 0, paidAmountTotal: 0, unpaidAmountTotal: 0, categories: {}, ...extra };
            revenueCategoryList.forEach((category) => {
                group.categories[category] = { paid: 0, unpaid: 0, paidAmount: 0, unpaidAmount: 0 };
            });
            return group;
        }

        // USER REQUEST (2026-08-13): Partial payment ko sahi se handle karna hai -
        // pehle jaise hi consumer cash list me match ho jaata tha, uska POORA net
        // bill "paid" maan liya jaata tha (chahe cash list me poora amount aaya ho
        // ya sirf partial). Ab agar match hone ke baad bhi net bill se kam paid
        // hua hai, to bacha hua (net bill - paid, sirf positive) turant unpaid/
        // pending bucket me bhi jud jaata hai - taaki wahi consumer "PAID" (jitna
        // paid hua) aur "PENDING" (jitna bacha hai) dono jagah sahi se dikhe. Agar
        // paid amount net bill ke barabar ya usse zyada hai, to pending 0/negative
        // ignore ho jaata hai (consumer poori tarah clear maana jaata hai).
        function addRevenueCategoryConsumer(group, row, paidInfoByIvrs, paidCountedIvrsSet = null) {
            const category = normalizeRevenueCategory(row.tariffCategory || row.category || "");
            const ivrs = normalizeRevenueIvrs(row.ivrsNo);
            const paidInfo = paidInfoByIvrs?.[ivrs];
            const dueAmount = parseRevenuePaidAmount(row.netBill || row.arrears || 0);
            // ISOLATED ADDITION (2026-09-17, USER-APPROVED corrections): yeh counter
            // "Unique Master Consumer" ki asli ginti rakhta hai - is function ko
            // exactly ek baar har unique (DC+IVRS) Master consumer ke liye call kiya
            // jaata hai (getRevenueMasterRowsForDc pehle se IVRS ke hisaab se dedupe
            // karta hai), isliye yeh count hamesha sahi rehta hai chahe consumer
            // aage PAID/UNPAID/OTHER kisi bhi bucket me jaaye ya (legacy path me)
            // category match na hone par bilkul drop ho jaaye. Download flow me
            // (downloadProgressRevenueCategorySummary) ise Paid+Unpaid totals ke
            // against check karke "invariant mismatch" pakda jaata hai - taaki
            // koi bhi galti silently report me na chhup jaaye.
            group.__uniqueMasterCount = (group.__uniqueMasterCount || 0) + 1;
            // ISOLATED ADDITION (2026-09-17, USER-APPROVED corrections): naya
            // backend reconciliation endpoint (getRevenueCategoryReconciliation)
            // se mila EXACT-DATE-capable, per-consumer (DC+IVRS) aggregate mile to
            // usi ke corrected business rules follow karo:
            //   (a) consumer PAID count hamesha max 1 - chahe us consumer ki
            //       kitni bhi payment rows selected period me match hui hon;
            //   (b) ek baar bhi valid payment milne par (partial ho ya poora)
            //       consumer SIRF PAID bucket me jaata hai, UNPAID me kabhi nahi
            //       (jo neeche legacy path me "remainingAfterPaid > 0" wala bug
            //       tha, usse yeh naya branch bilkul prabhavit nahi);
            //   (c) missing/unknown tariff category wale valid Master consumer
            //       "OTHER" bucket me jaate hain - grand total (group.paidTotal/
            //       unpaidTotal, jo invariant-check aur TOTAL column dono use
            //       karte hain) se kabhi drop nahi hote. Existing LV1-LV5
            //       per-category column layout (revenueCategoryList) bilkul
            //       unchanged rehta hai - OTHER us list me kabhi nahi jodi gayi,
            //       isliye PDF/Excel me koi naya column nahi aata.
            // Yeh naya branch legacy code (neeche, bilkul unchanged) ko bilkul
            // nahi chhedta - legacy sirf tab chalta hai jab reconciliation
            // backend available na ho (purana/redeploy-na-hua backend - capability
            // mismatch fallback).
            // Reconciliation response me sirf matched/paid IVRS entries aati hain.
            // Scope marker true ho aur current IVRS response-map me na ho, to woh
            // authoritative UNPAID hai; use legacy cache path par bhejne se purani
            // multi-row payment entries count ko dobara badha deti thi.
            if (paidInfo?.reconciled || paidInfoByIvrs?.__reconciledScope === true) {
                const bucketCategory = revenueCategoryList.includes(category) ? category : "OTHER";
                if (!group.categories[bucketCategory]) group.categories[bucketCategory] = { paid: 0, unpaid: 0, paidAmount: 0, unpaidAmount: 0 };
                const amount = Number(paidInfo?.amount || 0);
                if (amount > 0) {
                    group.categories[bucketCategory].paid += 1;
                    group.categories[bucketCategory].paidAmount += amount;
                    group.paidTotal += 1;
                    group.paidAmountTotal += amount;
                } else {
                    group.categories[bucketCategory].unpaid += 1;
                    group.categories[bucketCategory].unpaidAmount += dueAmount;
                    group.unpaidTotal += 1;
                    group.unpaidAmountTotal += dueAmount;
                }
                return;
            }
            if (!revenueCategoryList.includes(category)) return;
            const paidCountKey = `${normalizeRevenueUploadedPaidInfoSourceSignature(paidInfo)}|${ivrs}`;
            if (paidInfo && paidCountedIvrsSet?.has(paidCountKey)) return;
            const sourceCategoryPaidInfos = getRevenueCategoryPaidInfosBySourceCategory(paidInfo);
            if (sourceCategoryPaidInfos.length) {
                let paidThisConsumer = 0;
                sourceCategoryPaidInfos.forEach((item) => {
                    group.categories[item.category].paid += item.count;
                    group.categories[item.category].paidAmount += item.amount;
                    group.paidTotal += item.count;
                    group.paidAmountTotal += item.amount;
                    paidThisConsumer += Number(item.amount || 0);
                });
                paidCountedIvrsSet?.add(paidCountKey);
                const remainingAfterPaid = dueAmount - paidThisConsumer;
                if (remainingAfterPaid > 0) {
                    group.categories[category].unpaid += 1;
                    group.categories[category].unpaidAmount += remainingAfterPaid;
                    group.unpaidTotal += 1;
                    group.unpaidAmountTotal += remainingAfterPaid;
                }
                return;
            }

            const legacyPaidInfo = getRevenueCategoryPaidInfoForCategory(paidInfo, category);
            if (legacyPaidInfo) {
                const paidAmount = parseRevenuePaidAmount(legacyPaidInfo.amount || 0) || dueAmount;
                const paidCount = Math.max(1, Number(legacyPaidInfo.count || legacyPaidInfo.payment_count || legacyPaidInfo.paymentCount || 1));
                group.categories[category].paid += paidCount;
                group.categories[category].paidAmount += paidAmount;
                group.paidTotal += paidCount;
                group.paidAmountTotal += paidAmount;
                paidCountedIvrsSet?.add(paidCountKey);
                const remainingAfterPaid = dueAmount - paidAmount;
                if (remainingAfterPaid > 0) {
                    group.categories[category].unpaid += 1;
                    group.categories[category].unpaidAmount += remainingAfterPaid;
                    group.unpaidTotal += 1;
                    group.unpaidAmountTotal += remainingAfterPaid;
                }
                return;
            }

            group.categories[category].unpaid += 1;
            group.categories[category].unpaidAmount += dueAmount;
            group.unpaidTotal += 1;
            group.unpaidAmountTotal += dueAmount;
        }

        function getRevenueCategoryPaidInfosBySourceCategory(paidInfo) {
            if (!paidInfo?.categoryTotals) return [];
            return revenueCategoryList.map((category) => {
                const entry = paidInfo.categoryTotals[category] || {};
                const amount = Number(entry.amount || 0);
                const count = Number(entry.count || 0);
                return count > 0 ? { category, amount, count } : null;
            }).filter(Boolean);
        }

        function normalizeRevenueUploadedPaidInfoSourceSignature(paidInfo) {
            if (!paidInfo) return "";
            return [
                paidInfo.normalCount || 0,
                paidInfo.normalAmount || 0,
                paidInfo.agCount || 0,
                paidInfo.agAmount || 0,
                paidInfo.mixedCount || 0,
                paidInfo.mixedAmount || 0,
                paidInfo.unknownCount || 0,
                paidInfo.unknownAmount || 0
            ].join(":");
        }

        function getRevenueCategoryPaidInfoForCategory(paidInfo, category) {
            if (!paidInfo) return null;
            const isLv5 = category === "LV5";
            const amount = isLv5 ? Number(paidInfo.agAmount || 0) : Number(paidInfo.normalAmount || 0);
            const count = isLv5 ? Number(paidInfo.agCount || 0) : Number(paidInfo.normalCount || 0);
            return count > 0 ? { amount, count } : null;
        }

        function normalizeRevenueMonthFilterKey(value) {
            const raw = String(value || "").trim();
            let match = raw.match(/^(\d{4})[-/](\d{1,2})$/);
            if (match) return `${match[1]}-${match[2].padStart(2, "0")}`;
            match = raw.match(/^(\d{1,2})[-/](\d{4})$/);
            if (match) return `${match[2]}-${match[1].padStart(2, "0")}`;
            return getRevenueMonthKey(raw);
        }

        // UPDATED LOGIC (user request, 2026-08-13): pehle yahan row ki apni
        // "payment date" (file ke andar ka date column) se match hota tha -
        // pehle EXACT month/date match, phir cumulative "<=" match (pichhle
        // sabhi mahino ka bhi paid count ho). Lekin user ka business rule
        // clear hai: office me billing cycle 20 tareekh ke baad agle mahine
        // ka maana jaata hai (naye bill generate ho jaate hain), isliye jab
        // NORMAL (LV1-LV4) ya AG (LV5) cash list kisi mahine (jaise AUG) me
        // upload hoti hai, to us poori file ke sabhi consumer USI mahine
        // (AUG) me hi "paid" maane jaane chahiye - chahe file ke andar kisi
        // row ki payment date pichhle mahine (JULY) ki kyun na ho. Pichhle
        // mahine (JULY) ka report select karne par ab yeh consumer paid nahi
        // dikhenge (0/pending), kyunki wo payment already current upload-
        // mahine (AUG) me count ho chuka hai.
        //
        // Isliye match ab row ki "payment date" se nahi, balki "uploaded_date"
        // (cash list FILE kis mahine upload hui - backend PAID MASTER sheet
        // ke UPLOADED DATE column se aata hai) ke EXACT mahine se hota hai -
        // na cumulative (<=), na future bhi count. Yeh sirf paid-status
        // MATCHING ko badalta hai; NORMAL file abhi bhi sirf LV1-LV4 aur AG
        // file abhi bhi sirf LV5 count karti hai (wo alag
        // getRevenueUploadedPaidRowCategory() me handle hota hai, yahan nahi
        // chheda). Pending DO List apni alag paidSet logic use karta hai (date
        // se bilkul independent, wahan pehle se hi koi restriction nahi thi) -
        // isliye is change se wahan koi asar nahi padta.
        function isRevenueUploadedPaidInCategoryPeriod(row, mode, filterValue) {
            if (mode === "MONTHLY") {
                const uploadedRaw = getRevenueUploadedPaidRowUploadedDate(row);
                if (!uploadedRaw) return false;
                const uploadedMonthKey = getRevenueMonthKey(uploadedRaw);
                if (!uploadedMonthKey) return false;
                const targetMonthKey = normalizeRevenueMonthFilterKey(filterValue);
                if (!targetMonthKey) return false;
                return uploadedMonthKey === targetMonthKey;
            }
            // ISOLATED FIX (2026-09-17, USER-CONFIRMED bug): pehle DAILY (non-
            // MONTHLY) mode bhi sirf "uploaded MAHINA" match karta tha - EXACT
            // selected DATE kabhi check hi nahi hoti thi, isliye ek din select
            // karne par bhi poore mahine ke uploads paid dikh jaate the. Ab yeh
            // row ki apni ACTUAL payment date (getRevenueUploadedPaidRowDate,
            // jisme paymentDate/payment_date/paymentDateRaw jaise saare alias
            // fields pehle se handle hain) ko selected EXACT date se compare
            // karta hai. MONTHLY mode ka upar wala 2026-08-13 uploaded-month
            // business rule bilkul unchanged hai - sirf yeh niche wali DAILY
            // branch badli hai. (Naye backend reconciliation endpoint ke
            // available hone par is function ka DAILY result ab authoritative
            // paid/unpaid decision me use hi nahi hota - sirf legacy/purane-
            // backend fallback aur diagnostic stats ke liye reh gaya hai, par
            // ab wahan bhi sahi jawab deta hai.)
            const targetDate = normalizeRevenueReportDate(filterValue || getCurrentDateDDMMYYYY());
            if (!targetDate) return false;
            const rowPaymentDateRaw = getRevenueUploadedPaidRowDate(row);
            if (!rowPaymentDateRaw) return false;
            return normalizeRevenueReportDate(rowPaymentDateRaw) === targetDate;
        }

        // DD-MM-YYYY ko YYYY-MM-DD me convert karta hai taaki string "<=" se
        // chronological (calendar-wise) comparison sahi ho - DD-MM-YYYY ko
        // seedhe compare karne se date order galat aata hai.
        function revenueDateSortKey_(ddmmyyyy) {
            const m = String(ddmmyyyy || "").match(/^(\d{2})-(\d{2})-(\d{4})$/);
            if (!m) return "";
            return `${m[3]}-${m[2]}-${m[1]}`;
        }

        function getRevenueUploadedPaidRowDcName(row, fallbackDc = "") {
            return normalizeDcName(row?.dcName || row?.dc_name || row?.dc || row?.["DC Name"] || fallbackDc || "");
        }

        function getRevenueUploadedPaidRowIvrs(row) {
            return normalizeRevenueIvrs(row?.ivrsNo || row?.ivrs_no || row?.consumerNo || row?.consumer_no || row?.consumerNumber || row?.["IVRS NO"] || row?.["Consumer No"]);
        }

        function getRevenueUploadedPaidRowAmount(row) {
            return parseRevenuePaidAmount(row?.amountPaid || row?.amount_paid || row?.totalAmount || row?.amount || row?.paidAmount || row?.paymentAmount || row?.["AMOUNT PAID"] || row?.["Payment Amount"] || 0);
        }

        function getRevenueUploadedPaidRowCategory(row, sourceType = "") {
            const paidFileType = normalizeLookupValue(sourceType || row?.sourceType || row?.source_type || "");
            if (paidFileType.includes("AG")) return "LV5";
            return normalizeRevenueCategory(row?.tariffCategory || row?.tariff_category || row?.category || row?.["Tariff Category"] || row?.["TARIFF CATEGORY"] || row?.["Category"] || "");
        }

        // Cash list FILE "kis mahine upload hui" - backend PAID MASTER sheet ke
        // "UPLOADED DATE" column se aata hai (ya local upload-time stamp se, agar
        // abhi backend sync nahi hua). Isi field ke aadhar par paid-status ka
        // mahina decide hota hai, row ki apni "payment date" ke aadhar par nahi.
        function getRevenueUploadedPaidRowUploadedDate(row) {
            return row?.uploaded_date ||
                row?.uploadedDate ||
                row?.["UPLOADED DATE"] ||
                row?.uploadDate ||
                "";
        }

        function getRevenueUploadedPaidRowDate(row) {
            return row?.paymentDateRaw ||
                row?.payment_date_raw ||
                row?.["Payment Date Raw"] ||
                row?.paymentDate ||
                row?.payment_date ||
                row?.paidDate ||
                row?.paid_date ||
                row?.collectionDate ||
                row?.collection_date ||
                row?.["Payment Date"] ||
                row?.["PAYMENT DATE"] ||
                row?.["Paid Date"] ||
                row?.["PAID DATE"] ||
                row?.["Collection Date"] ||
                row?.["COLLECTION DATE"] ||
                row?.latestDate ||
                row?.date ||
                row?.["DATE"] ||
                "";
        }

        function getRevenueUploadedPaidPaymentRows(row) {
            let rows = row?.paymentRows || row?.payment_rows || row?.payments || row?.paymentDetails || [];
            if (typeof rows === "string") {
                try {
                    rows = JSON.parse(rows);
                } catch (_) {
                    rows = [];
                }
            }
            if (Array.isArray(rows) && rows.length) {
                const fallbackDc = getRevenueUploadedPaidRowDcName(row);
                const fallbackIvrs = getRevenueUploadedPaidRowIvrs(row);
                return rows.map((payment) => ({
                    ...payment,
                    dcName: getRevenueUploadedPaidRowDcName(payment, fallbackDc),
                    ivrsNo: getRevenueUploadedPaidRowIvrs(payment) || fallbackIvrs,
                    sourceType: payment?.sourceType || payment?.source_type || row?.sourceType || row?.source_type || "",
                    paymentDate: payment?.paymentDate || payment?.payment_date || payment?.paidDate || row?.paymentDate || row?.payment_date || "",
                    paymentDateRaw: payment?.paymentDateRaw || payment?.payment_date_raw || payment?.["Payment Date Raw"] || getRevenueUploadedPaidRowDate(payment) || getRevenueUploadedPaidRowDate(row),
                    // Nested payment_rows JSON (jo cash-list-file-level detail hai) ke paas
                    // apna "kis mahine file upload hui" wala field nahi hota - wo sirf
                    // outer (IVRS-level aggregate) row par hota hai. Isliye yahan outer row
                    // se propagate karte hain, taaki isRevenueUploadedPaidInCategoryPeriod()
                    // ka upload-month match har jagah sahi kaam kare.
                    uploaded_date: payment?.uploaded_date || payment?.uploadedDate || getRevenueUploadedPaidRowUploadedDate(row)
                }));
            }
            return [row];
        }

        async function fetchUploadedPaidEntriesWithRetry_(dcName, attempts = 2) {
            // NOTE: Kuch DC (jaise SEONI (T) - 33,000+ paid records) ka uploaded-paid
            // data itna bada hai ki Apps Script se poora JSON (payment_rows sahit)
            // padhne/bhejne me 45 second se zyada time lag sakta hai - pehle 45s
            // timeout par yeh fetch fail ho jaata tha aur paid-set khaali reh jaata
            // tha, jisse Pending DO List me saare paid consumer bhi galti se
            // "pending" dikhte the. Ab bade DC ke liye bhi safely poora data aane
            // deta hai (90s per attempt).
            for (let attempt = 1; attempt <= attempts; attempt++) {
                const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
                const timer = setTimeout(() => { try { if (controller) controller.abort(); } catch (_) {} }, 90000);
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getUploadedPaidEntries&dc_name=${encodeURIComponent(dcName)}&t=${Date.now()}`, controller ? { signal: controller.signal } : {});
                        return await response.json();
                    });
                    if (parsed && parsed.status === "success") return parsed;
                } catch (_) {} finally {
                    clearTimeout(timer);
                }
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
            }
            return null;
        }

        // Pending DO List / Cash Reconcile / Freshness ticker - inteeno ko sirf itna
        // hi chahiye "kaun paid hai" (dc_name + ivrs_no) aur "kab upload hua"
        // (uploaded_date) - inhe poori payment_rows/amount/source detail nahi
        // chahiye. Purana getUploadedPaidEntries action bahut bhaari response
        // deta tha (har row ka poora payment_rows JSON dobara), jo bade DC
        // (SEONI (T) - 33,000+ rows) ke liye slow network par timeout kar jaata
        // tha. Yeh naya "getUploadedPaidIvrsList" action halka/chhota response
        // deta hai (backend script me add karna hoga), isliye fast aur reliable
        // hai. Agar backend abhi purana hi hai (naya action nahi mila), to
        // fetchUploadedPaidEntriesWithRetry_ (purana, poora data) par fallback
        // ho jaata hai - koi cheez toot nahi ti.
        async function fetchUploadedPaidIvrsListWithRetry_(dcName, attempts = 3) {
            for (let attempt = 1; attempt <= attempts; attempt++) {
                const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
                // BUG FIX (user report): SEONI (T) jaisi bade DC (34,000+ consumer) me
                // pehle sirf 60 second ka per-attempt timeout tha - itne bade sheet ko
                // Apps Script se slow/mobile network par padhne-bhejne me isse zyada
                // time lag sakta hai, isliye yeh call beech me hi cut ho jaata tha aur
                // adhura/khali local fallback data use hota tha (isi wajah se Pending
                // count bahut zyada galat aata tha). Ab 150 second (2.5 minute) diya hai
                // taaki bade DC ko poora sync hone ka pura mauka mile, chahe thoda time
                // lage.
                const timer = setTimeout(() => { try { if (controller) controller.abort(); } catch (_) {} }, 150000);
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getUploadedPaidIvrsList&dc_name=${encodeURIComponent(dcName)}&t=${Date.now()}`, controller ? { signal: controller.signal } : {});
                        return await response.json();
                    });
                    if (parsed && parsed.status === "success" && Array.isArray(parsed.entries)) return parsed;
                } catch (_) {} finally {
                    clearTimeout(timer);
                }
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
            }
            // Backend abhi purane version par hai (naya lightweight action available
            // nahi) - purane bhaari endpoint par fallback taaki feature kaam karta rahe.
            return fetchUploadedPaidEntriesWithRetry_(dcName, attempts);
        }

        // =====================================================================
        // Revenue Freeze Tracking (2026-09-12)
        // =====================================================================
        // Admin ke "🧊 Freeze Now (All DC)" button se chalta hai - ALL 24 DC ka
        // Non-Payee 3M/6M/Since Connection aur Top 20/50 Defaulters data ek
        // sath (CIRCLE scope par) build karke, backend (freeze-tracking-submit-
        // script.gs, apni alag Sheet) me snapshot save kar deta hai. Existing
        // buildRevenueNonPayeeRows()/buildRevenueHqVillageConsumerRows() (jo
        // normal live reports bhi use karte hain) yahan REUSE hoti hain - taaki
        // freeze ka data bilkul wahi ho jo us waqt normal report dikha rahi
        // thi. activeViewLevel/activeDC/activeDiv ko sirf computation ke liye
        // temporarily "CIRCLE" kiya jaata hai, phir turant wapas restore ho
        // jaata hai - user jis bhi screen par ho (Admin panel), wahi bana rahega.
        // USER REQUEST (2026-09-13): "Freeze Now" beech me ruk jaaye (koi category
        // par 2 attempt ke bad bhi fail, tab band/network chali gayi, wagerah) to
        // pehle poora 24-DC/9-category process (10-15+ minute) dobara se shuru
        // karna padta tha. Ab is browser me ab tak kitni category safal hui, iska
        // record localStorage me rakhte hain - taaki (a) dobara "Freeze Now" dabane
        // par pehle se safal categories SKIP ho jaayein, sirf baaki bachi hui se
        // aage badhe, aur (b) app/tab band karke dobara khole to Admin Freeze
        // Control screen khulte hi "pichhli baar kitna % hua tha" turant dikh jaaye.
        // NOTE: yeh backend me apne-aap chalne wala background job NAHI hai (Apps
        // Script Web App ko is browser tab se hi request bhejni padti hai) - lekin
        // dobara click karna ab bahut halka/fast ho jaata hai kyonki sirf bachi hui
        // categories dobara save hoti hain, poora process nahi.
        const FREEZE_NOW_PROGRESS_KEY = "seoniFreezeNowProgress_v1";
        function readFreezeNowProgress() {
            try {
                const raw = localStorage.getItem(FREEZE_NOW_PROGRESS_KEY);
                return raw ? JSON.parse(raw) : null;
            } catch (_) { return null; }
        }
        function writeFreezeNowProgress(progress) {
            try { localStorage.setItem(FREEZE_NOW_PROGRESS_KEY, JSON.stringify(progress)); } catch (_) {}
        }
        function clearFreezeNowProgress() {
            try { localStorage.removeItem(FREEZE_NOW_PROGRESS_KEY); } catch (_) {}
        }

        async function runRevenueFreezeNow() {
            if (!revenueFreezeTrackingScriptUrl || revenueFreezeTrackingScriptUrl.indexOf("PASTE_") === 0) {
                return showToast("Freeze script URL abhi set nahi hai", false);
            }
            const statusBox = document.getElementById("freeze-admin-status");
            const setStatus = (text, ok) => {
                if (!statusBox) return;
                statusBox.style.display = "block";
                statusBox.style.background = ok ? "#ecfdf5" : "#eff6ff";
                statusBox.style.color = ok ? "#047857" : "#1d4ed8";
                statusBox.innerText = text;
            };
            setStatus("SYNCING DATA... PLEASE WAIT", false);
            const savedViewLevel = activeViewLevel, savedDC = activeDC, savedDiv = activeDiv;
            try {
                const allDcs = getAllDcNames();
                activeViewLevel = "CIRCLE"; activeDC = ""; activeDiv = "";
                // NOTE (2026-09-12): Live "Top 20/50 Defaulters" screen inhi teeno ko
                // saath me warm karta hai (ensureRevenueCategoryRawPaymentRowsLoaded
                // pehle yahan miss thi) - taaki Freeze Now ke Top20/Top50 bhi bilkul
                // wahi paid/pending data dekhein jo live report dikhati hai.
                await Promise.all([
                    ensureRevenueCategoryMasterDataLoaded(allDcs),
                    ensureRevenueCategoryRawPaymentRowsLoaded(),
                    warmRevenueCategoryUploadedPaidCache(true)
                ]);

                setStatus("Non-Payee / Top Defaulters lists ban rahi hain...", false);
                const np3 = buildRevenueNonPayeeRows("DAILY", "", "3M");
                const np6 = buildRevenueNonPayeeRows("DAILY", "", "6M");
                const sinceConn = buildRevenueNonPayeeRows("DAILY", "", "SINCE_CONNECTION");
                const allConsumerRows = buildRevenueHqVillageConsumerRows("DAILY", "");
                // USER-REPORTED BUG (2026-09-12): Pehle saari 24 DC ke consumers
                // ko EK SAATH milakar sirf EK global Top 50 list banti thi -
                // isse chhoti/kam-defaulter DC (jinke consumer overall top-50 me
                // jagah hi nahi bana paate) ka Freeze Report me Top 20/50 khaali
                // ya bahut kam dikhta tha (jaise Kurai DC me sirf 2 consumer),
                // jabki live "Top 20/50 Defaulters" report hamesha PER-DC/scope
                // hi dikhati hai. Fix: har DC ka apna ALAG Top 50 (usi me se
                // Top 20) nikalte hain, phir sabko jodte hain - taaki DC/
                // Division/Circle kisi bhi level par har DC apna sahi Top 20/50
                // dikhaye, live report jaisa hi.
                // BUG FIX/USER REQUEST (2026-09-13): Pehle DC/Division/Circle
                // teeno ka Top 50/20 Govt+Non Govt ko MILAKAR ek hi mixed list se
                // banta tha - agar Non Govt consumers ka pending amount generally
                // zyada hota (jaisa aksar hota hai), to Govt consumer apni Govt
                // category me sabse bade bakayadaar hone ke bawajood is mixed
                // Top-N me jagah hi nahi bana paate the, aur Freeze Report me
                // "Govt" filter chunne par khaali/adhoora dikhta tha. Ab Non Govt
                // aur Govt, dono ki APNI-ALAG Top-N nikal kar jodte hain (upto
                // 2xN) - taaki "All" filter me dono group (apni-apni sahi Top N)
                // dikhein, aur "Govt"/"Non Govt" akela chunne par bhi poori/sahi
                // Top N mile.
                const buildTopNSplitByGovt = (rowsForScope, n) => {
                    const sortDesc = (list) => list.slice().sort((a, b) => b.pendingAmount - a.pendingAmount);
                    const nonGovtTop = sortDesc(rowsForScope.filter((r) => !r.govtFlag)).slice(0, n);
                    const govtTop = sortDesc(rowsForScope.filter((r) => !!r.govtFlag)).slice(0, n);
                    return [...nonGovtTop, ...govtTop];
                };
                const top50 = [];
                const top20 = [];
                allDcs.forEach((dcName) => {
                    const dcRows = allConsumerRows.filter((r) => r.pendingAmount > 0 && normalizeDcName(r.dcName) === normalizeDcName(dcName));
                    top50.push(...buildTopNSplitByGovt(dcRows, 50));
                    top20.push(...buildTopNSplitByGovt(dcRows, 20));
                });

                // USER REQUEST (2026-09-12): "Har report apni-apni scope par apna
                // hi target de" - DC apna Top 50 (upar bana chuke), Division apna
                // Top 50 (us Division ki saari DC milakar ek hi list, jaise
                // Seoni Division ke 15 DC ya Lakhnadon Division ke 9 DC), aur
                // Circle apna Top 50 (saari 24 DC milakar ek hi list) - bilkul
                // Live "Top 20/50 Defaulters" report jaisa hi (jo bhi scope ho,
                // sirf usi scope ka ek global Top-N). Jis DC ka data abhi live
                // nahi/available nahi, wo apne aap in list se bahar rahegi.
                const topDivision50 = [];
                const topDivision20 = [];
                Object.keys(divisionConfigs).forEach((divisionName) => {
                    const divDcSet = new Set(getDivisionDcNames(divisionName).map((dc) => normalizeDcName(dc)));
                    const divRows = allConsumerRows.filter((r) => r.pendingAmount > 0 && divDcSet.has(normalizeDcName(r.dcName)));
                    topDivision50.push(...buildTopNSplitByGovt(divRows, 50));
                    topDivision20.push(...buildTopNSplitByGovt(divRows, 20));
                });
                const circleRows = allConsumerRows.filter((r) => r.pendingAmount > 0);
                const topCircle50 = buildTopNSplitByGovt(circleRows, 50);
                const topCircle20 = buildTopNSplitByGovt(circleRows, 20);

                const nowIso = getTodayIsoDate();
                const freezeId = "FRZ-" + nowIso;
                const freezeLabel = formatRevenueDateIndian(normalizeRevenueReportDate(getCurrentDateDDMMYYYY()));

                // USER REQUEST (2026-09-12): Freeze report me bhi Govt/Non-Govt filter
                // chahiye (Revenue ke Non-Payee/Top Defaulters jaisa) - isliye ab
                // govt_flag bhi save karte hain.
                const toFreezeRows = (rows) => rows.map((r) => ({
                    dc_name: r.dcName || "", ivrs_no: r.ivrsNo || "", consumer_name: r.consumerName || "",
                    hq_name: r.hqName || "", village: r.village || "", mobile_no: r.mobileNo || "",
                    tariff_category: r.tariffCategory || "", pending_amount: r.pendingAmount || 0,
                    govt_flag: r.govtFlag ? "GOVT" : "NONGOVT"
                }));

                const categories = [
                    { key: "NP3", label: "Non Payee 3M", rows: toFreezeRows(np3) },
                    { key: "NP6", label: "Non Payee 6M", rows: toFreezeRows(np6) },
                    { key: "SINCE_CONNECTION", label: "Since Connection", rows: toFreezeRows(sinceConn) },
                    { key: "TOP20", label: "Top 20 (DC)", rows: toFreezeRows(top20) },
                    { key: "TOP50", label: "Top 50 (DC)", rows: toFreezeRows(top50) },
                    { key: "TOP20_DIVISION", label: "Top 20 (Division)", rows: toFreezeRows(topDivision20) },
                    { key: "TOP50_DIVISION", label: "Top 50 (Division)", rows: toFreezeRows(topDivision50) },
                    { key: "TOP20_CIRCLE", label: "Top 20 (Circle)", rows: toFreezeRows(topCircle20) },
                    { key: "TOP50_CIRCLE", label: "Top 50 (Circle)", rows: toFreezeRows(topCircle50) }
                ];

                // NOTE (fixed 2026-09-12): 24 DC ka poora data ek hi Apps Script call me
                // save karne me 90 second se zyada lag sakta hai - isliye 4 minute (240
                // second) ka timeout diya hai. Saath hi ab % progress bhi dikhta hai
                // (jaise Admin Cash List upload me dikhta hai), 100% hote hi success.
                // Resume-support: pichhli baar (isi din ka freeze_id) jitni categories
                // safal ho chuki thi, unhe is baar skip kar dete hain.
                const existingProgress = readFreezeNowProgress();
                const alreadyDoneKeys = new Set(
                    (existingProgress && existingProgress.freezeId === freezeId && !existingProgress.completed && Array.isArray(existingProgress.doneCategories))
                        ? existingProgress.doneCategories
                        : []
                );
                const doneCategoryKeysSoFar = Array.from(alreadyDoneKeys);
                if (alreadyDoneKeys.size) {
                    setStatus(`Pichhli baar ${alreadyDoneKeys.size}/${categories.length} category save ho chuki thi - unhe skip karke baaki bachi hui se aage badha rahe hain...`, false);
                }

                let categoriesDone = 0;
                for (const cat of categories) {
                    if (alreadyDoneKeys.has(cat.key)) {
                        categoriesDone += 1;
                        continue;
                    }
                    const percentNow = Math.round((categoriesDone / categories.length) * 100);
                    // BUG FIX (2026-09-13) - USER-REPORTED: "Freeze Now" beech me ek category
                    // par HTTP 404 (Apps Script ka apna known "echo" content-delivery glitch,
                    // jo pehle bhi Freeze Report/ensureRevenueFreezeActiveInfo me dekha gaya
                    // tha - kabhi-kabhi high load par 1 baar aata hai, dobara try karne par
                    // chala jaata hai) par fail ho jaati thi, aur poora 24-DC/9-category
                    // process (jisme kaafi samay lagta hai) restart karna padta tha. Ab har
                    // category ke liye 2 attempt (1.5s gap) try hote hain, isi tarah jaise
                    // ensureRevenueFreezeActiveInfo me pehle se hai - poore process ko dobara
                    // chalane ki zaroorat sirf tab hi padegi jab dono attempt fail ho jaayein.
                    let categorySaved = false, lastCategoryErr = null;
                    for (let attempt = 1; attempt <= 2 && !categorySaved; attempt++) {
                        const retrySuffix = attempt > 1 ? ` (dobara try - attempt ${attempt})` : "";
                        setStatus(`${percentNow}% - Server par "${cat.label}" (${cat.rows.length} consumer) save ho raha hai${retrySuffix}... kripya wait kijiye`, false);
                        try {
                            const response = await fetchWithTimeout(revenueFreezeTrackingScriptUrl, {
                                method: "POST",
                                headers: { "Content-Type": "text/plain;charset=UTF-8" },
                                body: JSON.stringify({ action: "saveFreezeSnapshot", admin_password: freezeAdminPasswordEntered, freeze_id: freezeId, freeze_label: freezeLabel, freeze_date: nowIso, category: cat.key, rows: cat.rows })
                            // PERFORMANCE FIX (2026-09-12) ke saath saath, ek genuine
                            // SAME-DAY RE-RUN (jab purana data hatana bhi padta hai) ab
                            // bhi thoda dheema ho sakta hai - Apps Script ka khud ka hard
                            // execution limit 6 minute (360s) hai, isliye client timeout
                            // usse thoda kam (5.5 minute) rakha hai taaki server ko poora
                            // mauka mile, lekin browser hamesha ke liye atka na rahe.
                            }, 330000);
                            const text = await response.text();
                            let parsed = {};
                            try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                            // USER-REPORTED (2026-09-12): "Freeze save fail (Non Payee 6M)" jaisa
                            // generic message dikh raha tha, jisse asli wajah pata nahi chalti thi -
                            // ab agar backend se JSON ki jagah kuch aur (HTML error page, quota/
                            // timeout error, redeploy-needed page) ya galat HTTP status aaye, to
                            // uska ek chhota sa raw preview aur HTTP status bhi error message me
                            // dikhega - taaki asli wajah pata chal sake.
                            if (!response.ok || parsed.status === "error") {
                                const rawSnippet = String(text || "").replace(/\s+/g, " ").trim().slice(0, 180);
                                throw new Error(parsed.message || `Freeze save fail (${cat.label}) - HTTP ${response.status}${rawSnippet ? ": " + rawSnippet : ""}`);
                            }
                            categorySaved = true;
                        } catch (err) {
                            lastCategoryErr = err;
                            if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 1500));
                        }
                    }
                    if (!categorySaved) throw lastCategoryErr;
                    categoriesDone += 1;
                    doneCategoryKeysSoFar.push(cat.key);
                    // Har category safal hone ke turant baad progress save karte hain -
                    // taaki beech me kahin bhi ruk jaaye (agli category fail, tab band,
                    // network), ab tak ka progress kabhi na khoye.
                    writeFreezeNowProgress({
                        freezeId, freezeDate: nowIso, totalCategories: categories.length,
                        doneCategories: doneCategoryKeysSoFar,
                        updatedAt: new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }),
                        completed: false
                    });
                    setStatus(`${Math.round((categoriesDone / categories.length) * 100)}% ho gaya...`, false);
                }

                clearFreezeNowProgress();
                setStatus(`✅ 100% - Freeze SUCCESSFUL (${freezeLabel}) - Non Payee 3M: ${np3.length}, 6M: ${np6.length}, Since Connection: ${sinceConn.length}, Top 20: ${top20.length}, Top 50: ${top50.length}`, true);
                showToast("Freeze ho gaya", true);
                progressFreezeActiveFreeze = null;
                revenueFreezeSnapshotCache = {};
                lastRevenueProgressFreezeResult = null;
                lastRevenueProgressFreezeScopeKey = null;
                await loadFreezeAdminList();
            } catch (error) {
                setStatus("Freeze nahi ho paya: " + (error?.message || "error") + " (jo categories safal ho chuki hain wo save rahengi - 'Freeze Now' dobara dabane par wahi se aage badhega)", false);
                showToast("Freeze nahi ho paya", false);
            } finally {
                activeViewLevel = savedViewLevel; activeDC = savedDC; activeDiv = savedDiv;
            }
        }

        // USER REQUEST (2026-09-12): "All DC" wala bulk Freeze/Unfreeze button
        // pehle jaisa hi rehta hai, lekin ab har freeze card me ek DC dropdown
        // (sabhi DC + unka current status) bhi hai - taaki kisi EK particular DC
        // ko unfreeze/reactivate karne se baaki DC ka frozen data bilkul disturb
        // na ho.
        async function loadFreezeAdminList() {
            const listBox = document.getElementById("freeze-admin-list");
            if (!listBox) return;
            if (!revenueFreezeTrackingScriptUrl || revenueFreezeTrackingScriptUrl.indexOf("PASTE_") === 0) {
                listBox.innerHTML = `<div style="text-align:center; color:#991b1b; font-size:0.68rem;">Freeze script URL set nahi hai</div>`;
                return;
            }
            listBox.innerHTML = `<div style="text-align:center; color:#64748b; font-size:0.68rem;">SYNCING DATA... PLEASE WAIT<div class="app-sync-spinner"></div></div>`;
            try {
                const parsed = await loadRemoteJson(`${revenueFreezeTrackingScriptUrl}?action=listFreezes`);
                const freezes = Array.isArray(parsed?.freezes) ? parsed.freezes : [];
                if (!freezes.length) {
                    listBox.innerHTML = `<div style="text-align:center; color:#64748b; font-size:0.68rem;">Abhi tak koi freeze nahi hua</div>`;
                    return;
                }
                freezes.sort((a, b) => String(b.freeze_date || "").localeCompare(String(a.freeze_date || "")));

                // Har freeze ki individual DC overrides bhi le aao (dropdown me
                // current status dikhane ke liye) - jis DC ki koi alag override
                // save nahi hui, wo us freeze ki overall/bulk status hi dikhayegi.
                const dcStatusByFreeze = {};
                await Promise.all(freezes.map(async (f) => {
                    try {
                        const dcParsed = await loadRemoteJson(`${revenueFreezeTrackingScriptUrl}?action=listFreezeDcStatus&freeze_id=${encodeURIComponent(f.freeze_id)}`);
                        const overrideMap = {};
                        (Array.isArray(dcParsed?.dc_status) ? dcParsed.dc_status : []).forEach((d) => { overrideMap[normalizeDcName(d.dc_name)] = d.status; });
                        dcStatusByFreeze[f.freeze_id] = overrideMap;
                    } catch (_) {
                        dcStatusByFreeze[f.freeze_id] = {};
                    }
                }));

                const allDcs = getAllDcNames();
                listBox.innerHTML = freezes.map((f) => {
                    const overrideMap = dcStatusByFreeze[f.freeze_id] || {};
                    const selectId = `freeze-dc-select-${f.freeze_id}`.replace(/[^a-zA-Z0-9_-]/g, "_");
                    const dcOptionsHtml = allDcs.map((dc) => {
                        const norm = normalizeDcName(dc);
                        const dcStatus = overrideMap[norm] || f.status || "ACTIVE";
                        return `<option value="${escapeHtml(norm)}" data-status="${escapeHtml(dcStatus)}">${escapeHtml(norm)} - ${dcStatus === "UNFROZEN" ? "Unfrozen" : "Active"}</option>`;
                    }).join("");
                    return `
                        <div style="border:1.5px solid #e2e8f0; border-radius:12px; padding:10px; margin-top:8px;">
                            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                                <div>
                                    <div style="font-size:0.72rem; font-weight:900; color:#0f172a;">${escapeHtml(f.freeze_label || f.freeze_id)}</div>
                                    <div style="font-size:0.6rem; color:${f.status === "UNFROZEN" ? "#9f1239" : "#166534"}; font-weight:800;">All DC: ${escapeHtml(f.status || "ACTIVE")}</div>
                                </div>
                                <button class="btn-unique" style="background:${f.status === "UNFROZEN" ? "#0d9488" : "#b91c1c"}; color:#fff; padding:6px 12px; font-size:0.62rem; border-radius:10px; border:none;" onclick="toggleFreezeStatus('${escapeHtml(f.freeze_id)}', '${f.status === "UNFROZEN" ? "ACTIVE" : "UNFROZEN"}')">${f.status === "UNFROZEN" ? "Reactivate (All DC)" : "Unfreeze (All DC)"}</button>
                            </div>
                            ${(() => {
                                // USER REQUEST (2026-09-12): App band-khol karne (ya Admin
                                // panel dobara khulne) ke baad bhi is freeze ka last upload
                                // summary (kis category me kitne consumer save hue, sabhi
                                // DC milakar) dikhna chahiye - ab yeh FREEZE INDEX sheet me
                                // hi permanently save hai, sirf is session ki memory me nahi.
                                const c = f.counts || {};
                                const hasCounts = (c.NP3 || c.NP6 || c.SINCE_CONNECTION || c.TOP20 || c.TOP50);
                                if (!hasCounts) return "";
                                return `<div style="margin-top:8px; padding:8px 10px; background:#ecfeff; border-radius:10px; font-size:0.6rem; font-weight:800; color:#0e7490;">
                                    Last Upload - Non Payee 3M: ${Number(c.NP3 || 0)}, 6M: ${Number(c.NP6 || 0)}, Since Connection: ${Number(c.SINCE_CONNECTION || 0)}, Top 20: ${Number(c.TOP20 || 0)}, Top 50: ${Number(c.TOP50 || 0)}
                                </div>`;
                            })()}
                            <div style="margin-top:10px; padding-top:10px; border-top:1px dashed #cbd5e1;">
                                <div style="font-size:0.58rem; font-weight:800; color:#475569; margin-bottom:4px;">Ek particular DC ko unfreeze/reactivate karein (baaki DC disturb nahi honge):</div>
                                <select id="${selectId}" style="width:100%; height:38px; border:1.5px solid #94a3b8; border-radius:10px; padding:0 10px; font-size:0.68rem; font-weight:800; color:#0f172a;">
                                    ${dcOptionsHtml}
                                </select>
                                <button class="btn-unique" style="width:100%; margin-top:6px; background:#0891b2; color:#fff; padding:7px 12px; font-size:0.62rem; border-radius:10px; border:none;" onclick="const sel = document.getElementById('${selectId}'); const opt = sel.selectedOptions[0]; toggleFreezeDcStatus('${escapeHtml(f.freeze_id)}', sel.value, opt.dataset.status === 'UNFROZEN' ? 'ACTIVE' : 'UNFROZEN')">Selected DC Unfreeze/Reactivate</button>
                            </div>
                        </div>
                    `;
                }).join("");
            } catch (error) {
                listBox.innerHTML = `<div style="text-align:center; color:#991b1b; font-size:0.68rem;">List load nahi ho payi</div>`;
            }
        }

        async function toggleFreezeStatus(freezeId, newStatus) {
            try {
                const response = await fetchWithTimeout(revenueFreezeTrackingScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "text/plain;charset=UTF-8" },
                    body: JSON.stringify({ action: "setFreezeStatus", admin_password: freezeAdminPasswordEntered, freeze_id: freezeId, status: newStatus })
                }, 20000);
                const text = await response.text();
                let parsed = {};
                try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                if (!response.ok || parsed.status === "error") throw new Error(parsed.message || "Update fail");
                showToast("Status update ho gaya (sabhi DC)", true);
                progressFreezeActiveFreeze = null;
                revenueFreezeSnapshotCache = {};
                lastRevenueProgressFreezeResult = null;
                lastRevenueProgressFreezeScopeKey = null;
                await loadFreezeAdminList();
            } catch (error) {
                showToast("Status update nahi ho paya", false);
            }
        }

        // Sirf ek specific DC ki freeze status badalta hai - baaki DC (chahe
        // "All DC" status kuch bhi ho) bilkul disturb nahi hote.
        async function toggleFreezeDcStatus(freezeId, dcName, newStatus) {
            try {
                const response = await fetchWithTimeout(revenueFreezeTrackingScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "text/plain;charset=UTF-8" },
                    body: JSON.stringify({ action: "setFreezeDcStatus", admin_password: freezeAdminPasswordEntered, freeze_id: freezeId, dc_name: dcName, status: newStatus })
                }, 20000);
                const text = await response.text();
                let parsed = {};
                try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                if (!response.ok || parsed.status === "error") throw new Error(parsed.message || "Update fail");
                showToast(`${dcName} - status update ho gaya`, true);
                progressFreezeActiveFreeze = null;
                revenueFreezeSnapshotCache = {};
                lastRevenueProgressFreezeResult = null;
                lastRevenueProgressFreezeScopeKey = null;
                await loadFreezeAdminList();
            } catch (error) {
                showToast("DC status update nahi ho paya", false);
            }
        }

        function openFreezeAdmin() {
            closeHeaderMenu();
            askPassword("FREEZE_ADMIN");
        }

        function openOmvigAdmin() {
            closeHeaderMenu();
            askPassword("OMVIG_ADMIN");
        }

        function initFreezeAdmin() {
            const statusBox = document.getElementById("freeze-admin-status");
            if (statusBox) statusBox.style.display = "none";
            // USER REQUEST (2026-09-13): agar pichhli baar "Freeze Now" beech me hi
            // adhoora reh gaya tha, to screen khulte hi turant dikhna chahiye ki
            // kitna % ho chuka tha (localStorage-based resume-progress record,
            // dekhein runRevenueFreezeNow) - taaki dobara "Freeze Now" dabane se
            // pehle andaza ho jaye, aur dabane par wahi se aage badhega.
            const savedProgress = readFreezeNowProgress();
            if (statusBox && savedProgress && !savedProgress.completed && savedProgress.totalCategories && (savedProgress.doneCategories || []).length > 0) {
                const doneCount = savedProgress.doneCategories.length;
                const pct = Math.round((doneCount / savedProgress.totalCategories) * 100);
                statusBox.style.display = "block";
                statusBox.style.background = "#fff7ed";
                statusBox.style.color = "#9a3412";
                statusBox.innerText = `⏸ Pichhli baar ka "Freeze Now" adhoora reh gaya tha - ${pct}% (${doneCount}/${savedProgress.totalCategories} category) save ho chuki thi${savedProgress.updatedAt ? " (" + savedProgress.updatedAt + " tak)" : ""}. "Freeze Now" dobara dabane par yahi se aage badhega.`;
            }
            loadFreezeAdminList();
        }

        // ----- Freeze Tracking Report (Daily Progress -> Revenue dropdown) -----
        // Yeh "REVENUE_FREEZE" report type - DC/Division/Circle teeno level par
        // (baaki 8 report type jaisa hi, shared dropdown se) available hai.
        function getRevenueFreezeCategoryLabel(cat) {
            if (cat === "NP6") return "Non Payee From 6 Month";
            if (cat === "SINCE_CONNECTION") return "Non Payee From Date of Connection";
            if (cat === "TOP20") return "Top 20 Defaulters";
            if (cat === "TOP50") return "Top 50 Defaulters";
            return "Non Payee From 3 Month";
        }

        // BUG FIX (2026-09-13) - USER-REPORTED BUG: DC Daily Progress me NP3/NP6/
        // Since Connection Freeze Report bade DC (jaise CHHAPARA-1, CHHAPARA-2,
        // LAKHNADON, GANESHGANJ - inme non-payee list bahut badi hoti hai kyonki
        // in 3 categories me koi Top-20/50 jaisi limit nahi hai) par kabhi 100% par
        // atak jaata tha, kabhi "Freeze data load nahi ho payi", kabhi (sabse
        // confusing) "Abhi tak koi Freeze active nahi hai" galat message dikhata
        // tha - jabki freeze active hi tha, bas is listFreezes call ka hardcoded
        // 6-second timeout kamzor/field network par itne bade data ke liye kaafi
        // nahi tha, aur yahan har tarah ki failure (network ho ya kuch aur) ko
        // chup-chaap "null" (matlab "no active freeze") maan liya jaata tha. Ab
        // (a) isi call ke liye zyada generous 45-second timeout hai, aur (b) asli
        // fetch/parse error ko chup nahi karte - use upar loadRevenueProgressFreezeData()
        // ke apne try/catch tak jaane dete hain, taaki wahan sahi "load nahi ho
        // payi" (with Try Again) dikhe, na ki galat "no freeze active" message.
        async function ensureRevenueFreezeActiveInfo(forceRefresh = false) {
            if (progressFreezeActiveFreeze && !forceRefresh) return progressFreezeActiveFreeze;
            if (!revenueFreezeTrackingScriptUrl || revenueFreezeTrackingScriptUrl.indexOf("PASTE_") === 0) return null;
            // BUG FIX (2026-09-13, further): Console se confirm hua ki yahan kabhi-kabhi
            // Apps Script ka "echo" content-delivery layer 404/HTML error page de deta
            // hai (JSON ki jagah <!DOCTYPE...), jisse JSON.parse yahin throw ho jaata
            // (ek hi attempt hone se turant poori report fail ho jaati thi, chahe yeh
            // ek transient/one-off hiccup ho). Ab yahan bhi 2 attempts (800ms gap) -
            // dobara koshish karne par yeh aksar chal jaata hai. Sab attempts fail hone
            // par bhi pehle jaisa hi throw karte hain (upar wala comment dekhein - taaki
            // galat "no freeze active" na dikhe, sahi "Try Again" wala message dikhe).
            let lastErr = null;
            for (let attempt = 1; attempt <= 2; attempt++) {
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueFreezeTrackingScriptUrl, () => loadRemoteJson(`${revenueFreezeTrackingScriptUrl}?action=listFreezes`, 45000));
                    const freezes = Array.isArray(parsed?.freezes) ? parsed.freezes : [];
                    const active = freezes.filter((f) => f.status !== "UNFROZEN").sort((a, b) => String(b.freeze_date || "").localeCompare(String(a.freeze_date || "")))[0] || null;
                    progressFreezeActiveFreeze = active;
                    return active;
                } catch (err) {
                    lastErr = err;
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 800));
                }
            }
            throw lastErr;
        }

        // USER REQUEST (2026-09-12): Har DC ka freeze data backend par apni ALAG
        // sheet tab me save hota hai (jaise PAID - {DC} pattern) - taaki DC-level
        // report sirf apni ek chhoti tab padhe (fast). Isliye yahan ek baar me
        // sirf EK DC ka data mangte hain; Division/Circle scope ke liye neeche
        // fetchRevenueFreezeSnapshotRowsForScope() scope ki har DC ke liye yeh
        // function parallel (max 5 ek saath) call karke merge karti hai - us
        // scope me jitni zyada DC hongi utna hi zyada samay lagega (Circle sabse
        // dheema, DC sabse fast) - yeh expected/accepted trade-off hai.
        // USER REQUEST (2026-09-12): Ab har DC ki apni ALAG unfreeze/reactivate
        // status ho sakti hai (Admin panel se DC select karke) - isliye backend
        // ab { rows, dc_status } dono deta hai. dc_status "UNFROZEN" ho to us DC
        // ka data Division/Circle level merge me shaamil NAHI hota (baaki DC par
        // koi asar nahi), aur DC-level report me us DC ke liye seedha "yeh DC
        // unfreeze hai" message dikhta hai.
        async function fetchRevenueFreezeSnapshotRows(freezeId, category, dcName, attempts = 2) {
            const normalizedDc = normalizeDcName(dcName);
            const cacheKey = freezeId + "|" + category + "|" + normalizedDc;
            if (revenueFreezeSnapshotCache[cacheKey]) return revenueFreezeSnapshotCache[cacheKey];
            // BUG FIX (2026-09-13, updated): NP3/NP6/SINCE_CONNECTION me Top-N limit
            // na hone se badi DC (jaise SEONI (T), CHHAPARA-1, LAKHNADON) ka snapshot
            // bahut bada ho sakta hai. USER-REPORTED BUG: DC-level par yeh report
            // hamesha "load nahi ho payi" dikhati thi (turant, bina lambi wait ke bhi),
            // jabki Division/Circle par (jahan bahut si DC ek saath fetch hoti hain,
            // aur ek DC ka data pehle se cache me mil sakta hai) yeh kaam kar jaata
            // tha. Wajah: yahan pehle SIRF EK attempt (45s timeout) tha aur koi
            // try/catch nahi tha - agar yeh ek attempt fail/timeout ho jaaye (jaisa
            // sabse badi DC ke NP3/NP6/SinceConnection data ke saath ho sakta hai),
            // to exception seedha upar (loadRevenueProgressFreezeData ke try/catch)
            // tak chala jaata - DC-level par (jahan yehi ek DC hoti hai) poora report
            // turant fail ho jaata, jabki Division/Circle me (jahan bahut si DC me se
            // koi ek DC jaldi mil jaati) kabhi-kabhi chal jaata tha. Fix: (a) ab
            // Revenue Collection side ke fetches jaisa hi 2 attempts + zyada patient
            // 90-second timeout, (b) exception ko yahin pakad lete hain (throw nahi
            // karte) - baar-baar fail hone par bhi is DC ko sirf ek saaf "ERROR"
            // status dete hain (rows khaali), taaki poora Promise.all (Division/
            // Circle scope) is ek DC ki wajah se fail na ho, aur DC-level par ek
            // saaf "is DC ka data abhi load nahi ho saka" message dikh sake (generic
            // network error ki jagah).
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueFreezeTrackingScriptUrl, () => loadRemoteJson(`${revenueFreezeTrackingScriptUrl}?action=getFreezeSnapshot&freeze_id=${encodeURIComponent(freezeId)}&category=${encodeURIComponent(category)}&dc_name=${encodeURIComponent(normalizedDc)}`, 90000));
                    const rows = Array.isArray(parsed?.rows) ? parsed.rows : [];
                    const dcStatus = String(parsed?.dc_status || "").trim() || "ACTIVE";
                    const result = { rows, dc_status: dcStatus };
                    revenueFreezeSnapshotCache[cacheKey] = result;
                    return result;
                } catch (_) {
                    if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
                }
            }
            return { rows: [], dc_status: "ERROR" };
        }

        function getRevenueFreezeTargetDcs() {
            if (activeViewLevel === "DC") return [activeDC].filter(Boolean);
            if (activeViewLevel === "DIVISION") return getDivisionDcNames(activeDiv);
            return getAllDcNames();
        }

        // SPEED FIX (2026-09-15, USER-REPORTED slowness): pehle Division/Circle
        // scope ki har target DC ke liye ALAG single-DC HTTP call lagti thi (max
        // 24, 2-concurrent gate se throttle) - backend (.gs) ab ek naya `dc_names`
        // (comma-list) batch mode support karta hai jo kai DC EK HI call me deta
        // hai (FREEZE INDEX/FREEZE DC STATUS bhi sirf ek baar padhta hai, 24 baar
        // ki jagah). Poore Circle ko ek hi mega-call me maangna response-size
        // risk hai (bade NP3/NP6/SINCE_CONNECTION categories me Apps Script
        // "echo" layer bade response par 404 de sakta hai, jaisa O&M/VIG me pehle
        // mil chuka tha), isliye chhote batches (FREEZE_SNAPSHOT_BATCH_SIZE DC
        // per call) me bhejte hain - round-trips fir bhi 24 se ghatkar ~4-5 tak
        // aa jaate hain. Kisi batch ka naya endpoint fail ho jaaye (purana
        // backend abhi deploy hai, ya kuch aur) to sirf usi batch ki DCs ke liye
        // purana per-DC single-call fallback chal jaata hai - report kabhi bhi
        // khaali/galat nahi dikhegi, sirf batch-fail hone par utni hi dheemi
        // (purani jaisi) hogi.
        const FREEZE_SNAPSHOT_BATCH_SIZE = 6;
        async function fetchRevenueFreezeSnapshotBatch_(freezeId, category, dcNames, attempts = 2) {
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    const url = `${revenueFreezeTrackingScriptUrl}?action=getFreezeSnapshot&freeze_id=${encodeURIComponent(freezeId)}&category=${encodeURIComponent(category)}&dc_names=${encodeURIComponent(dcNames.join(","))}`;
                    const parsed = await withAppsScriptConcurrencyGate_(revenueFreezeTrackingScriptUrl, () => loadRemoteJson(url, 90000));
                    if (parsed && parsed.status === "success" && parsed.dc_data) return parsed.dc_data;
                } catch (_) { /* neeche fallback hoga */ }
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
            }
            return null;
        }

        // Current scope (DC/Division/Circle) ki har DC ka snapshot fetch karke,
        // dc_name wapas jod kar ek hi merged array banata hai. Jo DC ki tab hi
        // nahi hai (kabhi live nahi hui ya us category me kabhi koi consumer
        // nahi tha), uska seedha khaali [] aata hai - error nahi. Jo DC
        // individually UNFROZEN hai, uske rows merge me shaamil nahi hote
        // (Division/Circle report se wo DC hat jaata hai, baaki sab same rahta
        // hai) - dcStatusMap se pata chal jaata hai ki kaunsi DC unfrozen thi.
        async function fetchRevenueFreezeSnapshotRowsForScope(freezeId, category) {
            const targetDcs = getRevenueFreezeTargetDcs();
            const merged = [];
            const dcStatusMap = {};

            // DC-level (sirf 1 target) - purana single-call path hi behtar hai,
            // batching ka koi fayda nahi.
            if (targetDcs.length <= 1) {
                await runWithConcurrencyLimit_(targetDcs, 5, async (dcName) => {
                    const normalizedDc = normalizeDcName(dcName);
                    const { rows, dc_status } = await fetchRevenueFreezeSnapshotRows(freezeId, category, dcName);
                    dcStatusMap[normalizedDc] = dc_status;
                    if (dc_status === "UNFROZEN") return;
                    rows.forEach((r) => merged.push({ ...r, dc_name: normalizedDc }));
                });
                return { rows: merged, dcStatusMap };
            }

            const batches = [];
            for (let i = 0; i < targetDcs.length; i += FREEZE_SNAPSHOT_BATCH_SIZE) {
                batches.push(targetDcs.slice(i, i + FREEZE_SNAPSHOT_BATCH_SIZE));
            }
            await runWithConcurrencyLimit_(batches, 3, async (batchDcs) => {
                const dcData = await fetchRevenueFreezeSnapshotBatch_(freezeId, category, batchDcs);
                if (dcData) {
                    batchDcs.forEach((dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        const entry = dcData[normalizedDc] || {};
                        const rows = Array.isArray(entry.rows) ? entry.rows : [];
                        const dcStatus = String(entry.dc_status || "").trim() || "ACTIVE";
                        dcStatusMap[normalizedDc] = dcStatus;
                        // Batch response se mila data DC-level single-call cache me
                        // bhi bhar dete hain - taaki agar user isi DC ka DC-level
                        // report bhi kholta hai (ya dobara isi scope ko re-render
                        // karta hai), to dobara network call na lage.
                        revenueFreezeSnapshotCache[freezeId + "|" + category + "|" + normalizedDc] = { rows, dc_status: dcStatus };
                        if (dcStatus === "UNFROZEN") return;
                        rows.forEach((r) => merged.push({ ...r, dc_name: normalizedDc }));
                    });
                } else {
                    // Batch endpoint fail - sirf isi batch ki DCs ke liye purana
                    // per-DC single-call fallback.
                    await runWithConcurrencyLimit_(batchDcs, 5, async (dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        const { rows, dc_status } = await fetchRevenueFreezeSnapshotRows(freezeId, category, dcName);
                        dcStatusMap[normalizedDc] = dc_status;
                        if (dc_status === "UNFROZEN") return;
                        rows.forEach((r) => merged.push({ ...r, dc_name: normalizedDc }));
                    });
                }
            });
            return { rows: merged, dcStatusMap };
        }

        function getRevenueFreezeRowsInScope(rows) {
            if (activeViewLevel === "DC") return rows.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(activeDC));
            if (activeViewLevel === "DIVISION") {
                const dcSet = new Set(getDivisionDcNames(activeDiv).map((dc) => normalizeDcName(dc)));
                return rows.filter((r) => dcSet.has(normalizeDcName(r.dc_name)));
            }
            return rows;
        }

        // USER REQUEST (2026-09-12): Freeze report bhi Non-Payee (HQ/Village/
        // Category/Net Bill Slab/Govt-NonGovt) aur Top Defaulters (Govt-NonGovt)
        // jaisi hi filter dropdown use kare - "revenue ki same format" jaisa
        // pehle bhi kaha gaya tha.
        function resetFreezeFilterState() {
            freezeNonPayeeFilterState = { dc: "", hq: "", village: "", category: "", slab: "", govt: "" };
            freezeDefaultersGovtFilter = "";
        }

        function isFreezeCategoryDefaultersType() {
            return progressFreezeCategory === "TOP20" || progressFreezeCategory === "TOP50";
        }

        function setFreezeNonPayeeFilter(key, value) {
            if (!(key in freezeNonPayeeFilterState)) return;
            freezeNonPayeeFilterState[key] = value || "";
            if (key === "dc") { freezeNonPayeeFilterState.hq = ""; freezeNonPayeeFilterState.village = ""; }
            if (key === "hq") freezeNonPayeeFilterState.village = "";
            const body = document.getElementById("summary-content");
            if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
        }

        function setFreezeDefaultersGovtFilter(value) {
            freezeDefaultersGovtFilter = value || "";
            const body = document.getElementById("summary-content");
            if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
        }

        function isFreezeNetBillInSlab(row, slabValue) {
            if (!slabValue) return true;
            const amount = Number(row.pending_amount || 0);
            if (slabValue === "0-500") return amount >= 0 && amount <= 500;
            if (slabValue === "500-1000") return amount > 500 && amount <= 1000;
            if (slabValue === "1000-5000") return amount > 1000 && amount <= 5000;
            if (slabValue === "5000-10000") return amount > 5000 && amount <= 10000;
            if (slabValue === "10000-25000") return amount > 10000 && amount <= 25000;
            if (slabValue === "25000+") return amount > 25000;
            return true;
        }

        function buildFreezeOptionsHtml(values, selectedValue, placeholder) {
            const options = [`<option value="">${escapeHtml(placeholder)}</option>`].concat(
                (values || []).map((v) => `<option value="${escapeHtml(v)}" ${v === selectedValue ? "selected" : ""}>${escapeHtml(v)}</option>`)
            );
            return options.join("");
        }

        // Category ke hisaab se sahi filter set apply karke final rows deta hai -
        // NP3/NP6/SINCE_CONNECTION me 5 filters (Non-Payee jaisa), TOP20/TOP50 me
        // sirf Govt/Non-Govt (Top Defaulters jaisa).
        function getFreezeFilteredRowsWithStatus(rowsWithStatus) {
            if (isFreezeCategoryDefaultersType()) {
                const g = freezeDefaultersGovtFilter;
                if (!g) return rowsWithStatus;
                return rowsWithStatus.filter((row) => (g === "GOVT" ? row.govt_flag === "GOVT" : row.govt_flag !== "GOVT"));
            }
            const f = freezeNonPayeeFilterState;
            return rowsWithStatus.filter((row) => (
                (!f.dc || normalizeDcName(row.dc_name) === normalizeDcName(f.dc))
                && (!f.hq || normalizeLookupValue(row.hq_name) === normalizeLookupValue(f.hq))
                && (!f.village || normalizeLookupValue(row.village) === normalizeLookupValue(f.village))
                && (!f.category || normalizeLookupValue(row.tariff_category) === normalizeLookupValue(f.category))
                && isFreezeNetBillInSlab(row, f.slab)
                && (!f.govt || (f.govt === "GOVT" ? row.govt_flag === "GOVT" : row.govt_flag !== "GOVT"))
            ));
        }

        // USER REQUEST (2026-09-12): Pehle sirf freeze-date ke BAAD ki date wale
        // payment hi "Paid" count hote the - isse jo cash list PEHLE se upload
        // thi (freeze se pehle ya turant baad ki), uska data compare hi nahi
        // hota tha aur sab "Pending" dikhta tha. Ab koi date-filter nahi hai -
        // jitni bhi cash list ka data currently system me hai (purani + naya
        // daily upload, sabhi DC), sabhi consumer ke against jo bhi payment
        // (part-payment bhi) mila, wo seedha "Paid" gina jaata hai. Jaise-jaise
        // aage naye consumer daily upload me paid dikhenge, wo bhi apne aap is
        // hisaab me add hote jaayenge (yeh function har report load par current
        // cached data se dobara banta hai).
        // USER REQUEST (2026-09-12): "PAID" ke saath payment ki date bhi dikhe
        // ("PAID (DD/MM/YYYY)") - isliye har consumer ka SABSE HALIYA (latest)
        // payment date bhi yahin track karte hain (jaisa amount ko sum karte
        // hain, date me sabse aage wali date rakhte hain).
        function buildRevenueFreezePaidIndex(freezeDateIso) {
            const idx = {};
            getRevenueCategoryPaymentSourceRows().forEach((row) => {
                const dc = getRevenueUploadedPaidRowDcName(row);
                const ivrs = getRevenueUploadedPaidRowIvrs(row);
                if (!dc || !ivrs) return;
                const key = dc + "|" + ivrs;
                if (!idx[key]) idx[key] = { paidAmount: 0, lastPaidDate: "" };
                idx[key].paidAmount += getRevenueUploadedPaidRowAmount(row);
                const rowDate = normalizeRevenueReportDate(getRevenueUploadedPaidRowDate(row));
                if (rowDate) {
                    const newKey = revenueDateSortKey_(rowDate);
                    const oldKey = revenueDateSortKey_(idx[key].lastPaidDate);
                    if (newKey && (!oldKey || newKey > oldKey)) idx[key].lastPaidDate = rowDate;
                }
            });
            return idx;
        }

        function computeRevenueFreezeReportData() {
            if (!lastRevenueProgressFreezeResult) return null;
            const { active, rows: allRows, error } = lastRevenueProgressFreezeResult;
            if (error || !active) return { active: active || null, error: !!error, rowsWithStatus: [], totals: null };
            const scopedRows = getRevenueFreezeRowsInScope(allRows);
            const paidIndex = buildRevenueFreezePaidIndex(active.freeze_date);
            // USER-REPORTED BUG (2026-09-12): Freeze report kisi consumer ko
            // "PAID" dikha raha tha jabki Live Revenue Report (usi din, usi
            // consumer ka) use abhi bhi "PENDING" dikha raha tha - wajah: yahan
            // "koi bhi payment record mil gaya (chahe part-payment ho) matlab
            // PAID" maan liya jaata tha, jabki Live report me part-payment
            // hone par bhi consumer PENDING hi rehta hai (bacha hua bakaya kam
            // hokar). Ab dono jagah same logic: sirf tabhi "PAID" jab paid
            // amount, frozen pending amount ko POORA cover kar de - warna
            // "PENDING" hi rahega, bas bacha hua (reduced) bakaya dikhega.
            const scopedRowsWithStatus = scopedRows.map((r) => {
                const key = normalizeDcName(r.dc_name) + "|" + normalizeRevenueIvrs(r.ivrs_no);
                const info = paidIndex[key];
                const paidAmountNow = info ? info.paidAmount : 0;
                const frozenPending = Number(r.pending_amount || 0);
                const remainingPending = Math.max(0, frozenPending - paidAmountNow);
                const isPaid = paidAmountNow > 0 && remainingPending <= 0;
                return { ...r, isPaidNow: isPaid, paidAmountNow, remainingPending, paidDateNow: info ? info.lastPaidDate : "" };
            });
            // USER REQUEST (2026-09-12): HQ/Village/Category/Net Bill Slab/Govt-
            // NonGovt (NP3/6/Since Connection) ya Govt-NonGovt (Top 20/50) filter
            // apply karke, totals bhi usi FILTERED list se nikalte hain - jaisa
            // Non-Payee/Top Defaulters reports me hota hai.
            // USER REQUEST (2026-09-12): Live Report me sabse jyada bakaya
            // (pending amount) wala consumer sabse upar aata hai (descending
            // sort). Freeze Report abhi tak DC-wise group order me hi
            // dikhta tha (bina amount-sort ke), jisse dono reports ka order
            // alag lagta tha (data same hone ke bawajood). Ab Freeze Report
            // bhi Live jaisa hi - sabse bada bakayadar (frozen pending
            // amount ke hisab se) sabse upar - dikhayega.
            // USER REQUEST (2026-09-12): Payment-status ke hisaab se rows ko
            // group/reorder NAHI karna - Top 20/50 (aur baaki categories) ka
            // sequence bilkul wahi rahega jo sirf frozen pending amount ke
            // descending order se banta hai (Live Report jaisa), chahe wo row
            // baad me PAID ho gaya ho ya PART PAID - uski position nahi
            // badlegi, sirf uska status COLOUR (PAID=green, PART PAID=red)
            // alag dikhega taaki pehchana ja sake.
            const rowsWithStatusUnsorted = getFreezeFilteredRowsWithStatus(scopedRowsWithStatus);
            const rowsWithStatus = rowsWithStatusUnsorted.slice().sort((a, b) => Number(b.pending_amount || 0) - Number(a.pending_amount || 0));
            let paidCount = 0, paidAmount = 0, totalFrozenAmount = 0, pendingAmount = 0;
            rowsWithStatus.forEach((r) => {
                // BUG FIX (2026-09-14) - USER-REPORTED: Circle/Division/DC summary
                // aur consumer list me "PAID AMOUNT" kabhi-kabhi ekdum bada (galat)
                // dikh raha tha (jaise ek consumer ka frozen pending sirf ~9,378
                // tha lekin "paid" 3,00,128 dikh raha tha). ASLI WAJAH: r.paidAmountNow
                // us consumer ki cash list me AB TAK ki SAARI payments ka total hai
                // (koi date-filter nahi, taaki purani upload hui cash list bhi
                // match ho - yeh 2026-09-12 ka jaanboojh kar kiya gaya fix hai),
                // jabki AG/seasonal consumer jaisi baar-baar payment karne wali
                // entries ke liye yeh unka POORA payment history total ban jaata
                // hai, sirf isi freeze ke pending bill ka nahi. isPaidNow ke liye
                // yeh sahi hai (agar total payment >= frozen pending, to PAID),
                // lekin "kitna PAID hua" dikhane ke liye sirf itna hi sahi hai
                // jitna is frozen bill ka tha (r.pending_amount) - baaki unka
                // purana/anya payment history hai, is report se related nahi.
                if (r.isPaidNow) { paidCount += 1; paidAmount += Number(r.pending_amount || 0); }
                totalFrozenAmount += Number(r.pending_amount || 0);
                // USER REQUEST (2026-09-13): Division/Circle summary me "abhi kitna
                // bakaya hai" saaf dikhna chahiye - "Frozen Total Amount" wahi
                // ORIGINAL freeze-time amount hai (part-payment se kam nahi hota),
                // isliye alag se CURRENT remaining pending bhi jodte hain.
                pendingAmount += Number(r.remainingPending || 0);
            });
            const totalCount = rowsWithStatus.length;
            return {
                active, error: false, rowsWithStatus, allScopedRows: scopedRowsWithStatus,
                totals: {
                    totalCount, paidCount, pendingCount: totalCount - paidCount, paidAmount, totalFrozenAmount, pendingAmount,
                    paidPercent: totalCount ? ((paidCount / totalCount) * 100).toFixed(1) : "0.0"
                }
            };
        }

        // USER REQUEST (2026-09-12): Revenue Freeze Report ab Daily Progress ke
        // "Revenue Report" dropdown ke ANDAR nahi, balki Mobile/Revenue tabs ke
        // UPAR apna ek ALAG, seedha tab hai - click karte hi (bina kisi Daily/
        // Monthly date-selection ke) turant fetch ho jaata hai. Isse fetching
        // fast hoti hai kyonki Revenue module ki poori Category/Target/Staff
        // sync (jo Revenue tab kholte hi chal jaati hai) is se pehle chalani
        // nahi padti - seedha freeze data hi mangte hain.
        // Current DC/Division/Circle scope + freeze category ka ek "key" - jab tak
        // yeh badle nahi, dobara fetch ki zaroorat nahi (Mobile/Revenue ghoom kar
        // Freeze par wapas aane par bhi purana data seedha dikh jaata hai).
        function getRevenueFreezeScopeKey() {
            return `${activeViewLevel}|${activeDC}|${activeDiv}|${progressFreezeCategory}`;
        }

        // USER REQUEST (2026-09-12): "Har report apni-apni scope par apna hi
        // Top 20/50 target de" - jaise Live Top Defaulters report DC par sirf
        // usi DC ka, Division par sirf usi Division (uski saari DC milakar) ka,
        // aur Circle par saari 24 DC milakar ek hi global Top 20/50 dikhati
        // hai - Freeze Report ko bhi bilkul waisa hi banana tha. Isliye Top20/
        // Top50 categories teen alag "flavours" me save hoti hain
        // (runRevenueFreezeNow me) - yeh function current scope ke hisaab se
        // sahi flavour chunta hai; NP3/NP6/SINCE_CONNECTION me koi Top-N limit
        // nahi hai isliye unhe kisi scope-specific flavour ki zaroorat nahi.
        function getEffectiveFreezeFetchCategory(category) {
            if (category === "TOP20" || category === "TOP50") {
                if (activeViewLevel === "DIVISION") return category + "_DIVISION";
                if (activeViewLevel === "CIRCLE") return category + "_CIRCLE";
                return category; // DC level - per-DC Top 20/50, jaisa pehle se hai
            }
            return category;
        }

        async function loadRevenueProgressFreezeData() {
            progressFreezeLoading = true;
            const myToken = ++revenueFreezeSyncToken;
            const isStillValid = () => myToken === revenueFreezeSyncToken;
            const body = document.getElementById("summary-content");
            // USER REQUEST (2026-09-12): Freeze report me bhi Mobile/Revenue jaisa hi
            // "SYNCING ALL DC DATA... x%" progress-bar animation dikhna chahiye (pehle
            // yahan sirf plain "Freeze data load ho raha hai..." text tha).
            const progress = body ? renderSyncingProgress(body, isStillValid) : null;
            try {
                const active = await ensureRevenueFreezeActiveInfo();
                console.log("[FreezeReport] step1 active =", active); // DIAGNOSTIC (2026-09-13, temp)
                if (active) {
                    const fetchCategory = getEffectiveFreezeFetchCategory(progressFreezeCategory);
                    console.log("[FreezeReport] step2 calling fetchRevenueFreezeSnapshotRowsForScope", active.freeze_id, fetchCategory); // DIAGNOSTIC (2026-09-13, temp)
                    const { rows, dcStatusMap } = await fetchRevenueFreezeSnapshotRowsForScope(active.freeze_id, fetchCategory);
                    console.log("[FreezeReport] step3 snapshot done, rows.length =", rows.length, "dcStatusMap =", dcStatusMap); // DIAGNOSTIC (2026-09-13, temp)
                    await warmRevenueCategoryUploadedPaidCache();
                    console.log("[FreezeReport] step4 warmCache done"); // DIAGNOSTIC (2026-09-13, temp)
                    lastRevenueProgressFreezeResult = { active, rows, dcStatusMap };
                } else {
                    lastRevenueProgressFreezeResult = { active: null, rows: [], dcStatusMap: {} };
                }
            } catch (err) {
                // DIAGNOSTIC (2026-09-13): asli exception console me log karte hain -
                // taaki pata chale generic "load nahi ho payi" message ke peechhe
                // konsa exact JS error/exception hai (behavior me koi badlav nahi,
                // sirf ek console.error jyada hai).
                console.error("[FreezeReport] loadRevenueProgressFreezeData failed:", err);
                lastRevenueProgressFreezeResult = { active: null, rows: [], error: true };
            }
            progressFreezeLoading = false;
            lastRevenueProgressFreezeScopeKey = getRevenueFreezeScopeKey();
            if (!isStillValid()) return; // beech me hi koi aur scope/category select ho gaya
            if (progress) await progress.finish();
            const bodyAfter = document.getElementById("summary-content");
            // BUG FIX (2026-09-13): Pehle agar yahan render (renderFreezeModuleSummaryHtml)
            // kisi wajah se khud hi error de deta, to progress bar "100%" par hamesha
            // ke liye atka reh jaata tha (kyonki yeh poori line try/catch ke BAHAR thi) -
            // ab render bhi try/catch me hai, fail hone par bhi ek saaf "Try Again"
            // wala error message dikhega, blank/atka screen nahi.
            if (bodyAfter) {
                try {
                    bodyAfter.innerHTML = renderFreezeModuleSummaryHtml();
                } catch (err) {
                    // DIAGNOSTIC (2026-09-13): render phase me exact exception log karte
                    // hain (behavior me koi badlav nahi, sirf console.error jyada hai).
                    console.error("[FreezeReport] renderFreezeModuleSummaryHtml (first render) failed:", err);
                    lastRevenueProgressFreezeResult = { active: null, rows: [], error: true };
                    bodyAfter.innerHTML = renderFreezeModuleSummaryHtml();
                }
            }
        }

        function renderFreezeModuleSummaryHtml() {
            return `
                <div style="border:1.5px dashed #67e8f9; background:#ecfeff; border-radius:16px; padding:10px; margin-top:4px;">
                    ${renderRevenueProgressFreezeSummaryHtml()}
                </div>
            `;
        }

        // "Revenue Freeze Report" dropdown option select hone par ise call karte
        // hain - Mobile/Revenue jaisa refreshSummary() (jo Daily/Monthly date +
        // poori sync chain se guzarta hai) bilkul nahi chalata, seedha freeze
        // data load karta hai. USER REQUEST (2026-09-12): Agar isi scope
        // (DC/Division/Circle) aur isi category ke liye data pehle se load ho
        // chuka hai, to dobara fetch NAHI karte - seedha cached result dikha
        // dete hain (Mobile/Revenue par jaake wapas Freeze par aane par bhi).
        // BUG FIX (2026-09-13): "Try Again" button (error message ke saath) ka
        // handler - purana cached (failed) result hata kar seedha dobara load
        // karta hai, dropdown se category dobara chunne ki zaroorat nahi.
        function retryFreezeModuleLoad() {
            lastRevenueProgressFreezeResult = null;
            loadRevenueProgressFreezeData();
        }

        // BUG FIX (2026-09-13): Cache sirf tabhi reuse karni chahiye jab pichla
        // result GENUINELY safal (successful) tha - agar pichli baar fetch
        // fail hui thi (data.error = true, jaise network/backend slow ke
        // karan), to usi (galat/error) result ko baar-baar dikhana galat hai -
        // isse user ko lagta ki Freeze Report "kisi bhi level par nahi aa rahi"
        // (asal me sirf ek purana cached error dikh raha hota, dobara try hi
        // nahi hota jab tak khud "Try Again" na dabayein). Ab dono jagah
        // (refreshFreezeModuleSummary + setProgressFreezeCategory) yahi shared
        // check use karte hain - error wale result ko cache HIT nahi maante,
        // seedha fresh fetch karte hain.
        function isUsableFreezeCache(scopeKey) {
            return !!lastRevenueProgressFreezeResult && !lastRevenueProgressFreezeResult.error && lastRevenueProgressFreezeScopeKey === scopeKey;
        }

        function refreshFreezeModuleSummary() {
            updateProgressReportScopeTitle();
            const scopeKey = getRevenueFreezeScopeKey();
            if (isUsableFreezeCache(scopeKey)) {
                const body = document.getElementById("summary-content");
                if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
                return;
            }
            lastRevenueProgressFreezeResult = null;
            loadRevenueProgressFreezeData();
        }

        // USER REQUEST (2026-09-12): Sirf jab is dropdown se khud koi VALID
        // report chuna jaaye tabhi sync ho - "Choose Report Type" (khaali
        // value) chunne/dobara khulne par koi fetch nahi, seedha placeholder
        // par wapas.
        function setProgressFreezeCategory(value) {
            const valid = ["NP3", "NP6", "SINCE_CONNECTION", "TOP20", "TOP50"];
            if (!valid.includes(value)) {
                progressFreezeCategory = "";
                resetFreezeFilterState();
                lastRevenueProgressFreezeResult = null;
                lastRevenueProgressFreezeScopeKey = null;
                const body = document.getElementById("summary-content");
                if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
                return;
            }
            progressFreezeCategory = value;
            resetFreezeFilterState();
            // BUG FIX (2026-09-13): Pehle yahan HAMESHA cache clear karke dobara
            // fetch hota tha, chahe isi scope (DC/Division/Circle) aur isi
            // category ka data isi session me pehle hi ek baar load ho chuka ho
            // (jaise NP3 dekh kar Top20 par jaake wapas NP3 par aana) - isse
            // dropdown se koi bhi report chunte hi har baar naya sync chalta tha,
            // jo dheeme/slow network par bahut lamba mehsoos hota (user-reported:
            // "dobara sync hona sahi nahi lagta"). Ab refreshFreezeModuleSummary()
            // jaisa hi scope-key check karte hain - agar isi scope+category ka
            // result cache me maujood hai to seedha wahi dikha dete hain, warna
            // hi fresh fetch karte hain.
            const scopeKey = getRevenueFreezeScopeKey();
            if (isUsableFreezeCache(scopeKey)) {
                const body = document.getElementById("summary-content");
                if (body) body.innerHTML = renderFreezeModuleSummaryHtml();
                return;
            }
            lastRevenueProgressFreezeResult = null;
            loadRevenueProgressFreezeData();
        }

        // USER REQUEST (2026-09-12): "Part payment wala bhi date ke saath
        // dikhna chahiye" - sirf poori tarah PAID hone par hi "PAID (date)"
        // dikhta tha, part-payment (jo abhi bhi PENDING/reduced amount rehta
        // hai) me date nahi dikhti thi. Ab dono jagah (screen + Excel/PDF)
        // isi ek shared function se status-label banta hai - poora paid ho to
        // "PAID (date)", part-payment ho to "PENDING - PART PAID (date)"
        // (amount cell me pehle se bacha hua/reduced pending dikhta hai),
        // aur koi payment hi na mila ho to seedha "PENDING".
        function getFreezeRowStatusLabel(r) {
            const dateSuffix = r.paidDateNow ? ` (${formatRevenueDateIndian(r.paidDateNow)})` : "";
            if (r.isPaidNow) return `PAID${dateSuffix}`;
            if (r.paidAmountNow > 0) return `PENDING - PART PAID${dateSuffix}`;
            return "PENDING";
        }

        // USER REQUEST (2026-09-12): NP3 / NP6 / Since Connection ki list nikalते
        // waqt, list ke UPAR ek chhota summary bhi dikhe - DC scope me HQ-wise,
        // Division scope me DC-wise, aur Circle scope me DC-wise + har Division
        // ka Division Total + sabse aakhir me ek Grand Total row. Yeh ek hi
        // shared builder/renderer hai jo Live Non-Payee report aur Freeze Report
        // (NP3/NP6/Since Connection categories) dono me reuse hota hai - caller
        // sirf normalizedRows [{dcName, hqName, pendingAmount}] pass karta hai.
        function buildRevenueNonPayeeGroupSummary(normalizedRows) {
            const sumByKey = (list, keyFn) => {
                const map = {};
                (list || []).forEach((r) => {
                    const key = keyFn(r) || "-";
                    if (!map[key]) map[key] = { name: key, count: 0, pendingTotal: 0 };
                    map[key].count += 1;
                    map[key].pendingTotal += Number(r.pendingAmount || 0);
                });
                return map;
            };
            // BUG FIX (2026-09-13) - ASLI ROOT CAUSE: yahan pehle "normalizeHqName(...)"
            // call ho raha tha, jo kahin bhi is function ke scope me defined nahi tha
            // (sirf buildProgressRevenueSummaryRows() ke ANDAR ek alag local const ke
            // roop me tha) - isliye DC-level par (jab bhi yeh group-summary banti thi)
            // seedha "ReferenceError: normalizeHqName is not defined" throw ho jaata
            // tha, jo upar loadRevenueProgressFreezeData() ke try/catch tak jaakar
            // generic "Freeze data load nahi ho payi" dikhata tha - DIVISION/CIRCLE
            // par yeh line kabhi chalti hi nahi thi (wo normalizeDcName use karte hain,
            // jo globally defined hai), isliye sirf DC hamesha fail hoti thi, Division/
            // Circle hamesha chal jaate the. Ab yahin ek local helper define kar diya.
            const normalizeHqNameLocal_ = (value) => String(value || "GENERAL").trim().toUpperCase() || "GENERAL";

            if (activeViewLevel === "DC") {
                const map = sumByKey(normalizedRows, (r) => normalizeHqNameLocal_(r.hqName) || "GENERAL");
                const rows = Object.values(map).sort((a, b) => String(a.name).localeCompare(String(b.name)));
                return { colLabel: revenueHqLabelUpper(), rows };
            }

            if (activeViewLevel === "DIVISION") {
                const map = sumByKey(normalizedRows, (r) => normalizeDcName(r.dcName) || "-");
                const rows = getDivisionDcNames(activeDiv).map((dcName) => {
                    const key = normalizeDcName(dcName);
                    return map[key] || { name: key, count: 0, pendingTotal: 0 };
                });
                return { colLabel: "DC NAME", rows };
            }

            // CIRCLE: DC-wise, division-wise SUB_TOTAL rows, aur last me GRAND TOTAL.
            const map = sumByKey(normalizedRows, (r) => normalizeDcName(r.dcName) || "-");
            const rows = [];
            let grandCount = 0, grandPending = 0;
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const dcRows = getDivisionDcNames(divisionName).map((dcName) => {
                    const key = normalizeDcName(dcName);
                    return map[key] || { name: key, count: 0, pendingTotal: 0 };
                });
                rows.push(...dcRows);
                const divCount = dcRows.reduce((s, r) => s + r.count, 0);
                const divPending = dcRows.reduce((s, r) => s + r.pendingTotal, 0);
                grandCount += divCount; grandPending += divPending;
                rows.push({ name: getDivisionTotalLabel(divisionName), count: divCount, pendingTotal: divPending, type: "SUB_TOTAL" });
            });
            rows.push({ name: "GRAND TOTAL", count: grandCount, pendingTotal: grandPending, type: "GRAND_TOTAL" });
            return { colLabel: "DC NAME", rows };
        }

        // USER REQUEST (2026-09-13): Freeze Report (NP3/NP6/Since Connection) ka
        // Division/Circle DOWNLOAD ab bhi poori consumer-list de raha tha, jabki
        // screen par sirf summary dikhti hai - inconsistent tha. Yeh function
        // wahi DC-wise summary banata hai jo download me chahiye: DC NAME, TOTAL
        // CONSUMER, PAID (count+amount), PENDING (count+amount), aur (sirf
        // download me, screen par nahi) PAID %/PENDING %. DIVISION scope me
        // sirf usi Division ki DC list, CIRCLE scope me DC-wise + har Division
        // ka SUB_TOTAL + ek GRAND_TOTAL row (buildRevenueNonPayeeGroupSummary
        // jaisा hi structure).
        function buildFreezeDcWiseSummaryRows(rowsWithStatus) {
            const emptyGroup = (key) => ({ name: key, totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 });
            const withPercents = (g) => ({
                ...g,
                paidPercent: g.totalCount ? ((g.paidCount / g.totalCount) * 100).toFixed(1) : "0.0",
                pendingPercent: g.totalCount ? ((g.pendingCount / g.totalCount) * 100).toFixed(1) : "0.0"
            });
            const map = {};
            (rowsWithStatus || []).forEach((r) => {
                const key = normalizeDcName(r.dc_name) || "-";
                if (!map[key]) map[key] = emptyGroup(key);
                const g = map[key];
                g.totalCount += 1;
                // BUG FIX (2026-09-14): dekhein computeRevenueFreezeReportData() me
                // upar wala comment - "paid amount" yahan bhi sirf is frozen bill
                // (pending_amount) tak seemित hai, consumer ki poori purani payment
                // history tak nahi (jo AG/seasonal consumers ke liye ekdum bada
                // galat number dikhata tha).
                if (r.isPaidNow) { g.paidCount += 1; g.paidAmount += Number(r.pending_amount || 0); }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });

            if (activeViewLevel === "DIVISION") {
                return getDivisionDcNames(activeDiv).map((dcName) => {
                    const key = normalizeDcName(dcName);
                    return withPercents(map[key] || emptyGroup(key));
                });
            }

            // CIRCLE: DC-wise, har Division ka SUB_TOTAL, aakhir me GRAND_TOTAL.
            const rows = [];
            const grand = emptyGroup("GRAND TOTAL");
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const dcRows = getDivisionDcNames(divisionName).map((dcName) => {
                    const key = normalizeDcName(dcName);
                    return withPercents(map[key] || emptyGroup(key));
                });
                rows.push(...dcRows);
                const divTotal = emptyGroup(getDivisionTotalLabel(divisionName));
                dcRows.forEach((r) => {
                    divTotal.totalCount += r.totalCount; divTotal.paidCount += r.paidCount; divTotal.paidAmount += r.paidAmount;
                    divTotal.pendingCount += r.pendingCount; divTotal.pendingAmount += r.pendingAmount;
                });
                rows.push({ ...withPercents(divTotal), type: "SUB_TOTAL" });
                grand.totalCount += divTotal.totalCount; grand.paidCount += divTotal.paidCount; grand.paidAmount += divTotal.paidAmount;
                grand.pendingCount += divTotal.pendingCount; grand.pendingAmount += divTotal.pendingAmount;
            });
            rows.push({ ...withPercents(grand), type: "GRAND_TOTAL" });
            return rows;
        }

        // USER REQUEST (2026-09-13): Freeze Report (NP3/NP6/Since Connection) ke
        // screen par ab har scope (DC/Division/Circle) par ek hi richer group-wise
        // breakdown dikhta hai: NAME (HQ ya DC), TOTAL CONSUMER, PAID (COUNT +
        // AMOUNT-IN-LAKH), PENDING (COUNT + AMOUNT-IN-LAKH) - DC-level par HQ-wise,
        // Division/Circle par DC-wise (bilkul pehle jaisa scope-split). Amount
        // sirf is SUMMARY table me LAKH format me hai (jaise 50000 -> 0.50) -
        // neeche ki consumer LIST (DC-level) aur DOWNLOAD (Excel/PDF, dono scope
        // par) me poora/complete amount hi dikhta hai, yeh badlav sirf is on-screen
        // summary table tak seemित hai. Ek hi shared table-renderer, taaki HQ-wise
        // aur DC-wise dono jagah exact same look/behaviour rahe.
        // USER REQUEST (2026-09-16): O&M/VIG Daily summary table ke PAID column
        // header ko "YESTERDAY PAID" dikhana hai (Daily me sirf latest date ke
        // settlements hote hain, poora baseline-vs-paid compare nahi - isliye
        // PENDING hamesha 0 dikhta hai, jo bina label ke confusing tha). Isliye
        // yahan 2 OPTIONAL param jode (paidColLabel/pendingColLabel) - default
        // "PAID"/"PENDING" hi rehta hai, Freeze Tracking Report ke maujooda 3
        // call (jo naye param bilkul nahi bhejte) me output bilkul waisa hi
        // rahega, koi badlav nahi.
        function renderFreezeGroupSummaryTableHtml(nameColLabel, summaryRows, titleText, paidColLabel, pendingColLabel) {
            paidColLabel = paidColLabel || "PAID";
            pendingColLabel = pendingColLabel || "PENDING";
            const headCellStyle = "padding:6px 4px; font-size:0.56rem; font-weight:900; text-transform:uppercase; background:#0891b2; color:#fff; text-align:center;";
            const bodyCellStyle = "padding:5px 4px; font-size:0.62rem; text-align:center; border-bottom:1px solid #e2e8f0;";
            const rowsHtml = summaryRows.map((r) => {
                const isTotal = r.type === "SUB_TOTAL" || r.type === "GRAND_TOTAL";
                const rowBg = r.type === "GRAND_TOTAL" ? "background:#dbeafe;" : (r.type === "SUB_TOTAL" ? "background:#f1f5f9;" : "");
                const fw = isTotal ? "font-weight:900;" : "font-weight:700;";
                // USER REQUEST (2026-09-14): SUB_TOTAL/GRAND_TOTAL rows pehle sirf
                // BOLD + halka background se hi alag dikhte the - ab NAME/TOTAL
                // CONSUMER column ka TEXT COLOUR bhi alag (SUB_TOTAL = blue, GRAND_TOTAL
                // = rose/red) taaki total rows ekdum saaf alag pehchani jaayein.
                const totalColor = r.type === "GRAND_TOTAL" ? "#9f1239" : (r.type === "SUB_TOTAL" ? "#1d4ed8" : "#0f172a");
                return `<tr style="${rowBg}">
                    <td style="${bodyCellStyle} ${fw} color:${totalColor}; text-align:left;">${escapeHtml(r.name)}</td>
                    <td style="${bodyCellStyle} ${fw} color:${totalColor};">${r.totalCount}</td>
                    <td style="${bodyCellStyle} ${fw} color:#166534;">${r.paidCount}</td>
                    <td style="${bodyCellStyle} ${fw} color:#166534;">${formatRevenueLakhValue(r.paidAmount)}</td>
                    <td style="${bodyCellStyle} ${fw} color:#9f1239;">${r.pendingCount}</td>
                    <td style="${bodyCellStyle} ${fw} color:#9f1239;">${formatRevenueLakhValue(r.pendingAmount)}</td>
                </tr>`;
            }).join("");
            return `
                <div style="font-size:0.62rem; font-weight:900; color:#9f1239; text-align:center; margin-top:10px;">${escapeHtml(titleText)}</div>
                <div style="overflow-x:auto; margin-top:6px; border-radius:10px; border:1px solid #e2e8f0;">
                    <table style="width:100%; border-collapse:collapse; min-width:480px;">
                        <thead>
                            <tr>
                                <th rowspan="2" style="${headCellStyle}">${escapeHtml(nameColLabel)}</th>
                                <th rowspan="2" style="${headCellStyle}">TOTAL<br>CONSUMER</th>
                                <th colspan="2" style="${headCellStyle}">${escapeHtml(paidColLabel)}</th>
                                <th colspan="2" style="${headCellStyle}">${escapeHtml(pendingColLabel)}</th>
                            </tr>
                            <tr>
                                <th style="${headCellStyle}">COUNT</th>
                                <th style="${headCellStyle}">AMT (LAKH)</th>
                                <th style="${headCellStyle}">COUNT</th>
                                <th style="${headCellStyle}">AMT (LAKH)</th>
                            </tr>
                        </thead>
                        <tbody>${rowsHtml}</tbody>
                    </table>
                </div>`;
        }

        function renderFreezeDcWiseSummaryHtml(rowsWithStatus) {
            return renderFreezeGroupSummaryTableHtml("DC NAME", buildFreezeDcWiseSummaryRows(rowsWithStatus), "DC WISE SUMMARY (AMOUNT IN LAKH)");
        }

        // DC-level scope ke liye HQ-wise wahi group summary (buildFreezeDcWiseSummaryRows
        // jaisa hi structure, bas dc_name ki jagah hq_name se group hota hai - koi
        // SUB_TOTAL/GRAND_TOTAL nahi, kyonki DC-level par divisions nahi hote).
        function buildFreezeHqWiseSummaryRows(rowsWithStatus) {
            const emptyGroup = (key) => ({ name: key, totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 });
            const map = {};
            (rowsWithStatus || []).forEach((r) => {
                const key = String(r.hq_name || "").trim().toUpperCase() || "GENERAL";
                if (!map[key]) map[key] = emptyGroup(key);
                const g = map[key];
                g.totalCount += 1;
                // BUG FIX (2026-09-14): dekhein computeRevenueFreezeReportData() me
                // upar wala comment - "paid amount" yahan bhi sirf is frozen bill
                // (pending_amount) tak seemित hai, consumer ki poori purani payment
                // history tak nahi (jo AG/seasonal consumers ke liye ekdum bada
                // galat number dikhata tha).
                if (r.isPaidNow) { g.paidCount += 1; g.paidAmount += Number(r.pending_amount || 0); }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });
            return Object.values(map).sort((a, b) => String(a.name).localeCompare(String(b.name)));
        }

        function renderFreezeHqWiseSummaryHtml(rowsWithStatus) {
            return renderFreezeGroupSummaryTableHtml(revenueHqLabelUpper(), buildFreezeHqWiseSummaryRows(rowsWithStatus), "HQ WISE SUMMARY (AMOUNT IN LAKH)");
        }

        // USER REQUEST (2026-09-14): Freeze Report (NP3/NP6/Since Connection/Top20/50)
        // ki har download (full list ho ya summary, Excel ho ya PDF) me ab yeh bhi
        // saaf dikhna chahiye ki us waqt kaunse filter dropdown selection active the
        // (taaki baad me dekhne par pata chale kis filter ke saath report nikli thi).
        // Yeh ek chhota "Filters: ..." label banata hai jo teeno download function
        // (list, DC-wise summary, HQ-wise summary) apne PDF title ke neeche aur
        // CSV/Excel ke header rows me daalte hain.
        function buildFreezeActiveFiltersLabel_() {
            if (isFreezeCategoryDefaultersType()) {
                const g = freezeDefaultersGovtFilter === "GOVT" ? "Govt" : (freezeDefaultersGovtFilter === "NONGOVT" ? "Non Govt" : "All (Govt + Non Govt)");
                return `Filter: ${g}`;
            }
            const f = freezeNonPayeeFilterState;
            const parts = [];
            if (activeViewLevel !== "DC") parts.push(`DC: ${f.dc || "All"}`);
            parts.push(`HQ: ${f.hq || "All"}`);
            parts.push(`Village: ${f.village || "All"}`);
            parts.push(`Category: ${f.category || "All"}`);
            parts.push(`Slab: ${f.slab || "All"}`);
            parts.push(`Govt: ${f.govt === "GOVT" ? "Govt" : (f.govt === "NONGOVT" ? "Non Govt" : "All")}`);
            return `Filters: ${parts.join(" | ")}`;
        }

        // Freeze Report (NP3/NP6/Since Connection) ke Division/Circle download ke
        // liye DC-wise summary Excel/PDF banata hai (list ki jagah) - downloadRevenueFreezeReport()
        // se hi (uske try/catch ke andar) call hota hai.
        function downloadRevenueFreezeDcWiseSummary(fmt, data, downloadTypeLabel) {
            const summaryRows = buildFreezeDcWiseSummaryRows(data.rowsWithStatus);
            // USER REQUEST (2026-09-13): Division/Circle ki DC-wise summary (screen
            // aur is download dono me) ab PAID/PENDING amount LAKH me dikhaegi (jaise
            // 50000 -> 0.50) - poora/complete amount sirf DC-level ki consumer LIST
            // me dikhta rahega (yahan disturb nahi kiya).
            const headers = ["DC NAME", "TOTAL CONSUMER", "PAID COUNT", "PAID AMT (LAKH)", "PENDING COUNT", "PENDING AMT (LAKH)", "PAID %", "PENDING %"];
            const bodyRows = summaryRows.map((r) => [
                r.name, r.totalCount, r.paidCount, formatRevenueLakhValue(r.paidAmount),
                r.pendingCount, formatRevenueLakhValue(r.pendingAmount), `${r.paidPercent}%`, `${r.pendingPercent}%`
            ]);
            const rowTypeFlags = summaryRows.map((r) => (r.type === "GRAND_TOTAL" ? 2 : (r.type === "SUB_TOTAL" ? 1 : 0)));
            const scope = activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE";
            const reportTitle = `Freeze-Revenue Report - ${getRevenueFreezeCategoryLabel(progressFreezeCategory)} - ${scope} - Summary`;
            const freezeLine = `Freeze Date: ${data.active.freeze_label || data.active.freeze_date || ""}`;
            const filtersLine = buildFreezeActiveFiltersLabel_();
            const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
            if (fmt === "PDF") {
                if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF({ orientation: "landscape" });
                doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                doc.setFontSize(9); doc.text(freezeLine, 148, 22, { align: "center" });
                doc.setFontSize(8); doc.setTextColor(80); doc.text(filtersLine, 148, 28, { align: "center" });
                doc.autoTable({
                    startY: 33, head: [headers], body: bodyRows, theme: "grid",
                    styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" },
                    headStyles: { fillColor: [8, 145, 178] },
                    didParseCell: function (hookData) {
                        if (hookData.section === "body") {
                            const flag = rowTypeFlags[hookData.row.index];
                            if (flag === 2) { hookData.cell.styles.fillColor = [219, 234, 254]; hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [159, 18, 57]; }
                            else if (flag === 1) { hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [29, 78, 216]; }
                        }
                    }
                });
                savePdfDocumentForDevice(doc, `${fileName}.pdf`);
            } else {
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[reportTitle], [`Scope: ${scope}`], [freezeLine], [filtersLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
            }
            setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
        }

        // USER REQUEST (2026-09-14): DC level par bhi Division/Circle jaisa ek
        // "Summary Download" (Excel/PDF) chahiye - yeh HQ-wise summary (screen par
        // jo renderFreezeHqWiseSummaryHtml dikhata hai, wahi data) download karta
        // hai. DC-level ki poori consumer LIST (downloadRevenueFreezeReport) bilkul
        // untouched/alag button se hi milti rahegi ("Full List Download").
        function downloadRevenueFreezeHqWiseSummary(fmt, data, downloadTypeLabel) {
            if (!data || !data.active || !data.rowsWithStatus.length) return showToast("Download ke liye data nahi hai", false);
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
            const summaryRows = buildFreezeHqWiseSummaryRows(data.rowsWithStatus);
            const nameColLabel = revenueHqLabelUpper();
            const headers = [nameColLabel, "TOTAL CONSUMER", "PAID COUNT", "PAID AMT (LAKH)", "PENDING COUNT", "PENDING AMT (LAKH)", "PAID %", "PENDING %"];
            const bodyRows = summaryRows.map((r) => {
                const paidPercent = r.totalCount ? ((r.paidCount / r.totalCount) * 100).toFixed(1) : "0.0";
                const pendingPercent = r.totalCount ? ((r.pendingCount / r.totalCount) * 100).toFixed(1) : "0.0";
                return [r.name, r.totalCount, r.paidCount, formatRevenueLakhValue(r.paidAmount), r.pendingCount, formatRevenueLakhValue(r.pendingAmount), `${paidPercent}%`, `${pendingPercent}%`];
            });
            const scope = `DC - ${activeDC}`;
            const reportTitle = `Freeze-Revenue Report - ${getRevenueFreezeCategoryLabel(progressFreezeCategory)} - ${scope} - Summary`;
            const freezeLine = `Freeze Date: ${data.active.freeze_label || data.active.freeze_date || ""}`;
            const filtersLine = buildFreezeActiveFiltersLabel_();
            const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
            if (fmt === "PDF") {
                if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF({ orientation: "landscape" });
                doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                doc.setFontSize(9); doc.text(freezeLine, 148, 22, { align: "center" });
                doc.setFontSize(8); doc.setTextColor(80); doc.text(filtersLine, 148, 28, { align: "center" });
                doc.autoTable({
                    startY: 33, head: [headers], body: bodyRows, theme: "grid",
                    styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" },
                    headStyles: { fillColor: [8, 145, 178] }
                });
                savePdfDocumentForDevice(doc, `${fileName}.pdf`);
            } else {
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[reportTitle], [`Scope: ${scope}`], [freezeLine], [filtersLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
            }
            setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Freeze summary download nahi ho payi", false);
            }
        }

        function renderRevenueNonPayeeGroupSummaryHtml(normalizedRows) {
            const summary = buildRevenueNonPayeeGroupSummary(normalizedRows);
            let html = `<div style="font-size:0.62rem; font-weight:900; color:#9f1239; text-align:center; margin-top:10px;">${escapeHtml(summary.colLabel)} WISE SUMMARY</div>
                <div class="summary-wrapper" style="margin-top:6px;"><div class="summary-table-header" style="grid-template-columns: 1.5fr 0.75fr 1fr;"><div>${escapeHtml(summary.colLabel)}</div><div>COUNT</div><div>PENDING</div></div>`;
            if (!summary.rows.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Data nahi mila.</div></div>`;
            } else {
                summary.rows.forEach((row) => {
                    // USER REQUEST (2026-09-14): SUB_TOTAL (Division total) aur GRAND_TOTAL
                    // row pehle dono hi "blue-bold" (same colour) the - ab Freeze Report
                    // jaisa hi alag TEXT COLOUR se alag pehchane jaate hain (app ke apne
                    // existing subdn-bold/blue-bold classes reuse kiye - SUB_TOTAL = orange,
                    // GRAND_TOTAL = blue, jaisa baaki reports me DIV_TOTAL/SUBDN_TOTAL ke
                    // liye pehle se istemal hota hai).
                    const rowClass = row.type === "GRAND_TOTAL" ? " blue-bold" : (row.type === "SUB_TOTAL" ? " subdn-bold" : "");
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: 1.5fr 0.75fr 1fr;"><div>${escapeHtml(row.name)}</div><div class="font-black">${row.count}</div><div class="text-rose-700 font-black">${formatProgressReportAmount(row.pendingTotal)}</div></div>`;
                });
            }
            html += `</div>`;
            return html;
        }

        function renderRevenueProgressFreezeSummaryHtml() {
            // USER REQUEST (2026-09-13): Yeh category dropdown (NP3/NP6/Since
            // Connection/Top20/Top50) baaki filter dropdowns (DC/HQ/Village/
            // Category/Slab/Govt - orange border, white background) se alag
            // dikhna chahiye taaki confuse na ho ki "yeh dropdown alag/important
            // hai" - isliye ab solid teal background + white bold text (sabhi
            // scope - DC/Division/Circle - par, kyonki yeh ek hi shared function
            // hai).
            const categorySelectHtml = `
                <select onchange="setProgressFreezeCategory(this.value)" style="width:100%; height:46px; margin:8px auto 0; display:block; border:2px solid #0e7490; border-radius:12px; padding:0 12px; font-size:0.8rem; font-weight:900; color:#ffffff; background:#0891b2; box-shadow:0 2px 6px rgba(8,145,178,0.35);">
                    <option value="" ${progressFreezeCategory === "" ? "selected" : ""} disabled style="color:#64748b; background:#f1f5f9; font-weight:900;">Choose Report Type</option>
                    <option value="NP3" ${progressFreezeCategory === "NP3" ? "selected" : ""} style="color:#1d4ed8; background:#eff6ff; font-weight:900;">Non Payee From 3 Month</option>
                    <option value="NP6" ${progressFreezeCategory === "NP6" ? "selected" : ""} style="color:#7e22ce; background:#faf5ff; font-weight:900;">Non Payee From 6 Month</option>
                    <option value="SINCE_CONNECTION" ${progressFreezeCategory === "SINCE_CONNECTION" ? "selected" : ""} style="color:#0e7490; background:#ecfeff; font-weight:900;">Non Payee From Date of Connection</option>
                    <option value="TOP20" ${progressFreezeCategory === "TOP20" ? "selected" : ""} style="color:#c2410c; background:#fff7ed; font-weight:900;">Top 20 Defaulters</option>
                    <option value="TOP50" ${progressFreezeCategory === "TOP50" ? "selected" : ""} style="color:#9f1239; background:#fff1f2; font-weight:900;">Top 50 Defaulters</option>
                </select>`;
            // USER REQUEST (2026-09-12): Jab tak is dropdown se koi report na
            // chuna jaaye, koi bhi sync/fetch nahi - seedha ek placeholder
            // message dikhega (jaise upar wale "Choose Report Type" ka flow).
            if (!progressFreezeCategory) {
                return `${categorySelectHtml}<div style="text-align:center; color:#64748b; font-size:0.72rem; font-weight:800; padding:20px 0;">Upar diye gaye dropdown se report type chunein.</div>`;
            }
            if (progressFreezeLoading || !lastRevenueProgressFreezeResult) {
                return `${categorySelectHtml}<div style="text-align:center; font-size:0.72rem; font-weight:900; color:#1d4ed8; padding:20px 0;">SYNCING DATA... PLEASE WAIT<div class="app-sync-spinner"></div></div>`;
            }
            const data = computeRevenueFreezeReportData();
            if (!data || data.error) {
                // BUG FIX (2026-09-13): Pehle yahan sirf error text tha, user ko
                // dropdown se category dobara chunkar retry karna padta tha - ab
                // seedha "Try Again" button (jaise network/large-DC-data wali baar
                // chalti hai, dobara try karne par aksar chal jaata hai).
                return `${categorySelectHtml}<div style="text-align:center; color:#991b1b; font-size:0.72rem; margin-top:10px;">Freeze data load nahi ho payi (network slow ho sakta hai, khaaskar badi DC me)</div><button class="btn-unique" style="width:100%; margin-top:8px; background:#0891b2; color:#fff;" onclick="retryFreezeModuleLoad()">Try Again</button>`;
            }
            if (!data.active) {
                return `${categorySelectHtml}<div style="text-align:center; color:#9f1239; font-size:0.72rem; margin-top:10px;">Abhi tak koi Freeze active nahi hai. Sub DN Chhapara ke Admin panel se "🔒 ADMIN FREEZE CONTROL" me Freeze Now karein.</div>`;
            }
            // BUG FIX (2026-09-13): Agar is DC ka snapshot fetch (fetchRevenueFreezeSnapshotRows)
            // baar-baar koshish karne ke baad bhi fail ho (jaise sabse badi DC ka
            // bahut bada NP3/NP6/SinceConnection data), to ab poora report generic
            // "load nahi ho payi" nahi dikhata (jo pehle throw hoke yahan tak aata
            // tha) - us DC ko sirf "ERROR" status milta hai, aur DC-level par yeh
            // saaf, alag message dikhta hai (Division/Circle se yeh DC merge se
            // bahar nahi hoti, sirf uska data is dafa miss ho sakta hai).
            if (activeViewLevel === "DC" && (lastRevenueProgressFreezeResult?.dcStatusMap?.[normalizeDcName(activeDC)] === "ERROR")) {
                return `${categorySelectHtml}<div style="text-align:center; color:#991b1b; font-size:0.72rem; margin-top:10px;">Is DC (${escapeHtml(activeDC)}) ka Freeze data abhi load nahi ho saka (data bada hone ki wajah se time lag raha hai). Kripya "Try Again" dabayein.</div><button class="btn-unique" style="width:100%; margin-top:8px; background:#0891b2; color:#fff;" onclick="retryFreezeModuleLoad()">Try Again</button>`;
            }
            // Is DC ko Admin ne individually UNFREEZE kiya ho sakta hai (baaki DC
            // ka data disturb kiye bina) - aisi surat me DC-level report yahi
            // saaf message dikhati hai, aur Division/Circle report se yeh DC
            // apne aap merge se bahar rehti hai (fetchRevenueFreezeSnapshotRowsForScope).
            if (activeViewLevel === "DC" && (lastRevenueProgressFreezeResult?.dcStatusMap?.[normalizeDcName(activeDC)] === "UNFROZEN")) {
                return `${categorySelectHtml}<div style="text-align:center; color:#9f1239; font-size:0.72rem; margin-top:10px;">Is DC (${escapeHtml(activeDC)}) ko is Freeze se individually UNFREEZE kiya gaya hai. Admin panel se "Reactivate" karke dubara chalu karein.</div>`;
            }
            const showDcColumn = activeViewLevel !== "DC";
            const t = data.totals;
            // USER REQUEST (2026-09-12): "Revenue ki same format" - NP3/NP6/Since
            // Connection me Non-Payee jaisa 5-filter set (HQ/Village/Category/Net
            // Bill Slab/Govt-NonGovt, + DC jab scope DC na ho), aur Top 20/50 me
            // Top Defaulters jaisa sirf Govt/Non-Govt filter.
            const allScoped = data.allScopedRows || [];
            let filterBlockHtml = "";
            if (isFreezeCategoryDefaultersType()) {
                filterBlockHtml = `
                    <select onchange="setFreezeDefaultersGovtFilter(this.value)" style="width:100%; height:44px; margin:8px auto 0; display:block; border:1.5px solid #fda4af; border-radius:12px; padding:0 12px; font-size:0.76rem; font-weight:900; color:#0f172a; background:#ffffff;">
                        <option value="">All (Govt + Non Govt)</option>
                        <option value="GOVT" ${freezeDefaultersGovtFilter === "GOVT" ? "selected" : ""}>Govt</option>
                        <option value="NONGOVT" ${freezeDefaultersGovtFilter === "NONGOVT" ? "selected" : ""}>Non Govt</option>
                    </select>`;
            } else {
                const f = freezeNonPayeeFilterState;
                const dcScoped = allScoped.filter((row) => !f.dc || normalizeDcName(row.dc_name) === normalizeDcName(f.dc));
                const villageScoped = dcScoped.filter((row) => !f.hq || normalizeLookupValue(row.hq_name) === normalizeLookupValue(f.hq));
                const dcOptionsHtml = buildFreezeOptionsHtml(getRevenueUniqueValues(allScoped, "dc_name"), f.dc, "All DC");
                const hqOptionsHtml = buildFreezeOptionsHtml(getRevenueUniqueValues(dcScoped, "hq_name"), f.hq, revenueHqAllLabel(f.dc || activeDC));
                const villageOptionsHtml = buildFreezeOptionsHtml(getRevenueUniqueValues(villageScoped, "village"), f.village, revenueVillageAllLabel(f.dc || activeDC));
                const categoryOptionsHtml = buildFreezeOptionsHtml(getRevenueUniqueValues(allScoped, "tariff_category"), f.category, "All Categories");
                const freezeSelectStyle = "width:100%; height:46px; margin:8px auto 0; display:block; border:1.5px solid #fb923c; border-radius:14px; padding:0 12px; font-size:0.8rem; font-weight:900; color:#0f172a; background:#ffffff;";
                filterBlockHtml = `
                    ${showDcColumn ? `<select onchange="setFreezeNonPayeeFilter('dc', this.value)" style="${freezeSelectStyle}">${dcOptionsHtml}</select>` : ""}
                    <select onchange="setFreezeNonPayeeFilter('hq', this.value)" style="${freezeSelectStyle}">${hqOptionsHtml}</select>
                    <select onchange="setFreezeNonPayeeFilter('village', this.value)" style="${freezeSelectStyle}">${villageOptionsHtml}</select>
                    <select onchange="setFreezeNonPayeeFilter('category', this.value)" style="${freezeSelectStyle}">${categoryOptionsHtml}</select>
                    <select onchange="setFreezeNonPayeeFilter('slab', this.value)" style="${freezeSelectStyle}">
                        <option value="">All Net Bill Slabs</option>
                        <option value="0-500" ${f.slab === "0-500" ? "selected" : ""}>₹0 - ₹500</option>
                        <option value="500-1000" ${f.slab === "500-1000" ? "selected" : ""}>₹500 - ₹1,000</option>
                        <option value="1000-5000" ${f.slab === "1000-5000" ? "selected" : ""}>₹1,000 - ₹5,000</option>
                        <option value="5000-10000" ${f.slab === "5000-10000" ? "selected" : ""}>₹5,000 - ₹10,000</option>
                        <option value="10000-25000" ${f.slab === "10000-25000" ? "selected" : ""}>₹10,000 - ₹25,000</option>
                        <option value="25000+" ${f.slab === "25000+" ? "selected" : ""}>₹25,000 Above</option>
                    </select>
                    <select onchange="setFreezeNonPayeeFilter('govt', this.value)" style="${freezeSelectStyle}">
                        <option value="">All (Govt + Non Govt)</option>
                        <option value="GOVT" ${f.govt === "GOVT" ? "selected" : ""}>Govt</option>
                        <option value="NONGOVT" ${f.govt === "NONGOVT" ? "selected" : ""}>Non Govt</option>
                    </select>`;
            }
            let html = `
                <div style="font-size:0.75rem; font-weight:950; color:#0e7490; text-align:center;">Freeze-Revenue Report - ${escapeHtml(getRevenueFreezeCategoryLabel(progressFreezeCategory))}</div>
                <div style="font-size:0.6rem; font-weight:800; color:#64748b; text-align:center; margin-top:2px;">Freeze Date: ${escapeHtml(data.active.freeze_label || data.active.freeze_date || "")}</div>
                ${categorySelectHtml}
                ${filterBlockHtml}
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:10px auto 0;">
                    <div style="background:#f0fdfa; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#0e7490; text-transform:uppercase;">Total Frozen</div><div style="font-size:0.95rem; font-weight:950; color:#0e7490; margin-top:2px;">${t.totalCount}</div></div>
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid Till Now</div><div style="font-size:0.95rem; font-weight:950; color:#166534; margin-top:2px;">${t.paidCount} (${t.paidPercent}%)</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Pending</div><div style="font-size:0.95rem; font-weight:950; color:#9f1239; margin-top:2px;">${t.pendingCount}</div></div>
                </div>
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:8px auto 0;">
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid Amount (since freeze)</div><div style="font-size:0.85rem; font-weight:950; color:#166534; margin-top:2px;">${formatProgressReportAmount(t.paidAmount)}</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Pending Amount (abhi bakaya)</div><div style="font-size:0.85rem; font-weight:950; color:#9f1239; margin-top:2px;">${formatProgressReportAmount(t.pendingAmount)}</div></div>
                    <div style="background:#f0fdfa; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#0e7490; text-transform:uppercase;">Frozen Total Amount</div><div style="font-size:0.85rem; font-weight:950; color:#0e7490; margin-top:2px;">${formatProgressReportAmount(t.totalFrozenAmount)}</div></div>
                </div>
                ${!isFreezeCategoryDefaultersType() ? (
                    activeViewLevel === "DC"
                        ? renderFreezeHqWiseSummaryHtml(data.rowsWithStatus)
                        : renderFreezeDcWiseSummaryHtml(data.rowsWithStatus)
                ) : ""}
                ${(activeViewLevel === "DC" && !isFreezeCategoryDefaultersType()) ? `
                <div style="font-size:0.56rem; font-weight:850; color:#64748b; text-align:center; margin-top:10px;">SUMMARY DOWNLOAD (${escapeHtml(revenueHqLabelUpper())} WISE)</div>
                <div class="btn-export-row" style="margin-top:4px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadRevenueFreezeHqWiseSummary('XLS', computeRevenueFreezeReportData(), 'Excel')">Summary Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadRevenueFreezeHqWiseSummary('PDF', computeRevenueFreezeReportData(), 'PDF')">Summary PDF</button>
                </div>
                <div style="font-size:0.56rem; font-weight:850; color:#64748b; text-align:center; margin-top:10px;">FULL LIST DOWNLOAD</div>
                <div class="btn-export-row" style="margin-top:4px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadRevenueFreezeReport('XLS')">Full List Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadRevenueFreezeReport('PDF')">Full List PDF</button>
                </div>
                ` : `
                <div class="btn-export-row" style="margin-top:10px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadRevenueFreezeReport('XLS')">Freeze Report Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadRevenueFreezeReport('PDF')">Freeze Report PDF</button>
                </div>
                `}
                <div id="progress-category-download-status" style="display:none; text-align:center; font-weight:900; border-radius:14px; padding:8px 10px; width:100%; margin-top:8px;"></div>
            `;
            // USER REQUEST (2026-09-13): Division/Circle adhikari sirf SUMMARY
            // dekhte hain (upar wale tiles + HQ/DC-wise summary table hi kaafi
            // hai) - NP3/NP6/Since Connection ki poori consumer-list ab sirf DC
            // level par hi dikhegi (jaisa pehle se thi, bilkul untouched). Top
            // 20/50 Defaulters (isFreezeCategoryDefaultersType()) is change se
            // bahar hai - wo har scope par pehle jaisi list hi dikhati rahegi.
            const showFreezeConsumerList = activeViewLevel === "DC" || isFreezeCategoryDefaultersType();
            if (showFreezeConsumerList) {
                html += `<div class="summary-wrapper" style="margin-top:10px;"><div class="summary-table-header" style="grid-template-columns: ${showDcColumn ? "0.8fr 1.2fr 0.8fr 1fr" : "1.4fr 0.8fr 1fr"};">${showDcColumn ? "<div>DC</div>" : ""}<div>CONSUMER</div><div>STATUS</div><div>AMOUNT</div></div>`;
                if (!data.rowsWithStatus.length) {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Is scope me freeze me koi consumer nahi mila.</div></div>`;
                } else {
                    // USER REQUEST (2026-09-13): Top 20/50 Defaulters me "All (Govt +
                    // Non Govt)" chunne par ab poori Non Govt Top N pehle, ek divider
                    // line, fir poori Govt Top N - alag-alag dikhti hai (jaisa Live
                    // Top Defaulters me bhi kiya). Govt/Non Govt akela chunne par
                    // pehle jaisa hi single seedhi list dikhegi.
                    const freezeTopLimit = progressFreezeCategory === "TOP20" ? 20 : 50;
                    const showFreezeSplit = isFreezeCategoryDefaultersType() && !freezeDefaultersGovtFilter;
                    const renderFreezeRow = (r) => {
                        const cells = [];
                        if (showDcColumn) cells.push(`<div>${escapeHtml(r.dc_name || "-")}</div>`);
                        cells.push(`<div>${escapeHtml(r.consumer_name || "-")}<br><span style="font-size:0.56rem; color:#64748b;">${escapeHtml(r.hq_name || "")} / ${escapeHtml(r.village || "")}</span></div>`);
                        const paidStatusLabel = escapeHtml(getFreezeRowStatusLabel(r));
                        // USER REQUEST (2026-09-12): PAID wale row ka status text
                        // GREEN me, PART PAID wale row ka status text RED me dikhe
                        // (pure PENDING - koi payment nahi - normal/default colour
                        // me hi rahega). Row ki POSITION/sequence isse bilkul nahi
                        // badalta, sirf colour se pehchana jaata hai.
                        const statusColor = r.isPaidNow ? "#166534" : (r.paidAmountNow > 0 ? "#dc2626" : "#1e293b");
                        cells.push(`<div class="font-black" style="color:${statusColor};">${paidStatusLabel}</div>`);
                        // BUG FIX (2026-09-14): PAID row ka AMOUNT bhi sirf is frozen
                        // bill (r.pending_amount) tak seemित, consumer ki poori
                        // purani payment history (r.paidAmountNow) tak nahi.
                        cells.push(`<div class="font-black">${formatProgressReportAmount(r.isPaidNow ? Number(r.pending_amount || 0) : r.remainingPending)}</div>`);
                        return `<div class="summary-table-row" style="grid-template-columns: ${showDcColumn ? "0.8fr 1.2fr 0.8fr 1fr" : "1.4fr 0.8fr 1fr"};">${cells.join("")}</div>`;
                    };
                    const dividerRow = (label, color, bg) => `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div style="text-align:center; font-weight:900; color:${color}; background:${bg}; border-radius:8px; padding:5px; margin-top:${label.startsWith("GOVT") ? "6px" : "0"};">${label}</div></div>`;
                    if (showFreezeSplit) {
                        const nonGovtRows = data.rowsWithStatus.filter((r) => r.govt_flag !== "GOVT").slice(0, freezeTopLimit);
                        const govtRows = data.rowsWithStatus.filter((r) => r.govt_flag === "GOVT").slice(0, freezeTopLimit);
                        if (nonGovtRows.length) {
                            html += dividerRow(`NON GOVT - TOP ${nonGovtRows.length}`, "#166534", "#f0fdf4");
                            nonGovtRows.forEach((r) => { html += renderFreezeRow(r); });
                        }
                        if (govtRows.length) {
                            html += dividerRow(`GOVT - TOP ${govtRows.length}`, "#9f1239", "#fff1f2");
                            govtRows.forEach((r) => { html += renderFreezeRow(r); });
                        }
                    } else {
                        data.rowsWithStatus.slice(0, 200).forEach((r) => { html += renderFreezeRow(r); });
                        if (data.rowsWithStatus.length > 200) {
                            html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div style="text-align:center; color:#64748b; font-size:0.62rem; padding:6px;">... ${data.rowsWithStatus.length - 200} aur consumer, poori list Excel/PDF download me milegi</div></div>`;
                        }
                    }
                }
                html += `</div>`;
            }
            return html;
        }

        function downloadRevenueFreezeReport(fmt) {
            const data = computeRevenueFreezeReportData();
            if (!data || !data.active || !data.rowsWithStatus.length) return showToast("Download ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                // USER REQUEST (2026-09-13): Division/Circle par screen jaisa hi -
                // NP3/NP6/Since Connection ke download me ab poori consumer-list
                // NAHI, sirf DC-wise SUMMARY jaati hai (Total Consumer, Paid
                // count+amount, Pending count+amount, + Paid%/Pending% jo sirf
                // download me hai). DC-level (jahan poori list hi sahi/zaroori
                // hai) aur Top 20/50 Defaulters (jo har scope par apni list hi
                // dikhata/download karta hai) is change se bahar hain, bilkul
                // untouched.
                if (activeViewLevel !== "DC" && !isFreezeCategoryDefaultersType()) {
                    return downloadRevenueFreezeDcWiseSummary(fmt, data, downloadTypeLabel);
                }
                const showDcColumn = activeViewLevel !== "DC";
                const headers = [...(showDcColumn ? ["DC NAME"] : []), "IVRS NO", "CONSUMER NAME", "HQ", "VILLAGE", "MOBILE NO", "STATUS", "AMOUNT"];
                // USER REQUEST (2026-09-12): PAID row GREEN me, PART PAID row
                // RED me dikhna chahiye (PDF me actual colour se, CSV/"Excel"
                // me chunki plain text file hoti hai colour support nahi
                // karti - isliye wahan alag "**"/"++" marker laga kar visually
                // alag kiya gaya hai). Row ka POSITION (sequence) isse bilkul
                // nahi badalta - sirf STATUS cell ka colour/marker alag hai.
                const statusColIndex = showDcColumn ? 6 : 5;
                // 2 = fully PAID (green), 1 = PART PAID (red), 0 = pure PENDING (default),
                // -1 = group-header/divider row (no colour)
                // USER REQUEST (2026-09-13): Top 20/50 Defaulters ke download (Excel/PDF)
                // me bhi screen jaisa hi - "All" filter me pehle poori Non Govt Top N,
                // ek divider row, fir poori Govt Top N. Baaki categories/filters me
                // pehle jaisi hi seedhi list.
                const freezeTopLimit = progressFreezeCategory === "TOP20" ? 20 : 50;
                const showFreezeSplit = isFreezeCategoryDefaultersType() && !freezeDefaultersGovtFilter;
                const paymentStateFlags = [];
                const bodyRows = [];
                const pushFreezeRow = (r) => {
                    bodyRows.push([
                        ...(showDcColumn ? [r.dc_name || ""] : []),
                        r.ivrs_no || "", r.consumer_name || "", r.hq_name || "", r.village || "", r.mobile_no || "",
                        getFreezeRowStatusLabel(r),
                        // BUG FIX (2026-09-14): dekhein upar wale comments - PAID row ka
                        // AMOUNT sirf is frozen bill (pending_amount) tak seemित.
                        formatProgressReportAmount(r.isPaidNow ? Number(r.pending_amount || 0) : r.remainingPending)
                    ]);
                    paymentStateFlags.push(r.isPaidNow ? 2 : (r.paidAmountNow > 0 ? 1 : 0));
                };
                const pushFreezeGroupHeader = (label) => {
                    bodyRows.push([label, ...Array(headers.length - 1).fill("")]);
                    paymentStateFlags.push(-1);
                };
                if (showFreezeSplit) {
                    const nonGovtRows = data.rowsWithStatus.filter((r) => r.govt_flag !== "GOVT").slice(0, freezeTopLimit);
                    const govtRows = data.rowsWithStatus.filter((r) => r.govt_flag === "GOVT").slice(0, freezeTopLimit);
                    if (nonGovtRows.length) { pushFreezeGroupHeader(`NON GOVT - TOP ${nonGovtRows.length}`); nonGovtRows.forEach(pushFreezeRow); }
                    if (govtRows.length) { pushFreezeGroupHeader(`GOVT - TOP ${govtRows.length}`); govtRows.forEach(pushFreezeRow); }
                } else {
                    data.rowsWithStatus.forEach(pushFreezeRow);
                }
                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const reportTitle = `Freeze-Revenue Report - ${getRevenueFreezeCategoryLabel(progressFreezeCategory)} - ${scope}`;
                const freezeLine = `Freeze Date: ${data.active.freeze_label || data.active.freeze_date || ""}`;
                const filtersLine = buildFreezeActiveFiltersLabel_();
                const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(freezeLine, 148, 22, { align: "center" });
                    doc.setFontSize(8); doc.setTextColor(80); doc.text(filtersLine, 148, 28, { align: "center" });
                    doc.autoTable({
                        startY: 33, head: [headers], body: bodyRows, theme: "grid",
                        styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" },
                        headStyles: { fillColor: [8, 145, 178] },
                        didParseCell: function (hookData) {
                            if (hookData.section === "body" && hookData.column.index === statusColIndex) {
                                const state = paymentStateFlags[hookData.row.index];
                                if (state === 2) { hookData.cell.styles.textColor = [22, 101, 52]; hookData.cell.styles.fontStyle = "bold"; }
                                else if (state === 1) { hookData.cell.styles.textColor = [220, 38, 38]; hookData.cell.styles.fontStyle = "bold"; }
                            }
                        }
                    });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    // CSV plain text hai, colour nahi ho sakta - isliye PAID
                    // rows ke STATUS ke aage-peeche "++" aur PART PAID rows ke
                    // aage-peeche "**" laga diya taaki Excel me khulne par bhi
                    // wo alag pehchane ja sakein.
                    bodyRows.forEach((row, i) => {
                        const state = paymentStateFlags[i];
                        if (state === 2) row[statusColIndex] = `++ ${row[statusColIndex]} ++`;
                        else if (state === 1) row[statusColIndex] = `** ${row[statusColIndex]} **`;
                    });
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [freezeLine], [filtersLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Freeze report download nahi ho payi", false);
            }
        }
        // ===== End Revenue Freeze Tracking =====

        // Category Wise / Non-Payee / Target vs Achievement / Top Defaulters reports
        // ko per-consumer amount/date/category chahiye (sirf IVRS list se kaam nahi
        // chalega), lekin poori nested payment_rows duplication (jo purane endpoint
        // me har row do baar bhejta tha) inhe bhi nahi chahiye - sirf ek flat set of
        // fields kaafi hai. Yeh naya "getUploadedPaidCategoryList" action wahi flat
        // data deta hai, jisse bade DC (SEONI (T) jaisे) ke liye bhi response chhota
        // aur fast rehta hai. Backend abhi purana ho to purane bhaari endpoint par
        // fallback ho jaata hai, koi feature todta nahi.
        async function fetchUploadedPaidCategoryListWithRetry_(dcName, attempts = 2) {
            for (let attempt = 1; attempt <= attempts; attempt++) {
                const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
                // BUG FIX (2026-09-10): DIVISION-level Paid Count Summary kuchh DC
                // (CHHAPARA-1, DHUMA, GHANSORE, LAKHNADON) ke liye 0%/blank dikhata
                // tha - data backend me sahi tha, par warmRevenueCategoryUploadedPaid-
                // Cache() DIVISION ke saare (~20+) DC ka fetch Promise.all se ek hi
                // jhatke me chala deta tha, jisse Apps Script execution quota par
                // contention hoti thi aur bade PAID MASTER sheet wale DC ka doGet
                // queue me fasa reh jaata tha. ASLI FIX neeche runWithConcurrency-
                // Limit_() hai (ek time par sirf 5 DC ka request jaata hai, baki
                // queue me wait karte hain) - isse per-DC contention khatam ho
                // jaati hai. (Yahan pehle timeout 60s->90s aur attempts 2->3 bhi
                // badha diye the, par usse SINGLE DC (DC-level) report bhi ulta
                // slow ho gayi thi - ek akela DC bhi ab network hiccup hone par
                // 3x90s tak wait karta tha, pehle sirf 2x60s. Wapas 60s/2 attempts
                // par rakha hai - single-DC case me contention hoti hi nahi,
                // isliye 60s kaafi hai; DIVISION ka contention concurrency-limit
                // se hi fix hota hai, timeout badhane se nahi.)
                const timer = setTimeout(() => { try { if (controller) controller.abort(); } catch (_) {} }, 60000);
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getUploadedPaidCategoryList&dc_name=${encodeURIComponent(dcName)}&t=${Date.now()}`, controller ? { signal: controller.signal } : {});
                        return await response.json();
                    });
                    if (parsed && parsed.status === "success" && Array.isArray(parsed.entries)) return parsed;
                } catch (_) {} finally {
                    clearTimeout(timer);
                }
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
            }
            return fetchUploadedPaidEntriesWithRetry_(dcName, attempts);
        }

        // Ek saath sabhi DC ka fetch chalane (Promise.all) ki jagah, ek chhoti si
        // concurrency-limited "pool" - ek time par sirf `limit` (5) DC ka request
        // Apps Script ko jaata hai, baki queue me wait karte hain. Isse Apps Script
        // par load kam hota hai aur bade DC (CHHAPARA-1, DHUMA, GHANSORE, LAKHNADON
        // jaise) ko apna turn milte hi poora time milta hai jawab dene ke liye,
        // instead of 20+ requests ke saath compete karne ke.
        async function runWithConcurrencyLimit_(items, limit, worker) {
            let cursor = 0;
            async function runNext() {
                while (cursor < items.length) {
                    const index = cursor++;
                    await worker(items[index], index);
                }
            }
            const poolSize = Math.max(1, Math.min(limit, items.length));
            await Promise.all(Array.from({ length: poolSize }, () => runNext()));
        }

        // Pehle ye function har baar call hone par (panel khulte waqt + phir dropdown me
        // report select karte waqt + phir Download dabate waqt) sabhi target DC ka data
        // dobara network se fetch kar deta tha, chahe kuch second pehle hi wahi data aa
        // chuka ho - isi wajah se Daily Progress Revenue reports (Category/Target/
        // Defaulters/Non Payee, saat me se 6) slow feel hote the. Ab har DC ke liye last
        // warm hone ka time yaad rakhte hain aur agar 60 second ke andar dobara call ho to
        // us DC ko skip kar dete hain (forceRefresh=true dene par hamesha fresh fetch
        // hoga). DC-agnostic - sabhi 24 DC par apne aap lagu.
        const revenueCategoryCacheWarmedAt = {};
        const REVENUE_CATEGORY_CACHE_TTL_MS = 60000;
        async function warmRevenueCategoryUploadedPaidCache(forceRefresh = false) {
            if (!revenueCollectionSubmitScriptUrl) return;
            const allDcNames = Array.from(new Set(getRevenueCategoryTargetDcs().map((dcName) => normalizeDcName(dcName)).filter(Boolean)));
            const now = Date.now();
            const dcNames = forceRefresh
                ? allDcNames
                : allDcNames.filter((dcName) => now - (revenueCategoryCacheWarmedAt[dcName] || 0) > REVENUE_CATEGORY_CACHE_TTL_MS);
            if (!dcNames.length) return;
            await runWithConcurrencyLimit_(dcNames, 5, async (dcName) => {
                const parsed = await fetchUploadedPaidCategoryListWithRetry_(dcName);
                if (!parsed) return;
                const rows = Array.isArray(parsed?.entries) ? parsed.entries : (Array.isArray(parsed?.data) ? parsed.data : []);
                const localCache = getRevenueUploadedPaidCache();
                const mergedRows = rows.map((row) => {
                    const ivrs = getRevenueUploadedPaidRowIvrs(row);
                    const resolvedDc = getRevenueUploadedPaidRowDcName(row, dcName);
                    const localRow = localCache[getRevenueUploadedPaidCacheKey(ivrs, resolvedDc)];
                    let remotePaymentRows = row?.paymentRows || row?.payment_rows || row?.payments || row?.paymentDetails || [];
                    let localPaymentRows = localRow?.paymentRows || localRow?.payment_rows || localRow?.payments || localRow?.paymentDetails || [];
                    if (typeof remotePaymentRows === "string") {
                        try { remotePaymentRows = JSON.parse(remotePaymentRows); } catch (_) { remotePaymentRows = []; }
                    }
                    if (typeof localPaymentRows === "string") {
                        try { localPaymentRows = JSON.parse(localPaymentRows); } catch (_) { localPaymentRows = []; }
                    }
                    if ((!Array.isArray(remotePaymentRows) || !remotePaymentRows.length) && Array.isArray(localPaymentRows) && localPaymentRows.length) {
                        return {
                            ...row,
                            paymentRows: localPaymentRows,
                            payment_rows: localPaymentRows,
                            paymentCount: localPaymentRows.length,
                            payment_count: localPaymentRows.length
                        };
                    }
                    return row;
                });
                saveRevenueUploadedPaidEntriesLocalBulk(mergedRows, dcName, true);
                revenueCategoryCacheWarmedAt[dcName] = Date.now();
            });
        }

        function buildRevenueCategoryUploadedPaidInfo(mode, filterValue) {
            // ISOLATED ADDITION (2026-09-17, USER-APPROVED corrections): agar naye
            // backend reconciliation endpoint (getRevenueCategoryReconciliation) se
            // is exact mode+filterValue ke liye pehle se hi ensureRevenueCategory-
            // ReconciliationLoaded() ke through data warm ho chuka hai (caller
            // hamesha isse pehle await karta hai), to usi EXACT-DATE-capable,
            // per-consumer aggregate ko authoritative maan kar seedhe return karo -
            // neeche wala poora legacy computation (raw/local cache "more rows
            // wins" heuristic + uploaded-month matching) bilkul chhua nahi jaata,
            // aur sirf tab chalta hai jab reconciliation backend available na ho
            // (purana/redeploy-na-hua backend - capability mismatch fallback).
            //
            // Backward-compatible shape: normalCount/normalAmount/categoryTotals
            // jaise purane field bhi bhar dete hain, taaki isRevenueMasterConsumer-
            // Paid()/getRevenueMasterConsumerPaidAmount() (Particular Consumer
            // List, Non-Payee 3M/6M/Since-Connection, Top Defaulters - inn sabhi
            // reports ka apna khud ka koi code yahan CHHUA nahi gaya) bilkul
            // unchanged rehte hue bhi sahi kaam karte rahein.
            const reconciliation = revenueCategoryReconciliationCache_.get(
                revenueCategoryReconciliationCacheKey_(mode, filterValue, getRevenueCategoryTargetDcs())
            );
            if (reconciliation && reconciliation.supported) {
                const paidInfoByDc = {};
                getRevenueCategoryTargetDcs().forEach((dcName) => {
                    const normalizedDc = normalizeDcName(dcName);
                    if (!normalizedDc) return;
                    const dcInfo = paidInfoByDc[normalizedDc] || {};
                    Object.defineProperty(dcInfo, "__reconciledScope", {
                        value: true,
                        enumerable: false,
                        configurable: false
                    });
                    paidInfoByDc[normalizedDc] = dcInfo;
                });
                reconciliation.byKey.forEach((info, key) => {
                    const sepIdx = key.indexOf("|");
                    if (sepIdx < 0) return;
                    const dcName = key.slice(0, sepIdx);
                    const ivrs = key.slice(sepIdx + 1);
                    if (!dcName || !ivrs) return;
                    if (!paidInfoByDc[dcName]) paidInfoByDc[dcName] = {};
                    const amount = Number(info.amount || 0);
                    paidInfoByDc[dcName][ivrs] = {
                        reconciled: true,
                        amount,
                        category: info.category || "",
                        legacyAmbiguous: !!info.legacyAmbiguous,
                        normalCount: amount > 0 ? 1 : 0,
                        normalAmount: amount > 0 ? amount : 0,
                        agAmount: 0, agCount: 0,
                        mixedAmount: 0, mixedCount: 0,
                        unknownAmount: 0, unknownCount: 0,
                        categoryTotals: (amount > 0 && info.category) ? { [info.category]: { amount, count: 1 } } : {}
                    };
                });
                return paidInfoByDc;
            }
            const paidInfoByDc = {};
            getRevenueCategoryPaymentSourceRows().forEach((paymentRow) => {
                const dcName = getRevenueUploadedPaidRowDcName(paymentRow);
                const ivrs = getRevenueUploadedPaidRowIvrs(paymentRow);
                if (!dcName || !ivrs || !isRevenueUploadedPaidInCategoryPeriod(paymentRow, mode, filterValue)) return;
                if (!paidInfoByDc[dcName]) paidInfoByDc[dcName] = {};
                const existing = paidInfoByDc[dcName][ivrs] || {
                    normalAmount: 0, normalCount: 0,
                    agAmount: 0, agCount: 0,
                    unknownAmount: 0, unknownCount: 0,
                    mixedAmount: 0, mixedCount: 0,
                    categoryTotals: {}
                };
                const sourceType = normalizeLookupValue(paymentRow?.sourceType || paymentRow?.source_type || "");
                const hasNormalSource = sourceType.includes("NORMAL");
                const hasAgSource = sourceType.includes("AG");
                const sourceBucket = hasNormalSource && hasAgSource
                    ? "mixed"
                    : (hasAgSource ? "ag" : (hasNormalSource ? "normal" : "unknown"));
                const rowAmount = getRevenueUploadedPaidRowAmount(paymentRow);
                existing[`${sourceBucket}Amount`] = Number(existing[`${sourceBucket}Amount`] || 0) + rowAmount;
                existing[`${sourceBucket}Count`] = Number(existing[`${sourceBucket}Count`] || 0) + 1;
                const rowCategory = getRevenueUploadedPaidRowCategory(paymentRow, sourceType);
                if (revenueCategoryList.includes(rowCategory) && !(sourceBucket === "normal" && rowCategory === "LV5")) {
                    const categoryEntry = existing.categoryTotals[rowCategory] || { amount: 0, count: 0 };
                    categoryEntry.amount += rowAmount;
                    categoryEntry.count += 1;
                    existing.categoryTotals[rowCategory] = categoryEntry;
                }
                paidInfoByDc[dcName][ivrs] = existing;
            });
            return paidInfoByDc;
        }

        // ISOLATED ADDITION (2026-09-17, USER-APPROVED): optional `rows` (already-
        // built buildRevenueCategorySummaryRows() output) - jab diya jaata hai to
        // OTHER-bucket (missing/unknown tariff category, valid Master consumer)
        // ke Paid/Unpaid count+amount bhi diagnostic me judte hain, taaki Grand
        // Total aur LV1-LV5 column-sum ke beech ka antar (agar ho) kis wajah se
        // hai yeh pata chal sake. `rows` na diya jaaye to bilkul purana behaviour
        // (koi other* field object me nahi aata) - is function ka ek hi caller
        // hai, isliye backward-compat sirf documentation ke liye hai.
        function buildRevenueCategoryDiagnostic(mode, filterValue, rows = null) {
            const targetDcs = new Set(getRevenueCategoryTargetDcs().map((dcName) => normalizeDcName(dcName)).filter(Boolean));
            const masterIvrsByDc = {};
            targetDcs.forEach((dcName) => {
                masterIvrsByDc[dcName] = new Set(getRevenueMasterRowsForDc(dcName).map((row) => normalizeRevenueIvrs(row.ivrsNo)).filter(Boolean));
            });

            let uploadedRows = 0;
            let selectedMonthRows = 0;
            let matchedMasterRows = 0;
            let outOfMonthRows = 0;
            let masterNotMatchedRows = 0;
            let missingDate = 0;

            getRevenueCategoryPaymentSourceRows().forEach((paymentRow) => {
                    const dcName = getRevenueUploadedPaidRowDcName(paymentRow);
                    const ivrs = getRevenueUploadedPaidRowIvrs(paymentRow);
                    if (!dcName || !ivrs || !targetDcs.has(dcName)) return;

                    uploadedRows += 1;
                    const targetMonthKey = mode === "MONTHLY"
                        ? normalizeRevenueMonthFilterKey(filterValue)
                        : getRevenueMonthKey(filterValue || getCurrentDateDDMMYYYY());
                    const paidDate = normalizeRevenuePaidDate(getRevenueUploadedPaidRowDate(paymentRow), targetMonthKey);
                    if (!paidDate) {
                        missingDate += 1;
                        return;
                    }

                    if (!isRevenueUploadedPaidInCategoryPeriod(paymentRow, mode, filterValue)) {
                        outOfMonthRows += 1;
                        return;
                    }

                    selectedMonthRows += 1;
                    if (masterIvrsByDc[dcName]?.has(ivrs)) {
                        matchedMasterRows += 1;
                    } else {
                        masterNotMatchedRows += 1;
                    }
            });

            let otherPaidCount = 0, otherUnpaidCount = 0, otherPaidAmount = 0, otherUnpaidAmount = 0;
            (rows || []).forEach((row) => {
                if (row.type === "SUB_TOTAL" || row.type === "SUBDN_TOTAL") return;
                const other = row.categories?.OTHER;
                if (!other) return;
                otherPaidCount += Number(other.paid || 0);
                otherUnpaidCount += Number(other.unpaid || 0);
                otherPaidAmount += Number(other.paidAmount || 0);
                otherUnpaidAmount += Number(other.unpaidAmount || 0);
            });

            return {
                uploadedUnique: uploadedRows,
                selectedMonth: selectedMonthRows,
                matchedMaster: matchedMasterRows,
                outOfMonth: outOfMonthRows,
                masterNotMatched: masterNotMatchedRows,
                missingDate,
                otherPaidCount,
                otherUnpaidCount,
                otherPaidAmount,
                otherUnpaidAmount
            };
        }

        function buildRevenueCategorySummaryRows(mode, filterValue) {
            const paidInfoByDc = buildRevenueCategoryUploadedPaidInfo(mode, filterValue);

            if (activeViewLevel === "DC") {
                const groups = {};
                const dcName = normalizeDcName(activeDC);
                const paidInfo = paidInfoByDc[dcName] || {};
                const paidCountedIvrsSet = new Set();
                getRevenueMasterRowsForDc(activeDC).forEach((row) => {
                    const hqName = String(row.hqName || "GENERAL").trim().toUpperCase() || "GENERAL";
                    if (!groups[hqName]) groups[hqName] = createRevenueCategoryGroup(hqName);
                    addRevenueCategoryConsumer(groups[hqName], row, paidInfo, paidCountedIvrsSet);
                });
                return Object.values(groups).sort((a, b) => String(a.name).localeCompare(String(b.name)));
            }

            if (activeViewLevel === "DIVISION") {
                const result = [];
                getDivisionSubDnGroups(activeDiv).forEach((group) => {
                    const groupRows = group.dcs.map((dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        const g = createRevenueCategoryGroup(normalizedDc);
                        const paidInfo = paidInfoByDc[normalizedDc] || {};
                        const paidCountedIvrsSet = new Set();
                        getRevenueMasterRowsForDc(dcName).forEach((row) => addRevenueCategoryConsumer(g, row, paidInfo, paidCountedIvrsSet));
                        return g;
                    });
                    result.push(...groupRows);
                    result.push(sumRevenueCategoryGroups(groupRows, `${group.subDn} SUB DIVISION SUB TOTAL`, { type: "SUBDN_TOTAL" }));
                });
                return result;
            }

            const rows = [];
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const divisionRows = [];
                getDivisionSubDnGroups(divisionName).forEach((group) => {
                    const groupRows = group.dcs.map((dcName) => {
                        const normalizedDc = normalizeDcName(dcName);
                        const g = createRevenueCategoryGroup(normalizedDc, { divisionName });
                        const paidInfo = paidInfoByDc[normalizedDc] || {};
                        const paidCountedIvrsSet = new Set();
                        getRevenueMasterRowsForDc(dcName).forEach((row) => addRevenueCategoryConsumer(g, row, paidInfo, paidCountedIvrsSet));
                        return g;
                    });
                    divisionRows.push(...groupRows);
                    rows.push(...groupRows);
                    rows.push(sumRevenueCategoryGroups(groupRows, `${group.subDn} SUB DIVISION SUB TOTAL`, { type: "SUBDN_TOTAL", divisionName }));
                });
                rows.push(sumRevenueCategoryGroups(divisionRows, getDivisionTotalLabel(divisionName), { type: "SUB_TOTAL", divisionName }));
            });
            return rows;
        }

        function sumRevenueCategoryGroups(list, name, extra = {}) {
            const totalGroup = createRevenueCategoryGroup(name, extra);
            (list || []).forEach((row) => {
                revenueCategoryList.forEach((category) => {
                    totalGroup.categories[category].paid += Number(row.categories?.[category]?.paid || 0);
                    totalGroup.categories[category].unpaid += Number(row.categories?.[category]?.unpaid || 0);
                    totalGroup.categories[category].paidAmount += Number(row.categories?.[category]?.paidAmount || 0);
                    totalGroup.categories[category].unpaidAmount += Number(row.categories?.[category]?.unpaidAmount || 0);
                });
                totalGroup.paidTotal += Number(row.paidTotal || 0);
                totalGroup.unpaidTotal += Number(row.unpaidTotal || 0);
                totalGroup.paidAmountTotal += Number(row.paidAmountTotal || 0);
                totalGroup.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0);
                // ISOLATED ADDITION (2026-09-17): __uniqueMasterCount rollup - taaki
                // SUB TOTAL/DIVISION TOTAL rows par bhi invariant check ho sake.
                totalGroup.__uniqueMasterCount = (totalGroup.__uniqueMasterCount || 0) + Number(row.__uniqueMasterCount || 0);
            });
            return totalGroup;
        }

        function getRevenueCategoryGrandTotals(rows) {
            const totals = createRevenueCategoryGroup("GRAND TOTAL");
            (rows || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").forEach((row) => {
                revenueCategoryList.forEach((category) => {
                    totals.categories[category].paid += Number(row.categories?.[category]?.paid || 0);
                    totals.categories[category].unpaid += Number(row.categories?.[category]?.unpaid || 0);
                    totals.categories[category].paidAmount += Number(row.categories?.[category]?.paidAmount || 0);
                    totals.categories[category].unpaidAmount += Number(row.categories?.[category]?.unpaidAmount || 0);
                });
                totals.paidTotal += Number(row.paidTotal || 0);
                totals.unpaidTotal += Number(row.unpaidTotal || 0);
                totals.paidAmountTotal += Number(row.paidAmountTotal || 0);
                totals.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0);
                totals.__uniqueMasterCount = (totals.__uniqueMasterCount || 0) + Number(row.__uniqueMasterCount || 0);
            });
            return totals;
        }

        let categoryDownloadProgressToken = 0;
        function setProgressCategoryDownloadState(isDownloading, message = "") {
            const status = document.getElementById("progress-category-download-status");
            const buttons = document.querySelectorAll("#progress-revenue-body .btn-export-row button");
            const statusMessage = normalizeActionStatusMessage(message, isDownloading, !String(message || "").toLowerCase().includes("nahi"));
            buttons.forEach((button) => {
                button.disabled = isDownloading;
                button.style.opacity = isDownloading ? "0.65" : "1";
                button.style.pointerEvents = isDownloading ? "none" : "auto";
            });
            categoryDownloadProgressToken++;
            if (status) {
                if (isDownloading) {
                    status.style.display = "block";
                    status.style.background = "#dbeafe";
                    status.style.color = "#1d4ed8";
                    renderSyncingProgress(status, ((token) => () => token === categoryDownloadProgressToken)(categoryDownloadProgressToken), statusMessage || "Downloading...");
                } else {
                    status.style.display = statusMessage ? "block" : "none";
                    status.textContent = statusMessage;
                    const failed = statusMessage === getActionStatusText("failed");
                    status.style.background = failed ? "#fff1f2" : "#dcfce7";
                    status.style.color = failed ? "#991b1b" : "#047857";
                }
            }
        }

        function getRevenueCategoryScopeLabel() {
            if (activeViewLevel === "DC") return `DC: ${activeDC}`;
            if (activeViewLevel === "DIVISION") return `Division: ${activeDiv}`;
            return "Circle: SEONI CIRCLE";
        }

        function formatRevenuePercent(numerator, denominator) {
            const num = Number(numerator) || 0;
            const den = Number(denominator) || 0;
            if (!den) return "0%";
            return `${((num / den) * 100).toFixed(1)}%`;
        }

        function exportRevenueCategorySummary(fmt, rows, label, reportType, diagnostic = null, staleWarning = null) {
            const levelT = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
            const firstCols = activeViewLevel === "CIRCLE" ? ["DIVISION", "DC NAME"] : [activeViewLevel === "DC" ? revenueHqLabelUpper() : "DC NAME"];
            // Naya layout: saari 5 category (LV1-LV5) + TOTAL ek hi table me cram karne
            // ki jagah, DO ALAG TABLE banate hain - dono me SAARI DC/HQ rows (same order,
            // repeat) rahengi:
            //   Table 1 (upar): DOMESTIC + NON DOMESTIC + PUBLIC WATER WORKS (3 block)
            //   Table 2 (niche): LT INDUSTRIAL + AGRICULTURE + TOTAL (3 block, TOTAL me
            //                    ab bhi baaki categories jaisa hi PAID %/PAID AMT % hai)
            // Har block same 6 metric-column shape follow karta hai (Paid, Paid %, Paid
            // Amt (L), Paid Amt %, Unpaid, Unpaid Amt (L)) - isliye "3 upar 3 niche, 6-6
            // column ke block" wala flow bana rehta hai, sirf columns kam (3 category
            // per table) hone se har block wide/bada text me dikhta hai.
            const groupACategories = revenueCategoryList.slice(0, 3);
            const groupBCategories = revenueCategoryList.slice(3, 5);
            const metricSubHeaders = ["PAID", "PAID %", "PAID AMT (LAKH)", "PAID AMT %", "UNPAID", "UNPAID AMT (LAKH)"];
            const metricColsFor = (categories) => categories.flatMap((category) => {
                const catLabel = getRevenueCategoryDisplayLabel(category);
                return metricSubHeaders.map((h) => `${catLabel} ${h}`);
            });
            const headerA = [...firstCols, ...metricColsFor(groupACategories)];
            const headerB = [...firstCols, ...metricColsFor(groupBCategories), ...metricSubHeaders.map((h) => `TOTAL ${h}`)];
            // Diagnostic table hata di gayi hai - isse report ek hi page me (bina extra
            // diagnostic block ki jagah ghere) nikalti hai.
            const leadingCells = (row) => activeViewLevel === "CIRCLE" ? [row.divisionName || "", row.name] : [row.name];
            const categoryMetricCells = (category, row) => {
                const c = row.categories?.[category] || {};
                const paid = c.paid || 0, unpaid = c.unpaid || 0;
                const paidAmount = c.paidAmount || 0, unpaidAmount = c.unpaidAmount || 0;
                return [
                    paid,
                    formatRevenuePercent(paid, paid + unpaid),
                    formatRevenueLakhValue(paidAmount),
                    formatRevenuePercent(paidAmount, paidAmount + unpaidAmount),
                    unpaid,
                    formatRevenueLakhValue(unpaidAmount)
                ];
            };
            const totalMetricCells = (paidTotal, unpaidTotal, paidAmountTotal, unpaidAmountTotal) => [
                paidTotal || 0,
                formatRevenuePercent(paidTotal, (paidTotal || 0) + (unpaidTotal || 0)),
                formatRevenueLakhValue(paidAmountTotal || 0),
                formatRevenuePercent(paidAmountTotal, (paidAmountTotal || 0) + (unpaidAmountTotal || 0)),
                unpaidTotal || 0,
                formatRevenueLakhValue(unpaidAmountTotal || 0)
            ];
            const rowToArrayA = (row) => [...leadingCells(row), ...groupACategories.flatMap((category) => categoryMetricCells(category, row))];
            const rowToArrayB = (row) => [...leadingCells(row), ...groupBCategories.flatMap((category) => categoryMetricCells(category, row)), ...totalMetricCells(row.paidTotal, row.unpaidTotal, row.paidAmountTotal, row.unpaidAmountTotal)];
            const grand = getRevenueCategoryGrandTotals(rows);
            const grandLeading = activeViewLevel === "CIRCLE" ? ["", "GRAND TOTAL"] : ["GRAND TOTAL"];
            const grandCategoryCells = (category) => {
                const c = grand.categories[category];
                return categoryMetricCells(category, { categories: { [category]: c } });
            };
            const grandRowA = [...grandLeading, ...groupACategories.flatMap(grandCategoryCells)];
            const grandRowB = [...grandLeading, ...groupBCategories.flatMap(grandCategoryCells), ...totalMetricCells(grand.paidTotal, grand.unpaidTotal, grand.paidAmountTotal, grand.unpaidAmountTotal)];
            const title = `${levelT} ${reportType} CATEGORY WISE PAID/UNPAID SUMMARY`;
            const generatedAt = `${getCurrentDateDDMMYYYY()} ${getCurrentTimeHHMM()}`;

            if (fmt === "XLS") {
                const csvSafe = (value) => {
                    const text = String(value ?? "");
                    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
                };
                const lines = [
                    ["DEVELOPED BY", "AKHILESH PATIDAR (AE)"],
                    ["REPORT TITLE", title],
                    ["PERIOD", label],
                    ["SCOPE", getRevenueCategoryScopeLabel()],
                    ["GENERATED AT", generatedAt],
                    // ISOLATED ADDITION (2026-09-17, USER-APPROVED condition): reconciliation
                    // backend abhi purana/unavailable ho aur legacy fallback totals dikhaye
                    // ja rahe hon, to yeh ek extra "WARNING" row jud jaati hai - jab
                    // staleWarning na ho (normal case), yeh row bilkul nahi aati, baaki CSV
                    // structure byte-for-byte pehle jaisa hi rehta hai.
                    ...(staleWarning ? [["WARNING", staleWarning]] : []),
                    [],
                    ["TABLE 1: DOMESTIC / NON DOMESTIC / PUBLIC WATER WORKS AND STREET LIGHTS"],
                    headerA,
                    ...(rows || []).map(rowToArrayA),
                    grandRowA,
                    [],
                    ["TABLE 2: LT INDUSTRIAL / AGRICULTURE AND ALLIED ACTIVITIES / TOTAL"],
                    headerB,
                    ...(rows || []).map(rowToArrayB),
                    grandRowB
                ];
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([lines.map((row) => row.map(csvSafe).join(",")).join("\n")], { type: "text/csv" }));
                link.download = `Revenue_Category_Summary_${levelT}_${reportType}.csv`;
                link.click();
                return;
            }

            const { jsPDF } = window.jspdf;
            const doc = new jsPDF({ orientation: "landscape" });
            doc.setFontSize(7);
            doc.setTextColor(100);
            doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 10);
            doc.setFontSize(13);
            doc.setTextColor(29, 78, 216);
            doc.text(title, 148, 18, { align: "center" });
            doc.setFontSize(8);
            doc.setTextColor(30, 58, 138);
            doc.text(`${label} | ${getRevenueCategoryScopeLabel()}`, 148, 25, { align: "center" });
            doc.setFontSize(7);
            doc.setTextColor(100);
            doc.text(`Generated: ${generatedAt}`, 283, 10, { align: "right" });
            // ISOLATED ADDITION (2026-09-17, USER-APPROVED condition): staleWarning na
            // ho (normal case) to yeh block bilkul kuch nahi karta - tableStartY aur
            // poora neeche wala table layout pehle jaisa hi (32) rehta hai.
            if (staleWarning) {
                doc.setFontSize(8);
                doc.setTextColor(190, 18, 60);
                doc.text(staleWarning, 148, 30, { align: "center" });
            }
            const tableStartY = staleWarning ? 36 : 32;
            const groupedHeadFor = (categoriesWithLabels) => [
                [
                    ...firstCols.map((col) => ({ content: col, rowSpan: 2, styles: { valign: "middle", halign: "center", lineColor: [15, 23, 42], lineWidth: 0.25 } })),
                    ...categoriesWithLabels.map((groupLabel) => ({ content: groupLabel, colSpan: 6, styles: { halign: "center", lineColor: [15, 23, 42], lineWidth: 0.25 } }))
                ],
                [
                    ...categoriesWithLabels.flatMap(() => metricSubHeaders)
                ]
            ];
            const highlightTotalRows = (data) => {
                if (data.section === "body") {
                    const raw = data.row.raw || [];
                    if (raw.some((value) => /SUB TOTAL|DIVISION TOTAL/.test(String(value)))) {
                        data.cell.styles.fontStyle = "bold";
                        data.cell.styles.textColor = [30, 58, 138];
                        data.cell.styles.fillColor = [239, 246, 255];
                    }
                }
            };
            // Circle level par poori list ek lambi table me na chale, balki HAR DIVISION
            // apne khud ke alag PDF page par dikhe - taaki dekhne me confusion na ho
            // (pehle DC's random jagah page-break ho jaate the, ab hamesha division ki
            // boundary par hi naya page shuru hota hai). DC/Division level par yeh split
            // nahi hota, wahan sab kuch ek hi continuous flow me chalta hai (jaisa pehle).
            const splitRowsByDivision = (allRows) => {
                if (activeViewLevel !== "CIRCLE") return [{ divisionName: null, chunkRows: allRows || [] }];
                const chunks = [];
                let current = [];
                (allRows || []).forEach((row) => {
                    current.push(row);
                    if (row.type === "SUB_TOTAL") {
                        chunks.push({ divisionName: row.divisionName || "", chunkRows: current });
                        current = [];
                    }
                });
                if (current.length) chunks.push({ divisionName: current[0]?.divisionName || "", chunkRows: current });
                return chunks;
            };
            const divisionChunks = splitRowsByDivision(rows);
            divisionChunks.forEach((chunk, chunkIndex) => {
                const isLastChunk = chunkIndex === divisionChunks.length - 1;
                let startY = tableStartY;
                if (activeViewLevel === "CIRCLE") {
                    if (chunkIndex > 0) {
                        doc.addPage();
                        startY = 18;
                    }
                    doc.setFontSize(9.5);
                    doc.setTextColor(29, 78, 216);
                    doc.text(`DIVISION: ${chunk.divisionName || "-"}`, 14, startY);
                    startY += 6;
                }
                // TABLE 1: DOMESTIC / NON DOMESTIC / PUBLIC WATER WORKS AND STREET LIGHTS
                doc.setFontSize(8.5);
                doc.setTextColor(29, 78, 216);
                doc.text("TABLE 1: DOMESTIC / NON DOMESTIC / PUBLIC WATER WORKS AND STREET LIGHTS", 14, startY);
                // NOTE: Pehle fontSize 6.5/cellPadding 1.3 the aur HQ NAME column ki
                // width fix nahi thi - lambe combined HQ names (jaise "KAMAL KUMAR
                // DESHMUKH+RAKESH BAGHEL") 2-line me wrap ho jaate the, jisse row height
                // badh jaati thi aur Table 2 ke aakhri 1-2 row + Grand Total agle page
                // par chale jaate the. Ab font/padding thoda chhota kiya hai aur HQ NAME
                // column ki width fix (42mm) kar di hai taaki wrap na ho - isse dono
                // table ek hi landscape page me fit ho jaate hain.
                const categoryLeadingColumnStyles = activeViewLevel === "CIRCLE"
                    ? { 0: { halign: "left", cellWidth: 26 }, 1: { halign: "left", cellWidth: 42 } }
                    : { 0: { halign: "left", cellWidth: 46 } };
                doc.autoTable({
                    startY: startY + 3,
                    head: groupedHeadFor(groupACategories.map(getRevenueCategoryDisplayLabel)),
                    body: chunk.chunkRows.map(rowToArrayA),
                    foot: isLastChunk ? [grandRowA] : undefined,
                    theme: "grid",
                    styles: { fontSize: 6, cellPadding: 0.9, overflow: "linebreak", halign: "center", lineWidth: 0.12 },
                    headStyles: { fillColor: [37, 99, 235], halign: "center", fontSize: 6, lineColor: [15, 23, 42], lineWidth: 0.25 },
                    columnStyles: categoryLeadingColumnStyles,
                    footStyles: { fillColor: [241, 245, 249], textColor: [190, 18, 60], fontStyle: "bold", halign: "center" },
                    margin: { left: 8, right: 8, bottom: 8 },
                    didParseCell: highlightTotalRows
                });
                // TABLE 2: LT INDUSTRIAL / AGRICULTURE / TOTAL (TOTAL block ab % ke saath)
                let table2StartY = (doc.lastAutoTable?.finalY || startY + 3) + 6;
                if (table2StartY > 190) {
                    doc.addPage();
                    table2StartY = 20;
                }
                doc.setFontSize(8.5);
                doc.setTextColor(29, 78, 216);
                doc.text("TABLE 2: LT INDUSTRIAL / AGRICULTURE AND ALLIED ACTIVITIES / TOTAL", 14, table2StartY);
                doc.autoTable({
                    startY: table2StartY + 3,
                    head: groupedHeadFor([...groupBCategories.map(getRevenueCategoryDisplayLabel), "TOTAL"]),
                    body: chunk.chunkRows.map(rowToArrayB),
                    foot: isLastChunk ? [grandRowB] : undefined,
                    theme: "grid",
                    styles: { fontSize: 6, cellPadding: 0.9, overflow: "linebreak", halign: "center", lineWidth: 0.12 },
                    headStyles: { fillColor: [37, 99, 235], halign: "center", fontSize: 6, lineColor: [15, 23, 42], lineWidth: 0.25 },
                    columnStyles: categoryLeadingColumnStyles,
                    footStyles: { fillColor: [241, 245, 249], textColor: [190, 18, 60], fontStyle: "bold", halign: "center" },
                    margin: { left: 8, right: 8, bottom: 8 },
                    didParseCell: highlightTotalRows
                });
            });
            savePdfDocumentForDevice(doc, `Revenue_Category_Summary_${levelT}_${reportType}.pdf`);
        }

        async function downloadProgressRevenueCategorySummary(fmt) {
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const rawVal = document.getElementById("report-date").value;
                const parsed = parseSummarySelection(rawVal, summaryMode);
                const reportType = summaryMode === "MONTHLY" ? "MONTHLY" : "DAILY";
                const filterValue = getRevenueProgressFilterValue(parsed.daily, parsed.monthly);
                const [, , , reconciliation] = await Promise.all([
                    ensureRevenueCategoryMasterDataLoadedStrict_(getRevenueCategoryTargetDcs()),
                    ensureRevenueCategoryRawPaymentRowsLoaded(),
                    warmRevenueCategoryUploadedPaidCache(),
                    ensureRevenueCategoryReconciliationLoaded(reportType, filterValue)
                ]);
                const rows = buildRevenueCategorySummaryRows(reportType, filterValue);
                // USER-APPROVED correction #8: invariant mismatch mile to Excel/PDF
                // silently nahi niklegi - saaf error (DC/HQ naam + difference) dikhega.
                const invariantMismatches = checkRevenueCategorySummaryInvariant_(rows);
                if (invariantMismatches.length) {
                    const detail = invariantMismatches.slice(0, 5).map((m) => `${m.name} (${m.diff > 0 ? "+" : ""}${m.diff})`).join(", ");
                    throw new Error(`Paid+Unpaid Unique Master Consumer se match nahi kar raha - ${detail}${invariantMismatches.length > 5 ? " aadi" : ""}`);
                }
                // ISOLATED ADDITION (2026-09-17, USER-APPROVED condition): backend abhi
                // purana/reconciliation-unsupported hai to legacy fallback totals
                // "normal/correct report" ki tarah SILENT nahi dikhte - report ke andar
                // (additive line, existing layout/columns bilkul unchanged) aur download-
                // complete toast dono me saaf "STALE/LEGACY" warning jaata hai.
                const staleWarning = reconciliation && reconciliation.supported === false
                    ? "STALE/LEGACY - totals may be inaccurate (backend update pending)"
                    : null;
                const diagnostic = buildRevenueCategoryDiagnostic(reportType, filterValue, rows);
                exportRevenueCategorySummary(fmt, rows, parsed.label, reportType, diagnostic, staleWarning);
                setTimeout(() => setProgressCategoryDownloadState(false, staleWarning ? `${downloadTypeLabel} download ho chuki hai - STALE/LEGACY, totals may be inaccurate` : `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Category wise report download nahi ho payi", false);
            }
        }

        // Dropdown se jo bhi report type (Category Wise / Target vs Achievement / Top
        // 20-50 Defaulters) select hai, usi ke hisaab se sahi download function call karta
        // hai. Category Wise ke liye purani, poori tarah test-ki-hui exportRevenueCategory-
        // Summary() hi chalti hai - Target/Defaulters ke liye alag, seedhe simple export.
        function downloadProgressRevenueReportBox(fmt, forceGroupSummary) {
            if (progressRevenueReportType === "TARGET") return downloadProgressRevenueTargetSummary(fmt);
            if (progressRevenueReportType === "DEFAULTERS") return downloadProgressRevenueDefaultersSummary(fmt);
            // USER REQUEST (2026-09-14): Freeze Report jaisa hi pattern - NP3/NP6/Since
            // Connection ke DC level par ab "Summary Download" (HQ-wise, forceGroupSummary=true
            // wala naya button) aur "Full List Download" (bilkul pehle jaisa) dono alag
            // milte hain. Division/Circle par (jahan screen par bhi sirf summary dikhti
            // hai) ab download bhi summary hi deta hai - poori list nahi - taaki screen
            // aur download consistent rahein (downloadProgressRevenueNonPayeeSummary khud
            // is check ko andar bhi karta hai, forceGroupSummary sirf DC level ke naye
            // Summary button ke liye explicit shortcut hai).
            if (progressRevenueReportType === "NONPAYEE_3M") return downloadProgressRevenueNonPayeeSummary(fmt, "3M", forceGroupSummary);
            if (progressRevenueReportType === "NONPAYEE_6M") return downloadProgressRevenueNonPayeeSummary(fmt, "6M", forceGroupSummary);
            if (progressRevenueReportType === "NONPAYEE_SINCE_CONNECTION") return downloadProgressRevenueNonPayeeSummary(fmt, "SINCE_CONNECTION", forceGroupSummary);
            if (progressRevenueReportType === "PAIDCOUNT") return downloadProgressRevenuePaidCountSummary(fmt);
            return downloadProgressRevenueCategorySummary(fmt);
        }

        function downloadProgressRevenueTargetSummary(fmt) {
            const summaryData = lastRevenueProgressTargetSummaryData || lastRevenueProgressBoxData?.hqVillageSummaryData;
            if (!summaryData) return showToast("Report ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const tree = summaryData.tree || [];
                const colLabel = activeViewLevel === "DC" ? revenueHqLabelUpper() : "DC NAME";
                const headers = [colLabel, "TARGET", "ACHIEVED", "%"];
                const rows = tree.map((row) => {
                    const target = Number(row.paidAmountTotal || 0) + Number(row.unpaidAmountTotal || 0);
                    return [row.name, formatProgressReportAmount(target), formatProgressReportAmount(row.paidAmountTotal), `${getRevenueAchievementPct(row.paidAmountTotal, target)}%`];
                });
                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const reportTitle = `Target vs Achievement Summary - ${scope}`;
                const rawVal = document.getElementById("report-date")?.value || "";
                const parsed = parseSummarySelection(rawVal, summaryMode);
                const govtLabel = progressTargetGovtFilter === "GOVT" ? "Govt" : (progressTargetGovtFilter === "NONGOVT" ? "Non Govt" : "All");
                const periodLine = `Period: ${parsed.label || getTodayIsoDate()}  |  Type: ${govtLabel}`;
                const fileName = `${reportTitle}-${parsed.label || getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Scope: ${scope}`, 148, 22, { align: "center" });
                    doc.text(periodLine, 148, 28, { align: "center" });
                    doc.autoTable({ startY: 34, head: [headers], body: rows, theme: "grid", styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" }, headStyles: { fillColor: [29, 78, 216] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [periodLine], [], headers, ...rows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Target vs Achievement download nahi ho payi", false);
            }
        }

        // USER REQUEST (2026-08-13): pehle yahan "!row.paid" filter se koi bhi
        // consumer jo cash list me kisi bhi amount se match ho gaya ho (chahe
        // partial payment hi kyun na ho) poori tarah is list se bahar ho jaata
        // tha - matlab uska bacha hua bakaya kabhi Defaulters me nahi dikhta tha.
        // Ab row.pendingAmount (buildRevenueHqVillageConsumerRows me pehle se hi
        // Net Bill - Paid, sirf positive, nikala hua) use karte hain - partial
        // payment wale consumer bhi ab apne bache hue bakaya amount ke saath is
        // list me sahi se dikhenge.
        // BUG FIX/USER REQUEST (2026-09-13): Pehle "All (Govt + Non Govt)" chunne
        // par dono ko MILAKAR ek hi list banti thi, phir Top N kaata jaata tha -
        // isse agar Non Govt consumers ka pending amount generally zyada hota
        // (jaisa aksar hota hai), to Govt consumers Top N me jagah hi nahi bana
        // paate the (chahe wo apni Govt category me sabse bade bakayadaar hi
        // kyun na hon). Ab "All" par DONO group (Non Govt aur Govt) ki APNI-APNI
        // ALAG Top N list nikalte hain (jaisa GOVT/NONGOVT akela chunne par pehle
        // se hota hai) - total upto 2xN consumer, pehle poori Non Govt Top N,
        // fir poori Govt Top N (render/download dono me ek divider ke saath alag
        // dikhte hain). Return shape ab { rows, nonGovtCount } hai -
        // nonGovtCount > 0 hone par render/download ko pata chal jaata hai kahan
        // se Govt group shuru hota hai.
        function getProgressDefaultersFilteredRows(mode, filterValue) {
            const consumerRows = buildRevenueHqVillageConsumerRows(mode, filterValue).filter((row) => row.pendingAmount > 0);
            const govtFilter = progressDefaultersGovtFilter;
            const sortDesc = (list) => list.slice().sort((a, b) => b.pendingAmount - a.pendingAmount);
            if (govtFilter === "GOVT") {
                return { rows: sortDesc(consumerRows.filter((row) => !!row.govtFlag)).slice(0, progressRevenueDefaultersLimit), nonGovtCount: 0 };
            }
            if (govtFilter === "NONGOVT") {
                return { rows: sortDesc(consumerRows.filter((row) => !row.govtFlag)).slice(0, progressRevenueDefaultersLimit), nonGovtCount: 0 };
            }
            const nonGovtTop = sortDesc(consumerRows.filter((row) => !row.govtFlag)).slice(0, progressRevenueDefaultersLimit);
            const govtTop = sortDesc(consumerRows.filter((row) => !!row.govtFlag)).slice(0, progressRevenueDefaultersLimit);
            return { rows: [...nonGovtTop, ...govtTop], nonGovtCount: nonGovtTop.length };
        }

        function setProgressDefaultersGovtFilter(value) {
            progressDefaultersGovtFilter = value || "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        function setProgressTargetGovtFilter(value) {
            progressTargetGovtFilter = value || "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        function downloadProgressRevenueDefaultersSummary(fmt) {
            if (!lastRevenueProgressBoxData) return showToast("Report ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const { mode, filterValue } = lastRevenueProgressBoxData;
                const { rows, nonGovtCount } = getProgressDefaultersFilteredRows(mode, filterValue);
                if (!rows.length) { setProgressCategoryDownloadState(false, "Download ke liye data nahi hai"); return; }
                const headers = ["RANK", "IVRS NO", "CONSUMER NAME", revenueHqLabelUpper(), revenueVillageLabelUpper(), "GOVT/NON GOVT", "MOBILE NO", "PENDING AMOUNT"];
                // USER REQUEST (2026-09-13): "All" me screen jaisa hi - pehle poori
                // Non Govt Top N (1 se numbering), ek "NON GOVT"/"GOVT" divider row,
                // fir poori Govt Top N (1 se dobara numbering).
                const showSplit = !progressDefaultersGovtFilter && nonGovtCount > 0 && nonGovtCount < rows.length;
                const bodyRows = [];
                if (showSplit) bodyRows.push([`NON GOVT - TOP ${nonGovtCount}`, "", "", "", "", "", "", ""]);
                rows.forEach((row, index) => {
                    if (showSplit && index === nonGovtCount) bodyRows.push([`GOVT - TOP ${rows.length - nonGovtCount}`, "", "", "", "", "", "", ""]);
                    const displayIndex = showSplit && index >= nonGovtCount ? (index - nonGovtCount + 1) : (index + 1);
                    bodyRows.push([displayIndex, row.ivrsNo || "", row.consumerName || "", row.hqName || "", row.village || "", row.govtFlag ? "GOVT" : "NON GOVT", row.mobileNo || "", formatProgressReportAmount(row.pendingAmount)]);
                });
                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const govtLabel = progressDefaultersGovtFilter === "GOVT" ? "Govt" : (progressDefaultersGovtFilter === "NONGOVT" ? "Non Govt" : "All");
                const reportTitle = `Top ${progressRevenueDefaultersLimit} Defaulters - ${scope}`;
                const rawVal = document.getElementById("report-date")?.value || "";
                const parsed = parseSummarySelection(rawVal, summaryMode);
                const periodLine = `Period: ${parsed.label || getTodayIsoDate()}  |  Type: ${govtLabel}`;
                const fileName = `${reportTitle}-${parsed.label || getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Scope: ${scope}`, 148, 22, { align: "center" });
                    doc.text(periodLine, 148, 28, { align: "center" });
                    doc.autoTable({ startY: 34, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" }, headStyles: { fillColor: [159, 18, 57] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [periodLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Top Defaulters download nahi ho payi", false);
            }
        }

        function setProgressSummaryDownloadState(isDownloading, message = "") {
            const status = document.getElementById("progress-summary-download-status");
            const buttons = document.querySelectorAll("#summary-content .btn-export-row button");
            const statusMessage = normalizeActionStatusMessage(message, isDownloading, !String(message || "").toLowerCase().includes("nahi"));
            buttons.forEach((button) => {
                button.disabled = isDownloading;
                button.style.opacity = isDownloading ? "0.65" : "1";
                button.style.pointerEvents = isDownloading ? "none" : "auto";
            });
            if (status) {
                status.style.display = statusMessage ? "block" : "none";
                status.textContent = statusMessage;
                const failed = statusMessage === getActionStatusText("failed");
                status.style.background = isDownloading ? "#dbeafe" : (failed ? "#fff1f2" : "#dcfce7");
                status.style.color = isDownloading ? "#1d4ed8" : (failed ? "#991b1b" : "#047857");
            }
        }

        function renderRevenueHqVillageStaticTableHtml(tree, colLabel) {
            const rows = tree || [];
            let html = `<div class="summary-wrapper" style="margin-top:6px;"><div class="summary-table-header" style="grid-template-columns: 1.4fr 0.85fr 0.85fr 0.85fr;"><div>${colLabel}</div><div>TOTAL</div><div>PAID</div><div>UNPAID</div></div>`;
            if (!rows.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Data nahi mila.</div></div>`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    const totalCount = Number(row.paidTotal || 0) + Number(row.unpaidTotal || 0);
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: 1.4fr 0.85fr 0.85fr 0.85fr;"><div>${escapeHtml(row.name)}</div><div class="font-black">${totalCount}</div><div class="text-emerald-700 font-black">${row.paidTotal}</div><div class="text-rose-700 font-black">${row.unpaidTotal}</div></div>`;
                });
            }
            html += `</div>`;
            return html;
        }

        // USER REQUEST (2026-09-13): Live Revenue Report ke "{colLabel} WISE" on-screen
        // summary ko bhi Freeze Report jaisa hi richer table dikhana hai - NAME | TOTAL
        // CONSUMER | PAID (COUNT + AMT-LAKH) | PENDING (COUNT + AMT-LAKH). Data wahi
        // buildRevenueHqVillagePaidUnpaidTree() se aaya "tree" hai (paidTotal/unpaidTotal/
        // paidAmountTotal/unpaidAmountTotal already ismein hain) - sirf Freeze wale shared
        // renderFreezeGroupSummaryTableHtml() renderer ke expected shape (totalCount/
        // paidCount/paidAmount/pendingCount/pendingAmount) me map karte hain. SUBDN_TOTAL
        // (sub-division subtotal) ko halka "SUB_TOTAL" jaisa aur DIVISION SUB_TOTAL ko
        // zyada dark "GRAND_TOTAL" jaisa dikhaya hai taaki purani jaisi hi hierarchy
        // (sub-division halka, division dark) bani rahe. Download (Excel/PDF/CSV) is
        // change se bilkul untouched hai - wo apna alag flat-list code path use karta hai.
        function renderRevenueHqVillageRichSummaryTableHtml(tree, colLabel) {
            const summaryRows = (tree || []).map((row) => ({
                name: row.name,
                totalCount: Number(row.paidTotal || 0) + Number(row.unpaidTotal || 0),
                paidCount: Number(row.paidTotal || 0),
                paidAmount: Number(row.paidAmountTotal || 0),
                pendingCount: Number(row.unpaidTotal || 0),
                pendingAmount: Number(row.unpaidAmountTotal || 0),
                type: row.type === "SUB_TOTAL" ? "GRAND_TOTAL" : (row.type === "SUBDN_TOTAL" ? "SUB_TOTAL" : undefined)
            }));
            return renderFreezeGroupSummaryTableHtml(colLabel, summaryRows, `${colLabel} WISE SUMMARY (AMOUNT IN LAKH)`);
        }

        function renderRevenueTargetStaticTableHtml(tree, colLabel) {
            // User request: Daily Progress (DC/Division/Circle) ke Target vs
            // Achievement report me row-sequence ab % (achievement) ke hisaab se
            // descending hai - sabse zyada % wali row sabse upar, sabse kam wali
            // sabse niche. Pehle yeh rows buildRevenueHqVillagePaidUnpaidTree() ke
            // original order me (alphabetical HQ/DC name) aati thi.
            const rows = (tree || []).slice().sort((a, b) => {
                const targetA = Number(a.paidAmountTotal || 0) + Number(a.unpaidAmountTotal || 0);
                const targetB = Number(b.paidAmountTotal || 0) + Number(b.unpaidAmountTotal || 0);
                const pctA = getRevenueAchievementPct(a.paidAmountTotal, targetA);
                const pctB = getRevenueAchievementPct(b.paidAmountTotal, targetB);
                return pctB - pctA;
            });
            let html = `<div class="summary-wrapper" style="margin-top:6px;"><div class="summary-table-header" style="grid-template-columns: 1.4fr 0.85fr 0.85fr 0.7fr;"><div>${colLabel}</div><div>TARGET</div><div>ACHIEVED</div><div>%</div></div>`;
            if (!rows.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Data nahi mila.</div></div>`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    const target = Number(row.paidAmountTotal || 0) + Number(row.unpaidAmountTotal || 0);
                    const pct = getRevenueAchievementPct(row.paidAmountTotal, target);
                    const pctColor = pct >= 75 ? "#166534" : (pct >= 40 ? "#b45309" : "#9f1239");
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: 1.4fr 0.85fr 0.85fr 0.7fr;"><div>${escapeHtml(row.name)}</div><div class="font-black">${formatProgressReportAmount(target)}</div><div class="text-emerald-700 font-black">${formatProgressReportAmount(row.paidAmountTotal)}</div><div style="color:${pctColor}; font-weight:950;">${pct}%</div></div>`;
                });
            }
            html += `</div>`;
            return html;
        }

        // Target vs Achievement ka wahi tree (buildRevenueHqVillagePaidUnpaidTree se aaya
        // hua, jo hqVillageSummaryData.tree me already available hai - Category Wise summary
        // ke liye load ho hi chuka hai) reuse karte hain, sirf presentation Target/Achieved/%
        // ki hai. Isliye koi extra fetch nahi chahiye - dropdown switch turant, bina reload ke.
        function renderRevenueProgressTargetSummaryHtml(data) {
            const target = Number(data.totals.paidAmountTotal || 0) + Number(data.totals.unpaidAmountTotal || 0);
            const pct = getRevenueAchievementPct(data.totals.paidAmountTotal, target);
            const pctColor = pct >= 75 ? "#166534" : (pct >= 40 ? "#b45309" : "#9f1239");
            const colLabel = activeViewLevel === "DC" ? revenueHqLabelUpper() : "DC NAME";
            return `
                <div style="font-size:0.75rem; font-weight:950; color:#1d4ed8; text-align:center;">Target vs Achievement (Net Bill vs Paid)</div>
                <select onchange="setProgressTargetGovtFilter(this.value)" style="width:100%; height:44px; margin:9px auto 0; display:block; border:1.5px solid #93c5fd; border-radius:12px; padding:0 12px; font-size:0.76rem; font-weight:900; color:#0f172a; background:#ffffff;">
                    <option value="">All (Govt + Non Govt)</option>
                    <option value="GOVT" ${progressTargetGovtFilter === "GOVT" ? "selected" : ""}>Govt</option>
                    <option value="NONGOVT" ${progressTargetGovtFilter === "NONGOVT" ? "selected" : ""}>Non Govt</option>
                </select>
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:10px auto 0;">
                    <div style="background:#f1f5f9; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#64748b; text-transform:uppercase;">Target</div><div style="font-size:0.82rem; font-weight:950; color:#0f172a; margin-top:2px;">${formatProgressReportAmount(target)}</div></div>
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Achieved</div><div style="font-size:0.82rem; font-weight:950; color:#166534; margin-top:2px;">${formatProgressReportAmount(data.totals.paidAmountTotal)}</div></div>
                    <div style="background:#eff6ff; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#1d4ed8; text-transform:uppercase;">%</div><div style="font-size:0.95rem; font-weight:950; color:${pctColor}; margin-top:2px;">${pct}%</div></div>
                </div>
                <div style="font-size:0.62rem; font-weight:900; color:#1d4ed8; text-align:center; margin-top:10px;">${colLabel} WISE</div>
                ${renderRevenueTargetStaticTableHtml(data.tree, colLabel)}
            `;
        }

        // ===== Paid Count Summary (8th Revenue dropdown report, added 2026-09-09) =====
        // Reuses the same buildRevenueHqVillagePaidUnpaidTree() tree that Category Wise/
        // Target already load (data.hqVillageSummaryData) - no extra fetch needed, dropdown
        // switch is instant. DC level tree top rows = HQ nodes (each with village children).
        // Division/Circle level tree top rows = DC nodes (each with HQ children, mixed with
        // SUBDN_TOTAL/SUB_TOTAL rows we deliberately drop here - user only asked for a plain
        // DC-wise/HQ-wise/Village-wise summary, no sub-division subtotal rows).
        function getRevenuePaidCountPlainRows(tree) {
            return (tree || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL");
        }

        function sortRevenuePaidCountRowsAscPct(rows) {
            // USER REQUEST: sabse kam Paid % wali row sabse upar (default alphabetical
            // tree order ke bajaye) - taaki kam-performing HQ/Village/DC turant dikhe.
            return (rows || []).slice().sort((a, b) => {
                const totalA = Number(a.paidTotal || 0) + Number(a.unpaidTotal || 0);
                const totalB = Number(b.paidTotal || 0) + Number(b.unpaidTotal || 0);
                return getRevenueAchievementPct(a.paidTotal, totalA) - getRevenueAchievementPct(b.paidTotal, totalB);
            });
        }

        function findRevenuePaidCountNode(rows, name) {
            const normalized = normalizeLookupValue(name);
            return (rows || []).find((row) => normalizeLookupValue(row.name) === normalized);
        }

        function renderRevenuePaidCountTableHtml(rows, colLabel) {
            const sorted = sortRevenuePaidCountRowsAscPct(rows);
            const cols = "1.4fr 0.85fr 0.85fr 0.7fr";
            let html = `<div class="summary-wrapper" style="margin-top:6px;"><div class="summary-table-header" style="grid-template-columns: ${cols};"><div>${escapeHtml(colLabel)}</div><div>TOTAL</div><div>PAID</div><div>%</div></div>`;
            if (!sorted.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Data nahi mila.</div></div>`;
            } else {
                let grandTotal = 0, grandPaid = 0;
                sorted.forEach((row) => {
                    const total = Number(row.paidTotal || 0) + Number(row.unpaidTotal || 0);
                    const paid = Number(row.paidTotal || 0);
                    grandTotal += total; grandPaid += paid;
                    const pct = getRevenueAchievementPct(paid, total);
                    const pctColor = pct >= 75 ? "#166534" : (pct >= 40 ? "#b45309" : "#9f1239");
                    html += `<div class="summary-table-row" style="grid-template-columns: ${cols};"><div>${escapeHtml(row.name)}</div><div class="font-black">${total}</div><div class="text-emerald-700 font-black">${paid}</div><div style="color:${pctColor}; font-weight:950;">${pct}%</div></div>`;
                });
                const grandPct = getRevenueAchievementPct(grandPaid, grandTotal);
                html += `<div class="summary-table-row blue-bold" style="grid-template-columns: ${cols};"><div>TOTAL</div><div class="font-black">${grandTotal}</div><div class="text-emerald-700 font-black">${grandPaid}</div><div style="font-weight:950;">${grandPct}%</div></div>`;
            }
            html += `</div>`;
            return html;
        }

        function renderRevenueProgressPaidCountSummaryHtml(summaryData) {
            const tree = summaryData?.tree || [];
            const plainRows = getRevenuePaidCountPlainRows(tree);
            const isDc = activeViewLevel === "DC";
            const topLabel = isDc ? revenueHqLabelUpper() : "DC NAME";
            const topAllLabel = isDc ? revenueHqAllLabel().toUpperCase() : "ALL DC";
            const selectedNode = progressPaidCountFilter ? findRevenuePaidCountNode(plainRows, progressPaidCountFilter) : null;
            const optionsHtml = [`<option value="">${escapeHtml(topAllLabel)}</option>`]
                .concat(plainRows.map((row) => `<option value="${escapeHtml(row.name)}" ${selectedNode && normalizeLookupValue(selectedNode.name) === normalizeLookupValue(row.name) ? "selected" : ""}>${escapeHtml(row.name)}</option>`))
                .join("");
            const bodyRows = selectedNode ? (selectedNode.children || []) : plainRows;
            const colLabel = selectedNode ? (isDc ? revenueVillageLabelUpper() : "HQ NAME") : topLabel;
            return `
                <div style="font-size:0.75rem; font-weight:950; color:#1d4ed8; text-align:center;">Paid Count Summary</div>
                <select onchange="setProgressPaidCountFilter(this.value)" style="width:100%; height:44px; margin:9px auto 0; display:block; border:1.5px solid #93c5fd; border-radius:12px; padding:0 12px; font-size:0.76rem; font-weight:900; color:#0f172a; background:#ffffff;">
                    ${optionsHtml}
                </select>
                <div style="font-size:0.62rem; font-weight:900; color:#1d4ed8; text-align:center; margin-top:10px;">${escapeHtml(colLabel)} WISE</div>
                ${renderRevenuePaidCountTableHtml(bodyRows, colLabel)}
            `;
        }

        // Download scope follows the on-screen dropdown exactly (USER REQUEST 2026-09-09):
        // - Kisi specific HQ/DC select hai to sirf usi ke andar wali rows (Village/HQ) download
        //   hongi.
        // - "ALL HQ"/"ALL DC" (dropdown khaali) par DC level = pura HQ-wise + village-wise
        //   combined data; Division/Circle level = DC-wise + har DC ke andar HQ-wise (village
        //   tak nahi) - jaisa user ne confirm kiya.
        function downloadProgressRevenuePaidCountSummary(fmt) {
            const summaryData = lastRevenueProgressBoxData?.hqVillageSummaryData;
            if (!summaryData) return showToast("Report ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const tree = summaryData.tree || [];
                const plainRows = getRevenuePaidCountPlainRows(tree);
                const isDc = activeViewLevel === "DC";
                const topLabel = isDc ? revenueHqLabelUpper() : "DC NAME";
                const childLabel = isDc ? revenueVillageLabelUpper() : "HQ NAME";
                const selectedNode = progressPaidCountFilter ? findRevenuePaidCountNode(plainRows, progressPaidCountFilter) : null;
                const grandRow = (rows) => {
                    const grandTotal = rows.reduce((s, r) => s + Number(r.paidTotal || 0) + Number(r.unpaidTotal || 0), 0);
                    const grandPaid = rows.reduce((s, r) => s + Number(r.paidTotal || 0), 0);
                    return { grandTotal, grandPaid, pct: getRevenueAchievementPct(grandPaid, grandTotal) };
                };

                let headers, bodyRows, reportTitle;
                if (selectedNode) {
                    const childRows = sortRevenuePaidCountRowsAscPct(selectedNode.children || []);
                    headers = [childLabel, "TOTAL CONSUMER", "PAID CONSUMER", "PAID %"];
                    bodyRows = childRows.map((row) => {
                        const total = Number(row.paidTotal || 0) + Number(row.unpaidTotal || 0);
                        return [row.name, total, row.paidTotal, `${getRevenueAchievementPct(row.paidTotal, total)}%`];
                    });
                    const g = grandRow(childRows);
                    bodyRows.push(["TOTAL", g.grandTotal, g.grandPaid, `${g.pct}%`]);
                    reportTitle = `Paid Count Summary (${selectedNode.name} - ${childLabel} Wise)`;
                } else {
                    headers = [topLabel, childLabel, "TOTAL CONSUMER", "PAID CONSUMER", "PAID %"];
                    bodyRows = [];
                    const topSorted = sortRevenuePaidCountRowsAscPct(plainRows);
                    topSorted.forEach((topRow) => {
                        const childRows = sortRevenuePaidCountRowsAscPct(topRow.children || []);
                        childRows.forEach((childRow) => {
                            const total = Number(childRow.paidTotal || 0) + Number(childRow.unpaidTotal || 0);
                            bodyRows.push([topRow.name, childRow.name, total, childRow.paidTotal, `${getRevenueAchievementPct(childRow.paidTotal, total)}%`]);
                        });
                    });
                    const g = grandRow(topSorted);
                    bodyRows.push(["TOTAL", "", g.grandTotal, g.grandPaid, `${g.pct}%`]);
                    reportTitle = isDc ? "Paid Count Summary (All HQ Wise)" : "Paid Count Summary (All DC Wise)";
                }

                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                reportTitle = `${reportTitle} - ${scope}`;
                const rawVal = document.getElementById("report-date")?.value || "";
                const parsed = parseSummarySelection(rawVal, summaryMode);
                const periodLine = `Period: ${parsed.label || getTodayIsoDate()}`;
                const fileName = `${reportTitle}-${parsed.label || getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Scope: ${scope}`, 148, 22, { align: "center" });
                    doc.text(periodLine, 148, 28, { align: "center" });
                    doc.autoTable({ startY: 34, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" }, headStyles: { fillColor: [29, 78, 216] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [periodLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Paid Count Summary download nahi ho payi", false);
            }
        }
        // ===== End Paid Count Summary =====

        // Top 20/50 Defaulters ka data buildRevenueHqVillageConsumerRows() se aata hai - isi
        // function ka data "HQ / Village Wise Paid-Unpaid" list section aur dedicated "Top
        // 20/50 Defaulters" report dono use karte hain. Yahan par (Daily/Progress Report ki
        // Revenue tab me) bhi wahi consumer-level unpaid rows lekar, jo scope (DC/Division/
        // Circle) abhi active hai usi ke hisaab se top defaulters nikalte hain.
        function renderRevenueProgressDefaultersSummaryHtml(mode, filterValue) {
            const { rows, nonGovtCount } = getProgressDefaultersFilteredRows(mode, filterValue);
            let html = `
                <div style="font-size:0.75rem; font-weight:950; color:#9f1239; text-align:center;">Top ${progressRevenueDefaultersLimit} Defaulters (Cash List ke baad bakaya)</div>
                <div style="display:flex; gap:8px; width:100%; margin:9px auto 0;">
                    <div onclick="setProgressDefaultersLimit(20)" style="flex:1; height:28px; line-height:28px; text-align:center; border-radius:999px; cursor:pointer; font-size:0.6rem; font-weight:950; background:${progressRevenueDefaultersLimit === 20 ? "#9f1239" : "#ffe4e6"}; color:${progressRevenueDefaultersLimit === 20 ? "#ffffff" : "#9f1239"};">TOP 20</div>
                    <div onclick="setProgressDefaultersLimit(50)" style="flex:1; height:28px; line-height:28px; text-align:center; border-radius:999px; cursor:pointer; font-size:0.6rem; font-weight:950; background:${progressRevenueDefaultersLimit === 50 ? "#9f1239" : "#ffe4e6"}; color:${progressRevenueDefaultersLimit === 50 ? "#ffffff" : "#9f1239"};">TOP 50</div>
                </div>
                <select onchange="setProgressDefaultersGovtFilter(this.value)" style="width:100%; height:44px; margin:8px auto 0; display:block; border:1.5px solid #fda4af; border-radius:12px; padding:0 12px; font-size:0.76rem; font-weight:900; color:#0f172a; background:#ffffff;">
                    <option value="">All (Govt + Non Govt)</option>
                    <option value="GOVT" ${progressDefaultersGovtFilter === "GOVT" ? "selected" : ""}>Govt</option>
                    <option value="NONGOVT" ${progressDefaultersGovtFilter === "NONGOVT" ? "selected" : ""}>Non Govt</option>
                </select>
                <div class="summary-wrapper" style="margin-top:8px;"><div class="summary-table-header" style="grid-template-columns: 0.4fr 1.3fr 1fr;"><div>#</div><div>CONSUMER</div><div>PENDING</div></div>
            `;
            if (!rows.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Is scope me koi bakaya consumer nahi mila.</div></div>`;
            } else {
                // USER REQUEST (2026-09-13): "All" me dono group (Non Govt + Govt)
                // alag-alag dikhte hain - ek divider line ke saath, aur har group
                // ki apni numbering 1 se shuru (poori Non Govt Top N, phir poori
                // Govt Top N).
                const showSplit = !progressDefaultersGovtFilter && nonGovtCount > 0 && nonGovtCount < rows.length;
                if (showSplit) {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div style="text-align:center; font-weight:900; color:#166534; background:#f0fdf4; border-radius:8px; padding:5px;">NON GOVT - TOP ${nonGovtCount}</div></div>`;
                }
                rows.forEach((row, index) => {
                    if (showSplit && index === nonGovtCount) {
                        html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div style="text-align:center; font-weight:900; color:#9f1239; background:#fff1f2; border-radius:8px; padding:5px; margin-top:6px;">GOVT - TOP ${rows.length - nonGovtCount}</div></div>`;
                    }
                    const displayIndex = showSplit && index >= nonGovtCount ? (index - nonGovtCount + 1) : (index + 1);
                    html += `<div class="summary-table-row" style="grid-template-columns: 0.4fr 1.3fr 1fr;"><div class="font-black">${displayIndex}</div><div>${escapeHtml(row.consumerName || "-")}<br><span style="font-size:0.56rem; color:#64748b;">${escapeHtml(row.hqName)} / ${escapeHtml(row.village)}</span></div><div class="text-rose-700 font-black">${formatProgressReportAmount(row.pendingAmount)}</div></div>`;
                });
            }
            html += `</div>`;
            return html;
        }

        // "LAST PAYMENT DATE" master-data column ke aadhar par 3 naye Non Payee aging
        // report types - purane STAFF/CATEGORY/TARGET/DEFAULTERS jaisa hi dropdown-driven
        // flow, wahi lastRevenueProgressBoxData (mode/filterValue) reuse hota hai. Inke
        // saath HQ/Village/Category/Net Bill Slab/Govt-NonGovt - "Pending DO List" jaisa
        // filter set bhi rahega, taaki koi bhi combination nikal sake.
        let progressNonPayeeFilterState = { dc: "", hq: "", village: "", category: "", slab: "", govt: "" };

        function resetProgressNonPayeeFilterState() {
            progressNonPayeeFilterState = { dc: "", hq: "", village: "", category: "", slab: "", govt: "" };
        }

        function setProgressNonPayeeFilter(key, value) {
            if (!(key in progressNonPayeeFilterState)) return;
            progressNonPayeeFilterState[key] = value || "";
            // DC badalne par HQ/Village dono reset - warna purani DC ki HQ/Village select
            // rah jaati hai jo nayi DC me exist hi nahi karti.
            if (key === "dc") { progressNonPayeeFilterState.hq = ""; progressNonPayeeFilterState.village = ""; }
            if (key === "hq") progressNonPayeeFilterState.village = "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        function isProgressNonPayeeNetBillInSlab(row, slabValue) {
            if (!slabValue) return true;
            const amount = Number(row.pendingAmount || 0);
            if (slabValue === "0-500") return amount >= 0 && amount <= 500;
            if (slabValue === "500-1000") return amount > 500 && amount <= 1000;
            if (slabValue === "1000-5000") return amount > 1000 && amount <= 5000;
            if (slabValue === "5000-10000") return amount > 5000 && amount <= 10000;
            if (slabValue === "10000-25000") return amount > 10000 && amount <= 25000;
            if (slabValue === "25000+") return amount > 25000;
            return true;
        }

        function getProgressNonPayeeFilteredRows(mode, filterValue, bucket) {
            const allRows = buildRevenueNonPayeeRows(mode, filterValue, bucket);
            const f = progressNonPayeeFilterState;
            const rows = allRows.filter((row) => (
                (!f.dc || normalizeDcName(row.dcName) === normalizeDcName(f.dc))
                && (!f.hq || normalizeLookupValue(row.hqName) === normalizeLookupValue(f.hq))
                && (!f.village || normalizeLookupValue(row.village) === normalizeLookupValue(f.village))
                && (!f.category || normalizeLookupValue(row.tariffCategory) === normalizeLookupValue(f.category))
                && isProgressNonPayeeNetBillInSlab(row, f.slab)
                && (!f.govt || (f.govt === "GOVT" ? !!row.govtFlag : !row.govtFlag))
            ));
            return { allRows, rows };
        }

        function buildProgressNonPayeeOptionsHtml(values, selectedValue, placeholder) {
            const options = [`<option value="">${escapeHtml(placeholder)}</option>`].concat(
                (values || []).map((v) => `<option value="${escapeHtml(v)}" ${v === selectedValue ? "selected" : ""}>${escapeHtml(v)}</option>`)
            );
            return options.join("");
        }

        function renderRevenueProgressNonPayeeSummaryHtml(mode, filterValue, bucket) {
            const { allRows, rows } = getProgressNonPayeeFilteredRows(mode, filterValue, bucket);
            const f = progressNonPayeeFilterState;
            const bucketLabel = getRevenueNonPayeeBucketLabel(bucket);
            const totalPending = rows.reduce((sum, r) => sum + Number(r.pendingAmount || 0), 0);
            // Division/Circle level me ek hi HQ naam alag-alag DC me repeat ho sakta hai,
            // isliye HQ/Village se pehle DC chunna zaroori hai - warna baaki dropdown sahi
            // se kaam nahi karte. DC-level view me pehle se ek hi DC scope me hai, isliye
            // wahan yeh extra dropdown dikhane ki zaroorat nahi.
            const showDcDropdown = activeViewLevel !== "DC";
            const dcScoped = allRows.filter((row) => !f.dc || normalizeDcName(row.dcName) === normalizeDcName(f.dc));
            const villageScoped = dcScoped.filter((row) => !f.hq || normalizeLookupValue(row.hqName) === normalizeLookupValue(f.hq));
            const dcOptionsHtml = buildProgressNonPayeeOptionsHtml(getRevenueUniqueValues(allRows, "dcName"), f.dc, "All DC");
            const hqOptionsHtml = buildProgressNonPayeeOptionsHtml(getRevenueUniqueValues(dcScoped, "hqName"), f.hq, revenueHqAllLabel(f.dc || activeDC));
            const villageOptionsHtml = buildProgressNonPayeeOptionsHtml(getRevenueUniqueValues(villageScoped, "village"), f.village, revenueVillageAllLabel(f.dc || activeDC));
            const categoryOptionsHtml = buildProgressNonPayeeOptionsHtml(getRevenueUniqueValues(allRows, "tariffCategory"), f.category, "All Categories");
            const selectStyle = "width:100%; height:46px; margin:8px auto 0; display:block; border:1.5px solid #fb923c; border-radius:14px; padding:0 12px; font-size:0.8rem; font-weight:900; color:#0f172a; background:#ffffff;";
            let html = `
                <div style="font-size:0.75rem; font-weight:950; color:#9f1239; text-align:center;">${escapeHtml(bucketLabel)}</div>
                ${showDcDropdown ? `<select onchange="setProgressNonPayeeFilter('dc', this.value)" style="${selectStyle}">${dcOptionsHtml}</select>` : ""}
                <select onchange="setProgressNonPayeeFilter('hq', this.value)" style="${selectStyle}">${hqOptionsHtml}</select>
                <select onchange="setProgressNonPayeeFilter('village', this.value)" style="${selectStyle}">${villageOptionsHtml}</select>
                <select onchange="setProgressNonPayeeFilter('category', this.value)" style="${selectStyle}">${categoryOptionsHtml}</select>
                <select onchange="setProgressNonPayeeFilter('slab', this.value)" style="${selectStyle}">
                    <option value="">All Net Bill Slabs</option>
                    <option value="0-500" ${f.slab === "0-500" ? "selected" : ""}>₹0 - ₹500</option>
                    <option value="500-1000" ${f.slab === "500-1000" ? "selected" : ""}>₹500 - ₹1,000</option>
                    <option value="1000-5000" ${f.slab === "1000-5000" ? "selected" : ""}>₹1,000 - ₹5,000</option>
                    <option value="5000-10000" ${f.slab === "5000-10000" ? "selected" : ""}>₹5,000 - ₹10,000</option>
                    <option value="10000-25000" ${f.slab === "10000-25000" ? "selected" : ""}>₹10,000 - ₹25,000</option>
                    <option value="25000+" ${f.slab === "25000+" ? "selected" : ""}>₹25,000 Above</option>
                </select>
                <select onchange="setProgressNonPayeeFilter('govt', this.value)" style="${selectStyle}">
                    <option value="">All (Govt + Non Govt)</option>
                    <option value="GOVT" ${f.govt === "GOVT" ? "selected" : ""}>Govt</option>
                    <option value="NONGOVT" ${f.govt === "NONGOVT" ? "selected" : ""}>Non Govt</option>
                </select>
                <div style="display:grid; grid-template-columns: 1fr 1fr; gap:8px; width:100%; margin:10px auto 0;">
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Consumers</div><div style="font-size:0.95rem; font-weight:950; color:#9f1239; margin-top:2px;">${rows.length}</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Total Pending</div><div style="font-size:0.85rem; font-weight:950; color:#9f1239; margin-top:2px;">${formatProgressReportAmount(totalPending)}</div></div>
                </div>
                ${renderRevenueNonPayeeGroupSummaryHtml(rows)}
                ${activeViewLevel === "DC" ? `
                <div style="font-size:0.56rem; font-weight:850; color:#64748b; text-align:center; margin-top:10px;">SUMMARY DOWNLOAD (${escapeHtml(revenueHqLabelUpper())} WISE)</div>
                <div class="btn-export-row" style="margin-top:4px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadProgressRevenueReportBox('XLS', true)">Summary Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadProgressRevenueReportBox('PDF', true)">Summary PDF</button>
                </div>
                <div style="font-size:0.56rem; font-weight:850; color:#64748b; text-align:center; margin-top:10px;">FULL LIST DOWNLOAD</div>
                <div class="btn-export-row" style="margin-top:4px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadProgressRevenueReportBox('XLS')">Full List Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadProgressRevenueReportBox('PDF')">Full List PDF</button>
                </div>
                ` : `
                <div class="btn-export-row" style="margin-top:10px;">
                    <button class="btn-unique btn-excel-unique" onclick="downloadProgressRevenueReportBox('XLS')">${escapeHtml(getProgressRevenueReportTypeLabel())} Excel</button>
                    <button class="btn-unique btn-pdf-unique" onclick="downloadProgressRevenueReportBox('PDF')">${escapeHtml(getProgressRevenueReportTypeLabel())} PDF</button>
                </div>
                `}
                <div id="progress-category-download-status" style="display:none; text-align:center; font-weight:900; border-radius:14px; padding:8px 10px; width:100%; margin-top:8px;"></div>
            `;
            // USER REQUEST (2026-09-13): Division/Circle adhikari sirf SUMMARY
            // dekhte hain - Non Payee 3M/6M/Since Connection ki poori consumer-
            // list ab sirf DC level par hi dikhegi (upar wale "Consumers"/"Total
            // Pending" tiles aur HQ/DC-wise summary table hi Division/Circle par
            // dikhenge). DC level ka list-wala UI bilkul untouched hai.
            if (activeViewLevel === "DC") {
                html += `<div class="summary-wrapper" style="margin-top:10px;"><div class="summary-table-header" style="grid-template-columns: 1.3fr 0.7fr 1fr;"><div>CONSUMER</div><div>${bucket === "SINCE_CONNECTION" ? "TYPE" : "MONTHS"}</div><div>PENDING</div></div>`;
                if (!rows.length) {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Is filter me koi consumer nahi mila (ya master sheet me LAST PAYMENT DATE column abhi update nahi hui).</div></div>`;
                } else {
                    rows.slice(0, 200).forEach((row) => {
                        const middleCell = bucket === "SINCE_CONNECTION" ? "Never Paid" : `${row.monthsSincePayment} mo`;
                        html += `<div class="summary-table-row" style="grid-template-columns: 1.3fr 0.7fr 1fr;"><div>${escapeHtml(row.consumerName || "-")}<br><span style="font-size:0.56rem; color:#64748b;">${escapeHtml(row.hqName)} / ${escapeHtml(row.village)}</span></div><div class="font-black">${escapeHtml(middleCell)}</div><div class="text-rose-700 font-black">${formatProgressReportAmount(row.pendingAmount)}</div></div>`;
                    });
                    if (rows.length > 200) {
                        html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div style="text-align:center; color:#64748b; font-size:0.62rem; padding:6px;">... ${rows.length - 200} aur consumer, poori list Excel/PDF download me milegi</div></div>`;
                    }
                }
                html += `</div>`;
            }
            return html;
        }

        // USER REQUEST (2026-09-14): Freeze Report jaisa hi pattern - Non Payee 3M/6M/
        // Since Connection ke Division/Circle level par ab (jaisa screen par bhi sirf
        // summary dikhti hai) download bhi HQ/DC-wise SUMMARY hi deta hai, poori
        // consumer-list nahi (pehle yahan bhi poori list download hoti thi, jo screen
        // se inconsistent tha). DC level pehle jaisa hi (poori list) - naye "Summary
        // Download" button ke through wahan bhi yahi summary alag se milti hai.
        function downloadProgressRevenueNonPayeeGroupSummary(fmt, bucket) {
            if (!lastRevenueProgressBoxData) return showToast("Report ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const { mode, filterValue } = lastRevenueProgressBoxData;
                const { rows } = getProgressNonPayeeFilteredRows(mode || "DAILY", filterValue || "", bucket);
                if (!rows.length) { setProgressCategoryDownloadState(false, "Download ke liye data nahi hai"); return; }
                const summary = buildRevenueNonPayeeGroupSummary(rows);
                const headers = [summary.colLabel, "TOTAL CONSUMER", "PENDING AMOUNT"];
                const bodyRows = summary.rows.map((r) => [r.name, r.count, formatProgressReportAmount(r.pendingTotal)]);
                const rowTypeFlags = summary.rows.map((r) => (r.type === "GRAND_TOTAL" ? 2 : (r.type === "SUB_TOTAL" ? 1 : 0)));
                const showDcColumn = activeViewLevel !== "DC";
                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const f = progressNonPayeeFilterState;
                const filterLine = `${showDcColumn ? `DC: ${f.dc || "All"}  |  ` : ""}HQ: ${f.hq || "All"}  |  Village: ${f.village || "All"}  |  Category: ${f.category || "All"}  |  Net Bill Slab: ${f.slab || "All"}  |  Type: ${f.govt === "GOVT" ? "Govt" : (f.govt === "NONGOVT" ? "Non Govt" : "All")}`;
                const reportTitle = `${getRevenueNonPayeeBucketLabel(bucket)} - ${scope} - Summary`;
                const asOfLine = `As of: ${formatRevenueDateIndian(normalizeRevenueReportDate(getCurrentDateDDMMYYYY()))}`;
                const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Scope: ${scope}`, 148, 22, { align: "center" });
                    doc.text(filterLine, 148, 28, { align: "center" });
                    doc.text(asOfLine, 148, 33, { align: "center" });
                    doc.autoTable({
                        startY: 39, head: [headers], body: bodyRows, theme: "grid",
                        styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" },
                        headStyles: { fillColor: [159, 18, 57] },
                        didParseCell: function (hookData) {
                            if (hookData.section === "body") {
                                const flag = rowTypeFlags[hookData.row.index];
                                if (flag === 2) { hookData.cell.styles.fillColor = [219, 234, 254]; hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [159, 18, 57]; }
                                else if (flag === 1) { hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [194, 65, 12]; }
                            }
                        }
                    });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [filterLine], [asOfLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Non Payee summary download nahi ho payi", false);
            }
        }

        function downloadProgressRevenueNonPayeeSummary(fmt, bucket, forceGroupSummary) {
            if (forceGroupSummary || activeViewLevel !== "DC") return downloadProgressRevenueNonPayeeGroupSummary(fmt, bucket);
            if (!lastRevenueProgressBoxData) return showToast("Report ke liye data nahi hai", false);
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setProgressCategoryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const { mode, filterValue } = lastRevenueProgressBoxData;
                const { rows } = getProgressNonPayeeFilteredRows(mode || "DAILY", filterValue || "", bucket);
                if (!rows.length) { setProgressCategoryDownloadState(false, "Download ke liye data nahi hai"); return; }
                const showDcColumn = activeViewLevel !== "DC";
                const headers = [
                    ...(showDcColumn ? ["DC NAME"] : []),
                    "IVRS NO", "CONSUMER NAME", revenueHqLabelUpper(), revenueVillageLabelUpper(), "TARRIF CATEGORY", "GOVT/NON GOVT", "MOBILE NO",
                    bucket === "SINCE_CONNECTION" ? "STATUS" : "MONTHS SINCE PAYMENT", "LAST PAYMENT DATE", "PENDING AMOUNT"
                ];
                const bodyRows = rows.map((row) => [
                    ...(showDcColumn ? [row.dcName || ""] : []),
                    row.ivrsNo || "", row.consumerName || "", row.hqName || "", row.village || "", row.tariffCategory || "",
                    row.govtFlag ? "GOVT" : "NON GOVT", row.mobileNo || "",
                    bucket === "SINCE_CONNECTION" ? "Never Paid" : `${row.monthsSincePayment}`,
                    row.lastPaymentDate || "Never Paid",
                    formatProgressReportAmount(row.pendingAmount)
                ]);
                const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const f = progressNonPayeeFilterState;
                const filterLine = `${showDcColumn ? `DC: ${f.dc || "All"}  |  ` : ""}HQ: ${f.hq || "All"}  |  Village: ${f.village || "All"}  |  Category: ${f.category || "All"}  |  Net Bill Slab: ${f.slab || "All"}  |  Type: ${f.govt === "GOVT" ? "Govt" : (f.govt === "NONGOVT" ? "Non Govt" : "All")}`;
                const reportTitle = `${getRevenueNonPayeeBucketLabel(bucket)} - ${scope}`;
                const asOfLine = `As of: ${formatRevenueDateIndian(normalizeRevenueReportDate(getCurrentDateDDMMYYYY()))}`;
                const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setProgressCategoryDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Scope: ${scope}`, 148, 22, { align: "center" });
                    doc.text(filterLine, 148, 28, { align: "center" });
                    doc.text(asOfLine, 148, 33, { align: "center" });
                    doc.autoTable({ startY: 39, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [159, 18, 57] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Scope: ${scope}`], [filterLine], [asOfLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setProgressCategoryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setProgressCategoryDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Non Payee report download nahi ho payi", false);
            }
        }

        function setProgressRevenueReportType(value) {
            const validValues = ["STAFF", "CATEGORY", "TARGET", "DEFAULTERS", "NONPAYEE_3M", "NONPAYEE_6M", "NONPAYEE_SINCE_CONNECTION", "PAIDCOUNT"];
            progressRevenueReportType = validValues.includes(value) ? value : "STAFF";
            resetProgressNonPayeeFilterState();
            progressDefaultersGovtFilter = "";
            progressTargetGovtFilter = "";
            progressStaffTypeFilter = "";
            progressPaidCountFilter = "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        // Paid Count Summary ke apne dropdown (HQ ya DC chunne wala) ke liye - baaki
        // sab progressXxxFilter setters jaisa hi, sirf re-render karta hai.
        function setProgressPaidCountFilter(value) {
            progressPaidCountFilter = value || "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        function setProgressDefaultersLimit(limit) {
            progressRevenueDefaultersLimit = limit === 50 ? 50 : 20;
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        function getProgressRevenueReportTypeLabel() {
            if (progressRevenueReportType === "TARGET") return "Target vs Achievement";
            if (progressRevenueReportType === "DEFAULTERS") return `Top ${progressRevenueDefaultersLimit} Defaulters`;
            if (progressRevenueReportType === "STAFF") return "Paid by Staff";
            if (progressRevenueReportType === "NONPAYEE_3M") return "Non Payee From 3 Month";
            if (progressRevenueReportType === "NONPAYEE_6M") return "Non Payee From 6 Month";
            if (progressRevenueReportType === "NONPAYEE_SINCE_CONNECTION") return "Non Payee From Date of Connection";
            if (progressRevenueReportType === "PAIDCOUNT") return "Paid Count Summary";
            return "Category Wise";
        }

        // Daily Progress (DC/Division/Circle) me sirf summary dikhani hai - koi drill-down
        // ya per-consumer list/download yahan nahi, sirf Total/Paid/Unpaid + category-wise +
        // HQ ya DC-wise (level ke hisaab se) numbers. Poora consumer-level list/dropdown sirf
        // dedicated "HQ / Village Wise Paid-Unpaid" report me hi hai.
        function renderRevenueProgressHqVillageSummaryHtml(data) {
            const t = data.totals;
            const catRows = revenueCategoryList.map((cat) => {
                const c = data.categoryGrand.categories[cat] || { paid: 0, unpaid: 0 };
                const total = Number(c.paid || 0) + Number(c.unpaid || 0);
                if (!total) return "";
                return `<div class="summary-table-row" style="grid-template-columns: 1fr 1fr 1fr 1fr;"><div>${escapeHtml(getRevenueCategoryDisplayLabel(cat))}</div><div class="font-black">${total}</div><div class="text-emerald-700 font-black">${c.paid || 0}</div><div class="text-rose-700 font-black">${c.unpaid || 0}</div></div>`;
            }).join("");
            const colLabel = activeViewLevel === "DC" ? revenueHqLabelUpper() : "DC NAME";
            return `
                <div style="font-size:0.75rem; font-weight:950; color:#1d4ed8; text-align:center;">Total / Paid / Unpaid Summary</div>
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:10px auto 0;">
                    <div style="background:#f1f5f9; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#64748b; text-transform:uppercase;">Total Consumer</div><div style="font-size:0.95rem; font-weight:950; color:#0f172a; margin-top:2px;">${t.totalConsumer}</div></div>
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid</div><div style="font-size:0.95rem; font-weight:950; color:#166534; margin-top:2px;">${t.paidTotal}</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Unpaid</div><div style="font-size:0.95rem; font-weight:950; color:#9f1239; margin-top:2px;">${t.unpaidTotal}</div></div>
                </div>
                <div style="font-size:0.62rem; font-weight:900; color:#1d4ed8; text-align:center; margin-top:10px;">CATEGORY WISE</div>
                <div class="summary-wrapper" style="margin-top:6px;">
                    <div class="summary-table-header" style="grid-template-columns: 1fr 1fr 1fr 1fr;"><div>CATEGORY</div><div>TOTAL</div><div>PAID</div><div>UNPAID</div></div>
                    ${catRows || `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Category data nahi mila.</div></div>`}
                </div>
                <div style="font-size:0.62rem; font-weight:900; color:#1d4ed8; text-align:center; margin-top:10px;">${colLabel} WISE</div>
                ${renderRevenueHqVillageRichSummaryTableHtml(data.tree, colLabel)}
            `;
        }

        // "Paid by Staff" (jo pehle hamesha upar dikhta tha) ab bhi wahi table hai, sirf
        // ab dropdown se select hone par hi dikhta hai - baaki 3 report type isi jagah
        // (usi #progress-revenue-body me) unke apne render se replace ho jate hain.
        function setProgressStaffTypeFilter(value) {
            progressStaffTypeFilter = ["PAID", "TD"].includes(value) ? value : "";
            const body = document.getElementById("progress-revenue-body");
            if (body) body.innerHTML = renderProgressRevenueBodyInner();
        }

        // Paid by Staff aur TD by Staff dono ka data ek hi jagah (rows me paidCount/
        // paidAmount/tdCount/tdAmount saath) already aata hai - isliye alag se koi naya
        // fetch nahi chahiye, sirf yeh dropdown decide karta hai ki table/export me kaunsa
        // column set dikhana hai (dono / sirf Paid / sirf TD).
        function renderRevenueProgressStaffBodyHtml(rows, label) {
            const colLabel = getRevenueProgressColumnLabel();
            const totals = getRevenueProgressTotals(rows);
            const showPaid = progressStaffTypeFilter !== "TD";
            const showTd = progressStaffTypeFilter !== "PAID";
            const gridCols = showPaid && showTd ? "1.15fr 0.75fr 0.95fr 0.75fr 0.95fr" : "1.4fr 0.9fr 1.1fr";
            const headerCells = [`<div>${colLabel}</div>`];
            if (showPaid) headerCells.push(`<div>PAID</div>`, `<div>PAID AMT</div>`);
            if (showTd) headerCells.push(`<div>LINE TD</div>`, `<div>TD AMT</div>`);
            let html = `
                <select onchange="setProgressStaffTypeFilter(this.value)" style="width:100%; max-width:360px; height:40px; margin:0 auto 8px; display:block; border:1.5px solid #0f766e; border-radius:12px; padding:0 12px; font-size:0.74rem; font-weight:900; color:#0f766e; background:#ffffff;">
                    <option value="" ${progressStaffTypeFilter === "" ? "selected" : ""}>Paid + TD Both</option>
                    <option value="PAID" ${progressStaffTypeFilter === "PAID" ? "selected" : ""}>Paid by Staff</option>
                    <option value="TD" ${progressStaffTypeFilter === "TD" ? "selected" : ""}>TD by Staff</option>
                </select>
                <div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: ${gridCols};">${headerCells.join("")}</div>`;

            if (!rows.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Selected ${summaryMode === "DAILY" ? "date" : "month"} me revenue entry nahi hai.</div></div>`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    const cells = [`<div>${row.name}</div>`];
                    if (showPaid) cells.push(`<div>${row.paidCount}</div>`, `<div class="text-emerald-700 font-black">${formatProgressReportAmount(row.paidAmount)}</div>`);
                    if (showTd) cells.push(`<div>${row.tdCount}</div>`, `<div class="text-rose-700 font-black">${formatProgressReportAmount(row.tdAmount)}</div>`);
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: ${gridCols};">${cells.join("")}</div>`;
                });
            }

            const footerCards = [];
            if (showPaid) footerCards.push(`<div class="rounded-xl bg-emerald-50 border border-emerald-200 p-2">Paid: ${totals.paidCount}<br>${formatProgressReportAmount(totals.paidAmount)}</div>`);
            if (showTd) footerCards.push(`<div class="rounded-xl bg-rose-50 border border-rose-200 p-2">Line TD: ${totals.tdCount}<br>${formatProgressReportAmount(totals.tdAmount)}</div>`);
            const footerGridCols = showPaid && showTd ? "grid-cols-2" : "grid-cols-1";

            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">GRAND TOTAL (${label})</div><div class="mt-2 grid ${footerGridCols} gap-2 text-center text-[11px] font-black">${footerCards.join("")}</div>
                <div class="btn-export-row">
                    <button class="btn-unique btn-excel-unique" onclick="doExport('XLS')">
                        <svg width="18" height="18" fill="white" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16h-8v-2h8v2zm0-4h-8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
                        Excel Report
                    </button>
                    <button class="btn-unique btn-pdf-unique" onclick="doExport('PDF')">
                        <svg width="18" height="18" fill="white" viewBox="0 0 24 24"><path d="M20 2H8c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-8.5 7.5c0 .83-.67 1.5-1.5 1.5H9v2H7.5V7H10c.83 0 1.5.67 1.5 1.5v1zm5 2c0 .83-.67 1.5-1.5 1.5h-2.5V7H15c.83 0 1.5.67 1.5 1.5v3zm4-3H19v1h1.5V11H19v2h-1.5V7h3v1.5zM9 9.5h1v-1H9v1zM4 6H2v14c0 1.1.9 2 2 2h14v-2H4V6zm10 5.5h1v-3h-1v3z"/></svg>
                        PDF Report
                    </button>
                </div>
                <div id="progress-summary-download-status" style="display:none; text-align:center; font-weight:900; border-radius:16px; padding:10px 12px; width:100%; margin-top:12px;"></div>
            </div>`;
            return html;
        }

        // Category Wise / Target vs Achievement / Top 20-50 Defaulters - teeno isi dashed
        // box me, jo bhi type dropdown me select hai usi ka content + usi ka Excel/PDF.
        function renderRevenueProgressNonStaffBoxHtml() {
            const data = lastRevenueProgressBoxData || {};
            let bodyHtml;
            // Non Payee (3M/6M/Since Connection) me consumer list bahut lambi ho sakti hai
            // (hazaaron rows) - isliye in teeno ke liye Excel/PDF buttons aur download-status
            // ab renderRevenueProgressNonPayeeSummaryHtml() ke andar hi, summary cards (Consumers/
            // Total Pending) ke turant baad, list se PEHLE render ho jaate hain - taki user ko
            // download karne ke liye poori list scroll na karni pade. Isliye yahan (list ke baad)
            // dobara buttons nahi jodte, warna do baar dikhte. Baaki Category/Target/Defaulters
            // pehle jaisे hi (bodyHtml ke NEECHE) buttons rakhte hain - wahan list chhoti hoti hai.
            const isNonPayeeType = ["NONPAYEE_3M", "NONPAYEE_6M", "NONPAYEE_SINCE_CONNECTION"].includes(progressRevenueReportType);
            if (progressRevenueReportType === "TARGET") {
                // USER REQUEST (2026-08-13): Govt/Non-Govt filter - jab select ho, tab
                // hi tree ko us filter ke saath dobara (local, bina naye fetch ke)
                // banate hain, taaki Category Wise wali shared hqVillageSummaryData
                // (jo saath me isi box me use hoti hai) chhedni na pade.
                const targetSummaryData = progressTargetGovtFilter
                    ? buildRevenueHqVillageSummaryData(data.mode || "DAILY", data.filterValue || "", progressTargetGovtFilter)
                    : data.hqVillageSummaryData;
                lastRevenueProgressTargetSummaryData = targetSummaryData;
                bodyHtml = targetSummaryData ? renderRevenueProgressTargetSummaryHtml(targetSummaryData) : `<div style="font-size:0.75rem; font-weight:950; color:#1d4ed8; text-align:center;">Data nahi mila.</div>`;
            } else if (progressRevenueReportType === "DEFAULTERS") {
                bodyHtml = renderRevenueProgressDefaultersSummaryHtml(data.mode || "DAILY", data.filterValue || "");
            } else if (progressRevenueReportType === "NONPAYEE_3M") {
                bodyHtml = renderRevenueProgressNonPayeeSummaryHtml(data.mode || "DAILY", data.filterValue || "", "3M");
            } else if (progressRevenueReportType === "NONPAYEE_6M") {
                bodyHtml = renderRevenueProgressNonPayeeSummaryHtml(data.mode || "DAILY", data.filterValue || "", "6M");
            } else if (progressRevenueReportType === "NONPAYEE_SINCE_CONNECTION") {
                bodyHtml = renderRevenueProgressNonPayeeSummaryHtml(data.mode || "DAILY", data.filterValue || "", "SINCE_CONNECTION");
            } else if (progressRevenueReportType === "PAIDCOUNT") {
                bodyHtml = renderRevenueProgressPaidCountSummaryHtml(data.hqVillageSummaryData);
            } else {
                bodyHtml = data.hqVillageSummaryData ? renderRevenueProgressHqVillageSummaryHtml(data.hqVillageSummaryData) : `<div style="font-size:0.75rem; font-weight:950; color:#1d4ed8; text-align:center;">Category Wise Paid/Unpaid Summary</div>`;
            }
            const typeLabel = getProgressRevenueReportTypeLabel();
            const bottomButtonsHtml = isNonPayeeType ? "" : `
                    <div class="btn-export-row" style="margin-top:8px;">
                        <button class="btn-unique btn-excel-unique" onclick="downloadProgressRevenueReportBox('XLS')">${escapeHtml(typeLabel)} Excel</button>
                        <button class="btn-unique btn-pdf-unique" onclick="downloadProgressRevenueReportBox('PDF')">${escapeHtml(typeLabel)} PDF</button>
                    </div>
                    <div id="progress-category-download-status" style="display:none; text-align:center; font-weight:900; border-radius:14px; padding:8px 10px; width:100%; margin-top:8px;"></div>`;
            return `
                <div style="border:1.5px dashed #93c5fd; background:#eff6ff; border-radius:16px; padding:10px;">
                    ${bodyHtml}${bottomButtonsHtml}
                </div>
            `;
        }

        function renderProgressRevenueBodyInner() {
            if (["CATEGORY", "TARGET", "DEFAULTERS", "NONPAYEE_3M", "NONPAYEE_6M", "NONPAYEE_SINCE_CONNECTION", "PAIDCOUNT"].includes(progressRevenueReportType)) {
                return renderRevenueProgressNonStaffBoxHtml();
            }
            const staffData = lastRevenueProgressStaffData || { rows: [], label: "" };
            return renderRevenueProgressStaffBodyHtml(staffData.rows, staffData.label);
        }

        function renderRevenueProgressSummary(rows, label, hqVillageSummaryData = null, revenueMode = "DAILY", revenueFilterValue = "") {
            lastRevenueProgressBoxData = { hqVillageSummaryData, mode: revenueMode, filterValue: revenueFilterValue };
            lastRevenueProgressStaffData = { rows, label };
            const selectHtml = `
                <select onchange="setProgressRevenueReportType(this.value)" style="width:100%; max-width:360px; height:44px; margin:0 auto 10px; display:block; border:1.5px solid #0f766e; border-radius:12px; padding:0 12px; font-size:0.78rem; font-weight:950; color:#0f766e; background:#ffffff;">
                    <option value="STAFF" ${progressRevenueReportType === "STAFF" ? "selected" : ""}>Paid by Staff (Daily/Monthly)</option>
                    <option value="CATEGORY" ${progressRevenueReportType === "CATEGORY" ? "selected" : ""}>Category Wise</option>
                    <option value="TARGET" ${progressRevenueReportType === "TARGET" ? "selected" : ""}>Target vs Achievement</option>
                    <option value="DEFAULTERS" ${progressRevenueReportType === "DEFAULTERS" ? "selected" : ""}>Top 20/50 Defaulters</option>
                    <option value="NONPAYEE_3M" ${progressRevenueReportType === "NONPAYEE_3M" ? "selected" : ""}>Non Payee From 3 Month</option>
                    <option value="NONPAYEE_6M" ${progressRevenueReportType === "NONPAYEE_6M" ? "selected" : ""}>Non Payee From 6 Month</option>
                    <option value="NONPAYEE_SINCE_CONNECTION" ${progressRevenueReportType === "NONPAYEE_SINCE_CONNECTION" ? "selected" : ""}>Non Payee From Date of Connection</option>
                    <option value="PAIDCOUNT" ${progressRevenueReportType === "PAIDCOUNT" ? "selected" : ""}>Paid Count Summary</option>
                </select>
            `;
            return `${selectHtml}<div id="progress-revenue-body">${renderProgressRevenueBodyInner()}</div>`;
        }

        // USER REQUEST (2026-09-13): Puri app me jahan bhi koi report/data sync
        // hota hai, ek hi common message dikhe - "SYNCING DATA... PLEASE WAIT".
        // Isliye yahi standard text ab default label hai, aur baaki sabhi
        // call-sites (Mobile/Revenue/Freeze/SHMS/Pending List) bhi apna pehle
        // wala custom text hata kar isi ek jaisa text pass karte hain.
        function renderSyncingProgress(cont, isStillValid, label = "SYNCING DATA... PLEASE WAIT", subLabel = "") {
            cont.innerHTML = `
                <div class="text-center py-10">
                    <p class="font-black text-slate-500" style="font-size:0.85rem;">${escapeHtml(label)}</p>
                    ${subLabel ? `<p class="font-bold text-slate-400" style="font-size:0.66rem; margin-top:3px;">${escapeHtml(subLabel)}</p>` : ""}
                    <div class="app-sync-spinner"></div>
                    <div style="max-width:220px; margin:14px auto 0; background:#e2e8f0; border-radius:999px; height:8px; overflow:hidden;">
                        <div id="summary-sync-progress-fill" style="height:100%; width:2%; background:linear-gradient(90deg,#0d9488,#0f766e); border-radius:999px; transition:width 0.25s ease;"></div>
                    </div>
                    <p id="summary-sync-progress-text" class="font-bold text-slate-400" style="font-size:0.72rem; margin-top:6px;">2%</p>
                </div>
            `;
            let percent = 2;
            let displayed = 2;
            let finished = false;
            let intervalId = setInterval(() => {
                if (!isStillValid() || finished) {
                    clearInterval(intervalId);
                    return;
                }
                const fill = document.getElementById("summary-sync-progress-fill");
                const text = document.getElementById("summary-sync-progress-text");
                if (!fill || !text) {
                    clearInterval(intervalId);
                    return;
                }
                if (percent < 90) {
                    percent = Math.min(90, percent + Math.max(1, (90 - percent) / 8));
                } else {
                    // 90% ke baad kabhi na-ruke wali dhire-dhire creep - 99 ke jitna paas
                    // jaate hain, step utna hi chhota hota jaata hai, isliye number hamesha
                    // aage badhta hua dikhta hai, kabhi ek jagah "atka hua" nahi lagta.
                    percent = Math.min(98.9, percent + (99 - percent) * 0.05);
                }
                const nextDisplayed = Math.min(99, Math.round(percent));
                if (nextDisplayed !== displayed) {
                    displayed = nextDisplayed;
                    fill.style.width = `${displayed}%`;
                    text.innerText = `${displayed}%`;
                }
                const atCeiling = displayed >= 99;
                fill.classList.toggle("sync-progress-pulse", atCeiling);
                text.classList.toggle("sync-progress-pulse", atCeiling);
            }, 200);
            // Caller ko finish() call karna chahiye jab actual data/display ready ho jaaye -
            // usi waqt 100% dikhega, uske baad content swap karo. stop() error/cancel case ke liye
            // hai (bina 100% dikhaye turant progress hata deta hai).
            return {
                finish: () => new Promise((resolve) => {
                    finished = true;
                    clearInterval(intervalId);
                    if (!isStillValid()) return resolve();
                    const fill = document.getElementById("summary-sync-progress-fill");
                    const text = document.getElementById("summary-sync-progress-text");
                    if (fill && text) {
                        fill.classList.remove("sync-progress-pulse");
                        text.classList.remove("sync-progress-pulse");
                        fill.style.width = "100%";
                        text.innerText = "100%";
                    }
                    setTimeout(resolve, 220);
                }),
                stop: () => {
                    finished = true;
                    clearInterval(intervalId);
                }
            };
        }

        // USER REQUEST (2026-08-19, updated 2026-09-13): Progress Report screen ke
        // header ke niche wali pill me pehle hardcoded "PROGRESS REPORT" likha
        // rehta tha (jabki upar header me bhi "PROGRESS REPORT" likha hota hai -
        // do baar same text, aur DC/Division/Circle me se kaunsi hai pata hi
        // nahi chalta tha). Ab seedha "DC PROGRESS REPORT" / "DIVISION PROGRESS
        // REPORT" / "CIRCLE PROGRESS REPORT" dikhta hai (saath me DC/Division ka
        // naam bhi, DC/Division scope pehchanne ke liye) - jaise
        // "DC PROGRESS REPORT - CHHAPARA-1".
        function getProgressReportScopeLabel() {
            if (activeViewLevel === "DC") return `DC PROGRESS REPORT - ${activeDC}`;
            if (activeViewLevel === "DIVISION") return `DIVISION PROGRESS REPORT - ${activeDiv || ""}`.trim().replace(/-\s*$/, "");
            return "CIRCLE PROGRESS REPORT - SEONI";
        }

        function updateProgressReportScopeTitle() {
            const titleEl = document.getElementById("summary-title");
            if (titleEl) titleEl.innerText = getProgressReportScopeLabel();
        }

        async function refreshSummary() {
            // USER REQUEST (2026-09-12): Jab tak dropdown se koi report type select
            // nahi hua (placeholder par khaali), koi bhi sync/fetch shuru nahi honi
            // chahiye - isliye yahan seedha placeholder dikha kar ruk jaate hain.
            if (!summaryModule) return renderProgressReportPlaceholder();
            // Kisi bhi wajah se refreshSummary() call ho (DC/Division/Circle pick,
            // date change, wapas is view par aana) jab tak "Revenue Freeze Report"
            // tab active hai, seedha usi ke refresh path par bhej dete hain - iski
            // apni Daily/Monthly date-based logic bilkul nahi chalti (freeze usse
            // independent hai).
            if (summaryModule === "FREEZE") return refreshFreezeModuleSummary();
            updateProgressReportScopeTitle();
            const refreshToken = ++summaryRefreshToken;
            const moduleAtStart = summaryModule;
            const viewLevelAtStart = activeViewLevel;
            const dcAtStart = activeDC;
            const divAtStart = activeDiv;
            const isStaleSummaryRefresh = () => (
                refreshToken !== summaryRefreshToken ||
                moduleAtStart !== summaryModule ||
                viewLevelAtStart !== activeViewLevel ||
                dcAtStart !== activeDC ||
                divAtStart !== activeDiv
            );
            const cont = document.getElementById("summary-content");
            renderSyncingProgress(cont, () => refreshToken === summaryRefreshToken);
            const raw = document.getElementById("report-date").value;
            if (!raw) return;
            const parsedSummarySelection = parseSummarySelection(raw, summaryMode);
            const dStr = parsedSummarySelection.daily;
            const mStr = parsedSummarySelection.monthly;
            const label = parsedSummarySelection.label;

            if (summaryModule === "LOK_ADALAT") {
                if (!courtCaseRecords.length) {
                    await loadCourtCaseData();
                }
                await loadLokDistributedSheetData(true);
                if (isStaleSummaryRefresh()) return;

                const lokRows = [];
                let lokGrandTC = 0;
                let lokGrandTU = 0;

                const getLokCount = (dcName) => {
                    const normalizedDc = normalizeLookupValue(dcName);
                    if (courtCaseRecords.length) {
                        return courtCaseRecords.filter((record) => normalizeLookupValue(record.dcName) === normalizedDc).length;
                    }
                    return lokAdalatFallbackTotals[normalizedDc] || 0;
                };
                let servedData = [];
                try {
                    servedData = await loadRemoteJson(`${lokAdalatScriptUrl}?action=getSummary`);
                } catch (_) {
                    servedData = [];
                }
                const localServedMap = getServedCourtCaseMap();
                const getLokDateMatches = (rawValue) => {
                    const raw = String(rawValue || "").trim();
                    if (!raw) return false;
                    const normalized = raw.replace(/\./g, "-").replace(/\//g, "-");
                    const match = normalized.match(/^(\d{2})-(\d{2})-(\d{4})$/);
                    if (!match) return matchesProgressDate(raw, summaryMode, dStr, mStr);

                    const first = Number(match[1]);
                    const second = Number(match[2]);
                    const year = String(match[3]);
                    const monthlyCandidates = new Set();
                    const dailyCandidates = new Set();
                    const pushCandidate = (day, month) => {
                        if (!day || !month || day < 1 || day > 31 || month < 1 || month > 12) return;
                        dailyCandidates.add(`${String(day).padStart(2, "0")}/${String(month).padStart(2, "0")}/${year}`);
                        monthlyCandidates.add(`${String(month).padStart(2, "0")}/${year}`);
                    };

                    pushCandidate(first, second);
                    pushCandidate(second, first);

                    if (summaryMode === "DAILY") {
                        return dailyCandidates.has(dStr);
                    }
                    return monthlyCandidates.has(mStr);
                };

                const getLokGroupedCounts = (rows, dcFields, dateFields, matcher) => {
                    const grouped = {};
                    (Array.isArray(rows) ? rows : []).forEach((entry) => {
                        const entryDc = normalizeLookupValue((dcFields || []).map((field) => entry?.[field] || "").find(Boolean) || "");
                        const entryDate = String((dateFields || []).map((field) => entry?.[field] || "").find(Boolean) || "").trim();
                        if (!entryDc || !entryDate || !matcher(entryDate)) return;
                        grouped[entryDc] = (grouped[entryDc] || 0) + 1;
                    });
                    return grouped;
                };

                const remoteCounts = getLokGroupedCounts(servedData, ["dc_name", "dc", "DC NAME"], ["date", "DATE"], getLokDateMatches);
                const sheetCounts = getLokGroupedCounts(lokDistributedRows, ["dcName", "dc_name", "dc"], ["date", "DATE"], getLokDateMatches);
                const localCounts = (() => {
                    const grouped = {};
                    Object.values(localServedMap || {}).forEach((entry) => {
                        const entryDc = normalizeLookupValue(entry.dcName || "");
                        const servedAt = String(entry.servedAt || "").trim();
                        if (!entryDc || !servedAt) return;
                        const servedDate = new Date(servedAt);
                        if (Number.isNaN(servedDate.getTime())) return;
                        const dayStr = `${String(servedDate.getDate()).padStart(2, "0")}/${String(servedDate.getMonth() + 1).padStart(2, "0")}/${servedDate.getFullYear()}`;
                        const monthStr = `${String(servedDate.getMonth() + 1).padStart(2, "0")}/${servedDate.getFullYear()}`;
                        const matchesDate = summaryMode === "DAILY" ? dayStr === dStr : monthStr === mStr;
                        if (!matchesDate) return;
                        grouped[entryDc] = (grouped[entryDc] || 0) + 1;
                    });
                    return grouped;
                })();

                const getGroupTotal = (grouped) => Object.values(grouped || {}).reduce((sum, count) => sum + Number(count || 0), 0);
                const remoteGrand = getGroupTotal(remoteCounts);
                const sheetGrand = getGroupTotal(sheetCounts);
                const localGrand = getGroupTotal(localCounts);
                const preferredLokCounts = sheetGrand > 0
                    ? sheetCounts
                    : (remoteGrand > 0 ? remoteCounts : localCounts);

                const getLokDistributedCount = (dcName) => {
                    const normDc = normalizeLookupValue(dcName);
                    return Number(preferredLokCounts[normDc] || 0);
                };

                if (activeViewLevel === "DC") {
                    const total = getLokCount(activeDC);
                    const distributed = getLokDistributedCount(activeDC);
                    lokRows.push({ name: activeDC, tc: total, tu: distributed });
                    lokGrandTC += total;
                    lokGrandTU += distributed;
                } else {
                    const targetDcs = [...new Set((activeViewLevel === "DIVISION"
                        ? getDivisionDcNames(activeDiv)
                        : getAllDcNames()).map((dc) => normalizeDcName(dc)).filter(Boolean))];
                    targetDcs.forEach((dc) => {
                        const total = getLokCount(dc);
                        const distributed = getLokDistributedCount(dc);
                        lokRows.push({ name: dc, tc: total, tu: distributed });
                        lokGrandTC += total;
                        lokGrandTU += distributed;
                    });
                }

                const uniqueLokMap = new Map();
                lokRows.forEach((row) => {
                    const key = normalizeDcName(row.name);
                    if (!key || uniqueLokMap.has(key)) return;
                    uniqueLokMap.set(key, row);
                });
                uiListSummary = Array.from(uniqueLokMap.values());
                grandTC = uiListSummary.reduce((sum, row) => sum + Number(row.tc || 0), 0);
                grandTU = uiListSummary.reduce((sum, row) => sum + Number(row.tu || 0), 0);
                if (isStaleSummaryRefresh()) return;

                let lokHtml = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.2fr 0.9fr 1fr;"><div>DC NAME</div><div>TOTAL NOTICE</div><div>DISTRIBUTED NOTICE</div></div>`;
                uiListSummary.forEach((r) => {
                    lokHtml += `<div class="summary-table-row" style="grid-template-columns: 1.2fr 0.9fr 1fr;"><div>${r.name}</div><div>${r.tc}</div><div class="text-teal-600 font-black">${r.tu}</div></div>`;
                });
                lokHtml += `</div><div class="summary-footer"><div class="flex justify-between font-black"><span>GRAND TOTAL (${label})</span><span class="text-rose-600 text-lg">${grandTU}</span></div></div>`;
                cont.innerHTML = lokHtml;
                setProgressSummaryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`);
                return;
            }

            if (summaryModule === "REVENUE") {
                try {
                    if (activeViewLevel === "DC") {
                        await ensureConsumerDataLoadedFor([activeDC]);
                        const revenueSummaryDcKey = getRevenueCollectionDcKey(activeDC);
                        const forceMasterRefresh = revenueSummaryMasterLoadedDcKey !== revenueSummaryDcKey;
                        await loadRevenueCollectionData(activeDC, forceMasterRefresh);
                        revenueSummaryMasterLoadedDcKey = revenueSummaryDcKey;
                    }
                    // PERF FIX (2026-08-21): Daily Progress (Revenue tab) DC scope me ho
                    // to sirf usi DC ka data maango (Point 1 jaisa hi scope-tracking wala
                    // safe tarika - poori history, date-filter NAHI, kyunki yahan dropdown
                    // se date/month switch karne par bhi purana hi fetched data reuse hota
                    // hai). DIVISION/CIRCLE scope me pehle jaisa hi (sabhi DC) fetch hota
                    // hai, kyunki wahan sach me sabhi DC ka data chahiye.
                    const revenueSummaryScopeDc = activeViewLevel === "DC" ? activeDC : null;
                    await Promise.all([
                        syncRevenueLiveEntriesFromSheet(3, false, revenueSummaryScopeDc),
                        syncRevenueTdEntriesFromSheet(3, false, revenueSummaryScopeDc)
                    ]);
                    if (isStaleSummaryRefresh()) return;

                    const revenueMode = summaryMode === "MONTHLY" ? "MONTHLY" : "DAILY";
                    const revenueFilterValue = getRevenueProgressFilterValue(dStr, mStr);
                    uiListSummary = buildProgressRevenueSummaryRows(getRevenueCombinedFilteredEntries(revenueMode, revenueFilterValue));
                    const revenueTotals = getRevenueProgressTotals(uiListSummary);
                    grandTC = revenueTotals.paidCount + revenueTotals.tdCount;
                    grandTU = revenueTotals.paidAmount + revenueTotals.tdAmount;

                    // Total Consumer / Paid / Unpaid + category-wise + HQ/DC-wise summary
                    // (sirf summary, list/dropdown/consumer-level download yahan nahi hai -
                    // wo sirf dedicated "HQ / Village Wise Paid-Unpaid" report me hai).
                    // Note: getRevenueProgressFilterValue() jo format deta hai (DAILY ->
                    // DD-MM-YYYY, MONTHLY -> YYYY-MM), wahi buildRevenueCategoryUploadedPaidInfo
                    // ke andar isRevenueUploadedPaidInCategoryPeriod() bhi expect karta hai -
                    // isliye seedhe revenueFilterValue reuse kar sakte hain, alag se convert
                    // karne ki zaroorat nahi.
                    let hqVillageSummaryData = null;
                    try {
                        const [, , , reconciliation] = await Promise.all([
                            ensureRevenueCategoryMasterDataLoadedStrict_(getRevenueCategoryTargetDcs()),
                            ensureRevenueCategoryRawPaymentRowsLoaded(),
                            warmRevenueCategoryUploadedPaidCache(),
                            ensureRevenueCategoryReconciliationLoaded(revenueMode, revenueFilterValue)
                        ]);
                        if (isStaleSummaryRefresh()) return;
                        // ISOLATED ADDITION (2026-09-17, USER-APPROVED condition): yeh chhoti
                        // embedded quick-glance widget hai (poora dedicated report nahi) -
                        // agar reconciliation backend abhi purana/unavailable hai to yahan
                        // STALE/LEGACY totals dikhane ki jagah simply hide kar dete hain
                        // (existing hi placeholder text dikhta hai - koi galat number kabhi
                        // silently nahi dikhta). Dedicated HQ-Village/Target/Top-Defaulters
                        // reports me isi scenario par saaf STALE/LEGACY warning ke saath
                        // data dikhta hai (neeche dekhein) - yahan sirf yeh chhota widget hai.
                        hqVillageSummaryData = (reconciliation && reconciliation.supported === false)
                            ? null
                            : buildRevenueHqVillageSummaryData(revenueMode, revenueFilterValue);
                    } catch (_) {
                        hqVillageSummaryData = null;
                    }

                    cont.innerHTML = renderRevenueProgressSummary(uiListSummary, label, hqVillageSummaryData, revenueMode, revenueFilterValue);
                } catch (error) {
                    cont.innerHTML = '<p class="text-center text-red-500 py-10 font-black">REVENUE REPORT LOAD NAHI HO PAYI</p>';
                }
                return;
            }

            try {
                const targetMobileDcs = activeViewLevel === "DC"
                    ? [activeDC]
                    : (activeViewLevel === "DIVISION" ? getDivisionDcNames(activeDiv) : getAllDcNames());
                await ensureConsumerDataLoadedFor(targetMobileDcs);
                // PERF FIX (2026-09-13): DC-level scope me sirf usi EK DC ka
                // mobile-update data chahiye hota hai, lekin backend (getSummary)
                // pehle hamesha SAARI (~24) DC sheets ka poora data scan karke
                // bhejta tha - jaise-jaise data mahine dar mahine badhta gaya
                // (roz naye "Updated Mobile No" entries), yeh poora scan slow
                // hota gaya, aur DC-level (jahan sirf 1 sheet chahiye) bhi utna
                // hi slow/timeout hone laga jitna Circle-level. Backend (.gs)
                // me ab optional "dc" parameter support hai - DC scope me wahi
                // bhejte hain (sirf usi ek sheet scan hoti hai, fast), Division/
                // Circle scope me pehle jaisa hi bina "dc" ke poori request
                // jaati hai (unhe sach me saari DC ka data chahiye). Agar
                // backend abhi purana (bina is fix ke) deploy hai, to yeh naya
                // param chup-chaap ignore ho jayega aur pehle jaisa hi behave
                // karega - koi breaking change nahi.
                const mobileSummaryDcParam = activeViewLevel === "DC" && activeDC
                    ? `&dc=${encodeURIComponent(activeDC)}`
                    : "";
                // BUG FIX (2026-09-13): Yeh call abhi bhi purane hi 6-second
                // default timeout (loadRemoteJson) par chalti thi - sheet-scan
                // ab kaafi fast ho chuka hai (khaali rows delete + backend fix
                // ke baad), lekin dheeme/field network par khud request+response
                // hi 6 second se zyada le sakta hai, jisse har attempt turant
                // fail ho kar 3-4 retry ke bad (~15-20s) "ERROR FETCHING DATA"
                // dikhne laga. Freeze report jaisa hi ab isko bhi generous
                // 30-second timeout diya hai (backend load ab halka hai,
                // isliye asal me itna lagega nahi, bas dheeme network ke liye
                // gunjaish rakhi hai).
                const cloudData = await loadRemoteJson(`${scriptURL}?action=getSummary${mobileSummaryDcParam}`, 30000);
                if (isStaleSummaryRefresh()) return;
                uiListSummary = [];
                grandTC = 0;
                grandTU = 0;
                grandTW = 0;

                // "Wrong Mobile No" (tw) - date-independent hai (jaisa TOTAL CONS. bhi
                // hai): consumer master me jiska number invalid/khaali hai AUR jiske
                // liye kabhi bhi (kisi bhi date par) Update Mobile No se sahi number
                // submit nahi hua - "Wrong Mobile No List" screen wali hi definition,
                // bas yahan DC/HQ-wise summary-count ke roop me.
                const getFixedIvrsSetForDc = (dcName) => {
                    const normDc = normalizeDcName(dcName);
                    const set = new Set();
                    cloudData.forEach((u) => {
                        const uDc = (u.dc || "").trim().toUpperCase();
                        if (uDc !== normDc) return;
                        if (isMobileNoConsideredWrong(u.correct_mobile || "")) return;
                        const ivrs = normalizeLookupDigits(u.ivrs || "");
                        if (ivrs) set.add(ivrs);
                    });
                    return set;
                };
                const getMobileFieldFromRow = (row) => getConsumerField(row, ["MOBILE NO", "MOBILE NUMBER", "MOBILE"]);
                const isRowStillWrong = (row, fixedSet, freqMap) => {
                    const ivrs = normalizeLookupDigits(getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER", "IVRSNO"]));
                    const mobileVal = getMobileFieldFromRow(row);
                    // Ya to master sheet me hi khaali/galat-format/dummy number hai, ya
                    // isi DC me yah number 10 baar se adhik alag consumers me repeat ho
                    // raha hai (duplicate - practically itne connection ek number par
                    // sahi nahi ho sakte).
                    const isWrong = isMobileNoConsideredWrong(mobileVal) || isMobileNoDuplicateOverThreshold(mobileVal, freqMap);
                    if (!isWrong) return false;
                    return !(ivrs && fixedSet.has(ivrs));
                };

                const getStats = (dcName) => {
                    let tc = 0;
                    let tu = 0;
                    let tw = 0;
                    const normDc = normalizeDcName(dcName);
                    const rows = getConsumerRows(normDc);
                    tc = rows.length;
                    const fixedSet = getFixedIvrsSetForDc(dcName);
                    // Duplicate-count sirf abhi-bhi-wrong consumers se (Wrong Mobile No
                    // List screen jaisa hi) - taki dono jagah ka number match kare.
                    const stillActiveRowsForDup = rows.filter((row) => {
                        const ivrs = normalizeLookupDigits(getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER", "IVRSNO"]));
                        return !(ivrs && fixedSet.has(ivrs));
                    });
                    const freqMap = computeMobileDuplicateFreqMap(stillActiveRowsForDup, getMobileFieldFromRow);
                    rows.forEach((row) => {
                        if (isRowStillWrong(row, fixedSet, freqMap)) tw++;
                    });
                    cloudData.forEach((u) => {
                        const ts = (u.date || "").trim();
                        const uDc = (u.dc || "").trim().toUpperCase();
                        const mobileVal = u.correct_mobile || "";
                        const hasMobile = mobileVal.toString().trim().length === 10;
                        const matchesDate = matchesProgressDate(ts, summaryMode, dStr, mStr);
                        if (uDc === normDc && hasMobile && matchesDate) tu++;
                    });
                    return { tc, tu, tw };
                };

                if (activeViewLevel === "DC") {
                    const stats = {};
                    const fixedSet = getFixedIvrsSetForDc(activeDC);
                    const dcRows = getConsumerRows(activeDC);
                    const stillActiveDcRowsForDup = dcRows.filter((row) => {
                        const ivrs = normalizeLookupDigits(getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER", "IVRSNO"]));
                        return !(ivrs && fixedSet.has(ivrs));
                    });
                    const freqMap = computeMobileDuplicateFreqMap(stillActiveDcRowsForDup, getMobileFieldFromRow);
                    dcRows.forEach((row) => {
                        const h = getConsumerField(row, ["HQ", "HQ NAME", "HEADQUARTER", "HEAD QUARTER", "H.Q."], "GENERAL").trim().toUpperCase() || "GENERAL";
                        stats[h] = stats[h] || { tc: 0, tu: 0, tw: 0 };
                        stats[h].tc++;
                        if (isRowStillWrong(row, fixedSet, freqMap)) stats[h].tw++;
                    });
                    cloudData.forEach((u) => {
                        const ts = (u.date || "").trim();
                        const uDc = (u.dc || "").trim().toUpperCase();
                        const uHq = (u.hq || "GENERAL").trim().toUpperCase();
                        const mobileVal = u.correct_mobile || "";
                        const hasMobile = mobileVal.toString().trim().length === 10;
                        const matchesDate = matchesProgressDate(ts, summaryMode, dStr, mStr);
                        if (uDc === normalizeDcName(activeDC) && hasMobile && matchesDate) {
                            if (!stats[uHq]) stats[uHq] = { tc: 0, tu: 0, tw: 0 };
                            stats[uHq].tu++;
                        }
                    });
                    Object.keys(stats).sort().forEach((h) => {
                        uiListSummary.push({ name: h, tc: stats[h].tc, tu: stats[h].tu, tw: stats[h].tw });
                        grandTC += stats[h].tc;
                        grandTU += stats[h].tu;
                        grandTW += stats[h].tw;
                    });
                } else {
                    const targetDivs = activeViewLevel === "DIVISION" ? [activeDiv] : Object.keys(divisionConfigs);
                    targetDivs.forEach((div) => {
                        let divTC = 0;
                        let divTU = 0;
                        let divTW = 0;
                        getDivisionSubDnGroups(div).forEach((group) => {
                            let subTC = 0;
                            let subTU = 0;
                            let subTW = 0;
                            group.dcs.forEach((dc) => {
                                const s = getStats(dc);
                                uiListSummary.push({ name: dc, tc: s.tc, tu: s.tu, tw: s.tw });
                                subTC += s.tc;
                                subTU += s.tu;
                                subTW += s.tw;
                            });
                            uiListSummary.push({ name: `SUB DN ${group.subDn} TOTAL`, tc: subTC, tu: subTU, tw: subTW, type: "SUBDN_TOTAL" });
                            divTC += subTC;
                            divTU += subTU;
                            divTW += subTW;
                        });
                        if (activeViewLevel === "CIRCLE") uiListSummary.push({ name: `${div} TOTAL`, tc: divTC, tu: divTU, tw: divTW, type: "DIV_TOTAL" });
                        grandTC += divTC;
                        grandTU += divTU;
                        grandTW += divTW;
                    });
                }

                const colLabel = activeViewLevel === "DC" ? "HQ NAME" : "DC NAME";
                const mobileGridCols = "1.4fr 0.85fr 0.85fr 0.85fr";
                let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: ${mobileGridCols};"><div>${colLabel}</div><div>TOTAL CONS.</div><div>WRONG MOBILE NO</div><div>UPDATED MOBILE NO</div></div>`;
                uiListSummary.forEach((r) => {
                    const rowClass = r.type === "DIV_TOTAL" ? "blue-bold" : (r.type === "SUBDN_TOTAL" ? "subdn-bold" : "");
                    html += `<div class="summary-table-row ${rowClass}" style="grid-template-columns: ${mobileGridCols};"><div>${r.name}</div><div>${r.tc}</div><div class="text-rose-600 font-black">${r.tw || 0}</div><div class="text-teal-600 font-black">${r.tu}</div></div>`;
                });

                html += `</div><div class="summary-footer"><div class="flex justify-between font-black"><span>GRAND TOTAL (${label})</span><span class="text-rose-600 text-lg">${grandTU}</span></div><div class="flex justify-between font-black" style="margin-top:4px;"><span>TOTAL WRONG MOBILE NO</span><span class="text-rose-600 text-lg">${grandTW}</span></div>
                    <div class="btn-export-row">
                        <button class="btn-unique btn-excel-unique" onclick="doExport('XLS')">
                            <svg width="18" height="18" fill="white" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16h-8v-2h8v2zm0-4h-8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
                            Excel Report
                        </button>
                        <button class="btn-unique btn-pdf-unique" onclick="doExport('PDF')">
                            <svg width="18" height="18" fill="white" viewBox="0 0 24 24"><path d="M20 2H8c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-8.5 7.5c0 .83-.67 1.5-1.5 1.5H9v2H7.5V7H10c.83 0 1.5.67 1.5 1.5v1zm5 2c0 .83-.67 1.5-1.5 1.5h-2.5V7H15c.83 0 1.5.67 1.5 1.5v3zm4-3H19v1h1.5V11H19v2h-1.5V7h3v1.5zM9 9.5h1v-1H9v1zM4 6H2v14c0 1.1.9 2 2 2h14v-2H4V6zm10 5.5h1v-3h-1v3z"/></svg>
                            PDF Report
                        </button>
                    </div>
                    <div id="progress-summary-download-status" style="display:none; text-align:center; font-weight:900; border-radius:16px; padding:10px 12px; width:100%; margin-top:12px;"></div>
                </div>`;
                cont.innerHTML = html;
            } catch (e) {
                cont.innerHTML = '<p class="text-center text-red-500 py-10 font-black">ERROR FETCHING DATA</p>';
            }
        }

        function getFormattedDate(rawDate, mode) {
            if (!rawDate) return "";
            if (mode === "DAILY") {
                const [y, m, d] = rawDate.split("-");
                return `${d}/${m}/${y}`;
            }
            const [y, m] = rawDate.split("-");
            const months = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"];
            return `${months[parseInt(m, 10) - 1]}-${y}`;
        }

        function getProgressDateCandidates(rawValue) {
            const raw = String(rawValue || "").trim();
            if (!raw) return [];

            const candidates = new Set();
            const addCandidate = (day, month, year) => {
                const d = String(day || "").padStart(2, "0");
                const m = String(month || "").padStart(2, "0");
                const y = String(year || "").trim();
                if (!d || !m || !y || y.length !== 4) return;
                candidates.add(`${d}/${m}/${y}`);
            };

            if (/^\d{2}[/-]\d{2}[/-]\d{4}$/.test(raw)) {
                const [a, b, y] = raw.split(/[/-]/);
                addCandidate(a, b, y);
                addCandidate(b, a, y);
            }

            if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
                const [y, m, d] = raw.split("-");
                addCandidate(d, m, y);
            }

            const parsedDate = new Date(raw);
            if (!Number.isNaN(parsedDate.getTime())) {
                addCandidate(parsedDate.getDate(), parsedDate.getMonth() + 1, parsedDate.getFullYear());
            }

            if (!candidates.size && raw.includes("/")) {
                candidates.add(raw);
            }

            return Array.from(candidates);
        }

        function normalizeProgressDateValue(rawValue) {
            return getProgressDateCandidates(rawValue)[0] || "";
        }

        function matchesProgressDate(rawValue, mode, dailyValue, monthlyValue) {
            const candidates = getProgressDateCandidates(rawValue);
            if (!candidates.length) return false;
            if (mode === "DAILY") return candidates.includes(dailyValue);
            return candidates.some((normalized) => {
                const parts = normalized.split("/");
                if (parts.length !== 3) return false;
                return `${parts[1]}/${parts[2]}` === monthlyValue;
            });
        }

        function getCurrentDateDDMMYYYY() {
            const date = new Date();
            const day = String(date.getDate()).padStart(2, "0");
            const month = String(date.getMonth() + 1).padStart(2, "0");
            const year = date.getFullYear();
            return `${day}-${month}-${year}`;
        }

        function getTodayIsoDate() {
            const date = new Date();
            const day = String(date.getDate()).padStart(2, "0");
            const month = String(date.getMonth() + 1).padStart(2, "0");
            const year = date.getFullYear();
            return `${year}-${month}-${day}`;
        }

        function getTodayFeederDisplayDate() {
            return getCurrentDateDDMMYYYY().replace(/-/g, "/");
        }

        function formatFeederDisplayDateFromIso(isoValue) {
            const raw = String(isoValue || "").trim();
            if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) return getTodayFeederDisplayDate();
            const [year, month, day] = raw.split("-");
            return `${day}/${month}/${year}`;
        }

        function syncFeederDateInputs(isoValue) {
            const displayLabel = document.getElementById("feeder-reading-date-label");
            const safeIso = /^\d{4}-\d{2}-\d{2}$/.test(String(isoValue || "").trim()) ? String(isoValue).trim() : getTodayIsoDate();
            if (displayLabel) {
                displayLabel.innerText = formatFeederDisplayDateFromIso(safeIso);
            }
            const [year, month, day] = safeIso.split("-");
            const daySelect = document.getElementById("feeder-date-day");
            const monthSelect = document.getElementById("feeder-date-month");
            const yearSelect = document.getElementById("feeder-date-year");
            if (daySelect) daySelect.value = String(Number(day));
            if (monthSelect) monthSelect.value = String(Number(month));
            if (yearSelect) yearSelect.value = year;
            const dateButton = document.getElementById("feeder-reading-date");
            if (dateButton) {
                dateButton.dataset.iso = safeIso;
            }
        }

        function populateFeederDatePickerOptions() {
            const daySelect = document.getElementById("feeder-date-day");
            const monthSelect = document.getElementById("feeder-date-month");
            const yearSelect = document.getElementById("feeder-date-year");
            if (!daySelect || !monthSelect || !yearSelect) return;
            if (!daySelect.innerHTML) {
                daySelect.innerHTML = Array.from({ length: 31 }, (_, index) => {
                    const value = index + 1;
                    return `<option value="${value}">${String(value).padStart(2, "0")}</option>`;
                }).join("");
            }
            if (!monthSelect.innerHTML) {
                monthSelect.innerHTML = Array.from({ length: 12 }, (_, index) => {
                    const value = index + 1;
                    return `<option value="${value}">${String(value).padStart(2, "0")}</option>`;
                }).join("");
            }
            if (!yearSelect.innerHTML) {
                const currentYear = new Date().getFullYear();
                yearSelect.innerHTML = [currentYear - 1, currentYear, currentYear + 1]
                    .map((year) => `<option value="${year}">${year}</option>`)
                    .join("");
            }
        }

        function toggleFeederDatePicker(forceState) {
            const menu = document.getElementById("feeder-reading-date-menu");
            const trigger = document.getElementById("feeder-reading-date");
            if (!menu || !trigger) return;
            const shouldShow = typeof forceState === "boolean" ? forceState : !menu.classList.contains("show");
            if (shouldShow) {
                populateFeederDatePickerOptions();
                menu.classList.add("show");
                trigger.classList.add("active");
            } else {
                menu.classList.remove("show");
                trigger.classList.remove("active");
            }
        }

        function applyFeederDateSelection() {
            const daySelect = document.getElementById("feeder-date-day");
            const monthSelect = document.getElementById("feeder-date-month");
            const yearSelect = document.getElementById("feeder-date-year");
            if (!daySelect || !monthSelect || !yearSelect) return;
            const day = String(daySelect.value || "").padStart(2, "0");
            const month = String(monthSelect.value || "").padStart(2, "0");
            const year = String(yearSelect.value || "").trim();
            if (!day || !month || !year) return;
            syncFeederDateInputs(`${year}-${month}-${day}`);
            toggleFeederDatePicker(false);
            if (selectedFeederSubstation) {
                renderFeederRows();
            }
        }

        function formatFeederEntryDate(dateValue) {
            const raw = String(dateValue || "").trim();
            if (!raw) return getCurrentDateDDMMYYYY();
            if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
                const [year, month, day] = raw.split("-");
                return `${day}-${month}-${year}`;
            }
            if (/^\d{2}\/\d{2}\/\d{4}$/.test(raw)) {
                return raw.replace(/\//g, "-");
            }
            const normalized = normalizeFeederDateInput(raw);
            if (/^\d{2}\/\d{2}\/\d{4}$/.test(normalized)) {
                return normalized.replace(/\//g, "-");
            }
            return raw.replace(/\//g, "-");
        }

        function buildFeederDateKey_(value) {
            const raw = String(value || "").trim();
            if (!raw) return "";
            if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
            const normalized = raw.replace(/\//g, "-");
            if (/^\d{2}-\d{2}-\d{4}$/.test(normalized)) {
                const [day, month, year] = normalized.split("-");
                return `${year}-${month}-${day}`;
            }
            const parsed = new Date(raw);
            if (!Number.isNaN(parsed.getTime())) {
                const day = String(parsed.getDate()).padStart(2, "0");
                const month = String(parsed.getMonth() + 1).padStart(2, "0");
                const year = parsed.getFullYear();
                return `${year}-${month}-${day}`;
            }
            return "";
        }

        function formatFeederDateLabelFromKey_(dateKey) {
            const raw = String(dateKey || "").trim();
            const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!match) return raw;
            return `${match[3]}-${match[2]}-${match[1]}`;
        }

        function normalizeFeederSubstationKey_(value) {
            return String(value || "").replace(/\s+/g, " ").trim().toUpperCase();
        }

        function getRecentFeederSubmittedEntries_() {
            return Array.isArray(feederRecentSubmittedEntries) ? feederRecentSubmittedEntries : [];
        }

        function loadRecentFeederSubmittedEntries_() {
            try {
                const raw = localStorage.getItem(feederRecentSubmittedStorageKey);
                const parsed = JSON.parse(raw || "[]");
                feederRecentSubmittedEntries = Array.isArray(parsed) ? parsed.slice(-500) : [];
            } catch (_) {
                feederRecentSubmittedEntries = [];
            }
        }

        function persistRecentFeederSubmittedEntries_() {
            try {
                localStorage.setItem(feederRecentSubmittedStorageKey, JSON.stringify(getRecentFeederSubmittedEntries_().slice(-500)));
            } catch (_) {}
        }

        function saveRecentFeederSubmittedEntries_(entries) {
            if (!Array.isArray(entries) || !entries.length) return;
            const nextEntries = getRecentFeederSubmittedEntries_().concat(entries);
            const deduped = [];
            const seen = new Set();
            nextEntries.slice().reverse().forEach((entry) => {
                const key = [
                    normalizeFeederSubstationKey_(entry["33/11 KV SUBSTATION"] || entry.substation || ""),
                    String(entry["33 AND 11 KV FEEDER"] || entry.feeder || "").trim().toUpperCase(),
                    buildFeederDateKey_(entry["DATE(DD/MM/YYY)"] || entry.date || ""),
                    String(entry["TIME(HH/MM)"] || entry.time || "").trim(),
                    String(entry["DC NAME"] || entry.dc_name || "").trim().toUpperCase()
                ].join("|");
                if (!key || seen.has(key)) return;
                seen.add(key);
                deduped.unshift(entry);
            });
            feederRecentSubmittedEntries = deduped.slice(-500);
            persistRecentFeederSubmittedEntries_();
        }

        function getFeederSelectedDateKey_() {
            const dateButton = document.getElementById("feeder-reading-date");
            return buildFeederDateKey_(dateButton?.dataset.iso || "");
        }

        function getAllFeederHistoryEntries_(substation) {
            // BUG FIX (2026-09-14): jab substation-scoped lightweight cache available
            // hai (dekhein loadFeederSubstationHistory_), usi ko priority dete hain -
            // poori 1.5+ MB history (feederReportRows, jo slow/unstable load hoti hai)
            // sirf tab fallback hoti hai jab wo kisi aur reason se already load ho
            // chuki ho (jaise Report screen).
            const substationKey = normalizeFeederSubstationKey_(substation || "");
            const scopedRows = substationKey && feederSubstationHistoryCache_[substationKey];
            const sheetRows = scopedRows ? scopedRows : (Array.isArray(feederReportRows) ? feederReportRows : []);
            const localRows = getRecentFeederSubmittedEntries_();
            return [...sheetRows, ...localRows];
        }

        function getFeederSubmittedEntriesForDate_(substation, selectedDateKey) {
            const substationKey = normalizeFeederSubstationKey_(substation || "");
            const targetKey = String(selectedDateKey || "").trim();
            if (!substationKey || !targetKey) return [];
            return getAllFeederHistoryEntries_(substation).filter((entry) => {
                const entrySubstationKey = normalizeFeederSubstationKey_(entry["33/11 KV SUBSTATION"] || entry.substation || "");
                const entryDateKey = buildFeederDateKey_(entry["DATE(DD/MM/YYY)"] || entry["DATE(DD/MM/YYYY)"] || entry.date || "");
                return entrySubstationKey === substationKey && entryDateKey === targetKey;
            });
        }

        function getFeederSubmittedRowForDate_(row, selectedDateKey) {
            const targetKey = String(selectedDateKey || "").trim();
            if (!row || !targetKey) return null;
            const substationKey = normalizeFeederSubstationKey_(row.substation || "");
            const feederKey = String(row.feeder || "").trim().toUpperCase();
            const matchedEntries = getFeederSubmittedEntriesForDate_(row.substation || "", targetKey)
                .filter((entry) => {
                    const entrySubstationKey = normalizeFeederSubstationKey_(entry["33/11 KV SUBSTATION"] || entry.substation || "");
                    const entryFeederKey = String(entry["33 AND 11 KV FEEDER"] || entry.feeder || "").trim().toUpperCase();
                    return entrySubstationKey === substationKey && entryFeederKey === feederKey;
                })
                .sort((a, b) => {
                    const aTime = String(a["TIME(HH/MM)"] || a["TIME(HH:MM)"] || a.time || "");
                    const bTime = String(b["TIME(HH/MM)"] || b["TIME(HH:MM)"] || b.time || "");
                    return aTime.localeCompare(bTime);
                });
            return matchedEntries.length ? matchedEntries[matchedEntries.length - 1] : null;
        }

        function getFeederAutoPreviousReading_(row, selectedDateKey) {
            const targetKey = String(selectedDateKey || "").trim();
            if (!row || !targetKey) return "";
            const substationKey = normalizeFeederSubstationKey_(row.substation || "");
            const feederKey = String(row.feeder || "").trim().toUpperCase();
            const matchedEntries = getAllFeederHistoryEntries_(row.substation)
                .filter((entry) => {
                    const entrySubstationKey = normalizeFeederSubstationKey_(entry["33/11 KV SUBSTATION"] || entry.substation || "");
                    const entryFeederKey = String(entry["33 AND 11 KV FEEDER"] || entry.feeder || "").trim().toUpperCase();
                    const entryDateKey = buildFeederDateKey_(entry["DATE(DD/MM/YYY)"] || entry["DATE(DD/MM/YYYY)"] || entry.date || "");
                    return entrySubstationKey === substationKey && entryFeederKey === feederKey && entryDateKey && entryDateKey < targetKey;
                })
                .sort((a, b) => {
                    const aDateKey = buildFeederDateKey_(a["DATE(DD/MM/YYY)"] || a["DATE(DD/MM/YYYY)"] || a.date || "");
                    const bDateKey = buildFeederDateKey_(b["DATE(DD/MM/YYY)"] || b["DATE(DD/MM/YYYY)"] || b.date || "");
                    if (aDateKey !== bDateKey) return aDateKey.localeCompare(bDateKey);
                    const aTime = String(a["TIME(HH/MM)"] || a["TIME(HH:MM)"] || a.time || "");
                    const bTime = String(b["TIME(HH/MM)"] || b["TIME(HH:MM)"] || b.time || "");
                    return aTime.localeCompare(bTime);
                });
            const latest = matchedEntries[matchedEntries.length - 1];
            return latest ? String(latest["CURRENT READING"] || latest.current_reading || "").trim() : "";
        }

        function buildFeederPendingDateKeys_(substation) {
            const substationKey = normalizeFeederSubstationKey_(substation);
            if (!substationKey) return [];
            const submittedDates = new Set(
                getAllFeederHistoryEntries_(substation)
                    .filter((entry) => normalizeFeederSubstationKey_(entry["33/11 KV SUBSTATION"] || entry.substation || "") === substationKey)
                    .map((entry) => buildFeederDateKey_(entry["DATE(DD/MM/YYY)"] || entry["DATE(DD/MM/YYYY)"] || entry.date || ""))
                    .filter(Boolean)
            );
            const pendingKeys = [];
            const todayKey = buildFeederDateKey_(getTodayIsoDate());
            if (!todayKey || todayKey <= feederAlertStartDateKey) return [];
            const cursor = new Date(feederAlertStartDateKey);
            const yesterday = new Date(todayKey);
            yesterday.setDate(yesterday.getDate() - 1);
            while (cursor <= yesterday) {
                const day = String(cursor.getDate()).padStart(2, "0");
                const month = String(cursor.getMonth() + 1).padStart(2, "0");
                const year = cursor.getFullYear();
                const dateKey = `${year}-${month}-${day}`;
                if (!submittedDates.has(dateKey)) {
                    pendingKeys.push(dateKey);
                }
                cursor.setDate(cursor.getDate() + 1);
            }
            return pendingKeys;
        }

        function getFeederBlockingPendingDateKeys_(substation, selectedDateKey) {
            const targetKey = String(selectedDateKey || "").trim();
            if (!targetKey) return [];
            return buildFeederPendingDateKeys_(substation).filter((dateKey) => dateKey < targetKey);
        }

        function buildFeederPendingAlertMessage_(pendingKeys) {
            const pendingLabels = (pendingKeys || []).map((item) => formatFeederDateLabelFromKey_(item));
            if (!pendingLabels.length) return "";
            return pendingLabels.length === 1
                ? `Alert: ${pendingLabels[0]} ki Entry Pending hai Aapki`
                : `Alert: ${pendingLabels.join(" and ")} ki Entry Pending hai Aapki`;
        }

        function updateFeederPendingAlert(substation) {
            if (!substation) {
                setFeederStatus("", false);
                return;
            }
            const pendingKeys = buildFeederPendingDateKeys_(substation);
            const todayKey = buildFeederDateKey_(getTodayIsoDate());
            if (!todayKey || todayKey <= feederAlertStartDateKey) {
                setFeederStatus("Aapke Dwara Aaj se Pahle ki Sabhi Reading Submit kar Di hai, Sirf Aaj ki Entry Kare", true, "success");
                return;
            }
            if (!pendingKeys.length) {
                setFeederStatus("Aapke Dwara Aaj se Pahle ki Sabhi Reading Submit kar Di hai, Sirf Aaj ki Entry Kare", true, "success");
                return;
            }
            const message = buildFeederPendingAlertMessage_(pendingKeys);
            setFeederStatus(message, true, "alert");
        }

        function doExport(fmt) {
            if (progressSummaryDownloadInProgress) {
                showToast("Download process chal raha hai, kripya wait kijiye", false);
                return;
            }
            progressSummaryDownloadInProgress = true;
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            let downloadCompleted = false;
            setProgressSummaryDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
            const levelT = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
            const rawVal = document.getElementById("report-date").value;
            const dateLabel = summaryMode === "DAILY" ? "DATE - " + getFormattedDate(rawVal, "DAILY") : "MONTH - " + getFormattedDate(rawVal, "MONTHLY");
            const reportType = summaryMode === "DAILY" ? "DAILY" : "MONTHLY";
            const colLabel = summaryModule === "LOK_ADALAT" ? "DC NAME" : (activeViewLevel === "DC" ? "HQ NAME" : "DC NAME");
            const reportHeading = summaryModule === "LOK_ADALAT" ? "LOK ADALAT NOTICE SUMMARY" : "UPDATED MOBILE NO SUMMARY";
            const valueLabel = summaryModule === "LOK_ADALAT" ? "TOTAL NOTICE" : "UPDATED MOBILE NO";

            if (summaryModule === "REVENUE") {
                const revenueColLabel = getRevenueProgressColumnLabel();
                const revenueTotals = getRevenueProgressTotals(uiListSummary);
                const revenueScopeLabel = activeViewLevel === "DC" ? `DC: ${activeDC}` : (activeViewLevel === "DIVISION" ? `Division: ${activeDiv}` : "Circle: SEONI CIRCLE");
                const revenueFilterLabel = activeViewLevel === "DC" ? `${revenueHqLabel()} Filter: ${revenueHqAllLabel()}` : (activeViewLevel === "DIVISION" ? "DC Filter: All DC" : "Division/DC Filter: All");
                const showPaid = progressStaffTypeFilter !== "TD";
                const showTd = progressStaffTypeFilter !== "PAID";
                const typeLabel = progressStaffTypeFilter === "PAID" ? "Paid by Staff" : (progressStaffTypeFilter === "TD" ? "TD by Staff" : "Paid + TD Both");
                const revenueReportTitle = `${levelT} ${reportType} PROGRESS REPORT`;
                const revenueGeneratedAt = `${getCurrentDateDDMMYYYY()} ${getCurrentTimeHHMM()}`;
                const csvSafe = (value) => {
                    const text = String(value ?? "");
                    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
                };
                const revenueHeaders = [revenueColLabel];
                if (showPaid) revenueHeaders.push("NO OF CONSUMER PAID", "TOTAL PAID AMOUNT");
                if (showTd) revenueHeaders.push("NO OF LINE TD", "TD AMOUNT");
                const revenueRowValues = (row) => {
                    const values = [row.name];
                    if (showPaid) values.push(row.paidCount, formatProgressReportAmount(row.paidAmount));
                    if (showTd) values.push(row.tdCount, formatProgressReportAmount(row.tdAmount));
                    return values;
                };
                const revenueGrandTotalValues = () => {
                    const values = ["GRAND TOTAL"];
                    if (showPaid) values.push(revenueTotals.paidCount, formatProgressReportAmount(revenueTotals.paidAmount));
                    if (showTd) values.push(revenueTotals.tdCount, formatProgressReportAmount(revenueTotals.tdAmount));
                    return values;
                };

                if (fmt === "XLS") {
                    let csv = [
                        ["DEVELOPED BY", "AKHILESH PATIDAR (AE)"],
                        ["REPORT TITLE", revenueReportTitle],
                        ["PERIOD", dateLabel],
                        ["SCOPE", revenueScopeLabel],
                        ["FILTER", revenueFilterLabel],
                        ["TYPE", typeLabel],
                        ["GENERATED AT", revenueGeneratedAt],
                        [],
                        ["REVENUE COLLECTION SUMMARY"]
                    ].map((row) => row.map(csvSafe).join(",")).join("\n") + "\n";
                    csv += revenueHeaders.map(csvSafe).join(",") + "\n";
                    uiListSummary.forEach((row) => {
                        csv += revenueRowValues(row).map(csvSafe).join(",") + "\n";
                    });
                    csv += revenueGrandTotalValues().map(csvSafe).join(",");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `Revenue_Report_${levelT}_${reportType}${progressStaffTypeFilter ? "_" + progressStaffTypeFilter : ""}.csv`;
                    link.click();
                } else {
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7);
                    doc.setTextColor(100);
                    doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 10);
                    doc.setFontSize(15);
                    doc.setTextColor(29, 78, 216);
                    doc.text(revenueReportTitle, 148, 18, { align: "center" });
                    doc.setFontSize(9);
                    doc.setTextColor(30, 58, 138);
                    doc.text(dateLabel, 148, 25, { align: "center" });
                    doc.text(`${revenueScopeLabel} | ${revenueFilterLabel} | Type: ${typeLabel}`, 148, 31, { align: "center" });
                    doc.setFontSize(7);
                    doc.setTextColor(100);
                    doc.text(`Generated: ${revenueGeneratedAt}`, 283, 10, { align: "right" });
                    doc.setFontSize(9);
                    doc.setTextColor(30, 58, 138);
                    doc.text("REVENUE COLLECTION SUMMARY", 148, 38, { align: "center" });
                    doc.autoTable({
                        startY: 43,
                        head: [revenueHeaders],
                        body: uiListSummary.map((row) => revenueRowValues(row)),
                        foot: [revenueGrandTotalValues()],
                        theme: "grid",
                        styles: { fontSize: 8, cellPadding: 2, overflow: "linebreak", halign: "center" },
                        headStyles: { fillColor: [37, 99, 235], halign: "center" },
                        columnStyles: { 0: { halign: "left", cellWidth: 55 } },
                        footStyles: { fillColor: [241, 245, 249], textColor: [190, 18, 60], fontStyle: "bold", halign: "center" },
                        didParseCell(data) {
                            if (data.section === "body") {
                                const rowValue = data.row.raw[0];
                                if (rowValue && /SUB TOTAL|DIVISION TOTAL/.test(String(rowValue))) {
                                    data.cell.styles.fontStyle = "bold";
                                    data.cell.styles.textColor = [30, 58, 138];
                                    data.cell.styles.fillColor = [239, 246, 255];
                                }
                            }
                        }
                    });
                savePdfDocumentForDevice(doc, `Revenue_Report_${levelT}_${reportType}${progressStaffTypeFilter ? "_" + progressStaffTypeFilter : ""}.pdf`);
                }
                downloadCompleted = true;
                setTimeout(() => setProgressSummaryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
                return;
            }

            if (fmt === "XLS") {
                let csv = `DEVELOPED BY - AKHILESH PATIDAR (AE)\n${levelT} ${reportType} PROGRESS REPORT\n${dateLabel}\n${reportHeading}\n\n`;
                if (summaryModule === "LOK_ADALAT") {
                    csv += `${colLabel},${valueLabel},DISTRIBUTED NOTICE\n`;
                    uiListSummary.forEach((r) => {
                        csv += `${r.name},${r.tc},${r.tu}\n`;
                    });
                    csv += `GRAND TOTAL,${grandTC},${grandTU}`;
                } else {
                    csv += `${colLabel},TOTAL CONS.,WRONG MOBILE NO,${valueLabel}\n`;
                    uiListSummary.forEach((r) => {
                        csv += `${r.name},${r.tc},${r.tw || 0},${r.tu}\n`;
                    });
                    csv += `GRAND TOTAL,${grandTC},${grandTW},${grandTU}`;
                }
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `Report_${levelT}_${reportType}.csv`;
                link.click();
            } else {
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF();
                doc.setFontSize(7);
                doc.setTextColor(100);
                doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 10);
                doc.setFontSize(15);
                doc.setTextColor(0);
                doc.text(`${levelT} ${reportType} PROGRESS REPORT`, 105, 20, { align: "center" });
                doc.setFontSize(11);
                doc.text(dateLabel, 105, 28, { align: "center" });
                doc.setFontSize(9);
                doc.setTextColor(80);
                doc.text(reportHeading, 105, 34, { align: "center" });
                doc.autoTable({
                    startY: 40,
                    head: [summaryModule === "LOK_ADALAT" ? [colLabel, valueLabel, "DISTRIBUTED NOTICE"] : [colLabel, "TOTAL CONS.", "WRONG MOBILE NO", valueLabel]],
                    body: summaryModule === "LOK_ADALAT" ? uiListSummary.map((r) => [r.name, r.tc, r.tu]) : uiListSummary.map((r) => [r.name, r.tc, r.tw || 0, r.tu]),
                    foot: [summaryModule === "LOK_ADALAT" ? ["GRAND TOTAL", grandTC, grandTU] : ["GRAND TOTAL", grandTC, grandTW, grandTU]],
                    theme: "grid",
                    headStyles: { fillColor: [13, 148, 136], halign: "center" },
                    columnStyles: summaryModule === "LOK_ADALAT" ? { 0: { halign: "left" }, 1: { halign: "center" }, 2: { halign: "center" } } : { 0: { halign: "left" }, 1: { halign: "center" }, 2: { halign: "center" }, 3: { halign: "center" } },
                    footStyles: { fillColor: [241, 245, 249], textColor: [190, 18, 60], fontStyle: "bold", halign: "center" },
                    didParseCell(data) {
                        if (data.section === "body") {
                            const rowValue = data.row.raw[0];
                            if (rowValue && rowValue.toString().includes("TOTAL")) {
                                data.cell.styles.fontStyle = "bold";
                                data.cell.styles.textColor = [30, 58, 138];
                            }
                        }
                    }
                });
                savePdfDocumentForDevice(doc, `Report_${levelT}_${reportType}.pdf`);
            }
            downloadCompleted = true;
            setTimeout(() => setProgressSummaryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                showToast(error?.message || "Report download nahi ho payi", false);
                setProgressSummaryDownloadState(false, "Download nahi ho paya");
            } finally {
                setTimeout(() => {
                    progressSummaryDownloadInProgress = false;
                    if (downloadCompleted) {
                        setProgressSummaryDownloadState(false, `${downloadTypeLabel} download ho chuki hai`);
                    }
                }, 700);
            }
        }

        function getActionStatusText(state) {
            if (state === "processing") return "Processing...";
            if (state === "done") return "Done";
            if (state === "failed") return "Failed - Retry";
            return "";
        }

        function normalizeActionStatusMessage(message, isProcessing = false, ok = true) {
            if (isProcessing) return getActionStatusText("processing");
            const raw = String(message || "").trim();
            if (!raw) return "";
            const lower = raw.toLowerCase();
            if (ok && (lower.includes("download ho chuki") || lower.includes("upload successful") || lower.includes("upload complete") || lower.includes("submit ho"))) {
                return getActionStatusText("done");
            }
            if (!ok && (lower.includes("download nahi") || lower.includes("upload nahi") || lower.includes("submit nahi") || lower.includes("dobara try") || lower.includes("network issue") || lower.includes("blocked"))) {
                return getActionStatusText("failed");
            }
            return ok ? getActionStatusText("done") : getActionStatusText("failed");
        }

        function setActionButtonState(button, state, defaultText = "Submit") {
            if (!button) return;
            const isProcessing = state === "processing";
            button.disabled = isProcessing;
            const text = state === "idle" ? defaultText : (getActionStatusText(state) || defaultText);
            button.innerHTML = isProcessing ? `<span class="btn-inline-spinner"></span>${text}` : text;
            button.style.opacity = isProcessing ? "0.65" : "1";
            button.style.pointerEvents = isProcessing ? "none" : "auto";
        }

        let deferredPwaInstallPrompt = null;

        // Pehle yahan 14-din ka "dismiss cooldown" tha - ek baar banner cross (✕) karne
        // ke baad 14 din tak dobara nahi dikhta tha, chahe app install ho ya na ho. Ab
        // sirf ek hi cheez check hoti hai: app installed hai ya nahi. Jab tak install
        // nahi hota, har refresh/reopen par banner phir se dikhega; install ho jaane par
        // (isRunningAsInstalledPwa() true) hamesha ke liye band ho jayega.
        function isRunningAsInstalledPwa() {
            return window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
        }

        function showPwaInstallBanner(platform) {
            if (isRunningAsInstalledPwa()) return;
            const banner = document.getElementById("pwa-install-banner");
            const title = document.getElementById("pwa-install-banner-title");
            const message = document.getElementById("pwa-install-banner-message");
            const actionBtn = document.getElementById("pwa-install-action-btn");
            if (!banner) return;
            if (platform === "ios") {
                title.innerText = "App Install Karein";
                message.innerText = "Share button dabाइए, phir 'Add to Home Screen' select kijiye.";
                actionBtn.innerText = "Samjh Gaya";
            } else {
                title.innerText = "App Install Karein";
                message.innerText = "Home screen se seedhe app kholiye, network kam use hoga.";
                actionBtn.innerText = "Install";
            }
            banner.dataset.platform = platform;
            banner.style.display = "block";
        }

        function dismissPwaInstallBanner() {
            // Sirf abhi ke liye (is session/page-view me) banner hata do - koi long-term
            // "dismissed" flag save nahi karte, taaki agli baar refresh/reopen karne par
            // (jab tak app install nahi hua) banner phir se dikhe.
            const banner = document.getElementById("pwa-install-banner");
            if (banner) banner.style.display = "none";
        }

        async function handlePwaInstallAction() {
            const banner = document.getElementById("pwa-install-banner");
            const platform = banner?.dataset.platform;
            if (platform === "ios") {
                dismissPwaInstallBanner();
                return;
            }
            if (!deferredPwaInstallPrompt) {
                dismissPwaInstallBanner();
                return;
            }
            deferredPwaInstallPrompt.prompt();
            try { await deferredPwaInstallPrompt.userChoice; } catch (_) {}
            deferredPwaInstallPrompt = null;
            dismissPwaInstallBanner();
        }

        window.addEventListener("beforeinstallprompt", (event) => {
            event.preventDefault();
            deferredPwaInstallPrompt = event;
            showPwaInstallBanner("android");
        });

        window.addEventListener("appinstalled", () => {
            dismissPwaInstallBanner();
        });

        function initPwaInstallBannerForIos() {
            const isIos = /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
            if (isIos) showPwaInstallBanner("ios");
        }

        function toggleDarkMode() {
            const isOn = document.documentElement.classList.toggle("dark-mode-on");
            const btn = document.getElementById("dark-mode-toggle-btn");
            if (btn) btn.innerText = isOn ? "☀️" : "🌙";
            try { localStorage.setItem("seoni-dark-mode", isOn ? "1" : "0"); } catch (_) {}
        }

        function initDarkModePreference() {
            let saved = "0";
            try { saved = localStorage.getItem("seoni-dark-mode") || "0"; } catch (_) {}
            if (saved === "1") {
                document.documentElement.classList.add("dark-mode-on");
                const btn = document.getElementById("dark-mode-toggle-btn");
                if (btn) btn.innerText = "☀️";
            }
        }

        // App ko dobara band-open kiye bina "refresh" karne ka feature:
        // 1) Service worker ko turant check-for-update bolte hain (naya version mile to activate).
        // 2) Sabhi Cache Storage entries clear karte hain (SHELL_FILES/CDN cache) taaki agli
        //    fetch me purani cached copy kabhi na mile.
        // 3) Naya service worker "waiting" me mile to usko turant skipWaiting bolke activate
        //    karwate hain (controllerchange par page apne aap reload hoga).
        // 4) Fallback: agar upar wala kuch bhi fail ho ya na chale (service worker support na ho),
        //    phir bhi seedha location.reload() kar dete hain taaki user ko hamesha latest mile.
        let appRefreshInProgress = false;
        async function refreshAppNow() {
            if (appRefreshInProgress) return;
            appRefreshInProgress = true;
            const btn = document.getElementById("app-refresh-btn");
            if (btn) { btn.classList.add("app-refresh-spinning"); btn.disabled = true; }
            showToast("App refresh ho raha hai, kripya wait kijiye...", true);
            let reloaded = false;
            const doReload = () => {
                if (reloaded) return;
                reloaded = true;
                window.location.reload();
            };
            try {
                if ("caches" in window) {
                    const keys = await caches.keys();
                    // SAFETY FIX (2026-09-15, USER-REQUESTED): pehle yahan is
                    // ORIGIN ki SAARI caches delete ho jaati thi - Cache API
                    // origin-scoped hota hai, path-scoped nahi, isliye agar isi
                    // domain (jaise GitHub Pages account) par koi doosra project
                    // bhi host ho, uski cache bhi is Refresh button se saaf ho
                    // sakti thi. Ab sirf isi app ki apni cache ("seoni-app-"
                    // prefix wali, service-worker.js ke CACHE_VERSION se match)
                    // delete hoti hai.
                    await Promise.all(keys.filter((key) => key.startsWith("seoni-staging-app-shell-")).map((key) => caches.delete(key)));
                }
                if ("serviceWorker" in navigator) {
                    const reg = await navigator.serviceWorker.getRegistration();
                    if (reg) {
                        navigator.serviceWorker.addEventListener("controllerchange", doReload, { once: true });
                        await reg.update();
                        if (reg.waiting) reg.waiting.postMessage({ type: "SKIP_WAITING" });
                        // agar naya version na mila (waiting nahi bana) to controllerchange kabhi
                        // fire nahi hoga - isliye chhoti si wait ke baad khud hi reload kar do.
                        setTimeout(doReload, 1200);
                        return;
                    }
                }
                setTimeout(doReload, 300);
            } catch (error) {
                setTimeout(doReload, 300);
            }
        }

        function showToast(message, ok) {
            const t = document.getElementById("toast-notif");
            t.innerText = message;
            t.style.background = ok ? "#10b981" : "#ef4444";
            t.style.display = "block";
            setTimeout(() => {
                t.style.display = "none";
            }, 3000);
        }

        function showInfoModal(title, message) {
            return new Promise((resolve) => {
                const oldBox = document.getElementById("custom-info-overlay");
                if (oldBox) oldBox.remove();
                const overlay = document.createElement("div");
                overlay.id = "custom-info-overlay";
                overlay.setAttribute("role", "alertdialog");
                overlay.setAttribute("aria-modal", "true");
                overlay.setAttribute("aria-labelledby", "custom-info-title");
                overlay.setAttribute("aria-describedby", "custom-info-message");
                overlay.style.cssText = "position:fixed; inset:0; z-index:9999; background:rgba(15,23,42,0.36); display:flex; align-items:center; justify-content:center; padding:20px;";
                overlay.innerHTML = `
                    <div style="width:min(330px,92vw); background:#ffffff; border:2px solid #93c5fd; border-radius:22px; box-shadow:0 20px 45px rgba(15,23,42,0.28); padding:18px; text-align:center;">
                        <div id="custom-info-title" style="display:inline-block; background:#dbeafe; color:#1d4ed8; border:1.5px solid #60a5fa; border-radius:999px; padding:7px 18px; font-size:1rem; font-weight:950;">${escapeHtml(title)}</div>
                        <div id="custom-info-message" style="margin-top:14px; color:#111827; font-size:0.96rem; font-weight:800; white-space:pre-line; line-height:1.5;">${escapeHtml(message)}</div>
                        <button id="custom-info-ok" type="button" style="width:100%; height:44px; margin-top:18px; border:none; border-radius:999px; background:#000000; color:#ffffff; font-size:0.9rem; font-weight:950;">OK</button>
                    </div>
                `;
                document.body.appendChild(overlay);
                const okBtn = document.getElementById("custom-info-ok");
                okBtn.focus();
                const close = () => {
                    overlay.remove();
                    resolve(true);
                };
                okBtn.onclick = close;
            });
        }

        function showCustomConfirmBox(title, message) {
            return new Promise((resolve) => {
                const oldBox = document.getElementById("custom-confirm-overlay");
                if (oldBox) oldBox.remove();
                const overlay = document.createElement("div");
                overlay.id = "custom-confirm-overlay";
                overlay.style.cssText = "position:fixed; inset:0; z-index:9999; background:rgba(15,23,42,0.36); display:flex; align-items:center; justify-content:center; padding:20px;";
                overlay.innerHTML = `
                    <div style="width:min(330px,92vw); background:#ffffff; border:2px solid #93c5fd; border-radius:22px; box-shadow:0 20px 45px rgba(15,23,42,0.28); padding:18px; text-align:center;">
                        <div style="display:inline-block; background:#dbeafe; color:#1d4ed8; border:1.5px solid #60a5fa; border-radius:999px; padding:7px 18px; font-size:1rem; font-weight:950;">${escapeHtml(title)}</div>
                        <div style="margin-top:14px; color:#111827; font-size:0.98rem; font-weight:900;">${escapeHtml(message)}</div>
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:18px;">
                            <button id="custom-confirm-cancel" type="button" style="height:42px; border:none; border-radius:999px; background:#e5e7eb; color:#111827; font-size:0.9rem; font-weight:950;">Cancel</button>
                            <button id="custom-confirm-ok" type="button" style="height:42px; border:none; border-radius:999px; background:#000000; color:#ffffff; font-size:0.9rem; font-weight:950;">OK</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(overlay);
                const close = (result) => {
                    overlay.remove();
                    resolve(result);
                };
                overlay.querySelector("#custom-confirm-ok")?.addEventListener("click", () => close(true));
                overlay.querySelector("#custom-confirm-cancel")?.addEventListener("click", () => close(false));
                overlay.addEventListener("click", (event) => {
                    if (event.target === overlay) close(false);
                });
            });
        }

        function normalizeLookupValue(value) {
            return (value || "").toString().trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
        }

        function normalizeDcName(value) {
            return (value || "").toString().trim().toUpperCase();
        }

        function getDivisionConfig(divisionName) {
            return divisionConfigs[normalizeDcName(divisionName)] || null;
        }

        function getDivisionDcNames(divisionName) {
            const divisionConfig = getDivisionConfig(divisionName);
            return divisionConfig ? divisionConfig.dcs.map((dc) => dc.name) : [];
        }

        function getDivisionSubDnGroups(divisionName) {
            const divisionConfig = getDivisionConfig(divisionName);
            if (!divisionConfig) return [];
            const order = divisionConfig.subDnOrder || [];
            const groups = order.map((subDn) => ({
                subDn,
                dcs: divisionConfig.dcs.filter((dc) => dc.subDn === subDn).map((dc) => dc.name)
            })).filter((group) => group.dcs.length);
            const covered = new Set(order);
            const leftover = divisionConfig.dcs.filter((dc) => !covered.has(dc.subDn)).map((dc) => dc.name);
            if (leftover.length) groups.push({ subDn: "OTHER", dcs: leftover });
            return groups;
        }

        function getAllDcConfigs() {
            return Object.values(divisionConfigs).flatMap((division) => division.dcs);
        }

        function getAllDcNames() {
            return getAllDcConfigs().map((dc) => dc.name);
        }

        function splitCsvLine(line) {
            return line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map((item) => item.replace(/^"|"$/g, "").trim());
        }

        function xhrGetText(url, timeoutMs = 6000) {
            return new Promise((resolve, reject) => {
                try {
                    const xhr = new XMLHttpRequest();
                    xhr.open("GET", url, true);
                    xhr.timeout = timeoutMs;
                    xhr.ontimeout = () => reject(new Error("XHR timeout"));
                    xhr.onreadystatechange = () => {
                        if (xhr.readyState !== 4) return;
                        if (xhr.status >= 200 && xhr.status < 300 && xhr.responseText) {
                            resolve(xhr.responseText);
                        } else {
                            reject(new Error("XHR fetch failed"));
                        }
                    };
                    xhr.onerror = () => reject(new Error("XHR network error"));
                    xhr.send();
                } catch (error) {
                    reject(error);
                }
            });
        }

        // BUG FIX (2026-09-13): timeoutMs ab optional param hai (default 6000, jaisa
        // pehle hardcoded tha) - baaki SABHI existing callers (Mobile/Revenue/Court
        // Case/Stock/Feeder/etc, in sab par koi asar nahi) bina kisi change ke wahi
        // 6-second timeout use karte rahenge. Sirf Revenue FREEZE Report (NP3/NP6/
        // Since Connection, jinme koi Top-N limit na hone se DC ka data bada ho
        // sakta hai) apna zyada lamba, explicit timeout pass karega - neeche
        // ensureRevenueFreezeActiveInfo() aur fetchRevenueFreezeSnapshotRows() me.
        async function loadRemoteText(url, timeoutMs = 6000) {
            const withTs = url.includes("?") ? `${url}&t=${Date.now()}` : `${url}?t=${Date.now()}`;
            const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
            const timer = setTimeout(() => {
                try { if (controller) controller.abort(); } catch (_) {}
            }, timeoutMs);
            try {
                const response = await fetch(withTs, controller ? { signal: controller.signal } : {});
                const text = await response.text();
                if (text) return text;
            } catch (_) {} finally {
                clearTimeout(timer);
            }
            try {
                return await xhrGetText(withTs, timeoutMs);
            } catch (_) {}
            try {
                return await xhrGetText(url, timeoutMs);
            } catch (_) {}
            // BUG FIX (2026-09-13): pehle yahan aakhri fallback "fetch(url)" bina
            // kisi timeout/abort ke tha - agar network slow/unstable ho to yeh call
            // kabhi-kabhi kaafi der (kai minute) tak latka reh sakta tha, jisse
            // poori syncing 5+ minute tak atak jaati thi aur aakhir me
            // "ERROR FETCHING DATA" / "...LOAD NAHI HO PAYI" aata tha (Circle-level
            // Freeze aur DC-level Mobile dono me yahi shared function use hoti hai,
            // isliye dono jagah yeh dikh raha tha). Ab isko bhi upar jaisa hi
            // timeoutMs ke andar bound kar diya - teeno pehle attempt fail hone ke
            // baad yeh bhi jaldi fail ho jayega, latkega nahi.
            const finalController = typeof AbortController !== "undefined" ? new AbortController() : null;
            const finalTimer = setTimeout(() => {
                try { if (finalController) finalController.abort(); } catch (_) {}
            }, timeoutMs);
            try {
                const fallbackResponse = await fetch(url, finalController ? { signal: finalController.signal } : {});
                return await fallbackResponse.text();
            } finally {
                clearTimeout(finalTimer);
            }
        }

        // ITEM-9 FIX (2026-09-15, audit item "backend API versioning"): backend
        // ab (jin scripts me redeploy ho chuka hai) har object-shaped response
        // me "api_version" bhejta hai. Yahan hum sirf ek in-memory map me isi
        // session ke andar har URL ka "pehli baar dekha gaya" version yaad
        // rakhte hain - agar usi URL se BAAD me koi DIFFERENT version aaye
        // (matlab beech session me backend redeploy ho gaya), to sirf ek
        // console.warn karte hain. Koi data/return-value/behavior change nahi -
        // purane backend (jinme abhi yeh field hi nahi hai) bilkul pehle jaisे
        // hi chalte rahenge, kyoki parsed.api_version undefined hoga aur yeh
        // block chup-chaap skip ho jayega.
        const apiVersionSeenByUrl_ = {};
        async function loadRemoteJson(url, timeoutMs = 6000) {
            const text = await loadRemoteText(url, timeoutMs);
            const parsed = JSON.parse(text || "null");
            try {
                if (parsed && typeof parsed === "object" && !Array.isArray(parsed) && parsed.api_version != null) {
                    const baseUrl = String(url).split("?")[0];
                    const seen = apiVersionSeenByUrl_[baseUrl];
                    if (seen != null && seen !== parsed.api_version) {
                        console.warn(`[API-VERSION] ${baseUrl} ka backend version isi session me badal gaya (${seen} -> ${parsed.api_version}) - agar koi report/data ajeeb lage to app ko hard-refresh karein.`);
                    }
                    apiVersionSeenByUrl_[baseUrl] = parsed.api_version;
                }
            } catch (_) {}
            return parsed;
        }

        // GLOBAL APPS SCRIPT CONCURRENCY GATE (2026-09-13): USER-REPORTED BUG - Freeze
        // Report DC-level par bahut samay (minutes) leta tha, phir bhi "load nahi ho
        // payi" dikhata tha - Chrome Console me dekhne par asli wajah yeh nikli:
        // "script.googleusercontent.com/macros/echo...404" errors, aur Network tab
        // me Freeze ki apni request ke saath-saath DOOSRE modules (Live Revenue
        // getEntries, Line TD getTDEntries) ki background sync bhi USI WAQT chal
        // rahi thi (pichli screen se bachi hui, apne retry attempts poore kar rahi
        // thi) - sab EK HI Apps Script project par ek saath takra gayi. Itni saari
        // requests ek saath jaane par Google ka content-serving hissa (echo) kabhi-
        // kabhi 404 de deta hai - yeh "DC ka data bada hai" ya "network slow hai"
        // nahi hai, sirf bahut zyada concurrent requests ka takraav hai.
        // Fix: har Apps Script URL (host+path, query params chhodkar) ke liye ek
        // chhota queue - ek waqt me zyada se zyada 2 requests hi us URL par jaane
        // dete hain, baaki apni baari ka wait karte hain (turant fail nahi hote,
        // sirf thoda queue me rukte hain). Isse koi bhi ek screen (Freeze, Live
        // Revenue, Line TD, Mobile) dusri screen ki background activity ki wajah se
        // fail nahi hogi. Yeh sirf ek "traffic gate" hai - kisi bhi fetch/response
        // handling logic ko badalta nahi, sirf timing thodi manage karta hai.
        const appsScriptConcurrencyState_ = {};
        async function withAppsScriptConcurrencyGate_(scriptUrl, task) {
            const key = String(scriptUrl || "").split("?")[0] || "default";
            const state = appsScriptConcurrencyState_[key] || (appsScriptConcurrencyState_[key] = { active: 0, queue: [] });
            if (state.active >= 2) {
                await new Promise((resolve) => state.queue.push(resolve));
            }
            state.active += 1;
            try {
                return await task();
            } finally {
                state.active -= 1;
                const next = state.queue.shift();
                if (next) next();
            }
        }

        function isLikelyCsvPayload(rawText) {
            const raw = String(rawText || "").trim();
            if (!raw) return false;
            if (/^\s*</.test(raw)) return false;
            return raw.includes(",") && /[\r\n]/.test(raw);
        }

        function parseConsumerCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = splitCsvLine(lines[0]).map((header) => normalizeDcName(header));
            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const row = {};
                headers.forEach((header, index) => {
                    row[header] = cols[index] || "";
                });
                return row;
            });
        }

        function getConsumerRows(dcName) {
            return dcCacheRows[normalizeDcName(dcName)] || [];
        }

        function normalizeMobileDisplayValue(value) {
            const raw = String(value ?? "").trim();
            if (!raw) return raw;
            // Google Sheets kabhi-kabhi bade number ko scientific notation me export kar deta hai
            // (jaise "9.62E+09") — usko wapas poore digit wale number me convert karna.
            if (/^\d(\.\d+)?e\+?\d+$/i.test(raw)) {
                const num = Number(raw);
                if (Number.isFinite(num)) return String(Math.round(num));
            }
            return raw;
        }

        function getConsumerField(row, aliases, fallback = "") {
            if (!row) return fallback;
            for (const alias of aliases) {
                const value = row[normalizeDcName(alias)];
                if (value !== undefined && value !== null && String(value).trim() !== "") return String(value).trim();
            }
            return fallback;
        }

        function findConsumerRowByIvrs(rows, searchIvrs) {
            const target = normalizeLookupDigits(searchIvrs);
            if (!target) return null;

            return rows.find((row) => {
                const directValue = getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER"]);
                if (normalizeLookupDigits(directValue) === target) return true;

                const ivrsLikeEntry = Object.entries(row || {}).find(([key, value]) => {
                    const normalizedKey = normalizeLookupValue(key);
                    return normalizedKey.includes("IVRS") && normalizeLookupDigits(value) === target;
                });
                if (ivrsLikeEntry) return true;

                const firstValue = Object.values(row || {})[0] || "";
                return normalizeLookupDigits(firstValue) === target;
            }) || null;
        }

        function getConsumerHqName(row, fallback = "GENERAL") {
            const direct = getConsumerField(row, [
                "HQ", "HQ NAME", "HQNAME", "HEADQUARTER", "HEAD QUARTER", "H.Q.", "H.Q", "H Q", "HQ_NAME"
            ], "");
            if (direct) return normalizeDcName(direct) || fallback;

            const found = Object.entries(row || {}).find(([key, value]) => {
                const normalizedKey = normalizeLookupValue(key);
                return String(value || "").trim() && (
                    normalizedKey === "HQ" ||
                    normalizedKey.includes("HQNAME") ||
                    normalizedKey.includes("HEADQUARTER") ||
                    normalizedKey.includes("HEADQUATER")
                );
            });
            return normalizeDcName(found ? found[1] : fallback) || fallback;
        }

        // STOCK EMPTY/ERROR/STALE FIX (2026-09-16, USER-REQUESTED, multi-round-
        // corrected - see stockMaterialsStatus/stockMaterialsStale comment upar
        // unke declaration par): teen baar user ke independent review ne
        // correction maangi thi - (1) empty API+CSV ko "kuch nahi hua" ki jagah
        // explicit valid-empty maana jaaye, (2) unsaved Receive/Issue kaam kisi
        // bhi failure-path me kabhi reset na ho, (3) pehla-hi load fail hone par
        // ise "refresh failure" na samjha jaaye (jo shuru me "loaded" default
        // rakhne se hota tha) - "uninitialized"/"loading" ko alag rakh kar yeh
        // teesra bug fix hua hai.
        async function loadStockMaterialsData() {
            const hadPreviousData = stockMaterialsStatus === "loaded" || stockMaterialsStatus === "empty";
            const previousStockMaterials = Array.isArray(stockMaterials) ? stockMaterials.slice() : [];
            const previousStatus = stockMaterialsStatus;

            if (!hadPreviousData) {
                // "uninitialized" (bilkul pehla call) ya pehle se "error"/"loading"
                // tha - is attempt ko turant "loading" dikhate hain aur
                // stockMaterials khaali kar dete hain, taaki upar wala hardcoded
                // demo array is point ke baad KABHI "current stock" jaisa render
                // na ho, chahe network kitna bhi slow ho.
                stockMaterialsStatus = "loading";
                stockMaterials = [];
                renderStockDashboard(); // agar user pehle se Stock screen par hai to turant "loading" banner dikhe
            }
            // hadPreviousData === true (pehle se "loaded"/"empty") ho to status ko
            // yahan CHHEDTE NAHI - background-refresh ke dauraan purana data/view
            // bina flicker ke dikhta rehta hai.

            try {
                const rawData = await loadRemoteJson(`${stockSubmitScriptUrl}?action=getMasterStock`);
                const parsedMaterials = Array.isArray(rawData)
                    ? rawData.map((item, index) => {
                        const name = String(item.material_name || item["MATERIAL NAME"] || item.name || "").trim();
                        const unit = String(item.unit || item["UNIT"] || "Nos").trim();
                        const openingStock = Number(item.opening_stock ?? item["OPENING STOCK"] ?? 0) || 0;
                        const balanceStock = Number(item.balance_stock ?? item["BALANCE STOCK"] ?? openingStock) || 0;
                        if (!name) return null;
                        return {
                            id: String(item.id || `CSV-${String(index + 1).padStart(3, "0")}`),
                            name,
                            unit,
                            opening: openingStock,
                            currentBalance: balanceStock,
                            inward: 0,
                            issue: 0,
                            min: 0
                        };
                    }).filter(Boolean)
                    : [];

                if (parsedMaterials.length) {
                    stockMaterials = parsedMaterials;
                    pendingReceiveItems = [];
                    pendingIssueItems = [];
                    selectedStockReceiveItem = null;
                    selectedStockIssueItem = null;
                    stockMaterialsStatus = "loaded";
                    stockMaterialsStale = false;
                    renderStockDashboard();
                    return;
                }

                // API valid, 0 rows -> CSV fallback try karo
                const csvText = await loadRemoteText(stockMaterialsCsvUrl);
                const parsedCsvMaterials = parseStockMaterialsCsv(csvText);
                // FIX: dono sources se 0 rows aana ab explicitly ek VALID "empty"
                // result hai - pehle yahan sirf "if (parsedCsvMaterials.length)"
                // tha, dono khaali hone par function chup-chap kuch nahi karta
                // tha aur purana/demo data "current" jaisa dikhta reh jaata tha.
                stockMaterials = parsedCsvMaterials;
                pendingReceiveItems = [];
                pendingIssueItems = [];
                selectedStockReceiveItem = null;
                selectedStockIssueItem = null;
                stockMaterialsStatus = parsedCsvMaterials.length ? "loaded" : "empty";
                stockMaterialsStale = false;
                renderStockDashboard();
            } catch (_) {
                // FIX: yeh "empty" NAHI hai, "error" hai.
                if (hadPreviousData) {
                    // Refresh fail hua, pehle se valid data (loaded ya empty) tha -
                    // purana data/status wapas, sirf stale=true. pendingReceiveItems/
                    // pendingIssueItems/selectedStockReceiveItem/selectedStockIssueItem
                    // ko YAHAN BILKUL NAHI CHHEDTE - network blip se staff ka
                    // in-progress Receive/Issue kaam nahi udna chahiye.
                    stockMaterials = previousStockMaterials;
                    stockMaterialsStatus = previousStatus;
                    stockMaterialsStale = true;
                } else {
                    // Pehla load hi fail hua (ya "loading" state se hi fail) -
                    // kabhi koi valid data mila hi nahi. Khaali list + "error"
                    // status - "empty" dikhana galat hota (user "material master
                    // khaali hai" samajhta, jabki load hi fail hua). Pending/
                    // selected yahan bhi touch nahi karte (already khaali honge).
                    stockMaterials = [];
                    stockMaterialsStatus = "error";
                    stockMaterialsStale = false;
                }
                renderStockDashboard();
            }
        }

        // Shared status-banner helper - Stock ke paanchon read-screens (Dashboard
        // summary, Material List, Live Stock, Low Stock, Stock Report) isi ek
        // function ko reuse karte hain, taaki stale/error data kabhi bina warning
        // ke na dikhe (koi bhi screen se yeh check miss na ho).
        function getStockStatusBannerHtml_() {
            if (stockMaterialsStatus === "loading") {
                return `<div class="stock-summary-empty">⏳ Stock data load ho raha hai...</div>`;
            }
            if (stockMaterialsStatus === "error") {
                return `<div class="stock-summary-empty" style="color:#b91c1c;">⚠ Stock data load nahi ho paya. Kripya thodi der baad refresh karein.</div>`;
            }
            if (stockMaterialsStale) {
                return `<div class="stock-summary-empty" style="color:#b45309;">⚠ Stock data refresh nahi ho paya - purana (pichhla load kiya hua) data dikha rahe hain.</div>`;
            }
            return "";
        }

        function parseStockMaterialsCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = splitCsvLine(lines[0]).map((header) => normalizeDcName(header));
            return lines.slice(1).map((line, index) => {
                const cols = splitCsvLine(line);
                const row = {};
                headers.forEach((header, headerIndex) => {
                    row[header] = cols[headerIndex] || "";
                });
                const name = getConsumerField(row, ["MATERIAL NAME", "MATERIAL", "NAME"]);
                const unit = getConsumerField(row, ["UNIT", "UOM"], "Nos");
                const openingStock = Number(getConsumerField(row, ["OPENING STOCK", "OPENING", "OPENINGSTOCK"], "0")) || 0;
                const balanceStockRaw = getConsumerField(row, ["BALANCE STOCK", "BALANCE", "BALANCESTOCK"], "");
                const fallbackTotalStock = Number(getConsumerField(row, ["TOTAL STOCK", "TOTAL", "STOCK"], "0")) || 0;
                const balanceStock = balanceStockRaw === ""
                    ? (fallbackTotalStock || openingStock)
                    : (Number(balanceStockRaw) || 0);
                if (!name) return null;
                return {
                    id: `CSV-${String(index + 1).padStart(3, "0")}`,
                    name,
                    unit,
                    opening: openingStock || balanceStock,
                    currentBalance: balanceStock,
                    inward: 0,
                    issue: 0,
                    min: 0
                };
            }).filter(Boolean);
        }

        function updatePhotoMetaUI() {
            const metaBox = document.getElementById("receiver-photo-meta");
            const latLongNode = document.getElementById("receiver-photo-latlong");
            const locationNode = document.getElementById("receiver-photo-location");
            if (!metaBox || !latLongNode || !locationNode) return;
            if (!receiverGeoData) {
                metaBox.style.display = "none";
                latLongNode.innerHTML = "<strong>Lat-Long:</strong> Not captured";
                locationNode.innerHTML = "<strong>Location:</strong> Not captured";
                return;
            }
            metaBox.style.display = "block";
            latLongNode.innerHTML = `<strong>Lat-Long:</strong> ${receiverGeoData.latitude}, ${receiverGeoData.longitude}`;
            locationNode.innerHTML = `<strong>Location:</strong> ${receiverGeoData.locationText || "GPS location captured"}`;
        }

        function getCurrentPositionAsync() {
            return new Promise((resolve, reject) => {
                if (!navigator.geolocation) {
                    reject(new Error("Geolocation not supported"));
                    return;
                }
                navigator.geolocation.getCurrentPosition(resolve, reject, {
                    enableHighAccuracy: true,
                    timeout: 18000,
                    maximumAge: 0
                });
            });
        }

        function getGpsCameraPositionWithOptions(options) {
            return new Promise((resolve, reject) => {
                if (!navigator.geolocation) {
                    reject(new Error("Geolocation not supported"));
                    return;
                }
                navigator.geolocation.getCurrentPosition(resolve, reject, options);
            });
        }

        async function getGpsCameraPositionRobust() {
            try {
                return await getGpsCameraPositionWithOptions({
                    enableHighAccuracy: true,
                    timeout: 22000,
                    maximumAge: 0
                });
            } catch (firstError) {
                try {
                    return await getGpsCameraPositionWithOptions({
                        enableHighAccuracy: false,
                        timeout: 18000,
                        maximumAge: 10000
                    });
                } catch (_) {
                    throw firstError;
                }
            }
        }

        async function reverseGeocodeLocation(latitude, longitude) {
            try {
                const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}`);
                const data = await response.json();
                return data.display_name || `${latitude}, ${longitude}`;
            } catch (_) {
                return `${latitude}, ${longitude}`;
            }
        }

        function getCurrentDayName() {
            return new Date().toLocaleDateString("en-US", { weekday: "long" });
        }

        function isIosLikeDevice() {
            const ua = String(navigator.userAgent || "");
            return /iPhone|iPad|iPod/i.test(ua) || (ua.includes("Mac") && "ontouchend" in document);
        }

        function hasRecentGpsCameraGeo() {
            return !!(gpsCameraGeoData && gpsCameraGeoData.latitude && (Date.now() - gpsCameraGeoCapturedAt) < 5 * 60 * 1000);
        }

        function getGpsCameraErrorMessage(error) {
            const code = Number(error?.code || 0);
            if (code === 1) return "Location permission allow kijiye, tabhi GPS Camera open hoga.";
            if (code === 2) return "Location signal weak hai. Mobile location ON rakhiye aur open sky/network me dobara try kijiye.";
            if (code === 3) return "Location trace me time lag raha hai. Kripya GPS/Internet ON rakhkar dobara try kijiye.";
            return "Location detect nahi ho payi. Permission aur GPS ON karke dobara try kijiye.";
        }

        function setGpsCameraStatus(title, message, mode = "loading") {
            const modal = document.getElementById("gps-camera-status-modal");
            const titleNode = document.getElementById("gps-camera-status-title");
            const messageNode = document.getElementById("gps-camera-status-message");
            const spinner = document.getElementById("gps-camera-status-spinner");
            const button = document.getElementById("gps-camera-status-btn");
            if (!modal || !titleNode || !messageNode || !spinner || !button) return;
            modal.style.display = "flex";
            titleNode.innerText = title;
            messageNode.innerText = message;
            spinner.style.display = mode === "loading" ? "block" : "none";
            button.style.display = (mode === "ready" || mode === "error") ? "block" : "none";
            button.innerText = mode === "error" ? "DOBARA TRY KIJIYE" : "PHOTO CLICK KIJIYE";
            button.onclick = mode === "error" ? openGpsCameraFlow : openGpsCameraInputAfterLocation;
        }

        function hideGpsCameraStatus() {
            const modal = document.getElementById("gps-camera-status-modal");
            if (modal) modal.style.display = "none";
        }

        async function prewarmGpsCameraLocationIfAllowed() {
            try {
                if (hasRecentGpsCameraGeo() || gpsCameraGeoPromise || !navigator.permissions?.query) return;
                const permissionStatus = await navigator.permissions.query({ name: "geolocation" });
                if (permissionStatus.state !== "granted") return;
                gpsCameraGeoPromise = captureGpsCameraGeoLocation();
                await gpsCameraGeoPromise;
            } catch (_) {
            } finally {
                gpsCameraGeoPromise = null;
            }
        }

        async function captureGpsCameraGeoLocation(throwOnError = false) {
            try {
                gpsCameraGeoData = {
                    latitude: "Fetching...",
                    longitude: "Fetching...",
                    locationText: "GPS location detect ki ja rahi hai"
                };
                const position = await getGpsCameraPositionRobust();
                const latitude = position.coords.latitude.toFixed(6);
                const longitude = position.coords.longitude.toFixed(6);
                const locationText = await reverseGeocodeLocation(latitude, longitude);
                gpsCameraGeoData = { latitude, longitude, locationText };
                gpsCameraGeoCapturedAt = Date.now();
            } catch (error) {
                gpsCameraGeoData = null;
                gpsCameraGeoCapturedAt = 0;
                if (throwOnError) throw error;
            }
            return gpsCameraGeoData;
        }

        async function openGpsCameraFlow(target = "home") {
            if (gpsCameraOpeningInProgress) return;
            gpsCameraTarget = target || "home";
            gpsCameraOpeningInProgress = true;
            try {
                let meta = gpsCameraGeoData;
                if (!hasRecentGpsCameraGeo()) {
                    setGpsCameraStatus(
                        "Location Trace Ho Rahi Hai",
                        "Kripya wait kijiye. Location milne ke baad hi photo click allow hoga.",
                        "loading"
                    );
                    gpsCameraGeoPromise = gpsCameraGeoPromise || captureGpsCameraGeoLocation(true);
                    try {
                        meta = await gpsCameraGeoPromise;
                    } catch (error) {
                        gpsCameraGeoPromise = null;
                        if (gpsCameraTarget === "revenueTd") {
                            meta = {
                                latitude: "Available nahi",
                                longitude: "Available nahi",
                                locationText: "GPS location available nahi thi",
                                locationUnavailable: true
                            };
                            gpsCameraGeoData = meta;
                            gpsCameraGeoCapturedAt = Date.now();
                        } else {
                            setGpsCameraStatus("Location Nahi Mili", getGpsCameraErrorMessage(error), "error");
                            return;
                        }
                    }
                    gpsCameraGeoPromise = null;
                    if (!meta || !meta.latitude) {
                        if (gpsCameraTarget === "revenueTd") {
                            meta = {
                                latitude: "Available nahi",
                                longitude: "Available nahi",
                                locationText: "GPS location available nahi thi",
                                locationUnavailable: true
                            };
                            gpsCameraGeoData = meta;
                            gpsCameraGeoCapturedAt = Date.now();
                        } else {
                            setGpsCameraStatus("Location Nahi Mili", "Location permission allow kijiye, tabhi GPS Camera open hoga.", "error");
                            return;
                        }
                    }
                }
                gpsCameraGeoPromise = Promise.resolve(meta);
                setGpsCameraStatus(
                    meta.locationUnavailable ? "Location Nahi Mili - Photo Allowed" : "Location Mil Gayi",
                    meta.locationUnavailable
                        ? "TD photo location ke bina attach hogi. Photo click kijiye."
                        : `Lat-Long: ${meta.latitude}, ${meta.longitude}. Ab photo click kijiye.`,
                    "ready"
                );
            } finally {
                gpsCameraOpeningInProgress = false;
            }
        }

        function openGpsCameraInputAfterLocation() {
            const input = document.getElementById("gps-camera-input");
            if (!input) return;
            if (!hasRecentGpsCameraGeo()) {
                openGpsCameraFlow();
                return;
            }
            hideGpsCameraStatus();
            gpsCameraGeoPromise = Promise.resolve(gpsCameraGeoData);
            input.value = "";
            input.click();
        }

        function drawGpsCameraOverlay(imageDataUrl, metadata) {
            return new Promise((resolve, reject) => {
                const image = new Image();
                image.onload = () => {
                    const canvas = document.createElement("canvas");
                    canvas.width = image.width;
                    canvas.height = image.height;
                    const ctx = canvas.getContext("2d");
                    if (!ctx) {
                        reject(new Error("Canvas ready nahi hua"));
                        return;
                    }

                    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);

                    const baseLines = [
                        `Place: ${metadata.locationText || "-"}`,
                        `Lat-Long: ${metadata.latitude || "-"}, ${metadata.longitude || "-"}`,
                        `Day: ${metadata.dayText}   Date: ${metadata.dateText}   Time: ${metadata.timeText}`
                    ];

                    const fontSize = Math.max(24, Math.round(canvas.width * 0.028));
                    const lineHeight = Math.round(fontSize * 1.35);
                    const padding = Math.round(fontSize * 0.9);
                    ctx.font = `900 ${fontSize}px Inter, Arial, sans-serif`;
                    ctx.textBaseline = "top";
                    const maxTextWidth = canvas.width - (padding * 2);

                    const wrappedLines = baseLines.flatMap((line) => wrapCanvasText(ctx, line, maxTextWidth));
                    const boxHeight = padding * 2 + lineHeight * wrappedLines.length;

                    ctx.fillStyle = "rgba(0, 0, 0, 0.68)";
                    ctx.fillRect(0, canvas.height - boxHeight, canvas.width, boxHeight);

                    ctx.fillStyle = "#ffffff";

                    wrappedLines.forEach((line, index) => {
                        ctx.fillText(line, padding, canvas.height - boxHeight + padding + (index * lineHeight));
                    });

                    resolve(canvas.toDataURL("image/jpeg", 0.92));
                };
                image.onerror = reject;
                image.src = imageDataUrl;
            });
        }

        function wrapCanvasText(ctx, text, maxWidth) {
            const words = String(text || "").split(/\s+/).filter(Boolean);
            if (!words.length) return [""];
            const lines = [];
            let currentLine = words[0];

            for (let i = 1; i < words.length; i += 1) {
                const testLine = `${currentLine} ${words[i]}`;
                if (ctx.measureText(testLine).width <= maxWidth) {
                    currentLine = testLine;
                } else {
                    lines.push(currentLine);
                    currentLine = words[i];
                }
            }

            lines.push(currentLine);
            return lines;
        }

        function updateGpsCameraPreview(meta) {
            const modal = document.getElementById("gps-camera-modal");
            const imageNode = document.getElementById("gps-camera-preview-image");
            const placeNode = document.getElementById("gps-camera-place");
            const latLongNode = document.getElementById("gps-camera-latlong");
            const dateTimeNode = document.getElementById("gps-camera-datetime");
            if (!modal || !imageNode || !placeNode || !latLongNode || !dateTimeNode) return;

            imageNode.src = gpsCameraPhotoDataUrl;
            placeNode.innerHTML = `<strong>Place:</strong> ${escapeHtml(meta.locationText || "-")}`;
            latLongNode.innerHTML = `<strong>Lat-Long:</strong> ${escapeHtml(meta.latitude || "-")}, ${escapeHtml(meta.longitude || "-")}`;
            dateTimeNode.innerHTML = `<strong>Day-Date-Time:</strong> ${escapeHtml(meta.dayText)} | ${escapeHtml(meta.dateText)} | ${escapeHtml(meta.timeText)}`;
            modal.style.display = "flex";
        }

        async function handleGpsCameraPhoto(input) {
            if (!input || !input.files || !input.files[0]) return;
            showToast("GPS camera photo prepare ho rahi hai", true);
            try {
                const file = input.files[0];
                const rawDataUrl = await resizeImageForUpload(file, 1600, 0.9);
                const meta = hasRecentGpsCameraGeo()
                    ? gpsCameraGeoData
                    : await (gpsCameraGeoPromise || captureGpsCameraGeoLocation());
                if (!meta || !meta.latitude) {
                    showToast("Location permission ke bina photo save nahi hogi", false);
                    return;
                }
                const dateText = getCurrentDateDDMMYYYY().replace(/\//g, "-");
                const timeText = getCurrentTimeHHMM();
                const dayText = getCurrentDayName();
                const finalMeta = {
                    ...meta,
                    dayText,
                    dateText,
                    timeText
                };
                gpsCameraPhotoDataUrl = await drawGpsCameraOverlay(rawDataUrl, finalMeta);
                gpsCameraPhotoFileName = `gps-camera-${dateText}-${timeText.replace(":", "-")}.jpg`;
                if (gpsCameraTarget === "revenueTd") {
                    revenueTdPhotoDataUrl = gpsCameraPhotoDataUrl;
                    revenueTdPhotoName = gpsCameraPhotoFileName;
                    updateRevenueTdPhotoStatus(true);
                }
                updateGpsCameraPreview(finalMeta);
                showToast(gpsCameraTarget === "revenueTd" ? "TD photo ready hai, save kijiye" : "Photo ready hai, save kijiye", true);
            } catch (_) {
                showToast("Photo process nahi ho payi", false);
            } finally {
                gpsCameraGeoPromise = null;
            }
        }

        function dataUrlToFile(dataUrl, fileName) {
            const parts = String(dataUrl || "").split(",");
            const match = parts[0].match(/:(.*?);/);
            const mime = match ? match[1] : "image/jpeg";
            const binary = atob(parts[1] || "");
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i += 1) {
                bytes[i] = binary.charCodeAt(i);
            }
            return new File([bytes], fileName || "gps-camera-photo.jpg", { type: mime });
        }

        async function shareGpsCameraPhoto(fileName) {
            if (!navigator.share || !gpsCameraPhotoDataUrl) return false;
            try {
                const shareFile = dataUrlToFile(gpsCameraPhotoDataUrl, fileName);
                if (navigator.canShare && !navigator.canShare({ files: [shareFile] })) {
                    return false;
                }
                await navigator.share({
                    files: [shareFile],
                    title: "GPS Camera Photo"
                });
                showToast("Save/Share panel open ho gaya", true);
                return true;
            } catch (_) {
                return false;
            }
        }

        async function downloadGpsCameraPhoto() {
            if (!gpsCameraPhotoDataUrl) return showToast("Photo ready nahi hai", false);
            if (gpsCameraTarget === "revenueTd") {
                revenueTdPhotoDataUrl = gpsCameraPhotoDataUrl;
                revenueTdPhotoName = gpsCameraPhotoFileName || "line-td-photo.jpg";
                updateRevenueTdPhotoStatus(true);
                const modal = document.getElementById("gps-camera-modal");
                if (modal) modal.style.display = "none";
                const remarkInput = document.getElementById("revenue-td-remark");
                if (remarkInput) remarkInput.focus();
                showToast("TD photo form me save ho gayi, remark dal kar submit kijiye", true);
                return;
            }
            const fileName = gpsCameraPhotoFileName || "gps-camera-photo.jpg";
            const shared = await shareGpsCameraPhoto(fileName);
            if (shared) {
                const modal = document.getElementById("gps-camera-modal");
                if (modal) modal.style.display = "none";
                return;
            }
            // BUG FIX (2026-08-22): pehle yahan seedha `data:` URI (poora base64
            // photo data) ko <a href> me daal kar download trigger karte the.
            // Camera photo ka base64 data: URI bahut lamba (kai MB tak) ho sakta
            // hai - kai Android/Chrome versions par itna bada `data:` URI href se
            // download reliably start nahi hota (kabhi photo bas naye tab me khul
            // jaati hai, kabhi kuch bhi nahi hota) - isi wajah se "image download
            // nahi ho rahi" jaisa mehsoos hota tha. Ab pehle photo ko Blob me
            // convert karke `blob:` URL banate hain - yeh mobile browsers par
            // bade images/files download karne ka standard, zyada bharosemand
            // tarika hai. Agar kisi wajah se yeh bhi fail ho jaaye, to purana
            // `data:` URI tarika hi fallback ke roop me chalta hai.
            try {
                const file = dataUrlToFile(gpsCameraPhotoDataUrl, fileName);
                const blobUrl = URL.createObjectURL(file);
                const link = document.createElement("a");
                link.href = blobUrl;
                link.download = fileName;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                setTimeout(() => URL.revokeObjectURL(blobUrl), 4000);
            } catch (_) {
                const link = document.createElement("a");
                link.href = gpsCameraPhotoDataUrl;
                link.download = fileName;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
            showToast("Download start hua, mobile me Save to Photos/Gallery support na mile to share panel use kijiye", true);
        }

        function retakeGpsCameraPhoto() {
            const modal = document.getElementById("gps-camera-modal");
            if (modal) modal.style.display = "none";
            openGpsCameraFlow();
        }

        async function captureReceiverGeoLocation() {
            try {
                receiverGeoData = {
                    latitude: "Fetching...",
                    longitude: "Fetching...",
                    locationText: "GPS location detect ki ja rahi hai"
                };
                updatePhotoMetaUI();
                const position = await getCurrentPositionAsync();
                const latitude = position.coords.latitude.toFixed(6);
                const longitude = position.coords.longitude.toFixed(6);
                const locationText = await reverseGeocodeLocation(latitude, longitude);
                receiverGeoData = {
                    latitude,
                    longitude,
                    locationText
                };
                updatePhotoMetaUI();
            } catch (_) {
                receiverGeoData = {
                    latitude: "Available nahi",
                    longitude: "Available nahi",
                    locationText: "GPS permission allow nahi hui ya signal weak tha"
                };
                updatePhotoMetaUI();
            }
        }

        function resizeImageForUpload(file, maxWidth = 1280, quality = 0.78) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => {
                    const img = new Image();
                    img.onload = () => {
                        const ratio = Math.min(1, maxWidth / img.width);
                        const canvas = document.createElement("canvas");
                        canvas.width = Math.round(img.width * ratio);
                        canvas.height = Math.round(img.height * ratio);
                        const ctx = canvas.getContext("2d");
                        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                        resolve(canvas.toDataURL("image/jpeg", quality));
                    };
                    img.onerror = reject;
                    img.src = reader.result;
                };
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        function parseCourtCaseCsv(csvText) {
            const lines = csvText.split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = lines[0].split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map((item) => item.replace(/^"|"$/g, "").trim().toUpperCase());
            return lines.slice(1).map((line) => {
                const cols = line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map((item) => item.replace(/^"|"$/g, "").trim());
                const row = {};
                headers.forEach((header, index) => {
                    row[header] = cols[index] || "";
                });
                return {
                    rawLine: line,
                    caseNo: row["CASE NO"] || cols[0] || "",
                    dcName: (row["DC NAME"] || cols[1] || "").trim().toUpperCase(),
                    panchnamaNo: row["PANCHNAMA NO"] || cols[2] || "",
                    consumerName: row["CONSUMER NAME"] || cols[3] || "",
                    section: row["SECTION"] || cols[4] || "",
                    civilAmt: row["CIVIL AMT"] || cols[5] || "",
                    compoundingAmt: row["COMPOUNDIN AMT"] || row["COMPOUNDING AMT"] || cols[6] || "",
                    billedAmt: row["BILLED AMT"] || cols[7] || "",
                    rebate: row["REBATE"] || cols[8] || "",
                    totalPayableAmount: row["TOTAL PAYABLE AMOUNT"] || cols[9] || ""
                };
            });
        }

        function parseLokDistributedCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = splitCsvLine(lines[0]).map((header) => normalizeDcName(header));
            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const row = {};
                headers.forEach((header, index) => {
                    row[header] = cols[index] || "";
                });
                const date = row[normalizeDcName("DATE")] || cols[0] || "";
                const dcName = row[normalizeDcName("DC NAME")] || cols[3] || "";
                return {
                    date: String(date || "").trim(),
                    dcName: normalizeLookupValue(dcName || "")
                };
            }).filter((row) => row.date && row.dcName);
        }

        async function loadLokDistributedSheetData(forceRefresh = false) {
            if (!forceRefresh && lokDistributedLoaded) return true;
            try {
                const csvText = await loadRemoteText(lokAdalatDistributedCsvUrl);
                const parsed = parseLokDistributedCsv(csvText);
                lokDistributedRows = parsed;
                lokDistributedLoaded = true;
                return true;
            } catch (_) {
                lokDistributedRows = [];
                lokDistributedLoaded = false;
                return false;
            }
        }

        async function loadShmsData(forceRefresh = false) {
            if (!forceRefresh && shmsDataLoaded && shmsRows.length) return true;
            try {
                const csvText = await loadRemoteText(shmsCsvUrl);
                shmsRows = parseShmsCsv(csvText);
                shmsSubstations = Array.from(new Set(shmsRows.map((row) => row.substation).filter(Boolean)));
                shmsDataLoaded = shmsRows.length > 0;
                return shmsDataLoaded;
            } catch (_) {
                shmsRows = [];
                shmsSubstations = [];
                shmsDataLoaded = false;
                return false;
            }
        }

        function parseShmsCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const substation = String(cols[0] || "").replace(/\s+/g, " ").trim();
                const feeder = String(cols[1] || "").replace(/\s+/g, " ").trim();
                const meterNo = String(cols[2] || "").trim();
                if (!substation || !feeder) return null;
                return { substation, feeder, meterNo };
            }).filter(Boolean);
        }

        // BUG FIX (2026-09-14) - USER-REPORTED: Feeder Reading me ek substation
        // (jaise Chhapara ke substation) khud karte hi saari purani dates "Entry
        // Pending" dikha deti thi, jabki reading pehle hi submit ho chuki thi. ASLI
        // WAJAH: `getSummary` poori feeder history (sabhi DC/substation/date, 1.5+
        // MB JSON) ek saath deta tha - itna bada response Apps Script se laana
        // slow/unstable tha (kabhi timeout, kabhi HTML error page JSON ki jagah -
        // dono case me feederReportRows KHAALI reh jaata tha, isliye code ko lagta
        // tha "kisi bhi din koi reading submit hi nahi hui"). Backend me ab `getSummary`
        // ek optional `substation` param leta hai (additive, backward-compatible -
        // bina param ke pehle jaisa hi poora data deta hai) - jab user ek substation
        // chunta hai to sirf USI substation ka (bahut chhota, tez, reliable) data
        // maangte hain, poori history nahi. Substation-wise cache rakhte hain taaki
        // baar-baar same substation chunne par dubara fetch na ho.
        async function loadFeederSubstationHistory_(substation, forceRefresh = false) {
            const key = normalizeFeederSubstationKey_(substation);
            if (!key) return [];
            if (!forceRefresh && feederSubstationHistoryCache_[key]) return feederSubstationHistoryCache_[key];
            let rawData = null, lastErr = null;
            for (let attempt = 1; attempt <= 2 && rawData === null; attempt++) {
                try {
                    rawData = await loadRemoteJson(`${feederSubmitScriptUrl}?action=getSummary&substation=${encodeURIComponent(substation)}`, 30000);
                } catch (err) {
                    lastErr = err;
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 1500));
                }
            }
            if (rawData === null) return feederSubstationHistoryCache_[key] || [];
            const summaryRows = Array.isArray(rawData) ? rawData : (Array.isArray(rawData?.data) ? rawData.data : []);
            const mapped = summaryRows.map((row) => ({
                "33/11 KV SUBSTATION": String(row["33/11 KV SUBSTATION"] || row.substation || "").trim(),
                "33 AND 11 KV FEEDER": String(row["33 AND 11 KV FEEDER"] || row.feeder || "").trim(),
                "METER NO": String(row["METER NO"] || row.meter_no || row.meter || "").trim(),
                "PREVIUS READING": String(row["PREVIUS READING"] || row.previous_reading || "").trim(),
                "CURRENT READING": String(row["CURRENT READING"] || row.current_reading || "").trim(),
                "MF": String(row["MF"] || row.mf || "").trim(),
                "CONSUMPTION": String(row["CONSUMPTION"] || row.consumption || "").trim(),
                "DC NAME": String(row["DC NAME"] || row.dc_name || "").trim(),
                "DATE(DD/MM/YYY)": String(row["DATE(DD/MM/YYY)"] || row["DATE(DD/MM/YYYY)"] || row.date || "").trim(),
                "TIME(HH/MM)": String(row["TIME(HH/MM)"] || row["TIME(HH:MM)"] || row.time || "").trim()
            })).filter((row) => row["33/11 KV SUBSTATION"] || row["33 AND 11 KV FEEDER"]);
            feederSubstationHistoryCache_[key] = mapped;
            return mapped;
        }

        async function loadFeederData(forceRefresh = false) {
            if (!forceRefresh && feederDataLoaded && feederRows.length) return true;
            try {
                const csvText = await loadRemoteText(feederCsvUrl);
                feederRows = parseFeederCsv(csvText);
                feederSubstations = Array.from(new Set(feederRows.map((row) => row.substation).filter(Boolean)));
                feederDataLoaded = feederRows.length > 0;
                return feederDataLoaded;
            } catch (_) {
                try {
                    const reportLoaded = await loadFeederReportData(forceRefresh);
                    if (reportLoaded && feederReportRows.length) {
                        feederRows = buildFeederRowsFromReport_(feederReportRows);
                        feederSubstations = Array.from(new Set(feederRows.map((row) => row.substation).filter(Boolean)));
                        feederDataLoaded = feederRows.length > 0;
                        return feederDataLoaded;
                    }
                } catch (_) {}

                const localRows = buildFeederRowsFromReport_(getRecentFeederSubmittedEntries_());
                feederRows = localRows;
                feederSubstations = Array.from(new Set(feederRows.map((row) => row.substation).filter(Boolean)));
                feederDataLoaded = feederRows.length > 0;
                return feederDataLoaded;
            }
        }

        async function loadFeederReportData(forceRefresh = false) {
            if (!forceRefresh && feederReportLoaded && feederReportRows.length) return true;
            feederReportLoadMessage = "";
            const previousFeederReportRows = Array.isArray(feederReportRows) ? feederReportRows.slice() : [];
            // BUG FIX (2026-09-14) - USER-REPORTED: Feeder Reading me kabhi-kabhi
            // (khaaskar Chhapara jaisi badi DC me) saari purani dates "Entry Pending"
            // dikha deta tha, jabki reading pehle hi submit ho chuki thi. Live
            // diagnose karne par pata chala ASLI WAJAH: yeh "getSummary" call poori
            // feeder history (1.5+ MB JSON, sabhi DC/substation/date) ek saath laata
            // hai - itna bada response Apps Script se laane me kabhi 6 second
            // (loadRemoteJson ka default timeout) se zyada lag jaata tha, aur kabhi
            // Apps Script ka wahi known "echo" glitch (jo Freeze module me bhi dekha
            // gaya) HTML bhej deta tha JSON ki jagah - dono case me feederReportRows
            // KHAALI reh jaata tha, isliye code ko lagta tha "kisi bhi din koi
            // reading submit hi nahi hui" aur poori list "Pending" dikha deta tha.
            // Ab timeout 45 second tak badhaya aur 2 attempt (2s gap) try karte hain.
            let rawData = null, lastFeederSummaryErr = null;
            for (let attempt = 1; attempt <= 2 && rawData === null; attempt++) {
                try {
                    rawData = await loadRemoteJson(`${feederSubmitScriptUrl}?action=getSummary`, 45000);
                } catch (err) {
                    lastFeederSummaryErr = err;
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 2000));
                }
            }
            try {
                if (rawData === null) throw lastFeederSummaryErr || new Error("Feeder summary load fail");
                if (rawData && !Array.isArray(rawData) && rawData.status === "success" && rawData.message) {
                    feederReportLoadMessage = String(rawData.message || "").trim();
                }
                if (rawData && !Array.isArray(rawData) && rawData.status === "error" && rawData.message) {
                    feederReportLoadMessage = String(rawData.message || "").trim();
                }
                const summaryRows = Array.isArray(rawData)
                    ? rawData
                    : Array.isArray(rawData?.data)
                        ? rawData.data
                        : Array.isArray(rawData?.rows)
                            ? rawData.rows
                            : Array.isArray(rawData?.result)
                                ? rawData.result
                                : [];

                feederReportRows = summaryRows.map((row) => {
                    const normalizedDate = String(
                        row["DATE(DD/MM/YYY)"] ||
                        row["DATE(DD/MM/YYYY)"] ||
                        row.date ||
                        ""
                    ).trim();
                    const normalizedTime = String(
                        row["TIME(HH/MM)"] ||
                        row["TIME(HH:MM)"] ||
                        row.time ||
                        ""
                    ).trim();

                    return {
                        "33/11 KV SUBSTATION": String(row["33/11 KV SUBSTATION"] || row.substation || "").trim(),
                        "33 AND 11 KV FEEDER": String(row["33 AND 11 KV FEEDER"] || row.feeder || "").trim(),
                        "METER NO": String(row["METER NO"] || row.meter_no || row.meter || "").trim(),
                        "PREVIUS READING": String(row["PREVIUS READING"] || row.previous_reading || "").trim(),
                        "CURRENT READING": String(row["CURRENT READING"] || row.current_reading || "").trim(),
                        "MF": String(row["MF"] || row.mf || "").trim(),
                        "CONSUMPTION": String(row["CONSUMPTION"] || row.consumption || "").trim(),
                        "DC NAME": String(row["DC NAME"] || row.dc_name || "").trim(),
                        "DATE(DD/MM/YYY)": normalizedDate,
                        "TIME(HH/MM)": normalizedTime
                    };
                }).filter((row) => row["33/11 KV SUBSTATION"] || row["33 AND 11 KV FEEDER"]);

                if (feederReportRows.length) {
                    feederReportLoadMessage = "";
                    feederReportLoaded = true;
                    return true;
                }
            } catch (_) {}

            try {
                const csvText = await loadRemoteText(feederReportSheetCsvUrl);
                feederReportRows = parseFeederReportCsv(csvText);
                if (feederReportRows.length) {
                    feederReportLoadMessage = "";
                    feederReportLoaded = true;
                    return true;
                }
                if (!feederReportLoadMessage) {
                    feederReportLoadMessage = "Feeder report source se data nahi mila";
                }
                // RELIABILITY FIX (2026-09-15, USER-FLAGGED risk - STM report me
                // flag hui thi, Feeder me bhi same class ka risk tha): forced
                // refresh (jaise Download click) fail ho jaaye to pehle se
                // successfully-loaded data khaali nahi karte - sirf tabhi khaali
                // karte hain jab kabhi koi data mila hi na ho.
                feederReportRows = previousFeederReportRows;
                feederReportLoaded = previousFeederReportRows.length > 0;
                return feederReportRows.length > 0;
            } catch (_) {
                if (!feederReportLoadMessage) {
                    feederReportLoadMessage = "Feeder report source load nahi ho paya";
                }
                feederReportRows = previousFeederReportRows;
                feederReportLoaded = previousFeederReportRows.length > 0;
                return feederReportRows.length > 0;
            }
        }

        function parseFeederCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];

            const headerCols = splitCsvLine(lines[0]).map((item) => String(item || "").trim());
            const headerKeys = headerCols.map((item) => item.toLowerCase().replace(/[^a-z0-9]+/g, ""));
            const findHeaderIndex = (keywords, fallback) => {
                const idx = headerKeys.findIndex((key) => keywords.some((word) => key.includes(word)));
                return idx > -1 ? idx : fallback;
            };

            const substationIndex = findHeaderIndex(["substation", "ssname"], 0);
            const feederIndex = findHeaderIndex(["feeder"], 1);
            const meterIndex = findHeaderIndex(["meter", "meterno", "meternumber"], 2);
            const previousIndex = findHeaderIndex(["previusreading", "previousreading", "prevreading"], 3);
            const currentIndex = findHeaderIndex(["currentreading", "currreading"], 4);
            const mfIndex = findHeaderIndex(["mf", "multiplyingfactor", "multiplierfactor"], 5);
            const dcNameIndex = findHeaderIndex(["dcname"], 7);

            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const substation = String(cols[substationIndex] || "").replace(/\s+/g, " ").trim();
                const feeder = String(cols[feederIndex] || "").replace(/\s+/g, " ").trim();
                const meterNo = String(cols[meterIndex] || "").replace(/\s+/g, " ").trim();
                const mf = String(cols[mfIndex] || "").replace(/\s+/g, " ").trim();
                const previousReadingRaw = String(cols[previousIndex] || "").replace(/\s+/g, " ").trim();
                const currentReadingRaw = String(cols[currentIndex] || "").replace(/\s+/g, " ").trim();
                const previousReading = "";
                const currentReading = "";
                const dcName = String(cols[dcNameIndex] || "").replace(/\s+/g, " ").trim();
                if (!substation || !feeder) return null;
                return {
                    substation,
                    feeder,
                    meterNo,
                    mf,
                    previousReading,
                    currentReading,
                    csvPreviousReading: previousReadingRaw,
                    csvCurrentReading: currentReadingRaw,
                    dcName,
                    feederType: feeder.includes("33") ? "33 KV" : "11 KV"
                };
            }).filter(Boolean);
        }

        function parsePeakLoadCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];

            const headerCols = splitCsvLine(lines[0]).map((item) => String(item || "").trim());
            const headerKeys = headerCols.map((item) => item.toLowerCase().replace(/[^a-z0-9]+/g, ""));
            const findHeaderIndex = (keywords, fallback) => {
                const idx = headerKeys.findIndex((key) => keywords.some((word) => key.includes(word)));
                return idx > -1 ? idx : fallback;
            };

            const substationIndex = findHeaderIndex(["3311kvsubstation", "substation", "ssname"], 0);
            const feederIndex = findHeaderIndex(["11kvfeeder", "feeder"], 1);
            const meterIndex = findHeaderIndex(["meterno", "meter", "meternumber"], 2);

            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const substation = String(cols[substationIndex] || "").replace(/\s+/g, " ").trim();
                const feeder = String(cols[feederIndex] || "").replace(/\s+/g, " ").trim();
                const meterNo = String(cols[meterIndex] || "").replace(/\s+/g, " ").trim();
                if (!substation || !feeder) return null;
                return {
                    substation,
                    feeder,
                    meterNo,
                    feederType: "11 KV"
                };
            }).filter(Boolean);
        }

        async function loadPeakLoadData(forceRefresh = false) {
            if (!forceRefresh && peakLoadDataLoaded && peakLoadRows.length) return true;
            try {
                const csvText = await loadRemoteText(peakLoadCsvUrl);
                peakLoadRows = parsePeakLoadCsv(csvText);
                peakLoadDataLoaded = peakLoadRows.length > 0;
                return peakLoadDataLoaded;
            } catch (_) {
                try {
                    const feederLoaded = await loadFeederData(forceRefresh);
                    if (feederLoaded && feederRows.length) {
                        peakLoadRows = feederRows
                            .filter((row) => !String(row.feeder || "").toUpperCase().includes("33"))
                            .map((row) => ({
                                substation: String(row.substation || "").trim(),
                                feeder: String(row.feeder || "").trim(),
                                meterNo: String(row.meterNo || "").trim(),
                                feederType: "11 KV"
                            }));
                        peakLoadDataLoaded = peakLoadRows.length > 0;
                        return peakLoadDataLoaded;
                    }
                } catch (_) {}

                peakLoadRows = [];
                peakLoadDataLoaded = false;
                return false;
            }
        }

        function normalizePeakLoadDateKey(value) {
            const raw = String(value || "").trim();
            if (!raw) return "";
            let match = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
            if (match) {
                return `${match[1]}-${match[2].padStart(2, "0")}-${match[3].padStart(2, "0")}`;
            }
            match = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
            if (match) {
                return `${match[3]}-${match[2].padStart(2, "0")}-${match[1].padStart(2, "0")}`;
            }
            return raw;
        }

        function formatPeakLoadDateKeyForAlert(dateKey) {
            const match = String(dateKey || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!match) return String(dateKey || "");
            return `${match[3]}/${match[2]}/${match[1]}`;
        }

        function getPeakLoadDateRangeKeys(startKey, endKey) {
            const start = new Date(`${startKey}T00:00:00`);
            const end = new Date(`${endKey}T00:00:00`);
            if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start > end) return [];
            const keys = [];
            const cursor = new Date(start);
            while (cursor <= end) {
                const year = cursor.getFullYear();
                const month = String(cursor.getMonth() + 1).padStart(2, "0");
                const day = String(cursor.getDate()).padStart(2, "0");
                keys.push(`${year}-${month}-${day}`);
                cursor.setDate(cursor.getDate() + 1);
            }
            return keys;
        }

        function parsePeakLoadSubmittedCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headerCols = splitCsvLine(lines[0]).map((item) => String(item || "").trim());
            const headerKeys = headerCols.map((item) => item.toLowerCase().replace(/[^a-z0-9]+/g, ""));
            const findHeaderIndex = (keywords, fallback) => {
                const idx = headerKeys.findIndex((key) => keywords.some((word) => key.includes(word)));
                return idx > -1 ? idx : fallback;
            };
            const substationIndex = findHeaderIndex(["3311kvsubstation", "substation"], 0);
            const dateIndex = findHeaderIndex(["dateddmmyyyy", "date"], 3);

            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const substation = String(cols[substationIndex] || "").replace(/\s+/g, " ").trim();
                const dateKey = normalizePeakLoadDateKey(cols[dateIndex] || "");
                if (!substation || !dateKey) return null;
                return { substation, dateKey };
            }).filter(Boolean);
        }

        function parsePeakLoadSubmittedJson(data) {
            const rows = Array.isArray(data)
                ? data
                : Array.isArray(data?.rows)
                    ? data.rows
                    : Array.isArray(data?.data)
                        ? data.data
                        : [];

            return rows.map((row) => {
                if (Array.isArray(row)) {
                    return {
                        substation: String(row[0] || "").replace(/\s+/g, " ").trim(),
                        dateKey: normalizePeakLoadDateKey(row[3] || "")
                    };
                }

                const substation = row.substation
                    || row["33/11 KV SUBSTATION"]
                    || row["33/11 Kv Substation"]
                    || row["33/11 KV Substation"]
                    || "";
                const date = row.date
                    || row.entry_date
                    || row["DATE (DD-MM-YYYY)"]
                    || row["Date"]
                    || "";

                const dateKey = normalizePeakLoadDateKey(date);
                if (!substation || !dateKey) return null;
                return {
                    substation: String(substation).replace(/\s+/g, " ").trim(),
                    dateKey
                };
            }).filter(Boolean);
        }

        async function loadPeakLoadSubmittedRows() {
            try {
                const response = await fetch(`${peakLoadSubmitScriptUrl}?action=getSummary&t=${Date.now()}`);
                const data = await response.json();
                const rows = parsePeakLoadSubmittedJson(data);
                if (rows.length) return rows;
            } catch (_) {}

            const csvText = await loadRemoteText(peakLoadSubmittedCsvUrl);
            return parsePeakLoadSubmittedCsv(csvText);
        }

        // NEW FEATURE (2026-09-14): "Daily Hourly Peak Load" ka Daily Progress report
        // (Feeder Reading report jaisa hi pattern) - poori submitted history (full
        // row detail, sirf substation/date nahi) yahan alag se load hoti hai kyonki
        // upar wala parsePeakLoadSubmittedJson() sirf substation+date extract karta
        // hai (pending-check ke liye kaafi tha), report ke liye poori row chahiye.
        function normalizePeakLoadReportRow_(row) {
            if (Array.isArray(row)) {
                return {
                    "33/11 KV SUBSTATION": String(row[0] || "").replace(/\s+/g, " ").trim(),
                    "11 KV FEEDER": String(row[1] || "").replace(/\s+/g, " ").trim(),
                    "METER NO": String(row[2] || "").trim(),
                    "DATE (DD-MM-YYYY)": String(row[3] || "").trim(),
                    "TIME (HH:MM)": String(row[4] || "").trim(),
                    "PEAK LOAD (A)": String(row[5] || "").trim(),
                    "NAME OF OPERATOR": String(row[6] || "").trim()
                };
            }
            return {
                "33/11 KV SUBSTATION": String(row["33/11 KV SUBSTATION"] || row.substation || "").replace(/\s+/g, " ").trim(),
                "11 KV FEEDER": String(row["11 KV FEEDER"] || row.feeder || "").replace(/\s+/g, " ").trim(),
                "METER NO": String(row["METER NO"] || row.meter_no || "").trim(),
                "DATE (DD-MM-YYYY)": String(row["DATE (DD-MM-YYYY)"] || row.date || "").trim(),
                "TIME (HH:MM)": String(row["TIME (HH:MM)"] || row.time || "").trim(),
                "PEAK LOAD (A)": String(row["PEAK LOAD (A)"] || row.peak_load || "").trim(),
                "NAME OF OPERATOR": String(row["NAME OF OPERATOR"] || row.operator_name || "").trim()
            };
        }

        async function loadPeakLoadReportData(forceRefresh = false) {
            if (!forceRefresh && peakLoadReportLoaded && peakLoadReportRows.length) return true;
            peakLoadReportLoadMessage = "";
            const previousPeakLoadReportRows = Array.isArray(peakLoadReportRows) ? peakLoadReportRows.slice() : [];
            let rawData = null, lastErr = null;
            for (let attempt = 1; attempt <= 2 && rawData === null; attempt++) {
                try {
                    rawData = await loadRemoteJson(`${peakLoadSubmitScriptUrl}?action=getSummary&t=${Date.now()}`, 45000);
                } catch (err) {
                    lastErr = err;
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 2000));
                }
            }
            try {
                if (rawData === null) throw lastErr || new Error("Peak load summary load fail");
                const summaryRows = Array.isArray(rawData)
                    ? rawData
                    : Array.isArray(rawData?.data)
                        ? rawData.data
                        : Array.isArray(rawData?.rows)
                            ? rawData.rows
                            : [];
                peakLoadReportRows = summaryRows.map(normalizePeakLoadReportRow_).filter((row) => row["33/11 KV SUBSTATION"] || row["11 KV FEEDER"]);
                if (peakLoadReportRows.length) {
                    peakLoadReportLoaded = true;
                    return true;
                }
                peakLoadReportLoadMessage = "Peak Load report source se data nahi mila";
                // RELIABILITY FIX (2026-09-15, USER-FLAGGED risk): forced refresh
                // (jaise Download click) empty result de to pehle se successfully-
                // loaded data khaali nahi karte.
                peakLoadReportRows = previousPeakLoadReportRows;
                peakLoadReportLoaded = previousPeakLoadReportRows.length > 0;
                return peakLoadReportRows.length > 0;
            } catch (_) {
                peakLoadReportLoadMessage = "Peak Load report source load nahi ho paya";
                peakLoadReportRows = previousPeakLoadReportRows;
                peakLoadReportLoaded = previousPeakLoadReportRows.length > 0;
                return peakLoadReportRows.length > 0;
            }
        }

        function getFilteredPeakLoadReportRows() {
            const label = getFeederReportFilterLabel();
            if (!label) return [];
            if (shmsProgressMode === "MONTHLY") {
                return peakLoadReportRows.filter((row) => {
                    const dateKey = buildFeederDateKey_(row["DATE (DD-MM-YYYY)"] || "");
                    return buildShmsMonthKeyFromDateKey_(dateKey) === label;
                });
            }
            const dailyKey = buildShmsDateKey_(label);
            return peakLoadReportRows.filter((row) => buildFeederDateKey_(row["DATE (DD-MM-YYYY)"] || "") === dailyKey);
        }

        async function renderPeakLoadReportSummary(forceRefresh = false, isStillValid = () => true) {
            const summary = document.getElementById("shms-progress-summary");
            if (!summary) return;
            // SPEED FIX (2026-09-15, USER-REPORTED): pehle hamesha
            // loadPeakLoadReportData(true) chalta tha - date/month toggle par bhi
            // poori history dobara fetch hoti thi. Ab sirf tab-switch/first-load
            // par force hota hai, baaki toggle sirf loaded data re-filter karta hai.
            const needsFetch = forceRefresh || !peakLoadReportLoaded || !peakLoadReportRows.length;
            const progress = needsFetch ? renderSyncingProgress(summary, isStillValid, "SYNCING DATA... PLEASE WAIT") : null;
            await loadPeakLoadReportData(forceRefresh);
            if (!isStillValid()) { if (progress) progress.stop(); return; }
            const label = getFeederReportFilterLabel();
            const rows = getFilteredPeakLoadReportRows();
            if (progress) await progress.finish();
            if (!isStillValid()) return;
            summary.style.display = label ? "block" : "none";
            if (!label) {
                summary.innerHTML = "";
                return;
            }
            // ITEM-8 FIX (2026-09-15): naya fetch fail hone par purana (cached)
            // data dikhne par chhota staleness warning - sirf display text.
            const staleNote = (rows.length && peakLoadReportLoadMessage)
                ? `<br><span style="display:block; margin-top:6px; font-size:11px; color:#b45309;">⚠ Naya data load nahi ho saka, pehle se load data dikha rahe hain</span>`
                : "";
            const debugMessage = rows.length
                ? `${label} ke liye ${rows.length} peak load entries ready hain${staleNote}`
                : (peakLoadReportLoadMessage
                    ? `${label} ke liye 0 peak load entries ready hain<br><span style="display:block; margin-top:6px; font-size:11px; color:#b91c1c;">${peakLoadReportLoadMessage}</span>`
                    : `${label} ke liye 0 peak load entries ready hain`);
            summary.innerHTML = `<div style="margin-top:14px; background:#f8fafc; border:1.5px solid #cbd5e1; border-radius:16px; padding:14px; text-align:center; font-size:13px; font-weight:900; color:#0f172a;">${debugMessage}</div>`;
        }

        async function downloadPeakLoadReport(fmt) {
            try {
                // SPEED FIX (2026-09-15, USER-REPORTED): report screen par already
                // load ho chuka data ho to Download usi ko reuse karta hai, poori
                // history dobara fetch nahi karta.
                if (!peakLoadReportLoaded || !peakLoadReportRows.length) {
                    setShmsProgressStatus("Peak Load report data ready ki ja rahi hai...");
                    await loadPeakLoadReportData(false);
                    setShmsProgressStatus("");
                }
                const rows = getFilteredPeakLoadReportRows();
                const label = getFeederReportFilterLabel();
                if (!label) return showToast("Pehle date ya month select kijiye", false);

                const headers = ["33/11 KV SUBSTATION", "11 KV FEEDER", "METER NO", "DATE (DD-MM-YYYY)", "TIME (HH:MM)", "PEAK LOAD (A)", "NAME OF OPERATOR"];
                const bodyRows = rows.map((row) => headers.map((key) => String(row[key] ?? "")));
                const safeLabel = label.replace(/[\\/:*?"<>|]+/g, "_");

                if (fmt === "XLS") {
                    const csvRows = [
                        ["DAILY HOURLY PEAK LOAD REPORT"],
                        [shmsProgressMode === "MONTHLY" ? `MONTH - ${label}` : `DATE - ${label}`],
                        [],
                        headers,
                        ...bodyRows
                    ];
                    const csv = csvRows.map((row) => row.map((cell) => {
                        const value = String(cell ?? "");
                        return /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
                    }).join(",")).join("\n");
                    await saveShmsBlob(`PEAKLOAD_${shmsProgressMode}_${safeLabel}.csv`, new Blob([csv], { type: "text/csv;charset=utf-8" }), "text/csv;charset=utf-8");
                    return showToast(bodyRows.length ? "Excel report ka request bhej diya gaya. Agar preview me file na aaye to browser ya GitHub version me check kijiye." : "Blank Excel report ka request bhej diya gaya. Agar preview me file na aaye to browser ya GitHub version me check kijiye.", true);
                }

                if (!window.jspdf || !window.jspdf.jsPDF) {
                    return showToast("PDF library load nahi hui", false);
                }

                const { jsPDF } = window.jspdf;
                const doc = new jsPDF("l", "mm", "a4");
                doc.setFontSize(7);
                doc.setTextColor(100);
                doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                doc.setFontSize(15);
                doc.setTextColor(0);
                doc.text("DAILY HOURLY PEAK LOAD REPORT", 148, 16, { align: "center" });
                doc.setFontSize(11);
                doc.text(shmsProgressMode === "MONTHLY" ? `MONTH - ${label}` : `DATE - ${label}`, 148, 23, { align: "center" });
                doc.autoTable({
                    startY: 29,
                    head: [headers],
                    body: bodyRows.length ? bodyRows : [["", "", "", "", "", "", ""]],
                    theme: "grid",
                    headStyles: { fillColor: [17, 24, 39], halign: "center" },
                    styles: { fontSize: 7, cellPadding: 2, halign: "center" },
                    columnStyles: {
                        0: { halign: "left" },
                        1: { halign: "left" },
                        6: { halign: "left" }
                    }
                });
                const pdfBlob = doc.output("blob");
                await saveShmsBlob(`PEAKLOAD_${shmsProgressMode}_${safeLabel}.pdf`, pdfBlob, "application/pdf");
                showToast(bodyRows.length ? "PDF report ka request bhej diya gaya. Agar preview me file na aaye to browser ya GitHub version me check kijiye." : "Blank PDF report ka request bhej diya gaya. Agar preview me file na aaye to browser ya GitHub version me check kijiye.", true);
            } catch (error) {
                setShmsProgressStatus("");
                showToast(error?.message || "Peak Load report download nahi ho paya", false);
            }
        }

