        function initRevenueCollection() {
            const input = document.getElementById("revenue-search-ivrs");
            const resultBox = document.getElementById("revenue-result-box");
            const noteBox = document.getElementById("revenue-empty-note");
            const dcLabel = document.getElementById("revenue-active-dc-label");
            if (dcLabel) {
                if (activeDC) {
                    dcLabel.style.display = "block";
                    dcLabel.innerText = `DC: ${activeDC}`;
                } else {
                    dcLabel.style.display = "none";
                }
            }
            currentRevenueRecord = null;
            showRevenueSearchControls();
            hideRevenueSearchMoreButton();
            if (input) input.value = "";
            if (resultBox) resultBox.style.display = "none";
            hideRevenuePaymentBox();
            if (noteBox) {
                noteBox.style.display = "none";
                noteBox.innerText = activeDC
                    ? `${activeDC} master CSV connect hai. IVRS No search kijiye.`
                    : "Revenue Collection CSV connect hai. IVRS No search kijiye.";
            }
            renderRevenueOfflineRetryBox();
        }

        function normalizeRevenueIvrs(value) {
            const raw = String(value || "").trim();
            if (!raw) return "";
            const compact = raw.replace(/,/g, "").trim();
            const looksNumeric = /^[+-]?\d+(?:\.\d+)?(?:e[+-]?\d+)?$/i.test(compact);
            if (looksNumeric && (/[.e]/i.test(compact) || raw.includes(","))) {
                const numericValue = Number(compact);
                if (Number.isFinite(numericValue)) {
                    return String(Math.trunc(numericValue));
                }
            }
            return raw.replace(/\D/g, "").trim();
        }

        function getRevenueCollectionDcKey(dcName = activeDC) {
            return normalizeLookupValue(dcName || "");
        }

        // Revenue Master URL ka primary map kuch DC tak hi simit hai. Division
        // configuration me jo existing per-DC csvUrl diya hai, use fallback ke
        // roop me lene se Division report kisi valid DC (jaise ADEGAON) par
        // bina wajah fail nahi hoti. Koi naya source/logic add nahi hota.
        function getRevenueCollectionCsvUrl_(dcName = activeDC) {
            const dcKey = getRevenueCollectionDcKey(dcName);
            if (revenueCollectionCsvUrls[dcKey]) return revenueCollectionCsvUrls[dcKey];
            for (const division of Object.values(divisionConfigs || {})) {
                const match = (division.dcs || []).find((dc) => getRevenueCollectionDcKey(dc.name) === dcKey);
                if (match && match.csvUrl) return match.csvUrl;
            }
            return "";
        }

        // SEONI (T) DC ke liye request: underlying data column same rehta hai
        // (HQ NAME / VILLAGE), sirf iske Revenue reports me DISPLAY label alag
        // dikhna hai - "HQ Name" ki jagah "Name of Staff", "Village" ki jagah
        // "Group Dairy". Baaki sabhi 23 DC me pehle jaisa hi "HQ Name"/"Village"
        // dikhta rahega. Yeh sirf label/heading badalta hai - data/filtering
        // logic bilkul waisa hi rahega.
        function isSeoniTDc(dcName = activeDC) {
            return normalizeLookupValue(dcName || "") === normalizeLookupValue("SEONI (T)");
        }
        function revenueHqLabel(dcName = activeDC) {
            return isSeoniTDc(dcName) ? "Name of Staff" : "HQ Name";
        }
        function revenueHqLabelUpper(dcName = activeDC) {
            return revenueHqLabel(dcName).toUpperCase();
        }
        function revenueVillageLabel(dcName = activeDC) {
            return isSeoniTDc(dcName) ? "Group Dairy" : "Village";
        }
        function revenueVillageLabelUpper(dcName = activeDC) {
            return revenueVillageLabel(dcName).toUpperCase();
        }
        function revenueHqAllLabel(dcName = activeDC) {
            return isSeoniTDc(dcName) ? "All Name of Staff" : "All HQ Names";
        }
        function revenueVillageAllLabel(dcName = activeDC) {
            return isSeoniTDc(dcName) ? "All Group Dairy" : "All Villages";
        }

        function formatRevenueMonthYear(monthValue) {
            const raw = String(monthValue || "").trim();
            const match = raw.match(/^(\d{4})-(\d{2})$/);
            if (!match) return raw || "-";
            const date = new Date(Number(match[1]), Number(match[2]) - 1, 1);
            return date.toLocaleString("en-US", { month: "long", year: "numeric" });
        }

        function formatRevenueAmount(value) {
            const cleanValue = String(value || "").replace(/\s+/g, " ").trim();
            if (!cleanValue) return "-";
            return cleanValue.includes("₹") ? cleanValue : `₹ ${cleanValue}`;
        }

        function formatRevenuePaidTime(value) {
            if (value === null || value === undefined || value === "") return "-";
            const formatDateAsIst = (dateObj) => {
                if (!(dateObj instanceof Date) || Number.isNaN(dateObj.getTime())) return "";
                try {
                    return dateObj.toLocaleTimeString("en-GB", {
                        hour: "2-digit",
                        minute: "2-digit",
                        hour12: false,
                        timeZone: "Asia/Kolkata"
                    });
                } catch (_) {
                    return `${String(dateObj.getHours()).padStart(2, "0")}:${String(dateObj.getMinutes()).padStart(2, "0")}`;
                }
            };
            if (value instanceof Date) return formatDateAsIst(value) || "-";
            const raw = String(value || "").trim();
            if (!raw) return "-";

            const numericValue = Number(raw);
            if (Number.isFinite(numericValue) && numericValue >= 0 && numericValue < 1) {
                const totalMinutes = Math.round(numericValue * 24 * 60);
                return `${String(Math.floor(totalMinutes / 60) % 24).padStart(2, "0")}:${String(totalMinutes % 60).padStart(2, "0")}`;
            }

            if (/^\d{4}-\d{2}-\d{2}T\d{1,2}:\d{2}/.test(raw)) {
                const formatted = formatDateAsIst(new Date(raw));
                if (formatted) return formatted;
            }

            const directTime = raw.match(/(?:^|\s)(\d{1,2}):(\d{2})(?::\d{2})?(?:\s|$)/);
            if (directTime) {
                const hour = Number(directTime[1]);
                if (hour >= 0 && hour <= 23) {
                    return `${directTime[1].padStart(2, "0")}:${directTime[2]}`;
                }
            }

            const formatted = formatDateAsIst(new Date(raw));
            if (formatted) return formatted;
            return raw;
        }

        function parseRevenueCollectionCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];

            let headerLineIndex = 0;
            for (let i = 0; i < Math.min(lines.length, 20); i++) {
                const keys = splitCsvLine(lines[i]).map((header) => normalizeLookupValue(header));
                const hasIvrs = keys.some((key) => key.includes("IVRS"));
                const hasConsumer = keys.some((key) => key.includes("CONSUMER") || key.includes("NAME"));
                if (hasIvrs && hasConsumer) {
                    headerLineIndex = i;
                    break;
                }
            }

            const headers = splitCsvLine(lines[headerLineIndex]);
            const headerKeys = headers.map((header) => normalizeLookupValue(header));
            const findIndex = (keys, fallback) => {
                const idx = headerKeys.findIndex((header) => keys.some((key) => header.includes(key)));
                return idx >= 0 ? idx : fallback;
            };

            const ivrsIndex = findIndex(["IVRS"], 0);
            const nameIndex = findIndex(["CONSUMERNAME", "CONSUMER"], 1);
            const fatherIndex = findIndex(["FATHERNAME", "FATHER"], 2);
            const villageIndex = findIndex(["VILLAGE"], 3);
            const hqIndex = findIndex(["HQNAME", "HQ"], 4);
            const categoryIndex = findIndex(["TARRIFCATEGORY", "TARIFFCATEGORY", "CATEGORY"], 5);
            const mobileIndex = findIndex(["MOBILENO", "MOBILE"], 6);
            const arrearsIndex = findIndex(["ARREARS"], 7);
            const netBillIndex = findIndex(["NETBILL", "NET"], 8);
            // Yeh 2 column optional hain (sirf jin DC ki sheet update ho chuki hai unme
            // milenge) - isliye koi positional fallback nahi, sirf tabhi milenge jab header
            // name se mile. Na milne par -1 rehta hai, aur neeche wahi "column missing" wala
            // safe-default (govtFlag false, hasPaymentDateData false) apply hota hai jaisa
            // mapRevenueConsumerRow() me hai.
            const govtIndex = findIndex(["GOVTNONGOVT", "GOVT", "ISGOVERNMENT"], -1);
            const lastPaymentIndex = findIndex(["LASTPAYMENTDATE", "LASTPAYMENT"], -1);

            return lines.slice(headerLineIndex + 1).map((line) => {
                const cols = splitCsvLine(line);
                const lastPaymentDate = lastPaymentIndex >= 0 ? parseConsumerLastPaymentDate(cols[lastPaymentIndex]) : "";
                return {
                    ivrsNo: String(cols[ivrsIndex] || "").trim(),
                    consumerName: String(cols[nameIndex] || "").trim(),
                    fatherName: String(cols[fatherIndex] || "").trim(),
                    village: String(cols[villageIndex] || "").trim(),
                    hqName: String(cols[hqIndex] || "").trim(),
                    tariffCategory: String(cols[categoryIndex] || "").trim(),
                    mobileNo: String(cols[mobileIndex] || "").trim(),
                    arrears: String(cols[arrearsIndex] || "").trim(),
                    netBill: String(cols[netBillIndex] || "").trim(),
                    govtFlag: govtIndex >= 0 ? parseConsumerGovtFlag(cols[govtIndex]) : false,
                    lastPaymentDate: lastPaymentDate,
                    hasPaymentDateData: lastPaymentIndex >= 0,
                    neverPaid: lastPaymentIndex >= 0 ? !lastPaymentDate : false
                };
            }).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
        }

        function parseConsumerGovtFlag(value) {
            const raw = String(value == null ? "" : value).trim().toUpperCase();
            if (!raw) return false;
            return raw === "TRUE" || raw === "YES" || raw === "Y" || raw === "1" || raw === "GOVT" || raw === "GOVERNMENT";
        }

        function parseConsumerLastPaymentDate(value) {
            const raw = String(value == null ? "" : value).trim();
            if (!raw || raw === "0") return "";
            return raw;
        }

        // Sheet me column hi maujood hai ya nahi (chahe value khaali ho) - yeh check karta
        // hai. Zaroori hai kyoki "column missing" (jo DC ki sheet abhi update nahi hui) aur
        // "column hai lekin khaali/0" (jo waqai never-paid consumer hai) do alag cheezein
        // hain - inhe ek jaisa treat karna Non Payee reports ko galat bana dega un DC ke liye
        // jinki sheet abhi update nahi hui.
        function hasConsumerField(row, aliases) {
            if (!row) return false;
            return aliases.some((alias) => Object.prototype.hasOwnProperty.call(row, normalizeDcName(alias)));
        }

        function mapRevenueConsumerRow(row) {
            const lastPaymentAliases = ["LAST PAYMENT DATE", "LAST PAYMENT"];
            const hasPaymentDateData = hasConsumerField(row, lastPaymentAliases);
            const lastPaymentRaw = getConsumerField(row, lastPaymentAliases);
            const lastPaymentDate = parseConsumerLastPaymentDate(lastPaymentRaw);
            return {
                ivrsNo: getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER"]),
                consumerName: getConsumerField(row, ["CONSUMER NAME", "NAME"]),
                fatherName: getConsumerField(row, ["FATHER NAME", "FATHER"]),
                village: getConsumerField(row, ["VILLAGE", "ADDRESS", "ADDR"]),
                hqName: getConsumerHqName(row, ""),
                tariffCategory: getConsumerField(row, ["TARRIF CATEGORY", "TARIFF CATEGORY", "CATEGORY"]),
                mobileNo: getConsumerField(row, ["MOBILE NO", "MOBILE NUMBER", "MOBILE"]),
                arrears: getConsumerField(row, ["ARREARS", "ARREAR"]),
                netBill: getConsumerField(row, ["NET BILL", "NETBILL", "NET AMOUNT", "BILL AMOUNT"]),
                govtFlag: parseConsumerGovtFlag(getConsumerField(row, ["GOVT/NON GOVT", "GOVT NON GOVT", "GOVT", "IS GOVERNMENT"])),
                lastPaymentDate: lastPaymentDate,
                hasPaymentDateData: hasPaymentDateData,
                neverPaid: hasPaymentDateData ? !lastPaymentDate : false
            };
        }

        async function loadRevenueCollectionData(dcName = activeDC, forceRefresh = false, options = null) {
            const dcKey = getRevenueCollectionDcKey(dcName);
            if (!forceRefresh && revenueCollectionLoadedByDc[dcKey]) return revenueCollectionRowsByDc[dcKey] || [];

            const csvUrl = getRevenueCollectionCsvUrl_(dcName);
            const cacheKey = `seoni-revenue-collection-csv-v5-${dcKey}`;

            if (!forceRefresh) {
                try {
                    const cachedJson = JSON.parse(localStorage.getItem(`${cacheKey}-json`) || "[]");
                    if (Array.isArray(cachedJson) && cachedJson.length) {
                        revenueCollectionRowsByDc[dcKey] = cachedJson;
                        revenueCollectionLoadedByDc[dcKey] = true;
                        refreshRevenueCollectionCache(csvUrl, cacheKey, dcKey);
                        return cachedJson;
                    }
                    const cachedText = localStorage.getItem(cacheKey) || "";
                    const cachedRows = isLikelyCsvPayload(cachedText)
                        ? (
                            parseRevenueCollectionCsv(cachedText).length
                                ? parseRevenueCollectionCsv(cachedText)
                                : parseConsumerCsv(cachedText).map(mapRevenueConsumerRow).filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                        )
                        : [];
                    if (cachedRows.length) {
                        revenueCollectionRowsByDc[dcKey] = cachedRows;
                        revenueCollectionLoadedByDc[dcKey] = true;
                        refreshRevenueCollectionCache(csvUrl, cacheKey, dcKey);
                        return cachedRows;
                    }
                } catch (_) {}
            }

            if (csvUrl) {
                try {
                    const rawCsv = await loadRemoteText(csvUrl);
                    const rows = isLikelyCsvPayload(rawCsv)
                        ? (
                            parseRevenueCollectionCsv(rawCsv).length
                                ? parseRevenueCollectionCsv(rawCsv)
                                : parseConsumerCsv(rawCsv).map(mapRevenueConsumerRow).filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                        )
                        : [];
                    if (rows.length) {
                        revenueCollectionRowsByDc[dcKey] = rows;
                        revenueCollectionLoadedByDc[dcKey] = true;
                        try {
                            localStorage.setItem(cacheKey, rawCsv);
                        } catch (_) {}
                        return rows;
                    }
                } catch (_) {}

                for (const candidateUrl of getRevenueCsvCandidateUrls(csvUrl)) {
                    try {
                        const rawCsv = await loadRevenueCsvText(candidateUrl);
                        const rows = isLikelyCsvPayload(rawCsv)
                            ? (
                                parseRevenueCollectionCsv(rawCsv).length
                                    ? parseRevenueCollectionCsv(rawCsv)
                                    : parseConsumerCsv(rawCsv).map(mapRevenueConsumerRow).filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                            )
                            : [];
                        if (rows.length) {
                            revenueCollectionRowsByDc[dcKey] = rows;
                            revenueCollectionLoadedByDc[dcKey] = true;
                            try {
                                localStorage.setItem(cacheKey, rawCsv);
                                localStorage.setItem(`${cacheKey}-json`, JSON.stringify(rows));
                            } catch (_) {}
                            return rows;
                        }
                    } catch (_) {}
                }
            }

            // Revenue reconciliation reports ko exact/current Master chahiye. Unke
            // strict caller me remote CSV ke fail hone par purana consumer/cache
            // fallback silently accept nahi karte; normal callers ka purana
            // fallback behaviour bilkul unchanged rehta hai.
            if (options && options.requireRemote) return [];

            let mobileUpdateRows = getConsumerRows(dcName);
            if (!mobileUpdateRows.length) mobileUpdateRows = await ensureDcDataLoaded(dcName);
            const mappedMobileRows = mobileUpdateRows.map(mapRevenueConsumerRow).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
            if (mappedMobileRows.length) {
                revenueCollectionRowsByDc[dcKey] = mappedMobileRows;
                revenueCollectionLoadedByDc[dcKey] = true;
                return mappedMobileRows;
            }

            revenueCollectionRowsByDc[dcKey] = [];
            revenueCollectionLoadedByDc[dcKey] = false;
            return [];
        }

        async function refreshRevenueCollectionCache(csvUrl, cacheKey, dcKey) {
            if (!csvUrl || !cacheKey || !dcKey) return;
            try {
                const gvizRows = await loadRevenueCollectionViaGviz(csvUrl);
                if (!gvizRows.length) return;
                revenueCollectionRowsByDc[dcKey] = gvizRows;
                revenueCollectionLoadedByDc[dcKey] = true;
                try {
                    localStorage.setItem(`${cacheKey}-json`, JSON.stringify(gvizRows));
                } catch (_) {}
            } catch (_) {}
        }

        function loadRevenueCollectionViaGviz(csvUrl) {
            return new Promise((resolve, reject) => {
                const callbackName = `revenueGvizCallback_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
                const script = document.createElement("script");
                const timeout = setTimeout(() => {
                    cleanup();
                    reject(new Error("GViz timeout"));
                }, 3000);

                function cleanup() {
                    clearTimeout(timeout);
                    try {
                        delete window[callbackName];
                    } catch (_) {
                        window[callbackName] = undefined;
                    }
                    try {
                        if (script.parentNode) script.parentNode.removeChild(script);
                    } catch (_) {}
                }

                window[callbackName] = (response) => {
                    try {
                        const rows = parseRevenueGvizResponse(response);
                        cleanup();
                        resolve(rows);
                    } catch (error) {
                        cleanup();
                        reject(error);
                    }
                };

                script.onerror = () => {
                    cleanup();
                    reject(new Error("GViz script load failed"));
                };

                script.src = buildRevenueGvizUrl(csvUrl, callbackName);
                document.head.appendChild(script);
            });
        }

        function buildRevenueGvizUrl(csvUrl, callbackName) {
            const idMatch = String(csvUrl || "").match(/\/spreadsheets\/d\/(?!e\/)([^/]+)/);
            const baseUrl = idMatch
                ? `https://docs.google.com/spreadsheets/d/${idMatch[1]}/gviz/tq`
                : (csvUrl.includes("/pub?") ? csvUrl.replace(/\/pub\?.*$/i, "/gviz/tq") : csvUrl);
            return `${baseUrl}?gid=0&tqx=responseHandler:${callbackName};out:json&t=${Date.now()}`;
        }

        function parseRevenueGvizResponse(response) {
            if (!response || response.status !== "ok" || !response.table) return [];
            const headers = (response.table.cols || []).map((col) => String(col.label || col.id || "").trim());
            const headerKeys = headers.map((header) => normalizeLookupValue(header));
            const findIndex = (keys, fallback) => {
                const idx = headerKeys.findIndex((header) => keys.some((key) => header.includes(key)));
                return idx >= 0 ? idx : fallback;
            };

            const ivrsIndex = findIndex(["IVRS"], 0);
            const nameIndex = findIndex(["CONSUMERNAME", "CONSUMER"], 1);
            const fatherIndex = findIndex(["FATHERNAME", "FATHER"], 2);
            const villageIndex = findIndex(["VILLAGE"], 3);
            const hqIndex = findIndex(["HQNAME", "HQ"], 4);
            const categoryIndex = findIndex(["TARRIFCATEGORY", "TARIFFCATEGORY", "CATEGORY"], 5);
            const mobileIndex = findIndex(["MOBILENO", "MOBILE"], 6);
            const arrearsIndex = findIndex(["ARREARS"], 7);
            const netBillIndex = findIndex(["NETBILL", "NET"], 8);
            const govtIndex = findIndex(["GOVTNONGOVT", "GOVT", "ISGOVERNMENT"], -1);
            const lastPaymentIndex = findIndex(["LASTPAYMENTDATE", "LASTPAYMENT"], -1);
            const cellValue = (cells, index) => {
                const cell = cells[index] || {};
                return String(cell.f || cell.v || "").trim();
            };

            return (response.table.rows || []).map((row) => {
                const cells = row.c || [];
                const lastPaymentDate = lastPaymentIndex >= 0 ? parseConsumerLastPaymentDate(cellValue(cells, lastPaymentIndex)) : "";
                return {
                    ivrsNo: cellValue(cells, ivrsIndex),
                    consumerName: cellValue(cells, nameIndex),
                    fatherName: cellValue(cells, fatherIndex),
                    village: cellValue(cells, villageIndex),
                    hqName: cellValue(cells, hqIndex),
                    tariffCategory: cellValue(cells, categoryIndex),
                    mobileNo: cellValue(cells, mobileIndex),
                    arrears: cellValue(cells, arrearsIndex),
                    netBill: cellValue(cells, netBillIndex),
                    govtFlag: govtIndex >= 0 ? parseConsumerGovtFlag(cellValue(cells, govtIndex)) : false,
                    lastPaymentDate: lastPaymentDate,
                    hasPaymentDateData: lastPaymentIndex >= 0,
                    neverPaid: lastPaymentIndex >= 0 ? !lastPaymentDate : false
                };
            }).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
        }

        async function loadRevenueCsvText(url) {
            const withTs = url.includes("?") ? `${url}&t=${Date.now()}` : `${url}?t=${Date.now()}`;
            const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
            const timer = setTimeout(() => {
                try {
                    if (controller) controller.abort();
                } catch (_) {}
            }, 5500);
            try {
                const response = await fetch(withTs, controller ? { signal: controller.signal } : {});
                const text = await response.text();
                if (!text || /^\s*</.test(text)) throw new Error("CSV response valid nahi hai");
                return text;
            } finally {
                clearTimeout(timer);
            }
        }

        function getRevenueCsvCandidateUrls(csvUrl) {
            const urls = [];
            const addUrl = (url) => {
                if (url && !urls.includes(url)) urls.push(url);
            };
            addUrl(csvUrl);

            const singleUrl = csvUrl.includes("pub?")
                ? csvUrl.replace(/pub\?.*$/i, "pub?gid=0&single=true&output=csv")
                : csvUrl;
            addUrl(singleUrl);

            const gvizUrl = csvUrl.includes("/pub?")
                ? csvUrl.replace(/\/pub\?.*$/i, "/gviz/tq?tqx=out:csv&gid=0")
                : "";
            addUrl(gvizUrl);

            [csvUrl, singleUrl, gvizUrl].filter(Boolean).forEach((url) => {
                addUrl(`https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`);
            });
            return urls;
        }

        function renderRevenueConsumer(record, searchedIvrs) {
            const resultBox = document.getElementById("revenue-result-box");
            const noteBox = document.getElementById("revenue-empty-note");
            if (!resultBox) return;
            if (noteBox) noteBox.style.display = "none";
            const paidEntries = getRevenuePaidEntries(record.ivrsNo || searchedIvrs);
            const paidStatusHtml = paidEntries.length ? `
                <div class="revenue-status-blink" style="margin-top:7px; background:#dcfce7; border:1.5px solid #22c55e; border-radius:12px; padding:7px; text-align:center;">
                    <div style="font-size:0.78rem; font-weight:950; color:#166534;">Paid By Staff - ${escapeHtml(paidEntries.length)}/2</div>
                    ${paidEntries.map((paidEntry, index) => `
                        <div style="font-size:0.66rem; font-weight:900; color:#14532d; margin-top:2px;">
                            ${index + 1}. Amount: ${escapeHtml(formatRevenueAmount(paidEntry.paidAmount))} | Date: ${escapeHtml(paidEntry.paidDate || "-")} | Time: ${escapeHtml(formatRevenuePaidTime(paidEntry.paidTime))}
                        </div>
                    `).join("")}
                </div>
            ` : "";
            const uploadedPaidEntry = getRevenueUploadedPaidEntryLocal(record.ivrsNo || searchedIvrs);
            const uploadedPaidHtml = uploadedPaidEntry ? `
                <div class="revenue-status-blink" style="margin-top:7px; background:#f0fdf4; border:1.5px solid #16a34a; border-radius:12px; padding:7px; text-align:center;">
                    <div style="font-size:0.76rem; font-weight:950; color:#15803d;">NGB CASHLIST: PAID</div>
                    <div style="font-size:0.66rem; font-weight:900; color:#14532d; margin-top:2px;">
                        Amount: ${escapeHtml(formatRevenueAmount(uploadedPaidEntry.amountPaid))} | Date: ${escapeHtml(formatRevenueUploadedPaidDate(uploadedPaidEntry.paymentDate))}
                    </div>
                    <div style="font-size:0.6rem; font-weight:850; color:#64748b; margin-top:1px;">
                        Payments: ${escapeHtml(uploadedPaidEntry.paymentCount || "-")} ${uploadedPaidEntry.sourceType ? "| " + escapeHtml(uploadedPaidEntry.sourceType) : ""}
                    </div>
                </div>
            ` : "";
            const tdEntry = getRevenueTdEntryLocal(record.ivrsNo || searchedIvrs);
            const tdStatusHtml = tdEntry ? `
                <div class="revenue-td-blink" style="margin-top:7px; background:#fef2f2; border:1.5px solid #ef4444; border-radius:12px; padding:7px; text-align:center;">
                    <div style="font-size:0.76rem; font-weight:950; color:#991b1b;">Line TD Done - ${escapeHtml(tdEntry.tdDate || "-")} ${escapeHtml(formatRevenuePaidTime(tdEntry.tdTime))}</div>
                    ${tdEntry.remark ? `<div style="font-size:0.62rem; font-weight:850; color:#7f1d1d; margin-top:2px;">Remark: ${escapeHtml(tdEntry.remark)}</div>` : ""}
                </div>
            ` : "";

            resultBox.innerHTML = `
                <div style="background:linear-gradient(180deg,#eff6ff 0%,#ffffff 100%); border:1.5px solid #bfdbfe; border-radius:16px; padding:9px; text-align:left;">
                    <div style="display:flex; justify-content:space-between; gap:7px; align-items:center; margin-bottom:6px; background:#dbeafe; border:1.5px solid #60a5fa; border-radius:12px; padding:7px 9px;">
                        <span style="font-size:0.64rem; font-weight:950; color:#1d4ed8; letter-spacing:0.03em;">IVRS NO</span>
                        <span style="flex:1; text-align:center; font-size:0.82rem; font-weight:950; color:#dc2626;">${escapeHtml(record.ivrsNo || searchedIvrs)}</span>
                        <button type="button" onclick="openCurrentRevenueBill()" style="min-width:68px; height:30px; border:none; border-radius:9px; background:#2563eb; color:#fff; font-size:0.57rem; font-weight:950;">VIEW BILL</button>
                    </div>
                    <div style="background:#ffffff; border:1px solid #dbeafe; border-radius:13px; padding:7px 10px; box-shadow:0 5px 12px rgba(37,99,235,0.06);">
                        <div style="font-size:0.82rem; line-height:1.15; font-weight:950; color:#0f172a; text-align:center;">${escapeHtml(record.consumerName || "-")}</div>
                        <div style="margin-top:2px; font-size:0.67rem; font-weight:850; color:#475569; text-align:center;">S/o ${escapeHtml(record.fatherName || "-")}</div>
                    </div>

                    <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:7px;">
                        ${renderRevenueMiniBox(revenueVillageLabel(), record.village)}
                        ${renderRevenueMiniBox(revenueHqLabel(), record.hqName)}
                        ${renderRevenueMiniBox("Category", record.tariffCategory)}
                        ${renderRevenueMiniBox("Mobile No", normalizeMobileDisplayValue(record.mobileNo))}
                    </div>
                    ${renderRevenueMobileActionRow(record.mobileNo)}

                    <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:7px;">
                        <div style="background:#fff7ed; border:1.5px solid #fdba74; border-radius:12px; padding:7px; text-align:center;">
                            <div style="font-size:0.58rem; font-weight:950; color:#c2410c; text-transform:uppercase;">Arrears</div>
                            <div style="font-size:0.82rem; font-weight:950; color:#9a3412; margin-top:2px;">${escapeHtml(formatRevenueAmount(record.arrears))}</div>
                        </div>
                        <div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:12px; padding:7px; text-align:center;">
                            <div style="font-size:0.58rem; font-weight:950; color:#047857; text-transform:uppercase;">Net Bill</div>
                            <div style="font-size:0.82rem; font-weight:950; color:#065f46; margin-top:2px;">${escapeHtml(formatRevenueAmount(record.netBill))}</div>
                        </div>
                    </div>
                    ${uploadedPaidHtml}
                    ${paidStatusHtml}
                    ${tdStatusHtml}
                </div>
            `;
            resultBox.style.display = "block";
        }

        function renderRevenueMiniBox(label, value) {
            return `
                <div style="background:#f8fafc; border:1px solid #dbeafe; border-radius:11px; padding:6px; min-height:44px;">
                    <div style="font-size:0.56rem; font-weight:950; color:#2563eb; text-transform:uppercase;">${escapeHtml(label)}</div>
                    <div style="font-size:0.68rem; font-weight:850; color:#1e293b; margin-top:2px; word-break:break-word;">${escapeHtml(value || "-")}</div>
                </div>
            `;
        }

        function renderRevenueMobileActionRow(mobileNo) {
            const validMobile = normalizeRevenueMessageMobile(mobileNo);
            const disabledStyle = validMobile ? "" : "opacity:0.45; pointer-events:none;";
            // "UPDATE MOBILE NO" chautha button - Update Mobile No jaisa hi red rang, aur
            // CALL button ka rang ab peela (yellow) kar diya hai (pehle CALL hi red tha).
            // Yeh button IVRS search ke isi record ke sath seedha Update Mobile No screen
            // par le jaata hai (dobara IVRS search karne ki zaroorat nahi) - sabhi 24 DC
            // par same tarike se kaam karta hai kyunki yeh sirf activeDC + currentRevenueRecord
            // use karta hai (DC-specific hardcoding nahi hai).
            return `
                <div style="display:grid; grid-template-columns:1fr 1fr 1fr 1fr; gap:6px; margin-top:7px; ${disabledStyle}">
                    <button type="button" onclick="openCurrentRevenueSms()" style="min-height:36px; border:none; border-radius:10px; background:#2563eb; color:#fff; font-size:0.6rem; font-weight:950;">SMS</button>
                    <button type="button" onclick="openCurrentRevenueWhatsApp()" style="min-height:36px; border:none; border-radius:10px; background:#16a34a; color:#fff; font-size:0.58rem; font-weight:950;">WHATSAPP</button>
                    <button type="button" onclick="callCurrentRevenueConsumer()" style="min-height:36px; border:none; border-radius:10px; background:#f59e0b; color:#fff; font-size:0.6rem; font-weight:950;">CALL</button>
                    <button type="button" onclick="jumpToUpdateMobileNoFromRevenue()" style="min-height:36px; border:none; border-radius:10px; background:#dc2626; color:#fff; font-size:0.52rem; font-weight:950; line-height:1.1;">UPDATE<br>MOBILE NO</button>
                </div>
            `;
        }

        function jumpToUpdateMobileNoFromRevenue() {
            const record = currentRevenueRecord;
            const ivrsNo = normalizeRevenueIvrs(record?.ivrsNo);
            if (!ivrsNo) return showToast("Pehle IVRS search kijiye", false);
            switchView("mobile-update");
            const searchInput = document.getElementById("search-ivrs");
            if (searchInput) searchInput.value = ivrsNo;
            // User ki request (fast searching ke liye): yahan se ab sirf IVRS No
            // Mobile Update ke search box me copy-paste ho jaata hai - details
            // auto-open nahi hoti aur already-submitted check bhi yahan se trigger
            // nahi hota. User khud SEARCH button dabayega, tabhi performSearch()
            // chalega aur already-submitted/submit-button-hide wala normal flow
            // apne aap chalega (jaisa Mobile Update screen par direct search karne
            // par hota hai).
        }

        async function populateMobileUpdateSearchFromRevenue(record, ivrsNo) {
            currentData = {
                ivrs: ivrsNo,
                name: record.consumerName || "",
                father: record.fatherName || "",
                old: normalizeMobileDisplayValue(record.mobileNo || ""),
                addr: record.village || "",
                hq: record.hqName || ""
            };
            const newMobileInput = document.getElementById("new-mobile");
            if (newMobileInput) newMobileInput.value = "";
            document.getElementById("res-ivrs").innerText = currentData.ivrs;
            document.getElementById("res-name").innerText = currentData.name;
            document.getElementById("res-old").innerText = currentData.old || "N/A";
            document.getElementById("res-addr").innerText = currentData.addr;
            document.getElementById("result-box").style.display = "block";
            document.getElementById("submit-btn").style.display = "none";
            const alreadyBoxReset = document.getElementById("mobile-already-submitted-box");
            if (alreadyBoxReset) alreadyBoxReset.style.display = "none";
            // Yeh normally ab tak Revenue search ke waqt hi background me warm ho
            // chuka hota hai (searchRevenueIvrs() me loadMobileAlreadySubmittedMap()
            // call), isliye yeh await 60-second cache se turant resolve ho jaata hai.
            await loadMobileAlreadySubmittedMap();
            applyMobileAlreadySubmittedUi(getMobileAlreadySubmittedEntry(activeDC, currentData.ivrs));
        }

        function copyRevenueText(value) {
            const text = String(value || "");
            if (!text) return Promise.resolve(false);
            if (navigator.clipboard?.writeText) return navigator.clipboard.writeText(text).then(() => true).catch(() => false);
            try {
                const input = document.createElement("textarea");
                input.value = text;
                input.style.position = "fixed";
                input.style.opacity = "0";
                document.body.appendChild(input);
                input.select();
                const copied = document.execCommand("copy");
                input.remove();
                return Promise.resolve(copied);
            } catch (_) {
                return Promise.resolve(false);
            }
        }

        // Excel Automation (Compare Two Excel File) - yeh ek alag, standalone HTML tool
        // hai (SheetJS-based, Master Data vs Compare File reconcile karta hai). Content
        // backend se fetch hota hai (Sub DN Chhapara ke 3-dot menu se "Update Excel
        // Automation Tool" jab bhi naya .html upload hota hai, sabhi DC par turant
        // reflect ho jaata hai).
        // BUG FIX (5-6 taps lagne wala issue): pehle yahan pehle "await fetch(...)" hone
        // ke BAAD window.open() call hota tha - browsers window.open() ko sirf tabhi
        // bina block kiye allow karte hain jab wo seedha click handler ke andar,
        // SYNCHRONOUSLY chale. Await ke baad wala window.open() ek "delayed" call ban
        // jaata hai jise popup-blocker chupchap रोक deta hai - isiliye pehli baar click
        // karne par kuch nahi hota tha, aur kabhi-kabhi (jab pichla blocked tab abhi tak
        // memory me ho ya browser thoda alag react kare) 5-6 baar tap karne par khulta
        // dikhta tha.
        // Fix: ab tab click hote hi SYNCHRONOUSLY khol dete hain (isliye turant naya tab
        // dikhega, popup-blocker rokta nahi) aur usme "Loading..." dikha dete hain; jab
        // tak backend se content aata hai, button bhi disable/"Opening..." dikhata hai
        // taaki baar-baar tap na ho. Content aane par usi tab ke andar likh dete hain.
        // FURTHER FIX: backend (script.google.com) kabhi-kabhi bahut slow response deta
        // hai, jis wajah se pehle yahan "Opening..." der tak atka reh jaata tha aur user
        // dobara-dobara tap kar deta tha (jisse Chrome ka popup-abuse-blocker activate ho
        // jaata tha - "Naya tab nahi khul paya" wala error). Ab do cheezein ki hain: (1)
        // ek module-level "already in progress" flag - dobara click hone par turant
        // ignore ho jaata hai (button disable ke upar ek extra safety layer), (2) backend
        // fetch par 8-second ka hard timeout - itni der me jawab na aaye to turant static
        // GitHub wali file par fallback ho jaata hai (usi already-khule tab me), taaki tab
        // kabhi bhi "Loading..." par hamesha ke liye atka na rahe.
        let excelAutomationToolOpening = false;
        async function openExcelAutomationTool() {
            if (excelAutomationToolOpening) return;
            excelAutomationToolOpening = true;
            const btn = document.getElementById("excel-automation-open-btn");
            const originalBtnText = btn ? btn.innerText : "Compare 2 Excel File (V-LOOKUP)";
            if (btn) {
                btn.disabled = true;
                btn.style.opacity = "0.65";
                btn.style.pointerEvents = "none";
                btn.innerText = "Opening...";
            }
            const restoreBtn = () => {
                excelAutomationToolOpening = false;
                if (!btn) return;
                btn.disabled = false;
                btn.style.opacity = "1";
                btn.style.pointerEvents = "auto";
                btn.innerText = originalBtnText;
            };
            try {
                // IMPORTANT: yahan "noopener" flag NAHI lagana - spec ke hisab se
                // "noopener" ke saath window.open() hamesha NULL return karta hai (koi
                // reference nahi milta), isliye humein baad me isi tab me content likhne
                // ke liye reference chahiye. Isi wajah se ek blank tab + ek alag "asli"
                // tab (2 tabs) khul rahe the - newTab hamesha null aata tha, code fallback
                // path (naya alag tab) le leta tha.
                const newTab = window.open("", "_blank");
                if (newTab) {
                    try {
                        newTab.document.write("<!DOCTYPE html><html><head><title>Excel Automation - Loading...</title></head><body style=\"background:#0f172a; color:#e2e8f0; font-family:Arial,sans-serif; display:flex; align-items:center; justify-content:center; height:100vh; margin:0;\"><div style=\"text-align:center;\"><div style=\"font-size:1rem; font-weight:700;\">Excel Automation Tool load ho raha hai...</div></div></body></html>");
                        newTab.document.close();
                    } catch (_) {}
                } else {
                    showToast("Naya tab nahi khul paya - browser me popup allow kijiye", false);
                }
                const baseUrl = window.location.href.split("#")[0].split("?")[0];
                const toolUrl = baseUrl.replace(/[^/]*$/, "") + "excel-automation.html";
                try {
                    // NOTE (fixed): pehle yahan sirf 8 second ka timeout tha - is backend
                    // (Google Apps Script) ka response kabhi-kabhi 15-20+ second bhi le
                    // leta hai (jaisa doosri Revenue reports me bhi pehle dekha gaya hai),
                    // isliye 8 second me hi silently purani static GitHub file par
                    // fallback ho jaata tha - koi error bhi nahi dikhta tha, isliye naya
                    // upload kiya hua tool kabhi khulta hi nahi tha, hamesha purana hi
                    // dikhta rehta tha. Ab 40 second diya hai (poori DC-agnostic report
                    // fetches jaisa hi generous), aur agar phir bhi fallback ho to user ko
                    // saaf toast bhi dikhega ki "latest fetch nahi ho paya".
                    const fetchUrl = `${revenueCollectionSubmitScriptUrl}?action=getExternalToolHtml&tool_key=EXCEL_AUTOMATION&t=${Date.now()}`;
                    const response = await fetchWithTimeout(fetchUrl, {}, 40000);
                    const parsed = await response.json();
                    if (parsed && parsed.status === "success" && parsed.html) {
                        if (newTab && !newTab.closed) {
                            newTab.document.open();
                            newTab.document.write(parsed.html);
                            newTab.document.close();
                        } else {
                            const blob = new Blob([parsed.html], { type: "text/html" });
                            window.open(URL.createObjectURL(blob), "_blank", "noopener");
                        }
                        return;
                    }
                    showToast("Latest tool fetch nahi ho paya, purani file khul rahi hai", false);
                } catch (_) {
                    showToast("Latest tool fetch nahi ho paya, purani file khul rahi hai", false);
                }
                if (newTab && !newTab.closed) {
                    newTab.location.href = toolUrl;
                } else {
                    window.open(toolUrl, "_blank", "noopener");
                }
            } finally {
                restoreBtn();
            }
        }

        // Panchnama tool ka "open new tab" flow bilkul Excel Automation jaisa hi hai
