        async function selectRevenueAction(actionType) {
            const paidCheck = document.getElementById("revenue-action-paid");
            const tdCheck = document.getElementById("revenue-action-td");
            if (!currentRevenueRecord) {
                if (paidCheck) paidCheck.checked = false;
                if (tdCheck) tdCheck.checked = false;
                return showToast("Pahle IVRS search kijiye", false);
            }

            if (actionType === "PAID") {
                if (paidCheck && !paidCheck.checked) {
                    hideRevenuePaymentBox();
                    return;
                }
                if (tdCheck) tdCheck.checked = false;
                hideRevenueTdBox();
                if (getRevenuePaidEntries(currentRevenueRecord.ivrsNo).length >= 2) {
                    if (paidCheck) paidCheck.checked = false;
                    return showToast("Is IVRS par 2 payment already submit ho chuki hai", false);
                }
                showRevenuePaymentBox();
                return;
            }

            if (actionType === "TD") {
                if (tdCheck && !tdCheck.checked) {
                    hideRevenueTdBox();
                    return;
                }
                const alreadyPaid = getRevenuePaidEntries(currentRevenueRecord.ivrsNo).length > 0
                    || !!getRevenueUploadedPaidEntryLocal(currentRevenueRecord.ivrsNo);
                if (alreadyPaid) {
                    const confirmed = await showCustomConfirmBox("Please Confirm", "Consumer paid दिख रहा है, Line Disconnection confirm करें?");
                    if (!confirmed) {
                        if (tdCheck) tdCheck.checked = false;
                        return;
                    }
                }
                if (paidCheck) paidCheck.checked = false;
                hideRevenuePaymentBox();
                showRevenueTdBox();
            }
        }

