        function renderStaffAdminAccount(account) {
            const result = document.getElementById("staff-admin-result");
            const actions = document.getElementById("staff-admin-actions");
            if (!result || !actions || !account) return;
            result.innerHTML = `
                <div style="text-align:center; color:#1d4ed8; font-size:0.86rem; font-weight:950; margin-bottom:6px;">${escapeHtml(account.staff_name || "STAFF")}</div>
                <div><strong>Mobile:</strong> ${escapeHtml(account.mobile_no || "-")}</div>
                <div><strong>Staff ID:</strong> ${escapeHtml(account.staff_id || "-")}</div>
                <div><strong>DC:</strong> ${escapeHtml(account.dc_name || "-")}</div>
                <div><strong>HQ:</strong> ${escapeHtml(account.hq_name || "-")}</div>
                <div><strong>Role:</strong> ${escapeHtml(account.role || "-")}</div>
                <div><strong>Status:</strong> ${escapeHtml(account.status || "-")}</div>
                <div><strong>Device:</strong> ${account.device_registered ? "REGISTERED" : "NOT REGISTERED"}</div>
                <div><strong>Failed Attempts:</strong> ${escapeHtml(String(account.failed_attempts || 0))}</div>
                <div><strong>Locked Until:</strong> ${escapeHtml(account.locked_until || "NOT LOCKED")}</div>
            `;
            result.style.display = "block";
            actions.style.display = "block";
        }

        async function searchStaffAdminAccount() {
            if (!staffAdminUnlocked) return showToast("Pehle Admin Password daliye", false);
            const dcName = String(document.getElementById("staff-admin-dc")?.value || "").trim();
            const mobileNo = String(document.getElementById("staff-admin-mobile")?.value || "").replace(/\D/g, "");
            if (!dcName) return showToast("DC select kijiye", false);
            if (!/^[6-9]\d{9}$/.test(mobileNo)) return showToast("Valid 10-digit mobile number daliye", false);
            clearStaffAdminResult();
            const button = document.getElementById("staff-admin-search-btn");
            setActionButtonState(button, "loading", "Searching...");
            try {
                const response = await postRevenueMessageStaffApi({
                    action: "staffAdminSearch",
                    admin_password: staffAdminPassword,
                    dc_name: dcName,
                    mobile_no: mobileNo
                });
                staffAdminCurrentAccount = response.staff || null;
                renderStaffAdminAccount(staffAdminCurrentAccount);
                setStaffAdminStatus("Staff account mil gaya", true);
                setActionButtonState(button, "done", "Search Staff");
            } catch (error) {
                setStaffAdminStatus(escapeHtml(error?.message || "Staff account nahi mila"), false);
                setActionButtonState(button, "failed", "Search Staff");
            } finally {
                setTimeout(() => setActionButtonState(button, "idle", "Search Staff"), 700);
            }
        }

        async function performStaffAdminAction(adminAction) {
            if (!staffAdminUnlocked || !staffAdminCurrentAccount) return showToast("Pehle staff search kijiye", false);
            const labels = {
                RESET_DEVICE: "is staff ka registered device reset",
                RESET_PIN: "is staff ka PIN reset",
                UNLOCK_ACCOUNT: "is staff account ko unlock",
                DEACTIVATE_ACCOUNT: "is staff account ko deactivate"
            };
            const approved = await showCustomConfirmBox("Please Confirm", `${labels[adminAction] || "ye action"} karna hai?`);
            if (!approved) return;
            setStaffAdminStatus("Processing...", true);
            try {
                const response = await postRevenueMessageStaffApi({
                    action: "staffAdminAction",
                    admin_password: staffAdminPassword,
                    admin_action: adminAction,
                    dc_name: staffAdminCurrentAccount.dc_name || "",
                    mobile_no: staffAdminCurrentAccount.mobile_no || ""
                });
                staffAdminCurrentAccount = response.staff || staffAdminCurrentAccount;
                renderStaffAdminAccount(staffAdminCurrentAccount);
                const temporaryPassword = response.temporary_password
                    ? `<br><span style="display:inline-block; margin-top:7px; padding:7px 10px; border-radius:10px; background:#fef3c7; color:#92400e; font-size:0.88rem;">Temporary Password: <strong>${escapeHtml(response.temporary_password)}</strong></span><br><span style="font-size:0.68rem;">Staff ko yeh password dein. First login par naya 6-digit PIN banana hoga.</span>`
                    : "";
                setStaffAdminStatus(`${escapeHtml(response.message || "Action successful")}${temporaryPassword}`, true);
                showToast(response.message || "Staff Admin action successful", true);
            } catch (error) {
                setStaffAdminStatus(escapeHtml(error?.message || "Action complete nahi hua"), false);
            }
        }

