        // ===== VR Calculation (Voltage Regulation Calculator) =====
        const vrConductorOptionsByLine = {
            lt: [
                { key: "squirrel_09", label: "Squirrel (0.9 PF)", cc: 1.19 },
                { key: "weasel_09", label: "Weasel (0.9 PF)", cc: 1.94 },
                { key: "rabbit_09", label: "Rabbit (0.9 PF)", cc: 3.00 }
            ],
            "11kv": [
                { key: "weasel_08", label: "Weasel (0.8 PF)", cc: 1020 },
                { key: "rabbit_08", label: "Rabbit (0.8 PF)", cc: 1576 },
                { key: "raccoon_08", label: "Raccoon (0.8 PF)", cc: 2380 },
                { key: "dog_08", label: "Dog (0.8 PF)", cc: 3150 }
            ],
            "33kv": [
                { key: "raccoon_09", label: "Raccoon (0.9 PF)", cc: 19121 },
                { key: "dog_09", label: "Dog (0.9 PF)", cc: 22951 }
            ]
        };
        const vrDfValues = { urban: 1.5, rural: 2.0 };
        const vrLimits = { lt: 6, "11kv": 9, "33kv": 9 };
        const vrLineTypeLabels = { lt: "LT", "11kv": "11 kV", "33kv": "33 kV" };
        const vrDesignationOptions = ["Chief Engineer (Jr)", "Superintending Engineer (O&M)", "Executive Engineer (O&M)", "Assistant Engineer (O&M)", "Junior Engineer"];

        let vrCalcState = {
            initialized: false,
            lineStatus: "EXISTING",
            headerDescription: "",
            lineType: "33kv",
            conductorType: "dog_09",
            dfType: "urban",
            nodes: [],
            seals: [],
            draftSealDesignation: "Assistant Engineer (O&M)",
            draftSealLocation: "",
            showReferenceInfo: false,
            menuOpen: false,
            // Jab user "Saved Feeder Maps" se koi map Load karta hai, tab flow
            // badal jaata hai - manual "+ Add to List" / node-list wala point-by-
            // point banane wala form hide ho jaata hai, aur sirf "Proposed Point
            // Do Existing Points Ke Beech Jodein" wala form dikhta hai (kyoki map
            // pehle se bana hua hai, sirf usme proposed load jodna hai). Naya map
            // fresh banate waqt ya "Edit" se kholne par yeh false rehta hai, taaki
            // pehle jaisa poora manual flow (point add + SLD + calc + seal) dikhe.
            proposedInsertOnly: false
        };

        function vrNextLabel(n) {
            let s = "";
            n = n + 1;
            while (n > 0) {
                const rem = (n - 1) % 26;
                s = String.fromCharCode(65 + rem) + s;
                n = Math.floor((n - 1) / 26);
            }
            return s;
        }

        function vrRoundRect(ctx, x, y, w, h, r) {
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.arcTo(x + w, y, x + w, y + h, r);
            ctx.arcTo(x + w, y + h, x, y + h, r);
            ctx.arcTo(x, y + h, x, y, r);
            ctx.arcTo(x, y, x + w, y, r);
            ctx.closePath();
        }

        function vrWrapText(ctx, text, cx, y, maxWidth, lineHeight) {
            const words = String(text || "").split(" ");
            let line = "";
            let lines = [];
            for (const w of words) {
                const test = line + w + " ";
                if (ctx.measureText(test).width > maxWidth && line !== "") {
                    lines.push(line);
                    line = w + " ";
                } else {
                    line = test;
                }
            }
            lines.push(line);
            const startY = y - ((lines.length - 1) * lineHeight) / 2;
            lines.forEach((l, i) => ctx.fillText(l.trim(), cx, startY + i * lineHeight));
        }

        function vrDrawSLD(nodes) {
            const canvas = document.getElementById("vrSldCanvas");
            if (!canvas) return;
            const ctx = canvas.getContext("2d");

            const cols = 7;
            const canvasW = 1300;
            const numRows = Math.max(1, Math.ceil(nodes.length / cols));
            const boxH = 88, rowGapY = 92;
            const marginX = 20, marginY = 40, bottomLabelSpace = 50;
            const gapX = 40;
            const availW = canvasW - 2 * marginX;
            const boxW = (availW - (cols - 1) * gapX) / cols;
            const canvasH = marginY + numRows * boxH + (numRows - 1) * rowGapY + bottomLabelSpace + 10;

            const RES = 2;
            canvas.width = canvasW * RES;
            canvas.height = canvasH * RES;
            canvas.style.width = "100%";
            canvas.style.height = "auto";
            ctx.setTransform(RES, 0, 0, RES, 0, 0);
            ctx.fillStyle = "#fff";
            ctx.fillRect(0, 0, canvasW, canvasH);

            if (!nodes.length) return;

            const rowStarts = [];
            for (let r = 0; r < numRows; r++) rowStarts.push(marginX);

            const positions = nodes.map((node, i) => {
                const r = Math.floor(i / cols);
                const c = i % cols;
                const x = rowStarts[r] + c * (boxW + gapX);
                const y = marginY + r * (boxH + rowGapY);
                return { x, y };
            });

            nodes.forEach((node, i) => {
                const { x, y } = positions[i];
                const c = i % cols;

                if (c > 0) {
                    const prev = positions[i - 1];
                    const prevRight = prev.x + boxW;
                    const midY = y + boxH / 2;
                    ctx.strokeStyle = "#1e40af";
                    ctx.lineWidth = 2.2;
                    ctx.beginPath();
                    ctx.moveTo(prevRight, midY);
                    ctx.lineTo(x, midY);
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.moveTo(prevRight, midY - 5); ctx.lineTo(prevRight, midY + 5);
                    ctx.moveTo(x, midY - 5); ctx.lineTo(x, midY + 5);
                    ctx.stroke();

                    const midX = prevRight + (x - prevRight) / 2;
                    ctx.textAlign = "center";
                    ctx.fillStyle = "#1e40af";
                    ctx.font = "bold 13px Arial";
                    ctx.fillText(String(node.distance), Math.round(midX), Math.round(midY - 10));
                    ctx.font = "600 11px Arial";
                    ctx.fillStyle = "#64748b";
                    ctx.fillText("KM", Math.round(midX), Math.round(midY + 20));
                } else if (i > 0) {
                    const prev = positions[i - 1];
                    const prevRight = prev.x + boxW;
                    const prevMidY = prev.y + boxH / 2;
                    const curMidY = y + boxH / 2;
                    const gapMidY = prev.y + boxH + 66;
                    ctx.strokeStyle = "#1e40af";
                    ctx.lineWidth = 2.2;
                    ctx.beginPath();
                    ctx.moveTo(prevRight, prevMidY);
                    ctx.lineTo(prevRight, gapMidY);
                    ctx.lineTo(x - 14, gapMidY);
                    ctx.lineTo(x - 14, curMidY);
                    ctx.lineTo(x, curMidY);
                    ctx.stroke();

                    ctx.beginPath();
                    ctx.moveTo(x - 8, curMidY - 5);
                    ctx.lineTo(x, curMidY);
                    ctx.lineTo(x - 8, curMidY + 5);
                    ctx.stroke();

                    ctx.textAlign = "center";
                    ctx.fillStyle = "#1e40af";
                    ctx.font = "bold 11px Arial";
                    ctx.fillText(node.distance + " KM", (prevRight + x - 14) / 2, gapMidY - 6);
                }

                const proposedNode = !!node.isProposed;
                const nodeColor = proposedNode ? "#ea580c" : "#1e40af";

                ctx.save();
                ctx.shadowColor = proposedNode ? "rgba(234,88,12,0.2)" : "rgba(30,64,175,0.15)";
                ctx.shadowBlur = 7;
                ctx.shadowOffsetY = 2;
                ctx.fillStyle = proposedNode ? "#fff7ed" : "#fff";
                vrRoundRect(ctx, x, y, boxW, boxH, 7);
                ctx.fill();
                ctx.restore();

                ctx.strokeStyle = nodeColor;
                ctx.lineWidth = proposedNode ? 2.4 : 1.8;
                vrRoundRect(ctx, x, y, boxW, boxH, 7);
                ctx.stroke();

                if (proposedNode) {
                    ctx.fillStyle = "#ea580c";
                    ctx.font = "bold 9px Arial";
                    ctx.textAlign = "center";
                    ctx.fillText("PROPOSED", x + boxW / 2, y - 6);
                }

                ctx.fillStyle = "#111";
                ctx.font = "600 12px Arial";
                ctx.textAlign = "center";
                vrWrapText(ctx, node.name, x + boxW / 2, y + boxH / 2 - 8, boxW - 16, 14);

                ctx.beginPath();
                ctx.strokeStyle = "#e5e7eb";
                ctx.lineWidth = 1;
                ctx.moveTo(x + 12, y + boxH - 24);
                ctx.lineTo(x + boxW - 12, y + boxH - 24);
                ctx.stroke();

                ctx.font = "600 11px Arial";
                ctx.fillStyle = nodeColor;
                ctx.fillText(node.kva + " KVA", x + boxW / 2, y + boxH - 8);

                ctx.font = "bold 12px Arial";
                ctx.fillStyle = nodeColor;
                ctx.fillText("(" + node.label + ")", x + boxW / 2, y + boxH + 20);

                if (proposedNode && node.proposedNote) {
                    ctx.font = "9px Arial";
                    ctx.fillStyle = "#9a3412";
                    vrWrapText(ctx, '"' + node.proposedNote + '"', x + boxW / 2, y + boxH + 36, boxW - 10, 11);
                }
            });
            ctx.textAlign = "left";
        }

        function vrDrawFlatSLD(nodes) {
            const canvas = document.getElementById("vrFlatSldCanvas");
            if (!canvas) return;
            const ctx = canvas.getContext("2d");
            if (!nodes.length) {
                canvas.width = 1300; canvas.height = 130;
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                return;
            }

            const subBoxW = 120, subBoxH = 54, tickGap = 88, marginX = 20, gapAfterSub = 40;
            const hasProposed = nodes.some((n) => n.isProposed);
            const lineY = 62;
            const canvasW = marginX * 2 + subBoxW + gapAfterSub + Math.max(0, nodes.length - 1) * tickGap + 60;
            const canvasH = lineY + (hasProposed ? 110 : 45);

            const RES = 2;
            canvas.width = canvasW * RES;
            canvas.height = canvasH * RES;
            canvas.style.width = canvasW + "px";
            canvas.style.height = "auto";
            ctx.setTransform(RES, 0, 0, RES, 0, 0);
            ctx.fillStyle = "#fff";
            ctx.fillRect(0, 0, canvasW, canvasH);

            const subX = marginX, subY = lineY - subBoxH / 2;
            ctx.save();
            ctx.shadowColor = "rgba(30,64,175,0.15)";
            ctx.shadowBlur = 6;
            ctx.fillStyle = "#fff";
            vrRoundRect(ctx, subX, subY, subBoxW, subBoxH, 6);
            ctx.fill();
            ctx.restore();
            ctx.strokeStyle = "#1e40af";
            ctx.lineWidth = 1.8;
            vrRoundRect(ctx, subX, subY, subBoxW, subBoxH, 6);
            ctx.stroke();
            ctx.fillStyle = "#111";
            ctx.font = "600 11px Arial";
            ctx.textAlign = "center";
            vrWrapText(ctx, nodes[0].name, subX + subBoxW / 2, subY + subBoxH / 2, subBoxW - 16, 13);

            const lineStartX = subX + subBoxW;
            const lastTickX = lineStartX + gapAfterSub + Math.max(0, nodes.length - 2) * tickGap;
            ctx.strokeStyle = "#1e40af";
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(lineStartX, lineY);
            ctx.lineTo(nodes.length > 1 ? lastTickX : lineStartX + 20, lineY);
            ctx.stroke();

            for (let i = 1; i < nodes.length; i++) {
                const node = nodes[i];
                const tickX = lineStartX + gapAfterSub + (i - 1) * tickGap;
                const proposed = !!node.isProposed;
                ctx.strokeStyle = proposed ? "#ea580c" : "#1e40af";
                ctx.lineWidth = proposed ? 2.6 : 2;
                ctx.beginPath();
                ctx.moveTo(tickX, lineY - 9);
                ctx.lineTo(tickX, lineY + 9);
                ctx.stroke();

                ctx.textAlign = "center";
                ctx.fillStyle = proposed ? "#ea580c" : "#1e40af";
                ctx.font = "bold 13px Arial";
                ctx.fillText(node.label, Math.round(tickX), Math.round(lineY - 42));
                ctx.font = "600 11px Arial";
                ctx.fillStyle = "#555";
                ctx.fillText(node.distance + " KM", Math.round(tickX), Math.round(lineY - 20));

                ctx.font = "600 11px Arial";
                ctx.fillStyle = proposed ? "#ea580c" : "#1e40af";
                ctx.fillText(node.kva + " KVA", Math.round(tickX), Math.round(lineY + 26));

                if (proposed) {
                    const calloutY = lineY + 46;
                    ctx.strokeStyle = "#ea580c";
                    ctx.setLineDash([3, 3]);
                    ctx.lineWidth = 1.5;
                    ctx.beginPath();
                    ctx.moveTo(tickX, lineY + 34);
                    ctx.lineTo(tickX, calloutY);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    const boxW = 200, boxH = 54;
                    const boxX = Math.max(4, tickX - boxW / 2);
                    ctx.strokeStyle = "#ea580c";
                    ctx.lineWidth = 1.4;
                    ctx.strokeRect(boxX, calloutY, boxW, boxH);
                    ctx.fillStyle = "#7c2d12";
                    ctx.font = "600 10px Arial";
                    const label = 'INCLUDING PROPOSED LOAD OF "' + (node.proposedNote || node.name) + '" (' + node.kva + " KVA)";
                    vrWrapText(ctx, label, boxX + boxW / 2, calloutY + boxH / 2, boxW - 12, 12);
                }
            }
            ctx.textAlign = "left";
        }

        function vrComputeCalc() {
            const { lineStatus, lineType, conductorType, dfType, nodes } = vrCalcState;
            const conductorOptions = vrConductorOptionsByLine[lineType] || vrConductorOptionsByLine["33kv"];
            const conductorObj = conductorOptions.find((c) => c.key === conductorType) || conductorOptions[0];
            const cc = conductorObj.cc;
            const isHT = lineType === "11kv" || lineType === "33kv";
            const df = isHT ? 1.0 : (vrDfValues[dfType] || 1.5);
            const dfNote = isHT ? "HT Connection — DF fixed at 1.0" : (dfType === "urban" ? "Urban area — DF = 1.5" : "Rural area — DF = 2.0");

            const sectionRows = [];
            let totalKvaKm = 0;
            for (let i = 0; i < nodes.length - 1; i++) {
                const length = nodes[i + 1].distance;
                let downstreamKva = 0;
                for (let j = i + 1; j < nodes.length; j++) downstreamKva += nodes[j].kva;
                const kvakm = length * downstreamKva;
                const vr = (cc * df) > 0 ? kvakm / (cc * df) : 0;
                totalKvaKm += kvakm;
                sectionRows.push({
                    no: i + 1,
                    label: nodes[i].label + "-" + nodes[i + 1].label,
                    length: length,
                    kva: downstreamKva,
                    df: df.toFixed(1),
                    cc: cc,
                    kvakm: kvakm.toFixed(0),
                    vr: vr.toFixed(2)
                });
            }

            const totalVr = (cc * df) > 0 ? (totalKvaKm / (cc * df)) : 0;
            const limit = vrLimits[lineType] || 6;
            const exceedsLimit = totalVr > limit;
            const totalRowLabel = nodes.length > 0 ? ("TOTAL (" + nodes[0].label + "-" + nodes[nodes.length - 1].label + ")") : "TOTAL";
            const sectionCombosCaption = sectionRows.map((r) => "(" + r.label + ")").join("") +
                (nodes.length > 2 ? "(" + nodes[0].label + "-" + nodes[nodes.length - 1].label + ")" : "");
            const reportTitleLine1 = lineStatus + " " + (vrLineTypeLabels[lineType] || "33 kV") + " FEEDER";

            return { conductorOptions, conductorObj, cc, isHT, df, dfNote, sectionRows, totalKvaKm, totalVr, limit, exceedsLimit, totalRowLabel, sectionCombosCaption, reportTitleLine1 };
        }

        function vrRenderNodeList() {
            const container = document.getElementById("vr-node-list");
            if (!container) return;
            const nodes = vrCalcState.nodes;
            const isProposedStatus = vrCalcState.lineStatus === "PROPOSED";

            // Saved map "Load" karne ke baad manual point-add flow (heading +
            // "+ Add to List" form + node-list) chhupa dete hain - sirf neeche
            // wala "Insert Proposed Point" form dikhta hai. Fresh map banate
            // waqt ya "Edit" se khole gaye map me yeh sab pehle jaisa dikhta hai.
            const manualHeading = document.getElementById("vr-manual-points-heading");
            const draftForm = document.getElementById("vr-draft-form");
            const showManualFlow = !vrCalcState.proposedInsertOnly;
            if (manualHeading) manualHeading.style.display = showManualFlow ? "" : "none";
            if (draftForm) draftForm.style.display = showManualFlow ? "" : "none";
            container.style.display = showManualFlow ? "" : "none";
            // Points daalte hi (fresh map banate waqt) yahin niche "Save Current as
            // Map" ka option dikhta hai - ab three-dots menu tak jaane ki zaroorat
            // nahi. Agar koi saved map "Edit" mode me khula hai, to iski jagah
            // "Update Map / Cancel" banner dikhta hai. Load karke proposed-insert
            // mode me dono hide rehte hain.
            const inlineSaveWrap = document.getElementById("vr-inline-save-wrap");
            const editBanner = document.getElementById("vr-map-edit-banner");
            const isEditingMap = !!vrEditingMapId;
            // "Save Current as Map" sirf Existing status me hi dikhta hai - Saved
            // Feeder Maps hamesha Existing SLD ke liye hi bante hain, New/Proposed
            // me purana flow (three-dot menu / seedha calculate-download) use hoga.
            const isExistingStatus = vrCalcState.lineStatus === "EXISTING";
            if (inlineSaveWrap) inlineSaveWrap.style.display = (showManualFlow && isExistingStatus && nodes.length > 0 && !isEditingMap) ? "block" : "none";
            if (editBanner) editBanner.style.display = (showManualFlow && isEditingMap) ? "flex" : "none";
            if (!showManualFlow) {
                vrRenderInsertProposedForm();
                return;
            }

            const nameLabelEl = document.getElementById("vr-draft-name-label");
            const kvaWrap = document.getElementById("vr-draft-kva-wrap");
            const distWrap = document.getElementById("vr-draft-dist-wrap");
            if (nameLabelEl) nameLabelEl.innerText = nodes.length > 0 ? "Point Name" : "First Point Name";
            if (kvaWrap) kvaWrap.style.display = nodes.length > 0 ? "flex" : "none";
            if (distWrap) distWrap.style.display = nodes.length > 0 ? "flex" : "none";

            if (!nodes.length) {
                container.innerHTML = '<div style="text-align:center; padding:20px; color:#888; font-size:13px;">No points added yet — add the first point using the form above.</div>';
                return;
            }

            const gridCols = isProposedStatus ? "34px 1fr 1fr 60px 34px" : "34px 1fr 1fr 34px";

            let html = `<div class="vr-calc-node-thead" style="grid-template-columns:${gridCols};">`;
            html += `<span></span><span>KVA</span><span>KM</span>`;
            if (isProposedStatus) html += `<span>Proposed</span>`;
            html += `<span></span></div>`;

            html += nodes.map((node, i) => {
                const showDistance = i > 0;
                let row = `<div class="vr-calc-node-trow" style="grid-template-columns:${gridCols};">`;
                row += `<span class="vr-calc-node-label" title="${escapeHtml(node.name)}">${escapeHtml(node.label)}</span>`;
                if (showDistance) {
                    row += `<input type="number" value="${node.kva}" data-index="${i}" data-field="kva" onchange="vrHandleNodeChange(this)">`;
                    row += `<input type="number" step="0.1" value="${node.distance}" data-index="${i}" data-field="distance" onchange="vrHandleNodeChange(this)">`;
                } else {
                    row += `<span class="vr-calc-node-dash">—</span><span class="vr-calc-node-dash">—</span>`;
                }
                if (isProposedStatus) {
                    row += `<input type="checkbox" ${node.isProposed ? "checked" : ""} data-index="${i}" data-field="isProposed" onchange="vrHandleNodeChange(this)" style="width:18px; height:18px; justify-self:center;">`;
                }
                row += `<button class="vr-calc-remove-btn" onclick="vrRemoveNode(${i})" title="Remove">✕</button>`;
                row += `</div>`;
                if (node.isProposed) {
                    row += `<div class="vr-calc-node-note-row"><input type="text" placeholder="Proposed description e.g. Rice Mill" value="${escapeHtml(node.proposedNote || "")}" data-index="${i}" data-field="proposedNote" onchange="vrHandleNodeChange(this)"></div>`;
                }
                return row;
            }).join("");

            container.innerHTML = html;
            vrRenderInsertProposedForm();
        }

        // =====================================================================
        // SAVED FEEDER MAPS (Existing SLD reuse) - ek baar existing feeder ka
        // poora point-chain bana kar save kar lena hai, taaki future me naya
        // connection aane par sirf woh map load karke, do existing points ke
        // beech proposed load jodkar seedhe VR nikal saken - sabhi points
        // dobara manually na daalne padein. Abhi sirf is device/browser tak
        // (localStorage) limited hai, DC-wise alag rehta hai.
        // =====================================================================
        const vrSavedMapsStorageKey = "vr_saved_feeder_maps_v1";

        function vrGetAllSavedMaps() {
            try {
                return JSON.parse(localStorage.getItem(vrSavedMapsStorageKey) || "[]") || [];
            } catch (_) {
                return [];
            }
        }

        function vrSaveAllSavedMaps(maps) {
            try {
                localStorage.setItem(vrSavedMapsStorageKey, JSON.stringify(maps));
            } catch (_) {}
        }

        function vrGetSavedMapsForDc() {
            const dcKey = normalizeLookupValue(activeDC || "");
            return vrGetAllSavedMaps().filter((m) => normalizeLookupValue(m.dcName || "") === dcKey);
        }

        function vrSaveCurrentAsMap(nameInputId) {
            const nameEl = document.getElementById(nameInputId || "vr-map-save-name");
            const name = (nameEl?.value || "").trim();
            if (!name) { showToast("Map ka naam dijiye", false); return; }
            if (!vrCalcState.nodes.length) { showToast("Pehle points add karein", false); return; }
            const maps = vrGetAllSavedMaps();
            const newMap = {
                id: `vrmap_${Date.now()}`,
                dcName: activeDC || "",
                name,
                lineType: vrCalcState.lineType,
                conductorType: vrCalcState.conductorType,
                dfType: vrCalcState.dfType,
                headerDescription: vrCalcState.headerDescription,
                // Saved map hamesha "clean existing" state me rakhte hain - koi bhi
                // is session me flag kiya hua proposed point save nahi hota, taaki
                // agli baar load karne par sirf asli existing chain mile.
                nodes: JSON.parse(JSON.stringify(vrCalcState.nodes.map((n) => ({ ...n, isProposed: false, proposedNote: "" })))),
                savedAt: Date.now()
            };
            maps.push(newMap);
            vrSaveAllSavedMaps(maps);
            if (nameEl) nameEl.value = "";
            vrRenderSavedMapsList();
            showToast(`"${name}" map save ho gaya`, true);
        }

        function vrLoadSavedMap(id) {
            const map = vrGetAllSavedMaps().find((m) => m.id === id);
            if (!map) { showToast("Map nahi mila", false); return; }
            vrEditingMapId = null;
            vrCalcState.proposedInsertOnly = true;
            vrCalcState.lineType = map.lineType || vrCalcState.lineType;
            vrCalcState.conductorType = map.conductorType || vrCalcState.conductorType;
            vrCalcState.dfType = map.dfType || vrCalcState.dfType;
            vrCalcState.headerDescription = map.headerDescription || vrCalcState.headerDescription;
            vrCalcState.nodes = JSON.parse(JSON.stringify(map.nodes || []));
            vrCalcState.lineStatus = "PROPOSED";
            const statusSel = document.getElementById("vr-line-status");
            if (statusSel) statusSel.value = "PROPOSED";
            const typeSel = document.getElementById("vr-line-type");
            if (typeSel) typeSel.value = vrCalcState.lineType;
            const headerEl = document.getElementById("vr-header-desc");
            if (headerEl) headerEl.value = vrCalcState.headerDescription;
            vrToggleSavedMapsModal(false);
            vrRenderNodeList();
            vrRenderCalc();
            vrRenderSavedMapsList();
            showToast(`"${map.name}" map open ho gaya - ab proposed point jodein`, true);
        }

        // Ek baar map ban jaane ke baad usko delete karne ka option jaan-boojh
        // kar nahi diya gaya hai (map hamesha list me dikhega, taaki koi galti
        // se apna poora existing feeder SLD kho na de). Agar us map me sudhaar
        // karna ho (points ghatana/badhana/naam-load-distance badalna) to "Edit"
        // button se use edit-mode me kholiye - neeche wahi node-list (jo Insert
        // Proposed wale form ke upar hai) editable ban jaati hai, jahan har point
        // ke saamne wale ✕ se use hataya ja sakta hai (jaise 50 points me se 45
        // hatakar sirf 5 rakhne hain), naye point jode ja sakte hain, ya kisi bhi
        // point ka naam/load/distance seedhe badla ja sakta hai. Changes karne ke
        // baad "Update Map" dabane par wahi saved map (same id/naam) overwrite ho
        // jaata hai - koi naya duplicate map nahi banta.
        let vrEditingMapId = null;

        function vrEditSavedMap(id) {
            const map = vrGetAllSavedMaps().find((m) => m.id === id);
            if (!map) { showToast("Map nahi mila", false); return; }
            vrEditingMapId = id;
            vrCalcState.proposedInsertOnly = false;
            vrCalcState.lineType = map.lineType || vrCalcState.lineType;
            vrCalcState.conductorType = map.conductorType || vrCalcState.conductorType;
            vrCalcState.dfType = map.dfType || vrCalcState.dfType;
            vrCalcState.headerDescription = map.headerDescription || vrCalcState.headerDescription;
            vrCalcState.nodes = JSON.parse(JSON.stringify(map.nodes || []));
            vrCalcState.lineStatus = "EXISTING";
            const statusSel = document.getElementById("vr-line-status");
            if (statusSel) statusSel.value = "EXISTING";
            const typeSel = document.getElementById("vr-line-type");
            if (typeSel) typeSel.value = vrCalcState.lineType;
            const headerEl = document.getElementById("vr-header-desc");
            if (headerEl) headerEl.value = vrCalcState.headerDescription;
            vrToggleSavedMapsModal(false);
            vrRenderNodeList();
            vrRenderCalc();
            vrRenderSavedMapsList();
            showToast(`"${map.name}" edit mode me khul gaya - upar points add/remove/edit karke "Update Map" dabayein`, true);
        }

        function vrUpdateEditingMap() {
            if (!vrEditingMapId) return;
            if (!vrCalcState.nodes.length) { showToast("Kam se kam ek point to rehna chahiye", false); return; }
            const maps = vrGetAllSavedMaps();
            const idx = maps.findIndex((m) => m.id === vrEditingMapId);
            if (idx === -1) { showToast("Map nahi mila", false); vrEditingMapId = null; vrRenderSavedMapsList(); return; }
            const mapName = maps[idx].name;
            maps[idx] = {
                ...maps[idx],
                lineType: vrCalcState.lineType,
                conductorType: vrCalcState.conductorType,
                dfType: vrCalcState.dfType,
                headerDescription: vrCalcState.headerDescription,
                nodes: JSON.parse(JSON.stringify(vrCalcState.nodes.map((n) => ({ ...n, isProposed: false, proposedNote: "" })))),
                updatedAt: Date.now()
            };
            vrSaveAllSavedMaps(maps);
            vrEditingMapId = null;
            vrRenderNodeList();
            vrRenderSavedMapsList();
            showToast(`"${mapName}" map update ho gaya`, true);
        }

        function vrCancelEditingMap() {
            vrEditingMapId = null;
            vrRenderNodeList();
            vrRenderSavedMapsList();
        }

        function vrRenderSavedMapsList() {
            const container = document.getElementById("vr-saved-maps-list");
            const banner = document.getElementById("vr-map-edit-banner");
            const bannerNameEl = document.getElementById("vr-map-edit-name");
            if (banner) banner.style.display = vrEditingMapId ? "flex" : "none";
            if (bannerNameEl && vrEditingMapId) {
                const editingMap = vrGetAllSavedMaps().find((m) => m.id === vrEditingMapId);
                bannerNameEl.innerText = editingMap ? editingMap.name : "";
            }
            if (!container) return;
            const maps = vrGetSavedMapsForDc();
            if (!maps.length) {
                container.innerHTML = '<div style="text-align:center; padding:14px; color:#888; font-size:12px;">Is DC ke liye abhi koi saved map nahi hai.</div>';
                return;
            }
            container.innerHTML = maps.map((m) => {
                const isEditing = m.id === vrEditingMapId;
                return `
                <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; padding:10px 12px; border:1.5px solid ${isEditing ? "#2563eb" : "#e2e8f0"}; border-radius:12px; margin-bottom:8px; background:${isEditing ? "#eff6ff" : "#fff"};">
                    <div style="text-align:left;">
                        <div style="font-weight:900; font-size:0.8rem; color:#0f172a;">${escapeHtml(m.name)}${isEditing ? ' <span style="color:#2563eb; font-size:0.65rem;">(EDITING)</span>' : ""}</div>
                        <div style="font-size:0.65rem; color:#64748b; margin-top:2px;">${m.nodes.length} points · ${escapeHtml(vrLineTypeLabels[m.lineType] || m.lineType)} · ${escapeHtml(new Date(m.savedAt).toLocaleDateString("en-IN"))}</div>
                    </div>
                    <div style="display:flex; gap:6px;">
                        <button class="btn vr-btn-primary" style="padding:6px 12px; font-size:0.7rem;" onclick="vrLoadSavedMap('${m.id}')">Open Map</button>
                        <button class="btn" style="padding:6px 12px; font-size:0.7rem; background:#f1f5f9; color:#334155;" onclick="vrEditSavedMap('${m.id}')">Edit</button>
                    </div>
                </div>`;
            }).join("");
        }

        // =====================================================================
        // INSERT PROPOSED POINT BETWEEN TWO EXISTING POINTS - user do existing
        // points chunta hai (jaise Point 45 -> Point 46), naya proposed point ka
        // naam/load/pehle-point-se-distance deta hai. App automatic us segment
        // ki asli distance ko split kar deta hai: pehle point se jo distance di
        // gayi, aur baaki bacha hua doosre (far) point tak reh jaata hai - baaki
        // sabhi points/distances bilkul same rehte hain.
        // =====================================================================
        function vrRenderInsertProposedForm() {
            const wrap = document.getElementById("vr-insert-proposed-wrap");
            const pairSelect = document.getElementById("vr-insert-pair-select");
            if (!wrap || !pairSelect) return;
            const nodes = vrCalcState.nodes;
            if (!vrCalcState.proposedInsertOnly || nodes.length < 2) {
                wrap.style.display = "none";
                return;
            }
            wrap.style.display = "block";
            const currentValue = pairSelect.value;
            const options = nodes.slice(0, -1).map((n, i) => {
                const far = nodes[i + 1];
                return `<option value="${i}">${escapeHtml(n.name)} → ${escapeHtml(far.name)} (${far.distance} KM)</option>`;
            }).join("");
            pairSelect.innerHTML = `<option value="">-- Points select karein --</option>` + options;
            if (currentValue && Number(currentValue) < nodes.length - 1) pairSelect.value = currentValue;
        }

        function vrInsertProposedNode() {
            const pairSelect = document.getElementById("vr-insert-pair-select");
            const nameEl = document.getElementById("vr-insert-name");
            const kvaEl = document.getElementById("vr-insert-kva");
            const distEl = document.getElementById("vr-insert-dist");
            if (!pairSelect || pairSelect.value === "") { showToast("Pehle points ka pair select karein", false); return; }
            const pairIndex = parseInt(pairSelect.value, 10);
            const nodes = vrCalcState.nodes;
            const nearNode = nodes[pairIndex];
            const farNode = nodes[pairIndex + 1];
            if (!nearNode || !farNode) { showToast("Selection valid nahi hai", false); return; }
            const name = (nameEl?.value || "").trim() || "Proposed Point";
            const kva = parseFloat(kvaEl?.value) || 0;
            const distFromNear = parseFloat(distEl?.value) || 0;
            const originalSegmentDistance = farNode.distance;
            if (distFromNear <= 0 || distFromNear >= originalSegmentDistance) {
                showToast(`Distance ${nearNode.name} aur ${farNode.name} ke beech ki ${originalSegmentDistance} KM se kam honi chahiye`, false);
                return;
            }
            const newNode = {
                label: "",
                name,
                kva,
                distance: distFromNear,
                isProposed: true,
                proposedNote: name
            };
            farNode.distance = Number((originalSegmentDistance - distFromNear).toFixed(3));
            nodes.splice(pairIndex + 1, 0, newNode);
            nodes.forEach((n, i) => { n.label = vrNextLabel(i); });
            vrCalcState.lineStatus = "PROPOSED";
            const statusSel = document.getElementById("vr-line-status");
            if (statusSel) statusSel.value = "PROPOSED";
            if (nameEl) nameEl.value = "";
            if (kvaEl) kvaEl.value = "";
            if (distEl) distEl.value = "";
            if (pairSelect) pairSelect.value = "";
            vrRenderNodeList();
            vrRenderCalc();
            showToast(`"${name}" jud gaya - ${nearNode.name} se ${distFromNear} KM, ${farNode.name} tak ab ${farNode.distance} KM`, true);
        }

        function vrRenderSeals() {
            const container = document.getElementById("vr-seal-list");
            if (!container) return;
            const seals = vrCalcState.seals;

            let html = "";
            if (!seals.length) {
                html += '<div style="font-size:12px; color:#888; margin-bottom:10px;">No seal added yet — select designation and location below, then click Add.</div>';
            } else {
                html += seals.map((seal, i) => `
                    <div class="vr-calc-seal-card">
                        <span class="vr-calc-seal-desig">${escapeHtml(seal.designation || "")}</span>
                        <span class="vr-calc-seal-loc">${escapeHtml(seal.location || "")}</span>
                        <button class="vr-calc-seal-remove-sm" onclick="vrRemoveSeal(${i})" title="Remove">✕</button>
                    </div>`).join("");
            }

            const designationOptions = vrDesignationOptions.map((opt) => `<option value="${escapeHtml(opt)}" ${vrCalcState.draftSealDesignation === opt ? "selected" : ""}>${escapeHtml(opt)}</option>`).join("");
            html += `
                <div class="vr-calc-seal-draft-row">
                    <div style="display:flex; flex-direction:column; gap:4px; flex:1 1 200px;">
                        <label style="font-size:10px; font-weight:800; text-transform:uppercase; color:#555;">Designation</label>
                        <select onchange="vrSetDraftSealDesignation(this.value)">${designationOptions}</select>
                    </div>
                    <div style="display:flex; flex-direction:column; gap:4px; flex:1 1 180px;">
                        <label style="font-size:10px; font-weight:800; text-transform:uppercase; color:#555;">Location</label>
                        <input type="text" placeholder="e.g. Narsinghpur" value="${escapeHtml(vrCalcState.draftSealLocation || "")}" onchange="vrSetDraftSealLocation(this.value)">
                    </div>
                    <button class="btn vr-btn-primary" onclick="vrAddSeal()">+ Add Seal</button>
                </div>`;

            container.innerHTML = html;
            vrRenderSealPrintRows();
        }

        function vrRenderSealPrintRows() {
            const seals = vrCalcState.seals;
            const rowsHtml = seals.map((seal) => `
                <div style="text-align:center; font-size:10px; line-height:1.5; flex:0 0 140px; width:140px;">
                    <div style="font-weight:700;">${escapeHtml(seal.designation || "")}</div>
                    <div>M.P.P.K.V.V. CO. LTD.</div>
                    <div>${escapeHtml(seal.location || "")}</div>
                </div>`).join("");
            const print1 = document.getElementById("vr-seal-print-1");
            const print2 = document.getElementById("vr-seal-print-2");
            if (print1) print1.innerHTML = rowsHtml;
            if (print2) print2.innerHTML = rowsHtml;
        }

        function vrRenderCalc() {
            const calc = vrComputeCalc();
            const { lineStatus, headerDescription, lineType, conductorType, nodes } = vrCalcState;

            const conductorSelect = document.getElementById("vr-conductor-type");
            if (conductorSelect) {
                conductorSelect.innerHTML = calc.conductorOptions.map((opt) => `<option value="${opt.key}" ${opt.key === conductorType ? "selected" : ""}>${escapeHtml(opt.label)} (CC ${opt.cc})</option>`).join("");
            }

            const title1 = document.getElementById("vr-report-title-1");
            const title2 = document.getElementById("vr-report-title-2");
            if (title1) title1.innerText = "VOLTAGE REGULATION CALCULATION OF " + calc.reportTitleLine1;
            if (title2) title2.innerText = headerDescription || "";

            const printTitle1a = document.getElementById("vr-print-title-1a");
            const printTitle1b = document.getElementById("vr-print-title-1b");
            const printTitle2a = document.getElementById("vr-print-title-2a");
            const printTitle2b = document.getElementById("vr-print-title-2b");
            if (printTitle1a) printTitle1a.innerText = "SINGLE LINE DIAGRAM – " + calc.reportTitleLine1;
            if (printTitle1b) printTitle1b.innerText = headerDescription || "";
            if (printTitle2a) printTitle2a.innerText = "VOLTAGE REGULATION CALCULATION OF " + calc.reportTitleLine1;
            if (printTitle2b) printTitle2b.innerText = headerDescription || "";

            const rowsBody = document.getElementById("vr-section-rows");
            if (rowsBody) {
                let html = calc.sectionRows.map((row) => `
                    <tr>
                        <td>${row.no}</td>
                        <td class="vr-section-name">${escapeHtml(row.label)}</td>
                        <td>${row.length}</td>
                        <td>${row.kva}</td>
                        <td>${row.df}</td>
                        <td>${row.cc}</td>
                        <td>${row.kvakm}</td>
                        <td>${row.vr}</td>
                    </tr>`).join("");
                html += `<tr class="vr-total-row"><td colspan="6">${escapeHtml(calc.totalRowLabel)}</td><td>${calc.totalKvaKm.toFixed(0)}</td><td>${calc.totalVr.toFixed(2)}</td></tr>`;
                rowsBody.innerHTML = html;
            }

            const dfValueEl = document.getElementById("vr-df-value");
            const dfNoteEl = document.getElementById("vr-df-note");
            if (dfValueEl) dfValueEl.innerText = calc.df.toFixed(1);
            if (dfNoteEl) dfNoteEl.innerText = calc.dfNote;

            const captionEl = document.getElementById("vr-caption");
            if (captionEl) captionEl.innerHTML = `Voltage Regulation as per Section ${escapeHtml(calc.sectionCombosCaption)} — <strong>${escapeHtml(calc.conductorObj.label)}</strong> conductor.`;

            const formulaValuesEl = document.getElementById("vr-formula-values");
            if (formulaValuesEl) formulaValuesEl.innerHTML = `<span class="num">${calc.totalKvaKm.toFixed(0)}</span><span class="den">${calc.cc} × ${calc.df.toFixed(1)}</span>`;

            const finalVrEl = document.getElementById("vr-final-vr");
            if (finalVrEl) finalVrEl.innerText = `% VR = ${calc.totalVr.toFixed(2)}%`;

            const nodesWithFlag = nodes.map((n, i) => ({ ...n, showDistance: i > 0 }));
            vrDrawSLD(nodesWithFlag);
            vrDrawFlatSLD(nodes);
        }

        function vrSetLineStatus(value) {
            const previousStatus = vrCalcState.lineStatus;
            vrCalcState.lineStatus = value;
            if (value !== "PROPOSED") {
                vrCalcState.nodes = vrCalcState.nodes.map((n) => ({ ...n, isProposed: false }));
            }
            // User dropdown se Status (Existing/New/Proposed) badle to poora page
            // reset ho jaata hai - purane status ke points naye status me carry
            // nahi hote (Existing/New/Proposed alag-alag independent maps hote
            // hain). Yeh sirf manual dropdown-change par lagu hota hai - Load/Edit
            // Saved Map flow (vrLoadSavedMap/vrEditSavedMap) seedhe vrCalcState.lineStatus
            // set karte hain (is function ko call nahi karte), isliye woh is reset
            // se prabhavit nahi hote.
            if (value !== previousStatus) {
                vrCalcState.nodes = [];
                vrCalcState.proposedInsertOnly = false;
                vrEditingMapId = null;
                const nameEl = document.getElementById("vr-draft-name");
                const kvaEl = document.getElementById("vr-draft-kva");
                const distEl = document.getElementById("vr-draft-dist");
                if (nameEl) nameEl.value = "";
                if (kvaEl) kvaEl.value = "";
                if (distEl) distEl.value = "";
            }
            vrRenderNodeList();
            vrRenderCalc();
        }

        function vrSetHeaderDescription(value) {
            vrCalcState.headerDescription = value;
            vrRenderCalc();
        }

        function vrSetLineType(value) {
            vrCalcState.lineType = value;
            const opts = vrConductorOptionsByLine[value] || vrConductorOptionsByLine["33kv"];
            vrCalcState.conductorType = opts[0].key;
            vrRenderCalc();
        }

        function vrSetConductorType(value) {
            vrCalcState.conductorType = value;
            vrRenderCalc();
        }

        function vrSetDFType(value) {
            vrCalcState.dfType = value;
            vrRenderCalc();
        }

        function vrAddNodeFromDraft() {
            const nameEl = document.getElementById("vr-draft-name");
            const kvaEl = document.getElementById("vr-draft-kva");
            const distEl = document.getElementById("vr-draft-dist");
            const name = (nameEl && nameEl.value ? nameEl.value.trim() : "") || "New Point";
            const kva = parseFloat(kvaEl && kvaEl.value) || 0;
            const distance = parseFloat(distEl && distEl.value) || 0;
            vrCalcState.nodes.push({
                label: vrNextLabel(vrCalcState.nodes.length),
                name,
                kva,
                distance,
                isProposed: false,
                proposedNote: ""
            });
            if (nameEl) nameEl.value = "";
            if (kvaEl) kvaEl.value = "";
            if (distEl) distEl.value = "";
            vrRenderNodeList();
            vrRenderCalc();
        }

        function vrHandleNodeChange(el) {
            const index = parseInt(el.dataset.index, 10);
            const field = el.dataset.field;
            const node = vrCalcState.nodes[index];
            if (!node) return;
            let value;
            if (field === "name" || field === "proposedNote") value = el.value;
            else if (field === "isProposed") value = el.checked;
            else value = parseFloat(el.value) || 0;
            node[field] = value;
            if (field === "isProposed" && value && !node.proposedNote) node.proposedNote = node.name;
            vrRenderNodeList();
            vrRenderCalc();
        }

        function vrRemoveNode(index) {
            vrCalcState.nodes.splice(index, 1);
            vrCalcState.nodes.forEach((n, i) => { n.label = vrNextLabel(i); });
            vrRenderNodeList();
            vrRenderCalc();
        }

        function vrAddSeal() {
            const designation = vrCalcState.draftSealDesignation || vrDesignationOptions[0];
            const location = vrCalcState.draftSealLocation || "";
            vrCalcState.seals.unshift({ designation, location });
            vrCalcState.draftSealLocation = "";
            vrRenderSeals();
        }

        function vrSetDraftSealDesignation(value) {
            vrCalcState.draftSealDesignation = value;
        }

        function vrSetDraftSealLocation(value) {
            vrCalcState.draftSealLocation = value;
        }

        function vrRemoveSeal(index) {
            vrCalcState.seals.splice(index, 1);
            vrRenderSeals();
        }

        function vrToggleMenu() {
            vrCalcState.menuOpen = !vrCalcState.menuOpen;
            const dd = document.getElementById("vr-menu-dropdown");
            if (dd) dd.style.display = vrCalcState.menuOpen ? "block" : "none";
        }

        function vrToggleSavedMapsModal(show) {
            const modal = document.getElementById("vr-saved-maps-modal");
            if (!modal) return;
            modal.style.display = show ? "flex" : "none";
            if (show) vrRenderSavedMapsList();
        }

        // App ke main header (⋮ menu) se VR Calculation ke teeno options trigger
        // karne wale wrappers - pehle inka apna alag chhota ⋮ button/dropdown
        // VR card ke andar tha, ab baaki features (Mobile No Update, Revenue
        // Collection) jaisa hi shared main header menu use hota hai.
        function openVrSavedMapsMenu() {
            closeHeaderMenu();
            vrToggleSavedMapsModal(true);
        }

        function openVrReferenceInfoMenu() {
            closeHeaderMenu();
            vrShowReferenceInfoModal(true);
        }

        function openVrDownloadLogMenu() {
            closeHeaderMenu();
            openVrDownloadLog();
        }

        // Limits & CC Reference Table ab home screen par inline show/hide nahi
        // hota - alag se dialog (modal) me khulta hai aur cross (✕) button se
        // band hota hai, jaisa Saved Feeder Maps modal me hai.
        function vrShowReferenceInfoModal(show) {
            vrCalcState.showReferenceInfo = !!show;
            const modal = document.getElementById("vr-reference-info-modal");
            if (modal) modal.style.display = show ? "flex" : "none";
        }

        function initVrCalculation() {
            const statusSel = document.getElementById("vr-line-status");
            const typeSel = document.getElementById("vr-line-type");
            const headerEl = document.getElementById("vr-header-desc");
            if (statusSel) statusSel.value = vrCalcState.lineStatus;
            if (typeSel) typeSel.value = vrCalcState.lineType;
            if (headerEl) headerEl.value = vrCalcState.headerDescription;
            vrRenderNodeList();
            vrRenderSeals();
            vrRenderCalc();
            vrRenderSavedMapsList();
        }

        function vrSetDownloadStatus(message, ok) {
            const box = document.getElementById("vr-download-status");
            if (!box) return;
            if (!message) { box.style.display = "none"; return; }
            box.style.display = "block";
            box.style.color = ok ? "#166534" : "#b91c1c";
            box.innerText = message;
        }

        // Fire-and-forget log call - PDF download (window.print()) ko block/delay nahi
        // karta, aur agar script URL abhi set nahi hai ya network fail ho jaye to bhi
        // silently ignore ho jata hai, print flow par koi asar nahi padega.
        function logVrDownload() {
            if (!vrDownloadLogScriptUrl || !activeDC) return;
            try {
                const division = activeDiv || getRevenueDivisionNameForDc(activeDC);
                const p = new URLSearchParams();
                p.append("division", division || "");
                p.append("dc", activeDC || "");
                p.append("date", getCurrentDateDDMMYYYY());
                p.append("timestamp", `${getCurrentDateDDMMYYYY()} ${getCurrentTimeHHMM()}`);
                fetch(vrDownloadLogScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                    body: p.toString()
                }).catch(() => {});
            } catch (_) {}
        }

        function vrDownloadPDF() {
            logVrDownload();
            window.print();
        }

        // =====================================================================
        // VR Calculation - Download Log Report (Division/DC/Date wise count)
        // vrDownloadLogScriptUrl se raw logged rows fetch karke yahan group/count
        // karte hain - koi naya per-consumer data nahi, sirf ek chhota aggregation.
        // =====================================================================
        let vrDownloadLogMode = "ALL";
        let vrDownloadLogRawRows = [];
        let vrDownloadLogRenderToken = 0;
        // Same "ek baar is visit me load ho jaaye to ALL/DATE toggle sirf local
        // recompute kare" fix jo Revenue reports me kiya - yahan poora data hamesha
        // ek hi getSummary call se aata hai (division/date sirf local filter hain),
        // isliye is baar ye sirf ek boolean flag hai.
        let vrDownloadLogLoaded = false;

        function openVrDownloadLog() {
            const dd = document.getElementById("vr-menu-dropdown");
            if (dd) dd.style.display = "none";
            switchView("vr-download-log");
        }

        function initVrDownloadLog() {
            vrDownloadLogLoaded = false;
            const dateInput = document.getElementById("vr-download-log-date");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            setVrDownloadLogMode(vrDownloadLogMode || "ALL");
        }

        function setVrDownloadLogMode(mode) {
            vrDownloadLogMode = mode === "DATE" ? "DATE" : "ALL";
            const dateInput = document.getElementById("vr-download-log-date");
            const allBtn = document.getElementById("vr-download-log-all-mode-btn");
            const dateBtn = document.getElementById("vr-download-log-date-mode-btn");
            if (dateInput) dateInput.style.display = vrDownloadLogMode === "DATE" ? "block" : "none";
            if (allBtn) {
                allBtn.style.background = vrDownloadLogMode === "ALL" ? "#1d4ed8" : "#dbeafe";
                allBtn.style.color = vrDownloadLogMode === "ALL" ? "#ffffff" : "#1d4ed8";
            }
            if (dateBtn) {
                dateBtn.style.background = vrDownloadLogMode === "DATE" ? "#1d4ed8" : "#dbeafe";
                dateBtn.style.color = vrDownloadLogMode === "DATE" ? "#ffffff" : "#1d4ed8";
            }
            renderVrDownloadLog();
        }

        function buildVrDownloadLogGroupedRows() {
            const divisionValue = document.getElementById("vr-download-log-division")?.value || "";
            const dateValue = document.getElementById("vr-download-log-date")?.value || "";
            // Sheet me date "DD-MM-YYYY" (Indian) format me store hoti hai; purani/test
            // entries agar "YYYY-MM-DD" format me hain to normalizeRevenueReportDate()
            // dono ko wahi ek consistent "DD-MM-YYYY" me le aata hai.
            const normalizedFilterDate = dateValue ? normalizeRevenueReportDate(dateValue) : "";
            const sortKeyOf = (ddmmyyyy) => {
                const match = String(ddmmyyyy || "").match(/^(\d{2})-(\d{2})-(\d{4})$/);
                return match ? `${match[3]}${match[2]}${match[1]}` : "00000000";
            };
            const groups = {};
            vrDownloadLogRawRows.forEach((row) => {
                const division = String(row["Division"] || "").trim().toUpperCase() || "-";
                const dc = String(row["DC"] || "").trim().toUpperCase() || "-";
                const date = normalizeRevenueReportDate(String(row["Date"] || "").trim()) || "-";
                if (divisionValue && division !== divisionValue) return;
                if (vrDownloadLogMode === "DATE" && normalizedFilterDate && date !== normalizedFilterDate) return;
                const key = `${division}||${dc}||${date}`;
                if (!groups[key]) groups[key] = { division, dc, date, count: 0 };
                groups[key].count++;
            });
            return Object.values(groups).sort((a, b) => (
                sortKeyOf(b.date).localeCompare(sortKeyOf(a.date)) || a.division.localeCompare(b.division) || a.dc.localeCompare(b.dc)
            ));
        }

        async function renderVrDownloadLog() {
            const statusBox = document.getElementById("vr-download-log-status");
            const tableBox = document.getElementById("vr-download-log-table");
            if (!statusBox || !tableBox) return;
            if (!vrDownloadLogScriptUrl) {
                statusBox.innerHTML = "Yeh report abhi live nahi hai - Google Sheet ke saath Apps Script deploy hone ke baad hi data aayega.";
                tableBox.innerHTML = "";
                return;
            }
            const renderToken = ++vrDownloadLogRenderToken;
            const isRenderValid = () => renderToken === vrDownloadLogRenderToken && document.getElementById("vr-download-log-view")?.classList.contains("active");
            if (vrDownloadLogLoaded) {
                const rows = buildVrDownloadLogGroupedRows();
                const totalDownloads = rows.reduce((sum, row) => sum + row.count, 0);
                statusBox.innerHTML = `Total Download: <strong>${totalDownloads}</strong> | Groups: ${rows.length}`;
                if (!rows.length) {
                    tableBox.innerHTML = `<div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.8rem; font-weight:900; text-align:center; margin-top:10px;">Is filter me koi download record nahi mila.</div>`;
                    return;
                }
                let cachedHtml = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.3fr 1.1fr 0.9fr 0.7fr;"><div>DIVISION</div><div>DC</div><div>DATE</div><div>COUNT</div></div>`;
                rows.forEach((row) => {
                    cachedHtml += `<div class="summary-table-row" style="grid-template-columns: 1.3fr 1.1fr 0.9fr 0.7fr;"><div>${escapeHtml(row.division)}</div><div>${escapeHtml(row.dc)}</div><div>${escapeHtml(row.date)}</div><div class="font-black">${row.count}</div></div>`;
                });
                cachedHtml += `</div>`;
                tableBox.innerHTML = cachedHtml;
                return;
            }
            const progress = renderSyncingProgress(tableBox, isRenderValid, "SYNCING DATA... PLEASE WAIT");
            try {
                const data = await loadRemoteJson(`${vrDownloadLogScriptUrl}?action=getSummary&t=${Date.now()}`);
                if (!isRenderValid()) { progress.stop(); return; }
                vrDownloadLogRawRows = Array.isArray(data) ? data : [];
                vrDownloadLogLoaded = true;
                await progress.finish();
                if (!isRenderValid()) return;
                const rows = buildVrDownloadLogGroupedRows();
                const totalDownloads = rows.reduce((sum, row) => sum + row.count, 0);
                statusBox.innerHTML = `Total Download: <strong>${totalDownloads}</strong> | Groups: ${rows.length}`;
                if (!rows.length) {
                    tableBox.innerHTML = `<div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.8rem; font-weight:900; text-align:center; margin-top:10px;">Is filter me koi download record nahi mila.</div>`;
                    return;
                }
                let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.3fr 1.1fr 0.9fr 0.7fr;"><div>DIVISION</div><div>DC</div><div>DATE</div><div>COUNT</div></div>`;
                rows.forEach((row) => {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1.3fr 1.1fr 0.9fr 0.7fr;"><div>${escapeHtml(row.division)}</div><div>${escapeHtml(row.dc)}</div><div>${escapeHtml(row.date)}</div><div class="font-black">${row.count}</div></div>`;
                });
                html += `</div>`;
                tableBox.innerHTML = html;
            } catch (error) {
                progress.stop();
                statusBox.innerHTML = "Report load nahi ho payi";
            }
        }

        function setVrDownloadLogDownloadState(isLoading, message = "", ok = true) {
            const pdfBtn = document.getElementById("vr-download-log-pdf-btn");
            const excelBtn = document.getElementById("vr-download-log-excel-btn");
            const statusBox = document.getElementById("vr-download-log-download-status");
            const statusMessage = normalizeActionStatusMessage(message, isLoading, ok);
            [pdfBtn, excelBtn].forEach((btn) => {
                if (!btn) return;
                btn.disabled = isLoading;
                btn.style.opacity = isLoading ? "0.65" : "1";
                btn.style.pointerEvents = isLoading ? "none" : "auto";
            });
            if (!statusBox) return;
            statusBox.style.display = statusMessage ? "block" : "none";
            statusBox.style.background = ok ? "#ecfdf5" : "#fff1f2";
            statusBox.style.borderColor = ok ? "#86efac" : "#fda4af";
            statusBox.style.color = ok ? "#166534" : "#991b1b";
            statusBox.innerHTML = (isLoading ? `<span class="btn-inline-spinner" style="border-color: rgba(22,101,52,0.35); border-top-color: #166534; vertical-align: -1px;"></span>` : "") + escapeHtml(statusMessage);
        }

        function downloadVrDownloadLog(type) {
            const rows = buildVrDownloadLogGroupedRows();
            if (!rows.length) return showToast("Download ke liye data nahi hai", false);
            setVrDownloadLogDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download ho raha hai... kripya wait kijiye`, true);
            try {
                const headers = ["DIVISION", "DC", "DATE", "NO OF DOWNLOADED REPORT"];
                const bodyRows = rows.map((row) => [row.division, row.dc, row.date, row.count]);
                const totalDownloads = rows.reduce((sum, row) => sum + row.count, 0);
                const reportTitle = "VR Calculation - Download Log Report";
                const divisionValue = document.getElementById("vr-download-log-division")?.value || "All Divisions";
                const dateValue = vrDownloadLogMode === "DATE" ? formatRevenueDateIndian(normalizeRevenueReportDate(document.getElementById("vr-download-log-date")?.value || getCurrentDateDDMMYYYY())) : "All Time";
                const scopeLine = `Division: ${divisionValue}  |  Period: ${dateValue}  |  Total Download: ${totalDownloads}`;
                const suffix = vrDownloadLogMode === "DATE" ? (document.getElementById("vr-download-log-date")?.value || getTodayIsoDate()) : "ALL-TIME";
                const fileName = `VR-Download-Log-${suffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setVrDownloadLogDownloadState(false, "PDF library load nahi hui", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(scopeLine, 148, 22, { align: "center" });
                    doc.autoTable({ startY: 28, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 7, cellPadding: 1.5, overflow: "linebreak" }, headStyles: { fillColor: [29, 78, 216] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setVrDownloadLogDownloadState(false, "PDF download ho chuki hai", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[reportTitle], [scopeLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setVrDownloadLogDownloadState(false, "Excel download ho chuki hai", true);
            } catch (error) {
                setVrDownloadLogDownloadState(false, "Download nahi ho paya", false);
                showToast(error?.message || "Report download nahi ho payi", false);
            }
        }

        function vrDownloadExcel() {
            try {
                const calc = vrComputeCalc();
                const { headerDescription, lineStatus, lineType, nodes } = vrCalcState;
                const csvSafe = (value) => {
                    const text = String(value ?? "");
                    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
                };
                const rows = [];
                rows.push(["VOLTAGE REGULATION CALCULATION - " + lineStatus + " " + (vrLineTypeLabels[lineType] || "") + " LINE"]);
                rows.push([headerDescription || ""]);
                rows.push([]);
                rows.push(["S.No", "Section", "Length in Km", "KVA", "DF", "Conductor Constant", "KVA x Km", "VR (%)"]);
                calc.sectionRows.forEach((row) => {
                    rows.push([row.no, row.label, row.length, row.kva, row.df, row.cc, row.kvakm, row.vr]);
                });
                rows.push(["", calc.totalRowLabel, "", "", "", "", calc.totalKvaKm.toFixed(0), calc.totalVr.toFixed(2)]);
                rows.push([]);
                rows.push(["Conductor", calc.conductorObj.label]);
                rows.push(["Diversity Factor (DF)", calc.df.toFixed(1)]);
                rows.push(["% VR", calc.totalVr.toFixed(2) + "%"]);

                const csv = rows.map((r) => r.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" }));
                link.download = `Voltage_Regulation_${lineType.toUpperCase()}.csv`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                showToast("Excel download ho gaya", true);
                vrSetDownloadStatus("Excel download ho gaya", true);
            } catch (err) {
                showToast(err?.message || "Excel download nahi ho paya", false);
                vrSetDownloadStatus("Excel download nahi ho paya", false);
            }
        }

        // ===================================================================
        // Meeter Cheking (SEONI (T) DC only, added 2026-09-10)
        // Consumer/staff data ek DEDICATED sheet se aata hai (Revenue ke consumer
        // master se alag) - meterCheckingConfig me har DC ka apna consumerCsvUrl/
        // staffCsvUrl hai. Submit backend ek naya standalone script
        // (meter-checking-submit-script.gs) hai, jo revenue-submit-script-dc-wise.gs
        // ko chhedta nahi - risk kam rakhne ke liye. Report screen par CSV bhi
        // client-side hi (submission sheet ka gviz export) padha jaata hai, koi
        // backend doGet nahi chahiye.
        // ===================================================================

        function getMeterCheckingDcKey(dcName = activeDC) {
            return getRevenueCollectionDcKey(dcName);
        }

        function isMeterCheckingAvailableForDc(dcName = activeDC) {
            return !!meterCheckingConfig[getMeterCheckingDcKey(dcName)];
        }

        function updateMeterCheckingButtonVisibility() {
            const btn = document.getElementById("meter-checking-dashboard-btn");
            if (btn) btn.style.display = isMeterCheckingAvailableForDc(activeDC) ? "block" : "none";
        }

        function parseMeterCheckingConsumerCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = splitCsvLine(lines[0]).map((h) => normalizeLookupValue(h));
            const findIndex = (aliases, fallback) => {
                const idx = headers.findIndex((h) => aliases.some((key) => h.includes(key)));
                return idx >= 0 ? idx : fallback;
            };
            const ivrsIdx = findIndex(["IVRS"], 0);
            const meterIdx = findIndex(["METERNO", "METER"], 1);
            const nameIdx = findIndex(["CONSUMERNAME", "CONSUMER"], 2);
            const fatherIdx = findIndex(["FATHERNAME", "FATHER"], 3);
            const mobileIdx = findIndex(["MOBILENO", "MOBILE"], 4);
            const tariffIdx = findIndex(["TARIFFCODE", "TARIFF"], 5);
            const loadIdx = findIndex(["LOAD"], 6);
            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                return {
                    ivrsNo: String(cols[ivrsIdx] || "").trim(),
                    meterNo: String(cols[meterIdx] || "").trim(),
                    consumerName: String(cols[nameIdx] || "").trim(),
                    fatherName: String(cols[fatherIdx] || "").trim(),
                    mobileNo: String(cols[mobileIdx] || "").trim(),
                    tariffCode: String(cols[tariffIdx] || "").trim(),
                    load: String(cols[loadIdx] || "").trim()
                };
            }).filter((row) => row.ivrsNo || row.meterNo);
        }

        // BUG FIX (2026-09-11, user-reported: "search 1 sec me aata tha ab 5-10
        // sec lag rahe hai"): Consumer CSV (SEONI (T) jaisi bade DC me ~35,000+
        // rows, ~3MB+) pehle SIRF localStorage me cache hota tha. localStorage
        // ka poore origin ke liye ek chhota (~5-10MB) quota hota hai, jo
        // Revenue module ke apne bahut saare caches (har DC ka paid-category
        // cache, staff cache, report cache waghera) ke saath jaldi bhar jaata
        // hai. Quota bharne par localStorage.setItem() SILENTLY FAIL ho jaata
        // (try/catch me pakड़ा jaata, koi error nahi dikhta) - matlab cache
        // kabhi save hi nahi ho pata, aur HAR search 25-30 second wali POORI
        // CSV fetch karta (jaisa live test me confirm hua: cache khaali hone
        // par 26.7 sec, cache hone par 0.05 sec). IndexedDB ka quota bahut
        // zyada bada hota hai (localStorage jaisi tight limit nahi) - isliye
        // ab yeh CSV IndexedDB me (parsed rows ke roop me) cache karte hain,
        // taaki cache reliably bana rahe aur search hamesha fast (~1 sec) ho.
        const meterCheckingConsumerDbName = "seoni-meter-checking-consumer-db-v1-STAGING";
        const meterCheckingConsumerStoreName = "consumer-csv";

        function openMeterCheckingConsumerDb() {
            return new Promise((resolve, reject) => {
                if (!window.indexedDB) return reject(new Error("IndexedDB unavailable"));
                const request = indexedDB.open(meterCheckingConsumerDbName, 1);
                request.onupgradeneeded = () => {
                    const db = request.result;
                    if (!db.objectStoreNames.contains(meterCheckingConsumerStoreName)) {
                        db.createObjectStore(meterCheckingConsumerStoreName, { keyPath: "dc_key" });
                    }
                };
                request.onsuccess = () => resolve(request.result);
                request.onerror = () => reject(request.error || new Error("Meter Checking consumer database open failed"));
            });
        }

        async function getMeterCheckingConsumerRowsFromDb_(dcKey) {
            try {
                const db = await openMeterCheckingConsumerDb();
                const record = await new Promise((resolve, reject) => {
                    const transaction = db.transaction(meterCheckingConsumerStoreName, "readonly");
                    const request = transaction.objectStore(meterCheckingConsumerStoreName).get(dcKey);
                    request.onsuccess = () => resolve(request.result || null);
                    request.onerror = () => reject(request.error || new Error("Meter Checking consumer database read failed"));
                });
                db.close();
                return Array.isArray(record?.rows) ? record.rows : null;
            } catch (_) {
                return null;
            }
        }

        async function saveMeterCheckingConsumerRowsToDb_(dcKey, rows) {
            try {
                const db = await openMeterCheckingConsumerDb();
                await new Promise((resolve, reject) => {
                    const transaction = db.transaction(meterCheckingConsumerStoreName, "readwrite");
                    transaction.oncomplete = () => resolve();
                    transaction.onerror = () => reject(transaction.error || new Error("Meter Checking consumer database write failed"));
                    transaction.objectStore(meterCheckingConsumerStoreName).put({ dc_key: dcKey, rows, savedAt: Date.now() });
                });
                db.close();
            } catch (_) {}
        }

        async function loadMeterCheckingConsumerData(dcName = activeDC, forceRefresh = false) {
            const dcKey = getMeterCheckingDcKey(dcName);
            if (!forceRefresh && meterCheckingRowsLoadedDcKey === dcKey && meterCheckingRows.length) return meterCheckingRows;
            const cfg = meterCheckingConfig[dcKey];
            if (!cfg || !cfg.consumerCsvUrl) return [];
            const legacyCacheKey = `seoni-meter-checking-consumer-csv-v1-${dcKey}`;

            const refreshInBackground = () => {
                loadRemoteText(cfg.consumerCsvUrl).then((fresh) => {
                    if (isLikelyCsvPayload(fresh)) {
                        const freshRows = parseMeterCheckingConsumerCsv(fresh);
                        if (freshRows.length) {
                            meterCheckingRows = freshRows;
                            saveMeterCheckingConsumerRowsToDb_(dcKey, freshRows);
                        }
                    }
                }).catch(() => {});
            };

            if (!forceRefresh) {
                const dbRows = await getMeterCheckingConsumerRowsFromDb_(dcKey);
                if (Array.isArray(dbRows) && dbRows.length) {
                    meterCheckingRows = dbRows;
                    meterCheckingRowsLoadedDcKey = dcKey;
                    refreshInBackground();
                    return dbRows;
                }
                // Purane (IndexedDB laane se pehle wale) localStorage cache se ek
                // baar migrate kar lete hain, taaki jin devices par pehle se yeh
                // cache bana hua hai unhe bhi turant fast result mile - phir usko
                // localStorage se hata dete hain (IndexedDB me chala gaya, ab
                // dobara zaroorat nahi, isse quota bhi thoda khaali hota hai).
                try {
                    const cachedText = localStorage.getItem(legacyCacheKey) || "";
                    if (isLikelyCsvPayload(cachedText)) {
                        const rows = parseMeterCheckingConsumerCsv(cachedText);
                        if (rows.length) {
                            meterCheckingRows = rows;
                            meterCheckingRowsLoadedDcKey = dcKey;
                            saveMeterCheckingConsumerRowsToDb_(dcKey, rows);
                            try { localStorage.removeItem(legacyCacheKey); } catch (_) {}
                            refreshInBackground();
                            return rows;
                        }
                    }
                } catch (_) {}
            }

            try {
                const rawCsv = await loadRemoteText(cfg.consumerCsvUrl);
                const rows = isLikelyCsvPayload(rawCsv) ? parseMeterCheckingConsumerCsv(rawCsv) : [];
                if (rows.length) {
                    meterCheckingRows = rows;
                    meterCheckingRowsLoadedDcKey = dcKey;
                    saveMeterCheckingConsumerRowsToDb_(dcKey, rows);
                    try { localStorage.removeItem(legacyCacheKey); } catch (_) {}
                }
                return rows;
            } catch (_) {
                return meterCheckingRows;
            }
        }

        function parseMeterCheckingStaffCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            return lines.slice(1).map((line) => (splitCsvLine(line)[0] || "").trim()).filter(Boolean);
        }

        // isLikelyCsvPayload() ek comma hone ki demand karta hai (multi-column sheets ke
        // liye theek hai), lekin "NAME OF STAFF" sheet me SIRF ek hi column hai - uske CSV
        // export me kabhi comma aata hi nahi, isliye wo check hamesha fail ho jaata tha
        // aur staff list kabhi load hi nahi hoti thi (yeh asli root-cause bug tha, cache
        // ka issue nahi). Staff CSV ke liye yeh alag, comma na maangne wala, lenient check
        // use karo.
        function isLikelyStaffCsvPayload(rawText) {
            const raw = String(rawText || "").trim();
            if (!raw) return false;
            if (/^\s*</.test(raw)) return false;
            return raw.split(/\r?\n/).filter((line) => line.trim()).length >= 2;
        }

        async function loadMeterCheckingStaffNames(dcName = activeDC, forceRefresh = false) {
            const dcKey = getMeterCheckingDcKey(dcName);
            if (!forceRefresh && meterCheckingStaffLoadedDcKey === dcKey && meterCheckingStaffNames.length) return meterCheckingStaffNames;
            const cfg = meterCheckingConfig[dcKey];
            if (!cfg || !cfg.staffCsvUrl) return [];
            // v3 (2026-09-10): cache-key version bump - purani (galat check ki wajah se
            // khaali ho sakti hai) cached value ko automatically invalid karne ke liye,
            // taaki sabke browser me fresh list dobara load ho jaye.
            const staffCacheKey = `seoni-meter-checking-staff-csv-v3-${dcKey}`;

            if (!forceRefresh) {
                try {
                    const cachedText = localStorage.getItem(staffCacheKey) || "";
                    if (isLikelyStaffCsvPayload(cachedText)) {
                        const cachedNames = parseMeterCheckingStaffCsv(cachedText);
                        if (cachedNames.length) {
                            meterCheckingStaffNames = cachedNames;
                            meterCheckingStaffLoadedDcKey = dcKey;
                            loadRemoteText(cfg.staffCsvUrl).then((fresh) => {
                                if (isLikelyStaffCsvPayload(fresh)) {
                                    const freshNames = parseMeterCheckingStaffCsv(fresh);
                                    if (freshNames.length) {
                                        meterCheckingStaffNames = freshNames;
                                        try { localStorage.setItem(staffCacheKey, fresh); } catch (_) {}
                                        populateMeterCheckingStaffOptions(freshNames);
                                    }
                                }
                            }).catch(() => {});
                            return cachedNames;
                        }
                    }
                } catch (_) {}
            }

            try {
                const rawCsv = await loadRemoteText(cfg.staffCsvUrl);
                const names = isLikelyStaffCsvPayload(rawCsv) ? parseMeterCheckingStaffCsv(rawCsv) : [];
                if (names.length) {
                    meterCheckingStaffNames = names;
                    try { localStorage.setItem(staffCacheKey, rawCsv); } catch (_) {}
                    meterCheckingStaffLoadedDcKey = dcKey;
                }
                return meterCheckingStaffNames;
            } catch (_) {
                return meterCheckingStaffNames;
            }
        }

        // Staff list fetch ho rahe waqt input box me chhota spinner + "load ho rahi
        // hai" wala placeholder dikhane ke liye (2026-09-10 addition) - taaki user ko
        // pata chale ki list abhi load ho rahi hai, khaali box na lage.
        function setMeterCheckingStaffLoadingState(isLoading) {
            const input = document.getElementById("meter-checking-staff-input");
            const chevron = document.getElementById("meter-checking-staff-chevron");
            const spinner = document.getElementById("meter-checking-staff-spinner");
            if (input) {
                if (isLoading) {
                    if (input.dataset.origPlaceholder === undefined) input.dataset.origPlaceholder = input.placeholder;
                    input.placeholder = "Staff list load ho rahi hai...";
                    input.disabled = true;
                } else {
                    if (input.dataset.origPlaceholder !== undefined) input.placeholder = input.dataset.origPlaceholder;
                    input.disabled = false;
                }
            }
            if (chevron) chevron.style.display = isLoading ? "none" : "";
            if (spinner) spinner.style.display = isLoading ? "block" : "none";
        }

        function populateMeterCheckingStaffOptions(names) {
            setMeterCheckingStaffLoadingState(false);
            if (Array.isArray(names) && names.length) meterCheckingStaffNames = names;
            renderMeterCheckingStaffDropdownList(meterCheckingStaffNames);
            const reportSelect = document.getElementById("meter-checking-report-staff");
            if (reportSelect) {
                const current = reportSelect.value;
                reportSelect.innerHTML = `<option value="">All Staff</option>` + meterCheckingStaffNames.map((n) => `<option value="${escapeHtml(n)}" ${n === current ? "selected" : ""}>${escapeHtml(n)}</option>`).join("");
            }
        }

        function renderMeterCheckingStaffDropdownList(names) {
            const dropdown = document.getElementById("meter-checking-staff-dropdown");
            if (!dropdown) return;
            if (!names || !names.length) {
                dropdown.innerHTML = `<div class="option-item" style="opacity:0.6; cursor:default;">Staff list load nahi hui / khaali hai</div>`;
                return;
            }
            dropdown.innerHTML = names.map((n) => `<div class="option-item" data-staff-name="${escapeHtml(n)}" onclick="selectMeterCheckingStaff(this)">${escapeHtml(n)}</div>`).join("");
        }

        function filterMeterCheckingStaffDropdown() {
            const input = document.getElementById("meter-checking-staff-input");
            const query = normalizeLookupValue(input?.value || "");
            const filtered = query ? meterCheckingStaffNames.filter((n) => normalizeLookupValue(n).includes(query)) : meterCheckingStaffNames;
            renderMeterCheckingStaffDropdownList(filtered);
            const dropdown = document.getElementById("meter-checking-staff-dropdown");
            if (dropdown) dropdown.style.display = "block";
        }

        function showMeterCheckingStaffDropdown() {
            // BUG FIX (user reported): pehle yeh filterMeterCheckingStaffDropdown()
            // ko hi call karta tha, jo current input.value (jo ek baar naam select
            // karne ke bad us naam se bhar jaata hai) se list ko filter kar deta
            // tha - isliye dobara click/focus karne par sirf wahi ek naam dikhta
            // tha, sabhi naam gayab ho jaate the. Ab focus/click par HAMESHA POORI
            // list dikhate hain; filter sirf tab lagta hai jab user khud type
            // karta hai (oninput -> filterMeterCheckingStaffDropdown()).
            renderMeterCheckingStaffDropdownList(meterCheckingStaffNames);
            const dropdown = document.getElementById("meter-checking-staff-dropdown");
            if (dropdown) dropdown.style.display = "block";
        }

        function hideMeterCheckingStaffDropdown() {
            const dropdown = document.getElementById("meter-checking-staff-dropdown");
            if (dropdown) dropdown.style.display = "none";
        }

        function selectMeterCheckingStaff(el) {
            const name = el?.dataset?.staffName;
            if (!name) return;
            const input = document.getElementById("meter-checking-staff-input");
            if (input) input.value = name;
            hideMeterCheckingStaffDropdown();
        }

        // USER CORRECTION (2026-09-11): pehle Phase Current aur Neutral Current
        // dono ke apne-apne alag "Quick Select" number-dropdown (0 se 20 tak,
        // 0.5 step) the - user ne isko "badi gadbad" bataya. Naya (sahi) design:
        // EK hi "Phase/Neutral Current" dropdown hai jisme sirf 2 option hain -
        // "Phase Current" ya "Neutral Current" - staff pehle YEH CHUNTA HAI ki
        // abhi kis current ki reading bharni hai, uske bad sirf usi wale ki
        // text box khulti hai (dusri wali chhup jaati hai, lekin uska pehle se
        // bhara value delete nahi hota) - taaki staff dropdown se dobara select
        // karke dono reading bhar sake. Text box khud already digit+decimal
        // (inputmode="decimal" jo mobile par numeric dial-pad kholta hai) tak
        // restricted hai.
        function onMeterCheckingCurrentTypeChange(type) {
            const phaseBox = document.getElementById("meter-checking-phase-current");
            const neutralBox = document.getElementById("meter-checking-neutral-current");
            if (type === "phase") {
                if (neutralBox) neutralBox.style.display = "none";
                if (phaseBox) { phaseBox.style.display = "block"; phaseBox.focus(); }
            } else if (type === "neutral") {
                if (phaseBox) phaseBox.style.display = "none";
                if (neutralBox) { neutralBox.style.display = "block"; neutralBox.focus(); }
            } else {
                if (phaseBox) phaseBox.style.display = "none";
                if (neutralBox) neutralBox.style.display = "none";
            }
        }

        function resetMeterCheckingSearch() {
            currentMeterCheckingRecord = null;
            meterCheckingPhoto1 = { base64: "", name: "" };
            meterCheckingPhoto2 = { base64: "", name: "" };
            meterCheckingPhoto3 = { base64: "", name: "" };
            const ivrsInput = document.getElementById("meter-checking-search-ivrs");
            const meterInput = document.getElementById("meter-checking-search-meter");
            const searchBtn = document.getElementById("meter-checking-search-btn");
            if (ivrsInput) { ivrsInput.value = ""; ivrsInput.style.display = ""; }
            if (meterInput) { meterInput.value = ""; meterInput.style.display = ""; }
            if (searchBtn) searchBtn.style.display = "";
            const moreBtn = document.getElementById("meter-checking-search-more-btn");
            if (moreBtn) moreBtn.style.display = "none";
            const resultBox = document.getElementById("meter-checking-result-box");
            const formBox = document.getElementById("meter-checking-form-box");
            if (resultBox) { resultBox.style.display = "none"; resultBox.innerHTML = ""; }
            if (formBox) formBox.style.display = "none";
            ["meter-checking-staff-input", "meter-checking-pole-number", "meter-checking-current-type-dropdown", "meter-checking-phase-current", "meter-checking-neutral-current", "meter-checking-remark"].forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.value = "";
            });
            // Phase/Neutral Current text box sirf dropdown se ek option select karne
            // par hi khulta hai (khaali manually bhi fill hota hai) - naya search shuru
            // hone par usko wapas chhupa dete hain taaki dobara dropdown select hi
            // pehla step rahe.
            ["meter-checking-phase-current", "meter-checking-neutral-current"].forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.style.display = "none";
            });
            [1, 2, 3].forEach((n) => {
                const status = document.getElementById(`meter-checking-photo${n}-status`);
                if (status) { status.innerText = "Pending"; status.style.color = "#7a5233"; }
                const input = document.getElementById(`meter-checking-photo${n}`);
                if (input) input.value = "";
            });
            hideMeterCheckingStaffDropdown();
            if (ivrsInput) ivrsInput.focus();
        }

        function initMeterChecking() {
            resetMeterCheckingSearch();
            loadMeterCheckingConsumerData(activeDC).catch(() => {});
            if (!meterCheckingStaffNames.length || meterCheckingStaffLoadedDcKey !== getMeterCheckingDcKey(activeDC)) {
                setMeterCheckingStaffLoadingState(true);
            }
            loadMeterCheckingStaffNames(activeDC)
                .then((names) => populateMeterCheckingStaffOptions(names))
                .catch(() => setMeterCheckingStaffLoadingState(false));
        }

        function renderMeterCheckingConsumer(record) {
            const resultBox = document.getElementById("meter-checking-result-box");
            const formBox = document.getElementById("meter-checking-form-box");
            if (!resultBox) return;
            resultBox.innerHTML = `
                <div style="background:linear-gradient(180deg,#f5ede1 0%,#ffffff 100%); border:1.5px solid #a9744f; border-radius:16px; padding:9px; text-align:left;">
                    <div style="display:flex; justify-content:space-between; gap:7px; align-items:center; margin-bottom:6px; background:#ecdfc9; border:1.5px solid #8b5a2b; border-radius:12px; padding:7px 9px;">
                        <span style="font-size:0.64rem; font-weight:950; color:#5c3a21; letter-spacing:0.03em;">IVRS NO</span>
                        <span style="flex:1; text-align:center; font-size:0.82rem; font-weight:950; color:#dc2626;">${escapeHtml(record.ivrsNo || "-")}</span>
                    </div>
                    <div style="background:#ffffff; border:1px solid #a9744f; border-radius:13px; padding:7px 10px;">
                        <div style="font-size:0.82rem; line-height:1.15; font-weight:950; color:#0f172a; text-align:center;">${escapeHtml(record.consumerName || "-")}</div>
                        <div style="margin-top:2px; font-size:0.67rem; font-weight:850; color:#475569; text-align:center;">S/o ${escapeHtml(record.fatherName || "-")}</div>
                    </div>
                    <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:7px;">
                        ${renderRevenueMiniBox("Meter No", record.meterNo)}
                        ${renderRevenueMiniBox("Mobile No", normalizeMobileDisplayValue(record.mobileNo))}
                        ${renderRevenueMiniBox("Tariff Code", record.tariffCode)}
                        ${renderRevenueMiniBox("Load", record.load)}
                    </div>
                </div>
            `;
            resultBox.style.display = "block";
            if (formBox) formBox.style.display = "block";
        }

        async function searchMeterChecking() {
            const ivrsInput = document.getElementById("meter-checking-search-ivrs");
            const meterInput = document.getElementById("meter-checking-search-meter");
            const ivrs = String(ivrsInput?.value || "").trim();
            const meterNo = String(meterInput?.value || "").trim();
            if (!ivrs && !meterNo) return showToast("IVRS No ya Meter No me se koi ek dalen", false);

            const searchBtn = document.getElementById("meter-checking-search-btn");
            const oldText = searchBtn ? searchBtn.innerText : "Search";
            try {
                setActionButtonState(searchBtn, "processing", oldText);
                let rows = await loadMeterCheckingConsumerData(activeDC);
                const matcher = (row) => (ivrs && row.ivrsNo === ivrs) || (meterNo && normalizeLookupValue(row.meterNo) === normalizeLookupValue(meterNo));
                let found = rows.find(matcher);
                if (!found) {
                    rows = await loadMeterCheckingConsumerData(activeDC, true);
                    found = rows.find(matcher);
                }
                if (!found) {
                    const resultBox = document.getElementById("meter-checking-result-box");
                    if (resultBox) {
                        resultBox.innerHTML = `<div style="background:#fff1f2; border:1.5px solid #fda4af; border-radius:16px; padding:16px; color:#991b1b; font-weight:900; text-align:center;">Consumer Not Found in CSV</div>`;
                        resultBox.style.display = "block";
                    }
                    return showToast("Consumer Not Found in CSV", false);
                }
                currentMeterCheckingRecord = found;
                renderMeterCheckingConsumer(found);
                if (ivrsInput) ivrsInput.style.display = "none";
                if (meterInput) meterInput.style.display = "none";
                if (searchBtn) searchBtn.style.display = "none";
                const moreBtn = document.getElementById("meter-checking-search-more-btn");
                if (moreBtn) moreBtn.style.display = "block";
            } catch (_) {
                showToast("Consumer Not Found in CSV", false);
            } finally {
                setActionButtonState(searchBtn, "idle", oldText || "Search");
            }
        }

        async function handleMeterCheckingPhoto(index, input) {
            const file = input?.files?.[0] || null;
            const status = document.getElementById(`meter-checking-photo${index}-status`);
            if (!file) return;
            try {
                if (status) { status.innerText = "Processing..."; status.style.color = "#7a5233"; }
                const base64 = await resizeImageForUpload(file, 1280, 0.78);
                const photoObj = { base64, name: file.name || `meter-checking-photo${index}-${Date.now()}.jpg` };
                if (index === 1) meterCheckingPhoto1 = photoObj;
                else if (index === 2) meterCheckingPhoto2 = photoObj;
                else meterCheckingPhoto3 = photoObj;
                if (status) { status.innerText = "Ready"; status.style.color = "#166534"; }
            } catch (_) {
                if (status) { status.innerText = "Failed"; status.style.color = "#991b1b"; }
                showToast("Photo process nahi ho payi", false);
            }
        }

        async function submitMeterChecking() {
            if (!currentMeterCheckingRecord) return showToast("Pehle consumer search karein", false);
            const staffName = String(document.getElementById("meter-checking-staff-input")?.value || "").trim();
            const poleNumber = String(document.getElementById("meter-checking-pole-number")?.value || "").trim();
            const phaseCurrent = String(document.getElementById("meter-checking-phase-current")?.value || "").trim();
            const neutralCurrent = String(document.getElementById("meter-checking-neutral-current")?.value || "").trim();
            const remark = String(document.getElementById("meter-checking-remark")?.value || "").trim();
            if (!staffName) return showToast("Staff ka naam select karein", false);
            if (!meterCheckingStaffNames.some((n) => normalizeLookupValue(n) === normalizeLookupValue(staffName))) {
                return showToast("Staff list se hi valid naam select karein", false);
            }
            if (!poleNumber) return showToast("Pole Number dalen", false);
            if (!phaseCurrent) return showToast("Phase Current dalen", false);
            if (!neutralCurrent) return showToast("Neutral Current dalen", false);
            if (!remark) return showToast("Remark likhen", false);
            if (!meterCheckingSubmitScriptUrl || meterCheckingSubmitScriptUrl.indexOf("PASTE_") === 0) {
                return showToast("Submit script URL abhi set nahi hai", false);
            }

            const submitBtn = document.getElementById("meter-checking-submit-btn");
            setActionButtonState(submitBtn, "processing", "Submit");
            try {
                const record = currentMeterCheckingRecord;
                const payload = {
                    action: "submitMeterChecking",
                    dc_name: activeDC,
                    ivrs_no: record.ivrsNo || "",
                    meter_no: record.meterNo || "",
                    consumer_name: record.consumerName || "",
                    father_name: record.fatherName || "",
                    mobile_no: record.mobileNo || "",
                    tariff_code: record.tariffCode || "",
                    load: record.load || "",
                    staff_name: staffName,
                    pole_number: poleNumber,
                    phase_current: phaseCurrent,
                    neutral_current: neutralCurrent,
                    remark: remark,
                    photo1_base64: meterCheckingPhoto1.base64 || "",
                    photo1_name: meterCheckingPhoto1.name || "",
                    photo1_mime_type: "image/jpeg",
                    photo2_base64: meterCheckingPhoto2.base64 || "",
                    photo2_name: meterCheckingPhoto2.name || "",
                    photo2_mime_type: "image/jpeg",
                    photo3_base64: meterCheckingPhoto3.base64 || "",
                    photo3_name: meterCheckingPhoto3.name || "",
                    photo3_mime_type: "image/jpeg"
                };
                const response = await fetch(meterCheckingSubmitScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "text/plain;charset=utf-8" },
                    body: JSON.stringify(payload)
                });
                const responseText = await response.text();
                let parsed = {};
                try { parsed = JSON.parse(responseText || "{}"); } catch (_) {}
                if (!response.ok || (parsed.status && parsed.status !== "success")) {
                    throw new Error(parsed.message || "Meter Checking submit nahi ho payi");
                }
                setActionButtonState(submitBtn, "done", "Submit");
                showToast(parsed.message || "Meter Checking data submit ho gaya", true);
                resetMeterCheckingSearch();
            } catch (error) {
                setActionButtonState(submitBtn, "idle", "Submit");
                showToast(error?.message || "Submit nahi ho paya", false);
            }
        }

        // ----- Meeter Cheking Report (Date/Month wise, Staff wise) -----

        function getMeterCheckingReportSheetName(dcName = activeDC) {
            return `Script Meter Checking ${normalizeDcName(dcName)}`;
        }

        function getMeterCheckingReportCsvUrl(dcName = activeDC) {
            return `https://docs.google.com/spreadsheets/d/${meterCheckingReportSpreadsheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(getMeterCheckingReportSheetName(dcName))}`;
        }

        function parseMeterCheckingReportCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];
            const headers = splitCsvLine(lines[0]).map((h) => normalizeLookupValue(h));
            const idx = (aliases) => headers.findIndex((h) => aliases.includes(h));
            const ivrsIdx = idx(["IVRSNO"]);
            const meterIdx = idx(["METERNO"]);
            const nameIdx = idx(["CONSUMERNAME"]);
            const fatherIdx = idx(["FATHERNAME"]);
            const mobileIdx = idx(["MOBILENO"]);
            const tariffIdx = idx(["TARIFFCODE"]);
            const loadIdx = idx(["LOAD"]);
            // Sheet ka actual header "NAME OF STAFF" nikla (na ki "STAFF NAME" jo
            // .gs script naye tab par likhta hai) - kyunki yeh tab pehle se maujood
            // tha aur apne purane header ke saath hi use ho raha hai. Dono spelling
            // yahan accept karte hain taaki chahe header kuch bhi ho, staff column
            // sahi se mil jaaye.
            const staffIdx = idx(["STAFFNAME", "NAMEOFSTAFF"]);
            const poleIdx = idx(["POLENUMBER"]);
            const phaseIdx = idx(["PHASECURRENT"]);
            const neutralIdx = idx(["NEUTRALCURRENT"]);
            const remarkIdx = idx(["REMARK"]);
            const photo1Idx = idx(["PHOTO1"]);
            const photo2Idx = idx(["PHOTO2"]);
            const photo3Idx = idx(["PHOTO3"]);
            const dateIdx = idx(["DATE"]);
            const timeIdx = idx(["TIME"]);
            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                return {
                    ivrsNo: String(cols[ivrsIdx] || "").trim(),
                    meterNo: String(cols[meterIdx] || "").trim(),
                    consumerName: String(cols[nameIdx] || "").trim(),
                    fatherName: String(cols[fatherIdx] || "").trim(),
                    mobileNo: String(cols[mobileIdx] || "").trim(),
                    tariffCode: String(cols[tariffIdx] || "").trim(),
                    load: String(cols[loadIdx] || "").trim(),
                    staffName: String(cols[staffIdx] || "").trim(),
                    poleNumber: String(cols[poleIdx] || "").trim(),
                    phaseCurrent: String(cols[phaseIdx] || "").trim(),
                    neutralCurrent: String(cols[neutralIdx] || "").trim(),
                    remark: String(cols[remarkIdx] || "").trim(),
                    photo1: String(cols[photo1Idx] || "").trim(),
                    photo2: String(cols[photo2Idx] || "").trim(),
                    photo3: String(cols[photo3Idx] || "").trim(),
                    date: String(cols[dateIdx] || "").trim(),
                    time: String(cols[timeIdx] || "").trim()
                };
            }).filter((row) => row.ivrsNo || row.meterNo);
        }

        async function loadMeterCheckingReportRows(dcName = activeDC, forceRefresh = false) {
            const dcKey = getMeterCheckingDcKey(dcName);
            if (!forceRefresh && meterCheckingReportLoadedDcKey === dcKey) return meterCheckingReportRows;
            try {
                const rawCsv = await loadRemoteText(getMeterCheckingReportCsvUrl(dcName));
                const rows = isLikelyCsvPayload(rawCsv) ? parseMeterCheckingReportCsv(rawCsv) : [];
                meterCheckingReportRows = rows;
                meterCheckingReportLoadedDcKey = dcKey;
                meterCheckingReportStale = false; // ITEM-8 FIX (2026-09-15): fresh fetch safal
                return rows;
            } catch (_) {
                // ITEM-8 FIX (2026-09-15): pehle se koi data ho to use hi wapas
                // rakhte hain (behavior unchanged) - bas ek stale flag set karte
                // hain taaki screen par ek chhota warning dikhaya ja sake.
                meterCheckingReportStale = meterCheckingReportRows.length > 0;
                return meterCheckingReportRows;
            }
        }

        // DD/MM/YYYY (jaisa backend likhta hai) -> YYYY-MM-DD, taaki date/month
        // <input> values (jo ISO format me aate hain) se seedha compare ho sake.
        function meterCheckingDateToIso(dateText) {
            const parts = String(dateText || "").split("/");
            if (parts.length !== 3) return "";
            const [dd, mm, yyyy] = parts;
            if (!dd || !mm || !yyyy) return "";
            return `${yyyy}-${mm.padStart(2, "0")}-${dd.padStart(2, "0")}`;
        }

        function getMeterCheckingReportFilteredRows(rows) {
            const staffFilter = document.getElementById("meter-checking-report-staff")?.value || "";
            const periodValue = meterCheckingReportMode === "MONTHLY"
                ? (document.getElementById("meter-checking-report-month")?.value || getTodayIsoDate().slice(0, 7))
                : (document.getElementById("meter-checking-report-date")?.value || getTodayIsoDate());
            return (rows || []).filter((row) => {
                const iso = meterCheckingDateToIso(row.date);
                if (!iso) return false;
                const periodMatch = meterCheckingReportMode === "MONTHLY" ? iso.slice(0, 7) === periodValue : iso === periodValue;
                if (!periodMatch) return false;
                if (staffFilter && normalizeLookupValue(row.staffName) !== normalizeLookupValue(staffFilter)) return false;
                return true;
            });
        }

        function initMeterCheckingReport() {
            meterCheckingReportLoadedDcKey = "";
            const dateInput = document.getElementById("meter-checking-report-date");
            const monthInput = document.getElementById("meter-checking-report-month");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            if (monthInput && !monthInput.value) monthInput.value = getTodayIsoDate().slice(0, 7);
            loadMeterCheckingStaffNames(activeDC).then((names) => populateMeterCheckingStaffOptions(names)).finally(() => {
                setMeterCheckingReportMode(meterCheckingReportMode || "DAILY");
            });
        }

        function setMeterCheckingReportMode(mode) {
            meterCheckingReportMode = mode === "MONTHLY" ? "MONTHLY" : "DAILY";
            const dateInput = document.getElementById("meter-checking-report-date");
            const monthInput = document.getElementById("meter-checking-report-month");
            const dateBtn = document.getElementById("meter-checking-report-date-mode-btn");
            const monthBtn = document.getElementById("meter-checking-report-month-mode-btn");
            if (dateInput) dateInput.style.display = meterCheckingReportMode === "DAILY" ? "block" : "none";
            if (monthInput) monthInput.style.display = meterCheckingReportMode === "MONTHLY" ? "block" : "none";
            if (dateBtn) { dateBtn.style.background = meterCheckingReportMode === "DAILY" ? "#6f4226" : "#ecdfc9"; dateBtn.style.color = meterCheckingReportMode === "DAILY" ? "#ffffff" : "#5c3a21"; }
            if (monthBtn) { monthBtn.style.background = meterCheckingReportMode === "MONTHLY" ? "#6f4226" : "#ecdfc9"; monthBtn.style.color = meterCheckingReportMode === "MONTHLY" ? "#ffffff" : "#5c3a21"; }
            renderMeterCheckingReport();
        }

        async function renderMeterCheckingReport() {
            const tableBox = document.getElementById("meter-checking-report-table");
            if (!tableBox) return;
            const rows = await loadMeterCheckingReportRows(activeDC);
            const filtered = getMeterCheckingReportFilteredRows(rows);
            const staffFilter = document.getElementById("meter-checking-report-staff")?.value || "";
            // ITEM-8 FIX (2026-09-15): naya fetch fail hone par purana (cached)
            // data dikhne par chhota staleness note - sirf display text.
            const meterCheckingStaleNote = (filtered.length && meterCheckingReportStale)
                ? `<div style="margin-top:8px; text-align:center; font-size:11px; font-weight:900; color:#b45309;">⚠ Naya data load nahi ho saka, pehle se load data dikha rahe hain</div>`
                : "";

            if (meterCheckingReportMode === "MONTHLY") {
                // Month-wise: date ke hisaab se group karke sirf count dikhate hain
                // (staff filter select hone par "kis date pe kitne check kiye" wahi
                // ask hai) - poora consumer-level data download me milega.
                const byDate = {};
                filtered.forEach((row) => {
                    const key = row.date || "-";
                    byDate[key] = (byDate[key] || 0) + 1;
                });
                const dateKeys = Object.keys(byDate).sort((a, b) => meterCheckingDateToIso(a).localeCompare(meterCheckingDateToIso(b)));
                let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.4fr 1fr;"><div>DATE</div><div>CHECKED COUNT</div></div>`;
                if (!dateKeys.length) {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Is month me koi data nahi mila.</div></div>`;
                } else {
                    dateKeys.forEach((key) => {
                        html += `<div class="summary-table-row" style="grid-template-columns: 1.4fr 1fr;"><div>${escapeHtml(key)}</div><div class="font-black">${byDate[key]}</div></div>`;
                    });
                }
                html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL CHECKED${staffFilter ? ` - ${escapeHtml(staffFilter)}` : ""}</div><div class="mt-2 text-center text-[13px] font-black">${filtered.length}</div></div>`;
                tableBox.innerHTML = html + meterCheckingStaleNote;
            } else {
                // Date-wise: screen par sirf Name of Staff + Checked Connection ki
                // summary dikhate hain - poora consumer-level detail (Consumer/IVRS/
                // Meter/Time waghera) sirf downloadMeterCheckingReport() ki file me
                // milega, screen par nahi.
                const byStaff = {};
                filtered.forEach((row) => {
                    const key = row.staffName || "Unknown";
                    byStaff[key] = (byStaff[key] || 0) + 1;
                });
                const staffKeys = Object.keys(byStaff).sort((a, b) => byStaff[b] - byStaff[a]);
                let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.6fr 1fr;"><div>NAME OF STAFF</div><div>CHECKED CONNECTION</div></div>`;
                if (!staffKeys.length) {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Is date me koi data nahi mila.</div></div>`;
                } else {
                    staffKeys.forEach((name) => {
                        html += `<div class="summary-table-row" style="grid-template-columns: 1.6fr 1fr;"><div>${escapeHtml(name)}</div><div class="font-black">${byStaff[name]}</div></div>`;
                    });
                }
                html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL CHECKED${staffFilter ? ` - ${escapeHtml(staffFilter)}` : ""}</div><div class="mt-2 text-center text-[13px] font-black">${filtered.length}</div></div>`;
                tableBox.innerHTML = html + meterCheckingStaleNote;
            }
        }

        function setMeterCheckingReportDownloadState(isDownloading, message = "") {
            const status = document.getElementById("meter-checking-report-download-status");
            const buttons = document.querySelectorAll("#meter-checking-report-view .btn-export-row, #meter-checking-report-pdf-btn, #meter-checking-report-excel-btn");
            buttons.forEach((button) => {
                if (!button || button.tagName !== "BUTTON") return;
                button.disabled = isDownloading;
                button.style.opacity = isDownloading ? "0.65" : "1";
                button.style.pointerEvents = isDownloading ? "none" : "auto";
            });
            if (status) {
                status.style.display = message ? "block" : "none";
                status.textContent = message;
            }
        }

        // ===== Meeter Cheking Report PDF - Hindi/Devanagari REMARK fix =====
        // jsPDF khud complex-script (Devanagari) text-shaping support nahi karta -
        // font embed kar bhi den to matra reorder / conjuncts (jaise "क्ष") galat
        // dikhte. ASLI FIX: jis REMARK cell me Hindi text hai, usko browser ke
        // apne Canvas 2D API se draw karke (jo real OS text-shaping engine use
        // karta hai - Windows par "Nirmala UI", Android par "Noto Sans
        // Devanagari") ek chhoti image bana lete hain, aur PDF me us cell ke
        // upar wahi image chipka dete hain - taaki Hindi bilkul sahi (jaisa type
        // kiya) dikhe. Pure English/number wale remarks normal PDF text hi
        // rehte hain (extra kaam ki zaroorat nahi).
        function meterCheckingCellHasDevanagari_(text) {
            return /[ऀ-ॿ]/.test(String(text || ""));
        }

        // USER REQUEST (2026-09-14, O&M/VIG PDF alignment fix): pehle Hindi
        // cell ka text canvas ke LEFT se hi likha jaata tha, hamesha - jo
        // column ke apne halign (jaise "center") se match nahi karta tha,
        // isliye Hindi wale cell (jaise "लागू नहीं") aur plain English/number
        // wale cell alag-alag jagah dikhte the (ek row me "idhar-udhar" jaisa
        // lagta tha). Ab `align` param (default "left", Meeter Checking ka
        // purana behaviour bilkul same rakhne ke liye) column ke halign ke
        // hisab se text ko canvas ke andar bhi center/left karta hai.
        function renderMeterCheckingHindiCellImage_(text, cellWidthMm, cellHeightMm, align) {
            const scale = 6; // crisp raster taaki PDF zoom karne par bhi saaf dikhe
            const widthPx = Math.max(24, Math.round(cellWidthMm * scale));
            const heightPx = Math.max(24, Math.round(cellHeightMm * scale));
            const canvas = document.createElement("canvas");
            canvas.width = widthPx;
            canvas.height = heightPx;
            const ctx = canvas.getContext("2d");
            ctx.fillStyle = "#000000";
            ctx.textBaseline = "top";
            const padPx = 2 * scale;
            const maxWidth = Math.max(4, widthPx - padPx * 2);
            const fontStack = `"Noto Sans Devanagari","Nirmala UI","Mangal",sans-serif`;
            const words = String(text).split(/\s+/).filter(Boolean);
            let fontSizePx = Math.max(8, Math.round(heightPx * 0.3));
            let lines = [words.join(" ") || ""];
            for (; fontSizePx >= 6; fontSizePx--) {
                ctx.font = `400 ${fontSizePx}px ${fontStack}`;
                lines = [];
                let current = "";
                words.forEach((word) => {
                    const test = current ? `${current} ${word}` : word;
                    if (!current || ctx.measureText(test).width <= maxWidth) {
                        current = test;
                    } else {
                        lines.push(current);
                        current = word;
                    }
                });
                if (current) lines.push(current);
                const lineHeight = fontSizePx * 1.25;
                if (lines.length * lineHeight <= heightPx - padPx * 2 || fontSizePx <= 6) break;
            }
            ctx.font = `400 ${fontSizePx}px ${fontStack}`;
            const lineHeight = fontSizePx * 1.25;
            const totalTextHeight = lines.length * lineHeight;
            const startY = Math.max(padPx * 0.5, (heightPx - totalTextHeight) / 2);
            ctx.textAlign = align === "center" ? "center" : "left";
            const textX = align === "center" ? widthPx / 2 : padPx;
            lines.forEach((line, i) => {
                ctx.fillText(line, textX, startY + i * lineHeight, maxWidth);
            });
            return canvas.toDataURL("image/png");
        }

        function drawMeterCheckingHindiCell_(doc, cellData, align) {
            const { x, y, width, height } = cellData.cell;
            doc.setFillColor(255, 255, 255);
            doc.rect(x, y, width, height, "F");
            doc.setDrawColor(0, 0, 0);
            doc.setLineWidth(0.1);
            doc.rect(x, y, width, height, "S");
            try {
                const imgData = renderMeterCheckingHindiCellImage_(String(cellData.cell.raw ?? ""), width, height, align);
                doc.addImage(imgData, "PNG", x + 0.4, y + 0.3, Math.max(0.1, width - 0.8), Math.max(0.1, height - 0.6));
            } catch (_) {}
        }

        async function downloadMeterCheckingReport(fmt) {
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setMeterCheckingReportDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const rows = await loadMeterCheckingReportRows(activeDC, true);
                const filtered = getMeterCheckingReportFilteredRows(rows);
                if (!filtered.length) { setMeterCheckingReportDownloadState(false, "Download ke liye data nahi hai"); return; }
                const staffFilter = document.getElementById("meter-checking-report-staff")?.value || "";
                const headers = ["DATE", "TIME", "IVRS NO", "METER NO", "CONSUMER NAME", "FATHER NAME", "MOBILE NO", "TARIFF CODE", "LOAD", "STAFF NAME", "POLE NUMBER", "PHASE CURRENT", "NEUTRAL CURRENT", "REMARK"];
                const bodyRows = filtered.map((row) => [
                    row.date, row.time, row.ivrsNo, row.meterNo, row.consumerName, row.fatherName, row.mobileNo, row.tariffCode, row.load, row.staffName, row.poleNumber, row.phaseCurrent, row.neutralCurrent, row.remark
                ]);
                const periodLabel = meterCheckingReportMode === "MONTHLY"
                    ? (document.getElementById("meter-checking-report-month")?.value || getTodayIsoDate().slice(0, 7))
                    : (document.getElementById("meter-checking-report-date")?.value || getTodayIsoDate());
                const reportTitle = `Meeter Cheking Report - DC ${activeDC}${staffFilter ? ` - ${staffFilter}` : ""}`;
                const fileName = `${reportTitle}-${periodLabel}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setMeterCheckingReportDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 148, 15, { align: "center" });
                    doc.setFontSize(9); doc.text(`Period: ${periodLabel}`, 148, 22, { align: "center" });
                    const remarkColIndex = headers.length - 1;
                    doc.autoTable({
                        startY: 28, head: [headers], body: bodyRows, theme: "grid",
                        styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" },
                        headStyles: { fillColor: [111, 66, 38] },
                        didDrawCell: (cellData) => {
                            if (cellData.section === "body" && cellData.column.index === remarkColIndex && meterCheckingCellHasDevanagari_(cellData.cell.raw)) {
                                drawMeterCheckingHindiCell_(doc, cellData);
                            }
                        }
                    });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Period: ${periodLabel}`], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setMeterCheckingReportDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setMeterCheckingReportDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Meeter Cheking report download nahi ho payi", false);
            }
        }

        function openMeterCheckingReport() {
            closeHeaderMenu();
            switchView("meter-checking-report");
        }

        // ===== Meeter Cheking - Live Progress (2026-09-10 addition) =====
        // Revenue ke "Live Progress" jaisa hi - aaj (current day) me kis staff ne
        // kitne meter check kiye, uska sirf naam+count wala live summary. Screen
        // auto-refresh hoti rahti hai (view se bahar jaate hi refresh khud ruk
        // jaata hai). Download me bhi sirf yahi 2-column summary jaati hai, poora
        // consumer-level detail nahi (wo already "Download Report" me available hai).
        let meterCheckingLiveProgressTimer = null;

        function openMeterCheckingLiveProgress() {
            closeHeaderMenu();
            switchView("meter-checking-live-progress");
        }

        function getMeterCheckingTodaySummaryRows_(rows) {
            const todayIso = getTodayIsoDate();
            const todayRows = (rows || []).filter((row) => meterCheckingDateToIso(row.date) === todayIso);
            const counts = {};
            todayRows.forEach((row) => {
                const name = row.staffName || "Unknown";
                counts[name] = (counts[name] || 0) + 1;
            });
            const staffKeys = Object.keys(counts).sort((a, b) => counts[b] - counts[a]);
            return { todayRows, counts, staffKeys };
        }

        async function renderMeterCheckingLiveProgress() {
            const tableBox = document.getElementById("meter-checking-live-table");
            if (!tableBox) return;
            const dcLabelBox = document.getElementById("meter-checking-live-dc-label");
            if (dcLabelBox) dcLabelBox.innerText = activeDC || "-";
            const rows = await loadMeterCheckingReportRows(activeDC, true);
            const { todayRows, counts, staffKeys } = getMeterCheckingTodaySummaryRows_(rows);
            let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.6fr 1fr;"><div>NAME OF STAFF</div><div>CHECKED CONNECTION</div></div>`;
            if (!staffKeys.length) {
                html += `<div class="summary-table-row" style="grid-template-columns: 1fr;"><div class="text-rose-600">Aaj tak koi checking nahi hui hai.</div></div>`;
            } else {
                staffKeys.forEach((name) => {
                    html += `<div class="summary-table-row" style="grid-template-columns: 1.6fr 1fr;"><div>${escapeHtml(name)}</div><div class="font-black">${counts[name]}</div></div>`;
                });
            }
            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL CHECKED TODAY</div><div class="mt-2 text-center text-[13px] font-black">${todayRows.length}</div></div>`;
            tableBox.innerHTML = html;
        }

        function startMeterCheckingLiveProgressAutoRefresh() {
            if (meterCheckingLiveProgressTimer) clearInterval(meterCheckingLiveProgressTimer);
            meterCheckingLiveProgressTimer = setInterval(() => {
                const viewEl = document.getElementById("meter-checking-live-progress-view");
                if (!viewEl || !viewEl.classList.contains("active")) {
                    clearInterval(meterCheckingLiveProgressTimer);
                    meterCheckingLiveProgressTimer = null;
                    return;
                }
                renderMeterCheckingLiveProgress();
            }, 30000);
        }

        function setMeterCheckingLiveDownloadState(isDownloading, message = "") {
            const status = document.getElementById("meter-checking-live-download-status");
            [document.getElementById("meter-checking-live-pdf-btn"), document.getElementById("meter-checking-live-excel-btn")].forEach((button) => {
                if (!button) return;
                button.disabled = isDownloading;
                button.style.opacity = isDownloading ? "0.65" : "1";
                button.style.pointerEvents = isDownloading ? "none" : "auto";
            });
            if (status) {
                status.style.display = message ? "block" : "none";
                status.textContent = message;
            }
        }

        async function downloadMeterCheckingLiveProgress(fmt) {
            const downloadTypeLabel = fmt === "PDF" ? "PDF" : "Excel";
            setMeterCheckingLiveDownloadState(true, `${downloadTypeLabel} downloading... kripya wait kijiye`);
            try {
                const rows = await loadMeterCheckingReportRows(activeDC, true);
                const { todayRows, counts, staffKeys } = getMeterCheckingTodaySummaryRows_(rows);
                if (!todayRows.length) { setMeterCheckingLiveDownloadState(false, "Aaj ke liye data nahi hai"); return; }
                const headers = ["NAME OF STAFF", "CHECKED CONNECTION"];
                const bodyRows = staffKeys.map((name) => [name, counts[name]]);
                const todayLabel = getCurrentDateDDMMYYYY();
                const reportTitle = `Meeter Cheking Live Progress - DC ${activeDC}`;
                const fileName = `${reportTitle}-${todayLabel}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (fmt === "PDF") {
                    if (!window.jspdf?.jsPDF) { setMeterCheckingLiveDownloadState(false, "PDF library load nahi hui"); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF();
                    doc.setFontSize(7); doc.setTextColor(100); doc.text("DEVELOPED BY - AKHILESH PATIDAR (AE)", 14, 8);
                    doc.setFontSize(13); doc.setTextColor(0); doc.text(reportTitle, 105, 16, { align: "center" });
                    doc.setFontSize(9); doc.text(`Date: ${todayLabel}`, 105, 23, { align: "center" });
                    doc.autoTable({ startY: 29, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 8, cellPadding: 2 }, headStyles: { fillColor: [111, 66, 38] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                } else {
                    const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const csv = [[reportTitle], [`Date: ${todayLabel}`], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                    link.download = `${fileName}.csv`;
                    link.click();
                }
                setTimeout(() => setMeterCheckingLiveDownloadState(false, `${downloadTypeLabel} download ho chuki hai`), 500);
            } catch (error) {
                setMeterCheckingLiveDownloadState(false, "Download nahi ho paya");
                showToast(error?.message || "Live Progress download nahi ho payi", false);
            }
        }
